  {t:"护送一位兽人老萨满到祖灵洞",check:{a:"SPR",sk:"will",label:"护送"},ok:["老萨满腿脚不便，你一路照料。到祖灵洞时，他送你一根兽骨杖：'路上辟邪。'"],fail:["草原上风沙大，你们多走了半日。"],okEff:{gold:10,xp:18,item:"兽骨杖"},failEff:{gold:4,xp:8}},
  {t:"替冰狼部落（或北境猎人）侦察黑石营地的动静",check:{a:"AGI",sk:"stealth",label:"侦察"},ok:["你摸到营地外围，记下兵力调动的情报，安全返回。委托人很满意：'眼睛好使！'"],fail:["你差点被巡逻队发现，仓促撤回，只记到一半情报。"],okEff:{gold:16,xp:25,rep:2},failEff:{gold:6,xp:10}}
