N["npc_parallel_view"]=function(){return{place:"大陆",text:function(){
  var key = "";
  if(S.flags.npc_view_mercury) key="mercury";
  else if(S.flags.npc_view_allen) key="allen";
  else if(S.flags.npc_view_rexa) key="rexa";
  else if(S.flags.npc_view_cecilia) key="cecilia";
  else if(S.flags.npc_view_marcus) key="marcus";
  else if(S.flags.npc_view_elara) key="elara";
  else if(S.flags.npc_view_thorin) key="thorin";
  else if(S.flags.npc_view_luna) key="luna";
  else if(S.flags.npc_view_kai) key="kai";
  else if(S.flags.npc_view_sophia) key="sophia";
  else if(S.flags.npc_view_felix) key="felix";
  else if(S.flags.npc_view_aria) key="aria";
  var npc = NPC_PARALLEL[key];
  var action = npc.actions[Math.floor(Math.random()*npc.actions.length)];
  var t=[];
  t.push("你收到了一封信——或者，是一个消息。");
  t.push(npc.cn+"，最近在"+npc.location+"。");
  t.push("据说，他/她最近在——"+action+"。");
  t.push("你想起了跟他/她在一起的日子。那些日子，好像就在昨天，又好像——已经过了很久。");
  t.push("你知道，等你们再见面的时候，他/她一定会不一样了。因为——每个人都在往前走，没有人会在原地等你。");
  return t;
},options:[
  {t:"继续",go:"npc_parallel_hub"}
]}};

/* ===== 因果链伏笔回收 ===== */
N["causality_hub"]=function(){return{place:"大陆",text:function(){
  var t=[];
  t.push("你做过的每一个选择，都会在未来的某一天，结出果实。");
  t.push("有些果实是甜的，有些是苦的。但不管是甜是苦——都是你自己种的。");
  t.push("你想看看，你之前种下的那些种子，现在怎么样了吗？");
  return t;
},options:[
  {t:"查看你的选择带来的后果",go:"causality_review"},
  {t:"离开",go:"fc_jiaohui_entry"}
]}};

N["causality_review"]=function(){return{place:"大陆",text:function(){
  var t=[];
  t.push("你闭上眼睛，回忆你走过的路。");
  if(S.flags.medici_eclipse_proof){
    t.push("── 美第奇家族的秘密 ──");
    t.push("你在美第奇府邸的地下室里，听到了洛伦佐跟暗蚀会的对话。你把这个秘密告诉了议会的反对派。现在，议会正在秘密调查美第奇家族。");
    t.push("洛伦佐似乎察觉到了什么——他最近很少在公开场合露面。有人说，他在准备逃跑。也有人说，他在准备——鱼死网破。");
    t.push("你的那个选择，改变了自由城邦的政治格局。");
  }
  if(S.flags.rexa_vow){
    t.push("── 蕾克斯的誓言 ──");
    t.push("你答应过蕾克斯，要帮她找她的妹妹。她一直在等你——等你变强，等你毕业，等你跟她一起去查暗蚀会。");
    t.push("她最近给你写了一封信。信里只有一句话——「我等你。」");
  }
  if(S.flags.cecilia_secret){
    t.push("── 塞西莉亚的血脉 ──");
    t.push("塞西莉亚告诉了你她的秘密——黄林晶的后裔。她最近开始做那个梦了——七道光，其中一道在叫她的名字。");
    t.push("她很害怕。但她也说——因为有你在，她没那么害怕了。");
  }
  if(S.flags.elara_ally){
    t.push("── 艾拉拉的银叶 ──");
    t.push("艾拉拉给了你一片银叶树的叶子。她说，只要你拿着它，在任何一棵银叶树下呼唤她的名字，她都会听到。");
    t.push("你把叶子收在了行囊的最深处。它很轻，但你觉得——它比你想象的要重得多。");
  }
  if(S.flags.thorin_ally){
    t.push("── 索林的护身符 ──");
    t.push("索林把他父亲的护身符给了你。那是铁拳家的信物——一把锤子和一把钥匙交叉的图案。");
    t.push("他说，矮人说过的话，比铁还硬。他会帮你查他父亲的事——不管需要多久。");
  }
  if(S.flags.luna_accepted){
    t.push("── 露娜的眼泪 ──");
    t.push("你告诉露娜，她不是怪物。她哭了——那是她第一次在别人面前哭。");
    t.push("从那以后，她每天都会在医务室等你。她给你讲她看到的故事——老格雷的等待，走廊里的学者，操场上的小男孩。");
    t.push("你第一次觉得，死者并不可怕。他们只是——还没来得及离开的人。");
  }
  if(S.flags.kai_accepted){
    t.push("── 凯的兄弟 ──");
    t.push("你告诉凯，他不是怪物，他是凯。他跟你做了兄弟。");
    t.push("他最近在竞技场里，再也不一个人躲在角落了。他开始跟其他同学一起训练，一起吃饭，一起——笑。");
    t.push("有人说，凯变了。但你知道——他没有变。他只是——终于有人把他当人看了。");
  }
  if(S.flags.sophia_awakened){
    t.push("── 索菲亚的觉醒 ──");
    t.push("你告诉索菲亚，信仰不是别人给的，是自己找的。她开始重新思考她的信仰。");
    t.push("她最近在教堂里，不再念那些刻板的祷文了。她开始——自己写祷文。用她自己的话，跟她自己的光明神对话。");
    t.push("她的父亲——红衣主教，似乎察觉到了什么。他给她写了一封信，信里只有一句话——「不要走歪路。」");
  }
  if(S.flags.felix_ally){
    t.push("── 菲利克斯的同伙 ──");
    t.push("你答应帮菲利克斯报仇。他给了你一个暗蚀会的徽章。");
    t.push("他最近在暗蚀会里，地位越来越高了。但你知道——他在走钢丝。一步走错，就会万劫不复。");
    t.push("他给你写了一封信。信里只有一句话——「如果我回不来了，记得拉我一把。」");
  }
  if(S.flags.aria_fear){
    t.push("── 艾莉亚的记忆 ──");
    t.push("你告诉艾莉亚，你会帮她记着。她哭了——哭得像个孩子。");
    t.push("她最近唱歌的时候，开始用一个小本子记录——她怕自己忘了。她把每一首歌的故事，都写在本子上，然后——把本子交给你保管。");
    t.push("「你是我的记忆。」她说，「如果有一天我忘了自己——你要提醒我，我是谁。」");
  }
  if(S.flags.dragon_companion){
    t.push("── 小金 ──");
    t.push("你带着小金离开了龙脊山。它现在在你的肩膀上，像一只金色的大猫。");
    t.push("它每天都在长大——鳞片越来越亮，翅膀越来越有力。你知道，总有一天，它会变成一条真正的巨龙。");
    t.push("它每天都在问你——「我们什么时候去找妈妈？」");
  }
  if(S.flags.giant_helper){
    t.push("── 石心的纪念碑 ──");
    t.push("你帮石心建好了纪念碑。他给了你一个巨人族的信物。");
    t.push("你走的时候，他站在谷口，看着你离开。他没有说话，但你知道——他在说谢谢。");
    t.push("巨人族三千个战士的名字，终于被刻在了石头上。三千年后，终于有人——记住了他们。");
  }
  if(S.flags.seal5_fixed){
    t.push("── 第五印 ──");
    t.push("你修复了第五印。深渊之水，不会淹没大陆了。");
    t.push("但你也知道了真相——水族的灭族，跟黄林晶有关。那个已经消失的种族，是被黄林晶牺牲的。");
  }
  if(S.flags.seal6_sacrifice){
    t.push("── 第六印的真相 ──");
    t.push("你穿越了时光，看到了三千年前的真相——七印的本质，是牺牲九个半神。其中一个，不是自愿的。");
    t.push("黄林晶不是英雄。至少，不完全是。");
    t.push("你把这个真相藏在了心里。你知道——总有一天，它会改变一切。");
  }
  if(!S.flags.medici_eclipse_proof && !S.flags.rexa_vow && !S.flags.cecilia_secret && !S.flags.elara_ally && !S.flags.thorin_ally && !S.flags.luna_accepted && !S.flags.kai_accepted && !S.flags.sophia_awakened && !S.flags.felix_ally && !S.flags.aria_fear && !S.flags.dragon_companion && !S.flags.giant_helper && !S.flags.seal5_fixed && !S.flags.seal6_sacrifice){
    t.push("你还没有做出足够多的选择。你的故事——才刚刚开始。");
    t.push("继续往前走吧。你做的每一个选择，都会在未来的某一天，结出果实。");
  }
  t.push("");
  t.push("你睁开眼睛。太阳还在天上，风还在吹，世界还在转。");
  t.push("你的故事——还在继续。");
  return t;
},options:[
  {t:"继续",go:"fc_jiaohui_entry"}
]}};



/* ================================================================
   第一印 · 铁门关（已碎）— 四幕完整章节
   ================================================================ */

/* ---- 第一幕：线索追寻 ---- */
N["seal1_act1_intro"]=function(){return{place:"自由城邦 · 交汇城 · 酒馆",where:"夜",text:function(){
  var t=[];
  t.push("雨下了三天。交汇城的石板路被泡得发黑，屋檐下的灯笼在风里摇晃，像一只只快要熄灭的眼睛。");
  t.push("你推开「锈锚」酒馆的门，热气和酒味扑面而来。角落里，一个独臂老兵正在喝酒。他的甲胄上还留着铁门关的徽章——那是十年前的制式，现在已经没人用了。");
  t.push("酒馆老板压低声音告诉你：「那个人，从铁门关逃回来的。十年了，天天喝，天天说梦话。说什么『门后面不是兽人』『我们被骗了』。」");
  t.push("你看了一眼那个老兵。他的独臂在发抖，不是因为冷。");
  t.push("铁门关——第一印的所在地。三年前兽人攻破了那道关隘，然后……然后所有人都说不清然后了。官方的说法是兽人用了禁忌魔法，打碎了什么东西。但打碎了什么？没有人告诉你。");
  t.push("档案馆的铁门在身后合拢时，发出一声沉闷的响，像把什么关在了外面，又把什么关在了里面。");t.push("墨丘利走在前面，脚步很轻，可他的声音在空旷的馆厅里显得格外清晰：「这里的每一卷文书，都比你的年纪大。它们不说话，但它们都记得。」");t.push("他停在一排书架前，伸手抚过书脊，像在抚摸一排墓碑：「七印的研究，从三百年前就开始了。三百年来，无数人走进这座档案馆，想弄清楚七印是什么。」");t.push("「他们之中，有多少人弄清楚了？」你问。");t.push("墨丘利回过头，看着你，眼神有些复杂：「弄清楚的人，大多没有走出来。」");t.push("书架深处，一缕灰尘在光线里缓缓浮动。你忽然觉得，这座档案馆比你想象的要深，也要冷。");return t;
} /*v45inj:seal1_act1_intro*/,options:[
  {t:"走过去，给老兵买一杯酒，慢慢问",go:"seal1_act1_vet",effect:{time:1}},
  {t:"先去图书馆查铁门关之战的官方记录",go:"seal1_act1_archive",effect:{time:1}},
  {t:"找墨丘利教授，他可能知道些什么",go:"seal1_act1_mercury",effect:{time:1}},
  {t:"暂时不管，先忙别的",go:"fc_jiaohui_entry"}
]}};

N["seal1_act1_vet"]=function(){return{place:"锈锚酒馆 · 角落",text:function(){
  var t=[];
  t.push("你端着两杯酒走过去。老兵抬眼看你，瞳孔浑浊，但眼神里有一种——你说不上来的东西，像是烧尽的灰里还藏着一粒火星。");
  t.push("「又来一个问铁门关的。」他哼了一声，接过酒，一饮而尽。「你们这些年轻人，总觉得那地方有什么秘密。秘密？呵。」");
  t.push("他用独臂指着自己的脑袋：「秘密在这里。我亲眼看见的。」");
  t.push("「那天晚上，关隘碎了。不是兽人打碎的——是从里面碎的。我们的人，自己打开了门。」他的声音突然低下来，「我看见那个将军，他跪在地上，对着空气说话。然后门就开了。然后……然后就不是兽人了。」");
  t.push("「是什么？」你问。");
  t.push("老兵看着你，很久。「是影子。会吃人的影子。」");
  return t;
},options:[
  {t:"追问将军的名字和更多细节",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal1_act1_vet_detail",fail:"seal1_act1_vet_fail"},
  {t:"检查老兵的独臂——伤口不对劲",check:{a:"INT",sk:"detect",label:"侦查"},go:"seal1_act1_vet_wound",fail:"seal1_act1_vet_fail"},
  {t:"留下酒钱，离开",go:"seal1_act1_clue_gathered",effect:{time:1,flag:"seal1_vet_talked"}}
]}};

N["seal1_act1_vet_detail"]=function(){return{place:"锈锚酒馆",text:function(){
  var t=[];
  t.push("你又给他买了一杯。这次他喝得慢了些。");
  t.push("「将军叫霍夫曼。铁门关守将。」他的手指在桌面上敲着，像是在敲某种你听不懂的节奏。「别人都说他战死了。放屁。我亲眼看见他走进那道光里，然后——然后他就不是他了。」");
  t.push("「他的眼睛变成了纯黑色。没有眼白，没有瞳孔，就是两块黑。然后他笑了。不是人的笑法。」");
  t.push("「后来呢？」");
  t.push("后来？后来关隘就碎了。第一印——我们那时才知道那叫第一印——碎了之后，从裂缝里涌出来的不是兽人军队。是影子。成千上万的影子。它们吃人，不是咬死，是——」他的声音开始发抖，「是把人整个吞进去，连骨头都不剩。」");
  t.push("「我能逃出来，是因为我断了一条胳膊。影子吞了我的胳膊，我趁它们不注意滚下了山崖。」他举起独臂，「这不是战伤。这是——被吃掉的。」");
  t.push("你注意到他的断臂处有一道极淡的黑色纹路，像是有什么东西在皮肤下面蠕动。");
  return t;
},options:[
  {t:"用灵魂感知探查那道黑色纹路",check:{a:"SPR",sk:"soul",label:"灵魂感知"},go:"seal1_act1_soul_read",fail:"seal1_act1_soul_fail"},
  {t:"记下霍夫曼这个名字，去查他的下落",go:"seal1_act1_clue_gathered",effect:{time:1,flag:"seal1_hoffman_name",flag2:"seal1_vet_talked"}},
  {t:"告诉老兵你会去铁门关查清真相",go:"seal1_act1_clue_gathered",effect:{time:1,flag:"seal1_vet_trust",flag2:"seal1_vet_talked"}}
]}};

N["seal1_act1_vet_fail"]=function(){return{place:"锈锚酒馆",text:function(){
  var t=[];
  t.push("老兵突然警觉起来。他一把推开你的手，酒碗摔在地上碎了。");
  t.push("「你们都是一伙的！都是来查我的！」他站起来，独臂挥舞着，「我什么都没说！什么都没看见！」");
  t.push("酒馆里的人都看过来。老板皱着眉走过来，意思很明显——该走了。");
  t.push("你被推出了酒馆。雨还在下。但你至少记住了一件事：铁门关的事，有人不想让人知道。");
  t.push("那个老兵的恐惧不是装的。他害怕的不是你，是你背后可能存在的——什么东西。");
  return t;
},options:[
  {t:"改天再来，换个方式接近他",go:"seal1_act1_clue_gathered",effect:{time:2,flag:"seal1_vet_suspicious"}},
  {t:"换条线索，去查官方档案",go:"seal1_act1_archive",effect:{time:1}}
]}};

N["seal1_act1_vet_wound"]=function(){return{place:"锈锚酒馆",text:function(){
  var t=[];
  t.push("你假装不小心碰了一下他的断臂。他疼得倒吸一口凉气，但没有躲开——或者说，他已经习惯了这种疼。");
  t.push("你看到了伤口。不是刀伤，不是箭伤。断臂处的皮肤是灰白色的，边缘有一圈极细的黑色纹路，像树根一样往身体里延伸。");
  t.push("你见过这种纹路。在学院的禁书区，一本关于深渊生物的书里——「蚀痕」。被深渊生物触碰过的人，会留下这种痕迹。它会慢慢蔓延，直到——");
  t.push("直到整个人被吞噬。");
  t.push("老兵还活着，说明他的意志力极强，或者——有什么东西在压制着蚀痕的蔓延。");
  return t;
},options:[
  {t:"告诉他蚀痕的真相，并问他是怎么压制的",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal1_act1_soul_read",fail:"seal1_act1_vet_fail"},
  {t:"默默记下，去图书馆查蚀痕和铁门关的关系",go:"seal1_act1_clue_gathered",effect:{time:1,flag:"seal1_corruption_mark",flag2:"seal1_vet_talked"}}
]}};

N["seal1_act1_soul_read"]=function(){return{place:"锈锚酒馆",text:function(){
  var t=[];
  t.push("你闭上眼睛，将灵魂感知延伸出去。触碰到那道黑色纹路的一瞬间——");
  t.push("你看见了。");
  t.push("铁门关。夜。火光冲天。一个穿将军甲胄的人跪在关隘中央，他的面前是一道裂缝——不是空间裂缝，是某种更古老的东西，像是世界本身被撕开了一道口子。");
  t.push("将军在哭。他对着裂缝说：「我已经做了。放了我的女儿。」");
  t.push("裂缝里传出一个声音。不是语言，是直接灌进脑子里的意念。你听不清具体内容，但你感受到了——那是一种纯粹的、没有任何杂质的恶意。像是整个宇宙的恶意都浓缩在了那一个瞬间。");
  t.push("然后将军站起来。他的眼睛全黑了。他转身，面对自己的士兵，笑了。");
  t.push("你猛地收回感知，大口喘气。老兵看着你，脸色苍白：「你也看见了？」");
  return t;
},options:[
  {t:"点头。问他霍夫曼的女儿是谁",go:"seal1_act1_clue_gathered",effect:{time:1,flag:"seal1_soul_vision",flag2:"seal1_hoffman_daughter",flag3:"seal1_vet_talked"}},
  {t:"问他后来霍夫曼怎么样了",go:"seal1_act1_clue_gathered",effect:{time:1,flag:"seal1_soul_vision",flag2:"seal1_hoffman_fate",flag3:"seal1_vet_talked"}}
]}};

N["seal1_act1_soul_fail"]=function(){return{place:"锈锚酒馆",text:function(){
  var t=[];
  t.push("你试图探查那道纹路，但你的灵魂感知刚一靠近，就被一股巨大的力量弹了回来。");
  t.push("你眼前一黑，耳边响起无数人的尖叫——那是十年前死在铁门关的人，他们的痛苦被烙在了那道蚀痕里，十年不散。");
  t.push("你踉跄后退，撞翻了一张桌子。老兵冷冷地看着你：「别碰。那东西会吃人的。」");
  t.push("你的头还在疼。但你至少确认了一件事：那道蚀痕里封存着铁门关的真相。只是以你现在的能力，还读不出来。");
  return t;
},options:[
  {t:"记下这个线索，等变强了再来",go:"seal1_act1_clue_gathered",effect:{time:1,sanLoss:5,flag:"seal1_corruption_mark",flag2:"seal1_vet_talked"}},
  {t:"换个方式，去查官方档案",go:"seal1_act1_archive",effect:{time:1,sanLoss:5}}
]}};

N["seal1_act1_archive"]=function(){return{place:"交汇城 · 公共档案馆",text:function(){
  var t=[];
  t.push("档案馆在市政厅的地下。空气里有一股旧纸和霉味混合的气息。管理员是个戴眼镜的老妇人，她看了一眼你的申请，推了推眼镜。");
  t.push("「铁门关之战？」她的语气平淡，「三楼，军事档案区，307架。但我提醒你——很多档案在战后被『清理』过了。」");
  t.push("「清理？」");
  t.push("「官方说法是『火灾损毁』。」她意味深长地看了你一眼，「但那些档案放了几十年都没事，偏偏战后第二年就着火了。你说巧不巧？」");
  t.push("你在三楼找到了307架。大部分档案盒都是空的，或者只剩下几页烧剩的残页。但你在最底层的一个角落里，找到了一份被遗漏的文件——一份士兵的家书，日期是铁门关之战前三天。");
  t.push("档案室里很暗，只有一扇小窗漏进一缕光，照在积满灰尘的书架上。空气里有一股陈旧的纸墨味，还有一丝若有若无的霉味。");t.push("你翻到一卷发黄的羊皮纸，上面记载着一段残缺的记录：第三印异动的年份，世界树枯萎的范围，以及一行几乎被磨平的小字——「彼时，黄林晶在沙漠中失踪。」");t.push("你盯着那行小字看了很久。黄林晶——这个名字，你在什么地方听过。");t.push("你把那卷羊皮纸小心地放回原处，又抽出旁边一卷。翻开的那一瞬间，一张纸片从书页间飘落下来，落在你脚边。");t.push("你弯腰捡起。纸片上只有一句话，字迹潦草，像是匆忙写下的：「别相信档案室里的任何结论。它们都对，但不完整。」");t.push("纸片的右下角，有一个极小的印记——一只闭着的眼睛。");return t;
} /*v45inj:seal1_act1_archive*/,options:[
  {t:"阅读那封家书",check:{a:"INT",sk:"lore",label:"学识"},go:"seal1_act1_letter",fail:"seal1_act1_archive_fail"},
  {t:"继续翻找，看还有没有遗漏",check:{a:"AGI",sk:"stealth",label:"潜行"},go:"seal1_act1_hidden",fail:"seal1_act1_clue_gathered"},
  {t:"离开档案馆",go:"seal1_act1_clue_gathered",effect:{time:1,flag:"seal1_archive_checked"}}
]}};

N["seal1_act1_letter"]=function(){return{place:"档案馆",text:function(){
  var t=[];
  t.push("家书是一个叫托马斯的列兵写给他母亲的。字迹潦草，像是在匆忙中写的。");
  t.push("「母亲大人：");
  t.push("关隘里最近不对劲。将军把我们分成了三班，日夜守着中央那扇铁门。那扇门从来没有打开过，我们都不知道后面是什么。但将军说，那是『帝国最高机密』。");
  t.push("三天前，将军的女儿病了。很重。将军请了教会的牧师，但牧师看了一眼就走了，说『这不是病』。然后将军就把自己关在房间里，两天没出来。");
  t.push("昨天晚上，我听见将军在房间里说话。不是对人说话——是对着空气。他说『我答应你』『不要伤害她』。然后他笑了。那种笑法……母亲，我害怕。");
  t.push("如果我出事了，不要来找我。离铁门关越远越好。」");
  t.push("信没有寄出去。托马斯的名字在阵亡名单上。");
  t.push("你把信收好。霍夫曼的女儿——这是关键。她得了什么病？为什么牧师说『不是病』？将军答应了谁？");
  return t;
},options:[
  {t:"查霍夫曼女儿的下落——她是否还活着",go:"seal1_act1_clue_gathered",effect:{time:1,flag:"seal1_hoffman_daughter",flag2:"seal1_archive_checked",item:"托马斯的家书"}},
  {t:"查那扇『铁门』后面到底是什么",go:"seal1_act1_clue_gathered",effect:{time:1,flag:"seal1_iron_door",flag2:"seal1_archive_checked",item:"托马斯的家书"}}
]}};

N["seal1_act1_hidden"]=function(){return{place:"档案馆 · 密室",text:function(){
  var t=[];
  t.push("你注意到307架的背板有些松动。你轻轻一推，背板滑开，露出一个暗格。");
  t.push("暗格里有一个铁皮盒子。盒子上印着守望者的标记——一只睁开的眼睛。");
  t.push("你打开盒子。里面是一份守望者的调查报告，日期是铁门关之战后一个月。报告的开头写着：");
  t.push("「铁门关事件初步调查：第一印碎裂原因非外部攻击，系内部人为开启。守将霍夫曼疑似被深渊力量蛊惑，以女儿为筹码，主动开启封印。开启后涌出的暗影生物已被守夜人部队清理，但封印已不可逆。霍夫曼本人下落不明，其女霍夫曼·艾米丽被教会收容，现状不明。」");
  t.push("报告的最后有一行手写批注，笔迹潦草：「不要追查艾米丽。她身上有东西。——奥」");
  t.push("奥。奥雷利安。守望者的首席。他亲自写的批注。");
  return t;
},options:[
  {t:"记下所有信息，把报告放回去",go:"seal1_act1_clue_gathered",effect:{time:1,flag:"seal1_watcher_report",flag2:"seal1_hoffman_daughter",flag3:"seal1_emily_danger",item:"守望者调查报告抄录"}},
  {t:"把报告带走——这可能是重要证据",go:"seal1_act1_clue_gathered",effect:{time:1,flag:"seal1_stole_report",flag2:"seal1_watcher_report",flag3:"seal1_hoffman_daughter",item:"守望者调查报告原件"}}
]}};

N["seal1_act1_archive_fail"]=function(){return{place:"档案馆",text:function(){
  var t=[];
  t.push("你试图解读那些烧剩的残页，但大部分字迹已经模糊不清。你只能勉强认出几个词：「封印」「开启」「代价」。");
  t.push("管理员走过来，拍了拍你的肩膀：「别费劲了。能看的都被人拿走了。剩下的这些，都是故意留下的。」");
  t.push("「故意留下的？」");
  t.push("「是啊。」她推了推眼镜，「让你以为自己查到了什么，其实什么都没有。这才是最高明的掩盖——不是销毁，是给你一个假答案。」");
  t.push("你离开档案馆。雨停了，但天还是阴的。");
  return t;
},options:[
  {t:"换条线索，去找那个老兵",go:"seal1_act1_vet",effect:{time:1}},
  {t:"先整理已有线索，准备出发",go:"seal1_act1_clue_gathered",effect:{time:1,flag:"seal1_archive_checked"}}
]}};

N["seal1_act1_mercury"]=function(){return{place:"艾尔达魔法学院 · 墨丘利研究室",text:function(){
  var t=[];
  t.push("墨丘利的研究室在学院最偏僻的角落。门上贴着一张纸条：「请勿打扰——除非你带来了有趣的灵魂。」");
  t.push("你推开门，墨丘利正坐在一堆古籍中间，手里拿着一个发光的水晶球。他抬头看你，笑了笑：「我等你很久了。」");
  t.push("「你知道我要来？」");
  t.push("「我不知道。但我知道，迟早会有人来问铁门关的事。」他放下水晶球，表情严肃起来，「你想知道第一印的真相？」");
  t.push("你点头。");
  t.push("墨丘利沉默了一会儿。「第一印不是被兽人打碎的。是被一个父亲打碎的——为了救他的女儿。」他的声音很轻，「而那个女儿，现在还活着。在教会手里。」");
  t.push("「你怎么知道这些？」");
  t.push("「因为我去过铁门关。战后第三年。」他的眼神变得遥远，「我看到了那道裂缝。我也看到了——裂缝后面的东西。」");
  return t;
},options:[
  {t:"追问裂缝后面是什么",check:{a:"SPR",sk:"will",label:"意志"},go:"seal1_act1_mercury_truth",fail:"seal1_act1_mercury_refuse"},
  {t:"问他霍夫曼女儿的具体位置",go:"seal1_act1_clue_gathered",effect:{time:1,flag:"seal1_mercury_told",flag2:"seal1_hoffman_daughter"}},
  {t:"问他能不能和你一起去铁门关",go:"seal1_act1_clue_gathered",effect:{time:1,flag:"seal1_mercury_offer",flag2:"seal1_mercury_told"}}
]}};

N["seal1_act1_mercury_truth"]=function(){return{place:"墨丘利研究室",text:function(){
  var t=[];
  t.push("墨丘利看着你，目光锐利：「你确定要知道？有些真相，知道了就回不去了。」");
  t.push("你再次点头。");
  t.push("他叹了口气。「七印不是封印深渊的。七印是封印『原初之物』的——比深渊更古老、更可怕的存在。深渊只是原初之物的排泄物，是它泄漏出来的一丝气息。」");
  t.push("「黄林晶三千年前加固七印，不是为了对抗深渊，是为了不让原初之物醒来。每一道印下面，都压着一块原初之物的碎片。」");
  t.push("「第一印下面压着的，是『饥饿』。纯粹的、永无止境的饥饿。它吞噬一切——物质、能量、灵魂、甚至空间本身。铁门关的暗影生物，就是饥饿泄漏后产生的衍生物。」");
  t.push("你感到一阵寒意。不是因为冷，是因为这个真相太过庞大。");
  t.push("墨丘利继续说：「霍夫曼打开第一印，是因为他的女儿被饥饿的碎片感染了。只有打开封印，让饥饿『认出』自己的碎片，他女儿才能活。但打开封印的代价是——碎片会开始复苏。」");
  t.push("「现在第一印碎了三年。饥饿的碎片正在缓慢苏醒。如果不做什么，十年之内——」他没有说完。");
  return t;
},options:[
  {t:"问他修复第一印的方法",go:"seal1_act1_clue_gathered",effect:{time:1,sanLoss:10,flag:"seal1_truth_known",flag2:"seal1_hunger",flag3:"seal1_mercury_told"}},
  {t:"问他原初之物到底是什么",go:"seal1_act1_clue_gathered",effect:{time:1,sanLoss:15,flag:"seal1_truth_known",flag2:"seal1_primordial",flag3:"seal1_mercury_told"}}
]}};

N["seal1_act1_mercury_refuse"]=function(){return{place:"墨丘利研究室",text:function(){
  var t=[];
  t.push("你试图追问，但墨丘利摇了摇头。");
  t.push("「你的意志还不够强。现在知道真相，只会让你疯掉。」他站起来，走到窗边，「等你到了宗师境，再来找我。到那时候，我会把一切都告诉你。」");
  t.push("「但你至少可以告诉我——第一印还能修复吗？」");
  t.push("墨丘利沉默了很久。「能。但代价很大。」他转过身，「修复第一印需要三样东西：黄林晶留下的『铸印』、一个自愿成为锚点的灵魂、以及——」他顿了顿，「霍夫曼女儿的同意。」");
  t.push("「她的同意？」");
  t.push("「她身上有饥饿的碎片。修复封印需要把碎片从她体内取出来，放回印里。但这个过程她必须自愿，否则碎片会反抗，到时候死的人更多。」");
  return t;
},options:[
  {t:"记下这些条件，准备出发",go:"seal1_act1_clue_gathered",effect:{time:1,flag:"seal1_repair_conditions",flag2:"seal1_mercury_told"}},
  {t:"问他霍夫曼女儿在哪里",go:"seal1_act1_clue_gathered",effect:{time:1,flag:"seal1_repair_conditions",flag2:"seal1_hoffman_daughter",flag3:"seal1_mercury_told"}}
]}};

N["seal1_act1_clue_gathered"]=function(){return{place:"交汇城",text:function(){
  var t=[];
  t.push("你把收集到的线索整理了一遍。");
  if(S.flags.seal1_vet_talked) t.push("· 独臂老兵的证词：铁门关是从内部被打碎的，守将霍夫曼被某种力量控制。");
  if(S.flags.seal1_hoffman_name) t.push("· 霍夫曼——铁门关守将，战后下落不明。");
  if(S.flags.seal1_hoffman_daughter) t.push("· 霍夫曼的女儿艾米丽：得了一种『不是病』的病，战后被教会收容，现状不明。");
  if(S.flags.seal1_soul_vision) t.push("· 你的灵魂感知看到了真相：霍夫曼以女儿为筹码，主动开启了封印。");
  if(S.flags.seal1_watcher_report) t.push("· 守望者的调查报告：确认第一印系内部人为开启，霍夫曼被深渊力量蛊惑。");
  if(S.flags.seal1_mercury_told) t.push("· 墨丘利的情报：七印封印的不是深渊，是更古老的『原初之物』。第一印下面是『饥饿』。");
  if(S.flags.seal1_repair_conditions) t.push("· 修复条件：铸印+自愿的灵魂锚点+艾米丽的同意。");
  if(S.flags.seal1_corruption_mark) t.push("· 老兵身上的『蚀痕』：深渊生物触碰的痕迹，会缓慢蔓延。");
  t.push("");
  t.push("不管你信不信，铁门关的真相都在那里。你需要亲自去一趟。");
  t.push("从交汇城到铁门关，骑马大约需要五天。路上要经过北方公国的边境，最近那边不太平——兽人游骑兵活动频繁。");
  return t;
},options:[
  {t:"准备出发，骑马前往铁门关",go:"seal1_act2_journey",effect:{time:5,gold:-20}},
  {t:"先去买些补给和装备",go:"seal1_act1_supply",effect:{time:1}},
  {t:"再打听一下路上的安全情况",check:{a:"CHA",sk:"persu",label:"打听"},go:"seal1_act1_road_info",fail:"seal1_act2_journey"}
]}};

N["seal1_act1_supply"]=function(){return{place:"交汇城 · 集市",text:function(){
  var t=[];
  t.push("集市上很热闹。你在各个摊位间穿梭，挑选需要的东西。");
  t.push("铁匠铺的老板是个矮人，他向你推荐了一把『专门对付暗影生物』的匕首——刀刃上刻着圣光符文，要价三十金龙。「这玩意儿砍暗影比砍肉还利索，信不信由你。」");
  t.push("药剂师那里有抗蚀药剂——据说可以减缓蚀痕的蔓延，五十金龙一瓶。「这玩意儿稀罕，我这里只有三瓶。」");
  t.push("杂货铺老板向你推销铁门关的『旅游地图』——五银月一份。「虽然那地方现在没人去了，但地图还是准的。」");
  return t;
},options:[
  {t:"买圣光匕首（-30金龙）",go:"seal1_act1_clue_gathered",effect:{gold:-30,item:"圣光匕首"}},
  {t:"买抗蚀药剂（-50金龙）",go:"seal1_act1_clue_gathered",effect:{gold:-50,item:"抗蚀药剂"}},
  {t:"买地图（-5银月）",go:"seal1_act1_clue_gathered",effect:{gold:-1,item:"铁门关地图"}},
  {t:"不买了，直接出发",go:"seal1_act2_journey",effect:{time:1}}
]}};

N["seal1_act1_road_info"]=function(){return{place:"交汇城 · 酒馆",text:function(){
  var t=[];
  t.push("你在酒馆里拦住一个刚从北方回来的商队队长。他是个精明的中年人，看了看你，伸出两根手指。");
  t.push("「两个金龙。我告诉你路上的情况。」");
  t.push("你付了钱。他压低声音：「去铁门关？你疯了。那地方现在是禁区。北方公国的军队在五十里外设了卡子，不让人靠近。」");
  t.push("「但卡子不是防人的——是防里面的东西出来的。」他打了个寒颤，「上个月，有一队巡逻兵在卡子附近失踪了。只找到了盔甲，人没了。盔甲里面是空的，像是被什么东西从里面吃干净了。」");
  t.push("「还有，兽人最近在边境活动频繁。不是大部队，是小股游骑兵。他们好像也在找什么东西——往铁门关方向去的。」");
  t.push("「你要是非去不可，别走官道。绕山路，从精灵森林的边缘穿过去。虽然远一点，但安全。」");
  return t;
},options:[
  {t:"走官道，快但危险",go:"seal1_act2_journey_road",effect:{time:4,flag:"seal1_road_official"}},
  {t:"绕山路，慢但安全",go:"seal1_act2_journey_mountain",effect:{time:7,flag:"seal1_road_mountain"}},
  {t:"先回交汇城准备一下再走",go:"seal1_act1_supply",effect:{time:1}}
]}};

/* ---- 第二幕：抵达与探索 ---- */
N["seal1_act2_journey"]=function(){return{place:"前往铁门关的路上",text:function(){
  var t=[];
  t.push("你骑马出了交汇城，一路向北。");
  t.push("第一天，风景还正常。农田、村庄、炊烟。孩子们在路边追逐，看到你骑马经过就停下来看。");
  t.push("第三天，情况变了。村庄越来越少，田地越来越荒芜。有些村子的门是开着的，里面没有人——不是被遗弃，是被什么东西『清空』了。家具还在，锅里的饭还在，但人没了。");
  t.push("第五天，你看到了铁门关。");
  t.push("它矗立在两座山之间，像一道巨大的伤疤。关隘的城墙碎了一半，露出里面黑色的石头。空气中有一种奇怪的味道——不是腐臭，是一种更原始的、像是空腹的味道。");
  t.push("你的马开始不安地刨蹄子，不肯再往前走。");
  return t;
},options:[
  {t:"安抚马匹，继续靠近",check:{a:"CHA",sk:"survive",label:"生存"},go:"seal1_act2_arrive",fail:"seal1_act2_horse_panic"},
  {t:"下马步行，把马拴在远处",go:"seal1_act2_arrive",effect:{time:1}},
  {t:"先在远处观察，用望远镜看细节",check:{a:"INT",sk:"detect",label:"侦查"},go:"seal1_act2_observe",fail:"seal1_act2_arrive"}
]}};

N["seal1_act2_journey_road"]=function(){return{place:"官道 · 北方公国边境",text:function(){
  var t=[];
  t.push("你选择走官道。路确实好走，但第四天你遇到了北方公国的哨卡。");
  t.push("三个士兵拦住了你。为首的是个年轻军官，他看了看你的装束，语气不善：「前方是禁区。掉头。」");
  t.push("「我有急事——」");
  t.push("「急事也不行。」他按住剑柄，「上个月刚失踪了一队人。你要是再往前一步，我就以间谍罪逮捕你。」");
  return t;
},options:[
  {t:"说服他放行（说明你在调查铁门关真相）",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal1_act2_arrive",fail:"seal1_act2_arrested"},
  {t:"贿赂他（-20金龙）",go:"seal1_act2_arrive",effect:{gold:-20}},
  {t:"掉头，晚上绕过去",go:"seal1_act2_sneak",effect:{time:1}}
]}};

N["seal1_act2_journey_mountain"]=function(){return{place:"精灵森林边缘 · 山路",text:function(){
  var t=[];
  t.push("你选择绕山路。路很难走，到处是乱石和倒木。但你确实没有遇到军队——也没有遇到兽人。");
  t.push("第三天，你在一片林间空地上发现了一些痕迹。不是人的脚印——是某种更大的东西留下的。脚印有三个脚趾，每个脚趾都有锋利的爪痕。");
  t.push("你蹲下来检查。脚印很新，不超过两天。方向是——铁门关。");
  t.push("你想起商队队长的话：兽人小股游骑兵也在往铁门关方向去。但这脚印不是兽人的。兽人是五个脚趾。");
  t.push("这是别的什么东西。");
  return t;
},options:[
  {t:"跟踪脚印，看看是什么",check:{a:"AGI",sk:"stealth",label:"潜行"},go:"seal1_act2_track",fail:"seal1_act2_arrive"},
  {t:"不跟踪，继续赶路",go:"seal1_act2_arrive",effect:{time:2,flag:"seal1_mysterious_tracks"}}
]}};

N["seal1_act2_horse_panic"]=function(){return{place:"铁门关外",text:function(){
  var t=[];
  t.push("你的马突然人立起来，嘶鸣着掉头就跑。你被甩了下来，摔在地上，肩膀磕在石头上。");
  t.push("你爬起来，看着马消失在远方。它不会回来了——动物对这种地方有一种本能的恐惧。");
  t.push("你揉着肩膀，抬头看向铁门关。更近了。你能看清城墙上的裂痕——那些裂痕不是被撞碎的，是从里面被撑开的。像是有什么东西在城墙内部生长，把石头一点点挤开。");
  t.push("裂痕里有黑色的东西在缓慢流动。不是液体，更像是——雾气。有生命的雾气。");
  return t;
},options:[
  {t:"步行前进，小心那些黑色雾气",go:"seal1_act2_arrive",effect:{time:1,hp:-10,flag:"seal1_lost_horse"}},
  {t:"先处理肩膀的伤",check:{a:"INT",sk:"heal",label:"医疗"},go:"seal1_act2_arrive",fail:"seal1_act2_arrive"}
]}};

N["seal1_act2_observe"]=function(){return{place:"铁门关外 · 山坡",text:function(){
  var t=[];
  t.push("你在山坡上趴下，用望远镜观察铁门关的细节。");
  t.push("关隘的正门已经碎了，只剩下半扇铁门歪在一边。门上有很深的爪痕——不是兽人的，爪痕太大了。");
  t.push("关隘内部，你看到了一些移动的影子。不是人——它们的形状不对，时而聚成人形，时而散成一团黑雾。它们在关隘里游荡，像是在巡逻，又像是在——等待。");
  t.push("关隘中央有一个巨大的坑。坑的边缘是黑色的玻璃状物质——那是沙子被极高温度熔化后形成的。坑的深不见底，里面偶尔闪过一丝红光。");
  t.push("你还注意到，关隘的最高处站着一个人。或者说，一个『人形』。它一动不动，面朝北方。你看不清它的脸，但你能感觉到——它在看你。");
  return t;
},options:[
  {t:"趁它没动，快速潜入关隘",check:{a:"AGI",sk:"stealth",label:"潜行"},go:"seal1_act2_enter",fail:"seal1_act2_spotted"},
  {t:"绕到关隘侧面，找别的入口",go:"seal1_act2_side_enter",effect:{time:2}},
  {t:"先退回去，晚上再来",go:"seal1_act2_night",effect:{time:4}}
]}};

N["seal1_act2_track"]=function(){return{place:"精灵森林 · 追踪",text:function(){
  var t=[];
  t.push("你循着脚印追踪了大约一个小时。脚印把你带到了一个山洞前。");
  t.push("洞口有骨头。不是动物的骨头——是人的。你数了数，至少有五具。骨头很干净，像是被什么东西仔细舔过。");
  t.push("你拔出武器，慢慢走进山洞。洞不深，走了十几步就到了尽头。尽头有一个——");
  t.push("一个茧。用人的皮肤和头发编织成的茧，挂在洞顶上。茧在微微跳动，像是里面有什么东西在呼吸。");
  t.push("你感到一阵强烈的恶心。这是暗影生物的『孵化巢』——它们把人拖回来，用这种方式转化成新的暗影生物。");
  t.push("茧突然裂开了。一个东西从里面掉出来，趴在地上。它有人形，但皮肤是半透明的黑色，眼睛是两个空洞。它抬起头，看到了你。");
  return t;
},options:[
  {t:"先发制人，攻击！",check:{a:"STR",sk:"martial",label:"武技"},go:"seal1_act2_combat_win",fail:"seal1_act2_combat_lose"},
  {t:"转身就跑",check:{a:"AGI",sk:"athletic",label:"运动"},go:"seal1_act2_arrive",fail:"seal1_act2_combat_lose"},
  {t:"用圣光/魔法攻击它的弱点",check:{a:"INT",sk:"magic",label:"法术"},go:"seal1_act2_combat_win",fail:"seal1_act2_combat_lose"}
]}};

N["seal1_act2_combat_win"]=function(){return{place:"山洞",text:function(){
  var t=[];
  t.push("你的攻击精准地命中了那个东西。它发出一声不像人声的尖叫，身体开始溃散——黑色的雾气从它的伤口里涌出来，在空气中消散。");
  t.push("几秒钟后，它倒在地上，变成了一滩黑色的液体。液体很快蒸发，留下一小颗暗红色的结晶。");
  t.push("你捡起结晶。它在你手里微微发热，里面有什么东西在流动。这是『暗影核心』——暗影生物的精华，在黑市上能卖个好价钱。但更重要的是，它是研究暗影生物的重要材料。");
  t.push("你检查了山洞，确认没有其他孵化巢。然后你离开山洞，继续向铁门关前进。经过这一战，你对暗影生物有了更直观的了解——它们怕光，怕神圣能量，而且转化人类的方式比你想象的更恶心。");
  return t;
},options:[
  {t:"继续前往铁门关",go:"seal1_act2_arrive",effect:{time:2,item:"暗影核心",flag:"seal1_fought_shadow"}}
]}};

N["seal1_act2_combat_lose"]=function(){return{place:"山洞",text:function(){
  var t=[];
  t.push("你的攻击没有奏效——或者说，不够快。那个东西扑了上来，黑色的爪子划过你的手臂，留下三道深可见骨的伤口。");
  t.push("你感到一阵冰冷从伤口蔓延开来。不是普通的冷，是那种——灵魂被触碰的冷。你的视野开始模糊，耳边响起嗡嗡声。");
  t.push("你用尽最后的力气，一脚踹开它，转身就跑。你能听到它在后面追，但它的速度不快——或者说，它不急于追你。它在『玩』。");
  t.push("你跑出山洞，滚下山坡，直到撞到一棵树上才停下来。你喘着气，检查伤口。伤口在发黑。蚀痕。你被感染了。");
  t.push("但至少你还活着。");
  return t;
},options:[
  {t:"用抗蚀药剂处理伤口（如果有的话）",go:"seal1_act2_arrive",effect:{time:1,hp:-20,sanLoss:5,flag:"seal1_infected"}},
  {t:"不管伤口，继续前进",go:"seal1_act2_arrive",effect:{time:1,hp:-30,sanLoss:10,flag:"seal1_infected"}}
]}};

N["seal1_act2_arrive"]=function(){return{entry:{from:{"seal1_act2_horse":["马在半路上惊了，你差点被甩下山崖。你牵着它走完了剩下的路。抵达时，你和马都累得说不出话。", "你拍了拍它的脖子。它打了个响鼻，算是应了。"],"seal1_act2_journey":["路走了几天，你已经分不清晨昏。抵达的时候，你先找了一处能歇脚的地方，把背上的东西卸下来，才好好看了一眼眼前的地方。", "风从那边来，带着一股说不清的味道——像旧铁，像深水，像很久没人动过的门轴。"]},default:[]},/*v46entry:s1arr_horse+s1arr_journey*/place:"铁门关 · 关隘入口",text:function(){
  var t=[];
  t.push("你站在铁门关的正门前。");
  t.push("近距离看，这座关隘比你想象的更大。城墙有三十米高，全部由黑色的花岗岩砌成。但现在，一半的城墙已经坍塌，碎石堆成了小山。");
  t.push("空气中的『空腹感』更强了。你感到一阵莫名的饥饿——不是胃的饥饿，是某种更深层的、来自灵魂的空虚。像是有什么东西在你体内打开了一个洞，怎么填都填不满。");
  t.push("你摇摇头，把这种感觉压下去。然后你走进了关隘。");
  t.push("里面是一个巨大的广场。广场中央是那个坑——你在望远镜里看到的那个。坑的直径有二十米，边缘是玻璃化的黑色岩石。坑底深不见底，偶尔闪过一丝红光。");
  t.push("广场上散落着武器和盔甲。十年了，它们还在这里。没有人来收尸——或者说，来收尸的人也没能回去。");
  t.push("你注意到，坑的周围有一圈符文。符文已经暗淡了，但你还能辨认出一些——这是黄林晶的封印符文。七印的标准配置。");
  return t;
},options:[
  {t:"检查坑周围的符文",check:{a:"INT",sk:"magic",label:"法术"},go:"seal1_act2_runes",fail:"seal1_act2_runes_fail"},
  {t:"探索关隘内部的建筑（将军府/兵营/地牢）",go:"seal1_act2_explore",effect:{time:1}},
  {t:"直接下坑",check:{a:"SPR",sk:"will",label:"意志"},go:"seal1_act3_pit",fail:"seal1_act2_pit_fail"}
]}};

N["seal1_act2_runes"]=function(){return{place:"铁门关 · 封印坑边",text:function(){
  var t=[];
  t.push("你蹲下来，仔细研究坑周围的符文。");
  t.push("符文分三层。最外层是『锁』——标准的空间封印，把目标锁在固定位置。中间层是『压』——用巨大的能量压制目标的活动。最内层是『食』——");
  t.push("你愣住了。『食』？");
  t.push("你重新辨认。没错，最内层的符文是『吞噬』——它不是在封印什么东西，而是在『喂养』它。封印符文在吸收周围的能量，然后注入坑底。");
  t.push("你突然明白了墨丘利的话。七印不是在封印原初之物——是在『喂养』它。用整个大陆的生灵能量，喂养着坑底的那个东西。让它保持沉睡，因为如果它醒了——");
  t.push("如果它醒了，它会自己找吃的。到那时候，就不是一座关隘的事了。");
  t.push("符文已经碎了大半。外层的『锁』完全失效，中间层的『压』只剩下三成，最内层的『食』还在运转——但已经不稳定了。能量在泄漏，这就是为什么周围的村庄会被『清空』——泄漏的能量在吞噬附近的生命。");
  return t;
},options:[
  {t:"尝试修复符文（需要铸印）",go:"seal1_act2_runes_repair",effect:{time:1,flag:"seal1_runes_understood"}},
  {t:"记下符文结构，继续探索",go:"seal1_act2_explore",effect:{time:1,flag:"seal1_runes_understood",flag2:"seal1_feeding_truth"}},
  {t:"下坑，看看底部到底是什么",go:"seal1_act3_pit",effect:{time:1,flag:"seal1_runes_understood"}}
]}};

N["seal1_act2_runes_fail"]=function(){return{place:"铁门关 · 封印坑边",text:function(){
  var t=[];
  t.push("你试图解读那些符文，但它们太古老了。黄林晶时代的符文体系和现代魔法完全不同，你只能勉强认出几个基础符号。");
  t.push("但你注意到一件事：符文的排列方式不是圆形，而是螺旋形。从外向内，一圈一圈地收紧。这不是封印的标准形态——封印通常是圆形的，均匀分布能量。");
  t.push("螺旋形意味着——能量在向中心汇聚。不是在压制，是在『注入』。");
  t.push("你不确定这意味着什么，但你记下了这个细节。也许以后能找到答案。");
  return t;
},options:[
  {t:"继续探索关隘内部",go:"seal1_act2_explore",effect:{time:1,flag:"seal1_spiral_runes"}},
  {t:"下坑看看",go:"seal1_act3_pit",effect:{time:1,flag:"seal1_spiral_runes"}}
]}};

N["seal1_act2_runes_repair"]=function(){return{place:"铁门关 · 封印坑边",text:function(){
  var t=[];
  t.push("你尝试用自己的魔力修复符文。但你的手刚碰到第一道符文，就被一股巨大的力量弹了回来。");
  t.push("符文亮了一下，然后重新暗淡。你感到一阵眩晕——不是因为消耗了魔力，是因为符文在『吸』你的能量。它在试图把你变成新的燃料。");
  t.push("你赶紧松手。额头上全是冷汗。");
  t.push("普通的修复方法行不通。这些符文是黄林晶亲手刻的，只有用『铸印』——黄林晶留下的专门修复七印的工具——才能重新激活它们。");
  t.push("你没有铸印。至少现在没有。");
  return t;
},options:[
  {t:"记下需要铸印，继续探索",go:"seal1_act2_explore",effect:{time:1,hp:-5,sanLoss:5,flag:"seal1_need_castmark"}},
  {t:"先下坑看看底部",go:"seal1_act3_pit",effect:{time:1,flag:"seal1_need_castmark"}}
]}};

N["seal1_act2_explore"]=function(){return{place:"铁门关 · 关隘内部",text:function(){
  var t=[];
  t.push("你离开封印坑，探索关隘内部的建筑。");
  t.push("兵营已经塌了一半。里面的铺位还在，被褥整齐地叠着——像是士兵们只是出去巡逻了，随时会回来。你在一个铺位上找到了一本日记，日期截止到铁门关之战前一天。");
  t.push("将军府保存得相对完好。你走进去，大厅里的家具还在，只是落满了灰。墙上挂着一幅霍夫曼的画像——一个中年男人，面容坚毅，但眼神里有一种深藏的疲惫。");
  t.push("画像下面有一张书桌。桌上摊着一封信，墨迹已经褪色，但还能辨认：");
  t.push("「艾米丽：");
  t.push("爸爸对不起你。爸爸做了一个错误的选择，但如果重来一次，爸爸还是会这么做。因为你是爸爸的一切。");
  t.push("不要来找爸爸。不要来铁门关。好好活着。");
  t.push("——爸爸」");
  t.push("信没有写完。最后一个字只写了一半。");
  return t;
},options:[
  {t:"继续探索将军府，找霍夫曼的研究笔记",check:{a:"INT",sk:"detect",label:"侦查"},go:"seal1_act2_notes",fail:"seal1_act2_dungeon"},
  {t:"去地牢看看",go:"seal1_act2_dungeon",effect:{time:1}},
  {t:"回到封印坑，准备下坑",go:"seal1_act3_pit",effect:{time:1,item:"霍夫曼的未寄出信"}}
]}};

N["seal1_act2_notes"]=function(){return{place:"将军府 · 密室",text:function(){
  var t=[];
  t.push("你在将军府的书房里发现了一个暗格。暗格里有一摞笔记，是霍夫曼的手迹。");
  t.push("笔记的前半部分是普通的军事记录——兵力部署、粮草统计、巡逻安排。但从某一天开始，内容变了。");
  t.push("「艾米丽病了。牧师说不是病。我问他是什么，他不说。我看到他在发抖。」");
  t.push("「第三天，艾米丽开始说梦话。她说『它在叫我』『它饿了』。我问她是谁，她说是『住在门后面的朋友』。」");
  t.push("「第七天，我听到了那个声音。它在我脑子里说话。它说它能治好艾米丽，只要我打开门。」");
  t.push("「第十五天，我打开了门。」");
  t.push("笔记到这里就断了。后面的几页被撕掉了。但在最后一页的空白处，有一行用血写的字：");
  t.push("「它骗了我。它没有治好艾米丽。它把艾米丽变成了『门』。」");
  return t;
},options:[
  {t:"把笔记带走",go:"seal1_act2_dungeon",effect:{time:1,item:"霍夫曼的笔记",flag:"seal1_emily_is_door"}},
  {t:"记下内容，继续探索",go:"seal1_act2_dungeon",effect:{time:1,flag:"seal1_emily_is_door"}}
]}};

N["seal1_act2_dungeon"]=function(){return{place:"铁门关 · 地牢入口",text:function(){
  var t=[];
  t.push("地牢的入口在将军府后面。铁门已经锈死了，你用了很大力气才推开。");
  t.push("楼梯向下延伸，消失在黑暗中。空气里有一股潮湿的、发霉的味道，还夹杂着——甜味。不正常的甜。");
  t.push("你点燃火把，走下楼梯。地牢比你想象的大。两侧是囚室，大部分是空的。但最深处的一间囚室里，有东西。");
  t.push("不是人。是一幅画。画在墙上的，用某种暗红色的颜料——你怀疑是血。画的内容是一个巨大的、没有形状的东西，它有无数张嘴，每张嘴都在尖叫。画的下方写着一行字：");
  t.push("「它饿了。」");
  t.push("你感到一阵寒意。这幅画是十年前画的。但颜料还没有干。");
  return t;
},options:[
  {t:"仔细研究这幅画",check:{a:"SPR",sk:"soul",label:"灵魂感知"},go:"seal1_act2_painting",fail:"seal1_act2_painting_fail"},
  {t:"离开地牢，回到封印坑",go:"seal1_act3_pit",effect:{time:1,flag:"seal1_dungeon_painting"}},
  {t:"检查其他囚室",check:{a:"AGI",sk:"stealth",label:"潜行"},go:"seal1_act2_cells",fail:"seal1_act3_pit"}
]}};

N["seal1_act2_painting"]=function(){return{place:"地牢",text:function(){
  var t=[];
  t.push("你将灵魂感知延伸到那幅画上。");
  t.push("一瞬间，你被拉入了画中。");
  t.push("你看到了铁门关之战的真相。不是从外面看，是从『里面』——从那个被打开的封印的内部。");
  t.push("你看到了『饥饿』。它不是一个生物，是一个概念。是宇宙诞生时的第一个空洞。它没有形状，没有意识，只有一个永恒的指令——吞噬。");
  t.push("黄林晶没有封印它——黄林晶用七印把它『分割』了。把一个完整的『饥饿』分成了七份，分别压在七道印下面。然后用符文不断喂养它，让它满足于这一点点能量，不去吞噬更多。");
  t.push("第一印碎了。其中一份『饥饿』正在苏醒。它已经吞噬了铁门关的所有人，现在它在缓慢地向外扩张。按照这个速度，十年内它会到达交汇城。二十年内，半个大陆。");
  t.push("你猛地退出感知，大口喘气。你的手在发抖。");
  return t;
},options:[
  {t:"你知道了真相。回到封印坑，下坑",go:"seal1_act3_pit",effect:{time:1,sanLoss:15,flag:"seal1_hunger_true",flag2:"seal1_dungeon_painting"}},
  {t:"太可怕了。先离开铁门关，从长计议",go:"seal1_act4_retreat",effect:{time:1,sanLoss:10,flag:"seal1_fear"}}
]}};

N["seal1_act2_painting_fail"]=function(){return{place:"地牢",text:function(){
  var t=[];
  t.push("你试图感知那幅画，但你的灵魂刚一靠近，就被一股巨大的吸力拽了过去。");
  t.push("你看到了无数张嘴。它们在对你笑。然后它们开始——唱。不是语言，是一种直接灌入灵魂的旋律，告诉你『放弃吧』『被吞噬是一种解脱』。");
  t.push("你咬紧牙关，用尽全部意志切断了感知。你踉跄后退，撞在墙上，鼻子流出了血。");
  t.push("那幅画还在。颜料还没干。你不敢再看它了。");
  return t;
},options:[
  {t:"离开地牢，回到封印坑",go:"seal1_act3_pit",effect:{time:1,hp:-10,sanLoss:10,flag:"seal1_dungeon_painting"}},
  {t:"先离开铁门关，休息一下",go:"seal1_act4_retreat",effect:{time:1,hp:-10,sanLoss:10}}
]}};

N["seal1_act2_cells"]=function(){return{place:"地牢 · 囚室",text:function(){
  var t=[];
  t.push("你检查了其他囚室。大部分是空的，但在倒数第二间里，你发现了一具尸体。");
  t.push("尸体穿着牧师的袍服。十年了，居然没有腐烂——他的皮肤是灰白色的，像是被吸干了所有水分。他的手里攥着一个十字架，十字架上有一个暗格。");
  t.push("你打开暗格。里面是一卷羊皮纸，上面写着教会的密令：");
  t.push("「致铁门关守将霍夫曼：");
  t.push("你女儿的病，我们无能为力。但我们知道谁能救她——门后面的那位。");
  t.push("打开门。它会治好她。这是神的旨意。");
  t.push("——红衣主教 本尼迪克特」");
  t.push("你握着羊皮纸，手在发抖。教会。是教会诱导霍夫曼打开了第一印。");
  t.push("这个牧师可能是良心发现，把密令藏了起来。但他没来得及说出去——他死在了地牢里。");
  return t;
},options:[
  {t:"带走密令，这是重要证据",go:"seal1_act3_pit",effect:{time:1,item:"教会密令",flag:"seal1_church_involved"}},
  {t:"记下内容，继续",go:"seal1_act3_pit",effect:{time:1,flag:"seal1_church_involved"}}
]}};

N["seal1_act2_spotted"]=function(){return{place:"铁门关",text:function(){
  var t=[];
  t.push("你试图潜入，但你的脚踩到了一块碎石。");
  t.push("声音在空旷的关隘里回荡。关隘最高处的那个『人形』动了。它转过头——你现在看清了，它没有脸。整个头部是一团旋转的黑雾。");
  t.push("它发出一声尖锐的嘶鸣。关隘里游荡的暗影生物全部转向了你。它们开始移动。速度不快，但方向明确——朝你过来。");
  t.push("你转身就跑。暗影生物在后面追，你能听到它们的脚步声——不是踩在地上的声音，是空间被吞噬的『嘶嘶』声。");
  t.push("你跑出关隘，滚下山坡，一直跑到那条小溪边才停下来。暗影生物没有追出来——它们似乎不能离开关隘太远。");
  t.push("你喘着气，回头看向铁门关。那个『人形』还站在最高处，面朝你的方向。它在等你回去。");
  return t;
},options:[
  {t:"等天黑，从侧面潜入",go:"seal1_act2_side_enter",effect:{time:4,flag:"seal1_spotted"}},
  {t:"先撤退，从长计议",go:"seal1_act4_retreat",effect:{time:1,flag:"seal1_spotted"}}
]}};

N["seal1_act2_side_enter"]=function(){return{place:"铁门关 · 侧门",text:function(){
  var t=[];
  t.push("你绕到关隘的侧面。这里有一个较小的门，是物资运输用的。门已经碎了，但位置隐蔽，从正面看不到。");
  t.push("你侧身挤进去。里面是一条走廊，通向仓库。走廊里很暗，你只能靠着墙壁慢慢移动。");
  t.push("走廊的墙上有抓痕。很深的抓痕，从天花板一直延伸到地面。像是有什么巨大的东西从这里经过。");
  t.push("你走到走廊尽头，推开仓库的门。仓库里堆满了物资——粮食、武器、药品。十年了，粮食早就烂了，但武器和药品还在。");
  t.push("你在仓库的角落里发现了一个通往地下的楼梯。楼梯口有一块牌子，上面写着：「封印维护通道——仅限守将及授权人员」。");
  return t;
},options:[
  {t:"走维护通道，直接到封印坑底部",check:{a:"AGI",sk:"stealth",label:"潜行"},go:"seal1_act3_pit",fail:"seal1_act2_maintenance_fail"},
  {t:"先在仓库里搜刮有用的东西",go:"seal1_act2_loot",effect:{time:1}},
  {t:"回到地面，从正面进去",go:"seal1_act2_arrive",effect:{time:1}}
]}};

N["seal1_act2_maintenance_fail"]=function(){return{place:"维护通道",text:function(){
  var t=[];
  t.push("你沿着维护通道向下走。楼梯很陡，而且年久失修，有几级已经碎了。你小心翼翼地移动，但还是踩空了一步。");
  t.push("你摔了下去，滚了十几级台阶，最后撞在一面墙上才停下来。你的膝盖磕破了，手臂也擦伤了。");
  t.push("更糟糕的是，你摔倒的声音在通道里回荡。你听到上方传来了脚步声——不是人的脚步声，是那种『嘶嘶』的、空间被吞噬的声音。");
  t.push("暗影生物发现你了。");
  t.push("你爬起来，一瘸一拐地向通道深处跑。身后的嘶嘶声越来越近。");
  return t;
},options:[
  {t:"加速跑，争取在被追上之前到达坑底",check:{a:"AGI",sk:"athletic",label:"运动"},go:"seal1_act3_pit",fail:"seal1_act3_caught"},
  {t:"找个地方躲起来",check:{a:"AGI",sk:"stealth",label:"潜行"},go:"seal1_act3_pit",fail:"seal1_act3_caught"}
]}};

N["seal1_act2_loot"]=function(){return{place:"仓库",text:function(){
  var t=[];
  t.push("你在仓库里翻找。粮食已经完全烂了，但你找到了一些还能用的东西：");
  t.push("· 三瓶治疗药剂（玻璃密封，还没过期）");
  t.push("· 一把完好的铁剑（虽然不是什么好货，但比没有强）");
  t.push("· 一个军用背包（里面有打火石、绳索、净水片）");
  t.push("· 一箱圣光手雷（教会的制式装备，对暗影生物有特效）");
  t.push("你把能用的都塞进背包。圣光手雷尤其珍贵——这东西在外面买不到。");
  t.push("然后你走向那个通往地下的楼梯。");
  return t;
},options:[
  {t:"走维护通道",go:"seal1_act3_pit",effect:{time:1,item:"治疗药剂x3",item2:"圣光手雷x5",item3:"军用背包"}}
]}};

N["seal1_act2_night"]=function(){return{place:"铁门关外 · 夜",text:function(){
  var t=[];
  t.push("你退到远处，等到天黑。");
  t.push("夜晚的铁门关更加恐怖。关隘里不时闪过暗红色的光，像是有什么东西在呼吸。暗影生物在夜里更加活跃——你能看到它们在城墙上游走，像是无数黑色的萤火虫。");
  t.push("但夜晚也有好处：暗影生物的视力在黑暗中反而变差（它们靠感知灵魂来定位）。如果你能压制自己的灵魂波动，就有可能潜行进去。");
  t.push("你闭上眼睛，调整呼吸，将灵魂波动降到最低。然后你站起来，向关隘走去。");
  return t;
},options:[
  {t:"灵魂潜行，从正面进去",check:{a:"SPR",sk:"soul",label:"灵魂感知"},go:"seal1_act2_arrive",fail:"seal1_act2_spotted"},
  {t:"从侧面的维护通道进去",go:"seal1_act2_side_enter",effect:{time:1}}
]}};

N["seal1_act2_arrested"]=function(){return{place:"北方公国哨卡",text:function(){
  var t=[];
  t.push("年轻军官一挥手，两个士兵上来把你按住。「间谍罪，带走。」");
  t.push("你被关进了哨卡的临时牢房。牢房很小，只有一张草席。军官告诉你，明天会把你押送到最近的城镇受审。");
  t.push("但你注意到，哨卡的士兵们很紧张。他们在低声交谈，时不时看向铁门关的方向。");
  t.push("半夜，你被尖叫声惊醒。哨卡外面传来了那种『嘶嘶』声——空间被吞噬的声音。士兵们在喊叫，然后声音一个接一个地消失。");
  t.push("牢房的门被撞开了。不是士兵——是暗影生物。它飘进牢房，看到了你。");
  return t;
},options:[
  {t:"用武器战斗",check:{a:"STR",sk:"martial",label:"武技"},go:"seal1_act2_escape_combat",fail:"seal1_act2_captured"},
  {t:"趁它不注意，从破掉的门跑出去",check:{a:"AGI",sk:"stealth",label:"潜行"},go:"seal1_act2_arrive",fail:"seal1_act2_captured"}
]}};

N["seal1_act2_escape_combat"]=function(){return{place:"哨卡",text:function(){
  var t=[];
  t.push("你抄起牢房里的铁凳，砸向暗影生物。它被砸中，发出一声嘶鸣，身体散成一团黑雾。");
  t.push("你冲出牢房。哨卡里一片混乱——暗影生物有四五只，正在吞噬剩下的士兵。你不敢恋战，翻过围栏，向铁门关方向跑去。");
  t.push("身后的嘶嘶声渐渐远了。暗影生物没有追你——它们有更『新鲜』的猎物。");
  t.push("你跑了大约一个小时，直到确认安全才停下来。你喘着气，回头看向哨卡的方向。那里已经没有声音了。");
  t.push("你活下来了。但那些士兵——他们没有。");
  return t;
},options:[
  {t:"继续前往铁门关",go:"seal1_act2_arrive",effect:{time:2,hp:-15,flag:"seal1_escaped_prison"}}
]}};

N["seal1_act2_captured"]=function(){return{place:"哨卡",text:function(){
  var t=[];
  t.push("你没能逃掉。暗影生物缠住了你，冰冷的触感从四肢蔓延开来。你感到自己的生命力在被抽走。");
  t.push("但就在你以为自己要被吞噬的时候，一道圣光从天而降。暗影生物发出一声尖叫，松开了你。");
  t.push("你抬头看到一个穿白袍的人站在哨卡门口。是教会的审判骑士。他手里握着一把发光的长剑，面无表情地看着你。");
  t.push("「你是谁？为什么会在这里？」他的声音冰冷。");
  t.push("你告诉他你在调查铁门关的真相。他沉默了一会儿，然后说：「跟我走。有些事情，你需要知道。」");
  return t;
},options:[
  {t:"跟他走",go:"seal1_act2_knight",effect:{time:1,hp:-20,sanLoss:5,flag:"seal1_knight_rescued"}},
  {t:"拒绝，自己去铁门关",go:"seal1_act2_arrive",effect:{time:1,hp:-20}}
]}};

N["seal1_act2_knight"]=function(){return{place:"哨卡 · 临时营地",text:function(){
  var t=[];
  t.push("审判骑士把你带到哨卡外面的一个临时营地。他自我介绍叫加百列，是教会审判骑士团的小队长。");
  t.push("「铁门关的事，教会知道。」他的语气很平淡，「十年前就知道。但我们选择了掩盖。」");
  t.push("「为什么？」");
  t.push("「因为真相会引发恐慌。」他看着你，「第一印下面压着的东西，如果让普通人知道了，整个大陆都会陷入混乱。人们会疯掉。」");
  t.push("「所以你们就让霍夫曼背锅？让他变成叛徒？」");
  t.push("加百列沉默了。「霍夫曼不是叛徒。他是——受害者。教会利用了他。但这件事不能公开。」");
  t.push("「你为什么要告诉我这些？」");
  t.push("「因为我老了。」他苦笑了一下，「我守了铁门关十年，看着暗影生物一天天变强。我知道，掩盖是没有用的。总有一天，需要有人去做些什么。」他看着你，「也许那个人是你。」");
  return t;
},options:[
  {t:"问他修复第一印的方法",go:"seal1_act3_pit",effect:{time:1,flag:"seal1_knight_ally",flag2:"seal1_church_involved"}},
  {t:"请他和你一起下坑",go:"seal1_act3_pit",effect:{time:1,flag:"seal1_knight_ally",flag2:"seal1_knight_joins"}}
]}};

/* ---- 第三幕：真相与抉择 ---- */
N["seal1_act3_pit"]=function(){return{entry:{from:{"seal1_act2_dungeon":["地窟里阴冷，湿气重，你出来的时候，衣服能拧出水。", "你在洞口站了一会儿，等眼睛适应了外面的光，才走向深坑。"],"seal1_act2_explore":["你把周围探了个遍，连犄角旮旯都没放过。该看的看了，不该看的也看了。", "现在，只剩深坑本身了。"],"seal1_act2_runes_fail":["符文的事，你没能解得开。那几笔线条在你脑子里转了好几天，还是连不成句子。", "你暂时放下了——深坑就在眼前，有些答案，不在纸上。"],"seal1_act2_runes":["你把那些符文看了个遍。有些认得，有些认不得——认得的那几个，让你后背发凉。", "你合上笔记，看向深坑入口。答案，应该就在底下。"]},default:[]},/*v46entry:s1pit_runes*/place:"铁门关 · 封印坑底部",text:function(){
  var t=[];
  t.push("你沿着维护通道向下走。楼梯很长，转了至少五个弯。空气越来越冷，那种『空腹感』越来越强。");
  t.push("终于，你到达了坑底。");
  t.push("坑底是一个巨大的洞穴。洞穴的中央有一块黑色的石头——不，不是石头。是一个『核心』。它有一人高，形状不规则，表面覆盖着无数张嘴的浮雕。那些嘴在微微开合，发出无声的尖叫。");
  t.push("核心周围是一圈符文——比地面上的更古老、更复杂。符文在缓慢地运转，将能量注入核心。但符文已经碎了大半，能量在大量泄漏。");
  t.push("你走近核心。你能感受到它的『饥饿』——那是一种纯粹的、没有任何感情的渴望。它不想毁灭世界，它只是——饿了。就像人需要呼吸一样，它需要吞噬。");
  t.push("核心突然亮了一下。一个声音在你脑子里响起：");
  t.push("「你……来了。」");
  return t;
},options:[
  {t:"和它对话",check:{a:"SPR",sk:"will",label:"意志"},go:"seal1_act3_talk",fail:"seal1_act3_madness"},
  {t:"检查核心周围的符文，寻找修复方法",check:{a:"INT",sk:"magic",label:"法术"},go:"seal1_act3_core_runes",fail:"seal1_act3_core_fail"},
  {t:"用圣光/魔法攻击核心",check:{a:"INT",sk:"magic",label:"法术"},go:"seal1_act3_attack",fail:"seal1_act3_attack_fail"}
]}};

N["seal1_act3_talk"]=function(){return{place:"封印坑底",text:function(){
  var t=[];
  t.push("你鼓起全部意志，回应那个声音：「你是谁？」");
  t.push("「我是……饥饿。原初的七分之一。」它的声音像是从很远的地方传来，又像是在你脑子里直接响起，「黄林晶……把我分成了七份。我在这里……睡了三千年。」");
  t.push("「霍夫曼打开了封印。你醒了。」");
  t.push("「他……不是故意的。他想救他的女儿。」饥饿的声音里居然有一丝——你不敢确定——同情，「他的女儿……身上有我的碎片。我能感受到她。她很痛苦。」");
  t.push("「你能治好她吗？」");
  t.push("「治好？」饥饿沉默了一会儿，「碎片……在她体内生长。如果取出来，她会死。如果不取出来，她会变成……新的门。」");
  t.push("「除非……你把碎片还给我。放回核心里。那样她就能活。但封印会重新运转——我会继续沉睡。」");
  t.push("你明白了。修复第一印的方法，就是把艾米丽体内的碎片取出来，放回核心。但这个过程需要艾米丽自愿——否则碎片会反抗。");
  return t;
},options:[
  {t:"答应它，会找到艾米丽并修复封印",go:"seal1_act3_choice",effect:{time:1,flag:"seal1_hunger_talked",flag2:"seal1_repair_method"}},
  {t:"问它有没有别的办法",go:"seal1_act3_choice",effect:{time:1,flag:"seal1_hunger_talked"}},
  {t:"拒绝和它合作，考虑破坏核心",go:"seal1_act3_choice",effect:{time:1,flag:"seal1_hunger_talked",flag2:"seal1_destroy_idea"}}
]}};

N["seal1_act3_madness"]=function(){return{place:"封印坑底",text:function(){
  var t=[];
  t.push("你试图回应那个声音，但你的意志不够强。饥饿的意念像洪水一样涌入你的大脑，你看到了——");
  t.push("你看到了宇宙的诞生。虚无中，第一个『洞』出现了。那就是饥饿。它不是被创造的，它是创造本身的副产品——有存在，就有不存在；有充盈，就有空洞。");
  t.push("你看到了黄林晶。三千年前，他站在这个洞穴里，面对完整的饥饿。他没有打赢它——他根本不可能打赢。他用了一个更聪明的办法：把饥饿分成七份，分别封印，然后喂养它们，让它们满足于小份的能量，不去吞噬整个世界。");
  t.push("你看到了无数个世界被饥饿吞噬。不是这个世界——是其他的。在黄林晶之前，饥饿已经吞噬了无数个世界。这个世界，是它的下一个目标。");
  t.push("你尖叫着切断了联系。你倒在地上，大口喘气，眼泪和鼻涕混在一起流下来。你的SAN值在剧烈下降。");
  t.push("但你也知道了真相。全部的真相。");
  return t;
},options:[
  {t:"爬起来，面对核心",go:"seal1_act3_choice",effect:{time:1,sanLoss:25,flag:"seal1_cosmic_truth",flag2:"seal1_hunger_talked"}},
  {t:"你需要休息。先离开坑底",go:"seal1_act4_retreat",effect:{time:1,sanLoss:25,flag:"seal1_cosmic_truth"}}
]}};

N["seal1_act3_core_runes"]=function(){return{place:"封印坑底",text:function(){
  var t=[];
  t.push("你蹲下来，仔细研究核心周围的符文。");
  t.push("这些符文比地面上的更复杂，分七层。你花了很长时间才辨认出每一层的功能：");
  t.push("第一层：定位——将核心固定在这个空间坐标。");
  t.push("第二层：分割——将核心与其他六份饥饿隔离。");
  t.push("第三层：压制——限制核心的活动范围。");
  t.push("第四层：喂养——持续注入能量，满足核心的基本需求。");
  t.push("第五层：伪装——让外界以为这是一个普通的封印。");
  t.push("第六层：预警——核心苏醒时自动通知守望者。");
  t.push("第七层：自毁——如果核心完全苏醒，引爆整个封印，将核心和周围一切一起湮灭。");
  t.push("你愣住了。第七层——自毁。黄林晶在每道印下面都装了自毁装置。如果封印完全失效，他宁可炸掉半个大陆，也不让饥饿完全苏醒。");
  t.push("现在，前六层已经失效或半失效。第七层还在——但它的倒计时已经开始了。按照符文的状态，你估计——最多还有五年。");
  return t;
},options:[
  {t:"五年内必须修复第一印。记下这个信息",go:"seal1_act3_choice",effect:{time:1,flag:"seal1_self_destruct",flag2:"seal1_five_years"}},
  {t:"尝试拆除第七层自毁装置",check:{a:"INT",sk:"magic",label:"法术"},go:"seal1_act3_disarm",fail:"seal1_act3_choice"}
]}};

N["seal1_act3_disarm"]=function(){return{place:"封印坑底",text:function(){
  var t=[];
  t.push("你试图拆除第七层自毁符文。你的手指刚碰到第一道符文，整个洞穴就开始震动。");
  t.push("核心发出一声尖锐的嘶鸣——它感觉到了你的意图。自毁符文开始加速运转，红光越来越亮。");
  t.push("你赶紧松手。震动慢慢平息了。但你注意到，自毁符文的倒计时加快了——从五年变成了四年。");
  t.push("你不能再碰它了。至少在找到正确的方法之前不能。");
  return t;
},options:[
  {t:"记下教训，面对核心",go:"seal1_act3_choice",effect:{time:1,flag:"seal1_disarm_failed",flag2:"seal1_four_years"}}
]}};

N["seal1_act3_core_fail"]=function(){return{place:"封印坑底",text:function(){
  var t=[];
  t.push("你试图解读符文，但它们太复杂了。你的魔法知识不足以理解黄林晶的封印体系。");
  t.push("但你注意到一个细节：核心表面的那些嘴，它们的开合频率在变化。有时候快，有时候慢。你观察了一会儿，发现了规律——");
  t.push("它们在『说话』。不是语言，是一种更古老的交流方式。嘴的开合频率对应着不同的意念。你虽然听不懂具体内容，但你能感受到大致的情绪：");
  t.push("饥饿。疲惫。还有一丝——孤独。");
  t.push("它被关在这里三千年了。只有它一个。");
  return t;
},options:[
  {t:"对它产生了一丝同情",go:"seal1_act3_choice",effect:{time:1,flag:"seal1_pity_hunger"}},
  {t:"压下情绪，继续想办法",go:"seal1_act3_choice",effect:{time:1}}
]}};

N["seal1_act3_attack"]=function(){return{place:"封印坑底",text:function(){
  var t=[];
  t.push("你聚集全部魔力，向核心发出一击。");
  t.push("圣光/火焰/奥术能量击中了核心。核心表面的那些嘴全部张开，发出一声——你听不到但能感受到的——尖叫。");
  t.push("你的攻击在核心表面留下了一道痕迹。但仅仅一秒钟，痕迹就消失了。核心在自我修复。");
  t.push("更糟糕的是，你的攻击激怒了它。核心开始剧烈震动，洞穴顶部的碎石纷纷落下。一股巨大的吸力从核心传来，你感到自己的生命力在被抽走。");
  t.push("你赶紧后退，切断了魔力输出。吸力慢慢减弱。");
  t.push("核心的声音在你脑子里响起，带着一丝——愤怒？「不要……打我。我……不想伤害你。但如果你再打我……我会……吃掉你。」");
  return t;
},options:[
  {t:"道歉，尝试和它沟通",go:"seal1_act3_talk",effect:{time:1,hp:-15,flag:"seal1_attacked_hunger"}},
  {t:"继续攻击，试试能不能毁掉它",check:{a:"INT",sk:"magic",label:"法术"},go:"seal1_act3_attack_more",fail:"seal1_act3_attack_fail"}
]}};

N["seal1_act3_attack_more"]=function(){return{place:"封印坑底",text:function(){
  var t=[];
  t.push("你再次聚集魔力，这次用了全力。");
  t.push("你的攻击比上一次强了数倍。核心表面的嘴全部张开，发出无声的尖叫。但这一次，核心没有自我修复——你的攻击在它表面留下了一道深深的裂痕。");
  t.push("从裂痕里，涌出了大量的黑色雾气。雾气在洞穴里凝聚，变成了——暗影生物。十只。二十只。五十只。");
  t.push("它们全部朝你扑过来。");
  t.push("你转身就跑。暗影生物在后面追，你能听到它们的嘶嘶声越来越近。你冲上维护通道，拼命往上爬。");
  t.push("你跑出关隘的时候，暗影生物没有追出来——它们不能离开核心太远。但你知道，你刚才的攻击让核心变得更加不稳定了。自毁倒计时又加快了。");
  return t;
},options:[
  {t:"先撤退，从长计议",go:"seal1_act4_retreat",effect:{time:1,hp:-30,sanLoss:10,flag:"seal1_made_worse",flag2:"seal1_three_years"}}
]}};

N["seal1_act3_attack_fail"]=function(){return{place:"封印坑底",text:function(){
  var t=[];
  t.push("你的第二次攻击没能奏效——核心在你聚集魔力的时候就开始了反击。");
  t.push("一股巨大的吸力将你拽向核心。你感到自己的身体在被拉伸，灵魂在被剥离。你看到了自己的手——它们开始变得透明，像是要被吸进核心里。");
  t.push("你用尽全部意志，切断了魔力输出，同时向后翻滚。吸力消失了。你摔在地上，大口喘气。你的手恢复了正常，但你感到一阵深深的疲惫——你的灵魂被『咬』了一口。");
  t.push("核心的声音响起：「我说过……不要打我。」");
  t.push("你不敢再攻击了。至少现在不敢。");
  return t;
},options:[
  {t:"尝试和它沟通",go:"seal1_act3_talk",effect:{time:1,hp:-25,sanLoss:15,flag:"seal1_attacked_hunger"}},
  {t:"撤退",go:"seal1_act4_retreat",effect:{time:1,hp:-25,sanLoss:15}}
]}};

N["seal1_act3_caught"]=function(){return{place:"维护通道",text:function(){
  var t=[];
  t.push("你被暗影生物追上了。它们缠住了你，冰冷的触感从四肢蔓延。你感到自己的生命力在快速流失。");
  t.push("但就在你以为自己要被吞噬的时候，一道圣光从上方射下来。暗影生物发出尖叫，松开了你。");
  t.push("你抬头看到加百列——那个审判骑士。他不知道什么时候跟了过来。他手里握着发光的长剑，一剑一个，将暗影生物全部驱散。");
  t.push("「你太鲁莽了。」他伸手把你拉起来，「下面是什么？」");
  t.push("你告诉他核心的事。他沉默了很久，然后说：「我守了十年，从来没有勇气下去。你比我勇敢。」");
  return t;
},options:[
  {t:"请他和你一起面对核心",go:"seal1_act3_pit",effect:{time:1,hp:-20,flag:"seal1_knight_joins"}},
  {t:"先撤退，疗伤",go:"seal1_act4_retreat",effect:{time:1,hp:-20,flag:"seal1_knight_ally"}}
]}};

N["seal1_act3_choice"]=function(){return{place:"封印坑底",text:function(){
  var t=[];
  t.push("你站在核心面前，思考着你的选择。");
  t.push("你已经知道了真相。第一印下面压着『饥饿』——原初之物的七分之一。它不是邪恶的，它只是饿了。黄林晶用七印把它分割、喂养，让它保持沉睡。");
  t.push("现在第一印碎了。饥饿在苏醒。五年后（或者更短），自毁装置会引爆，炸掉半个大陆。");
  t.push("你有三个选择：");
  t.push("【修复】找到艾米丽，取出她体内的碎片，放回核心，重新激活封印。饥饿继续沉睡，大陆安全。但艾米丽会失去碎片——她可能会死，或者变成一个普通人。");
  t.push("【破坏】彻底摧毁核心。饥饿的这一份会消失。但你不确定——摧毁一份饥饿，会不会让其他六份变得更强？而且摧毁核心的瞬间，释放的能量可能会炸掉整个北方。");
  t.push("【利用】和饥饿达成协议。你帮它找到更多『食物』，它帮你获得力量。这是最危险的选择——但也是最快获得力量的方式。");
  t.push("核心在等待你的回答。");
  return t;
},options:[
  {t:"选择修复——找到艾米丽，修复封印",go:"seal1_act4_repair",effect:{flag:"seal1_choice_repair"}},
  {t:"选择破坏——摧毁核心，一劳永逸",go:"seal1_act4_destroy",effect:{flag:"seal1_choice_destroy"}},
  {t:"选择利用——和饥饿达成协议",go:"seal1_act4_exploit",effect:{flag:"seal1_choice_exploit"}},
  {t:"暂时不做选择，先离开",go:"seal1_act4_retreat",effect:{flag:"seal1_choice_pending"}}
]}};

/* ---- 第四幕：后果与余波 ---- */
N["seal1_act4_repair"]=function(){return{place:"封印坑底",text:function(){
  var t=[];
  t.push("你对核心说：「我会修复封印。我会找到艾米丽，把碎片还给你。」");
  t.push("核心沉默了很久。然后它的声音响起，比之前温和了一些：「谢谢你。」");
  t.push("「但我有一个条件。」你说，「在我找到艾米丽之前，你不能再吞噬任何人。」");
  t.push("「我……尽量。」核心的声音有些犹豫，「饥饿……不是我能控制的。但我会……压制它。」");
  t.push("你感到核心的吸力减弱了一些。它在遵守诺言。");
  t.push("你离开坑底，走出关隘。阳光照在你脸上，你眯起眼睛。");
  t.push("你现在需要做的事：找到艾米丽·霍夫曼。她在教会手里。你需要去圣城一趟。");
  t.push("但在那之前，你需要变得更强。面对教会，你现在的力量还不够。");
  return t;
},options:[
  {t:"离开铁门关，返回交汇城",go:"seal1_act4_aftermath",effect:{time:5,flag:"seal1_repair_path"}},
  {t:"在离开前，再检查一下关隘有没有遗漏的线索",go:"seal1_act4_clue",effect:{time:1}}
]}};

N["seal1_act4_destroy"]=function(){return{place:"封印坑底",text:function(){
  var t=[];
  t.push("你对核心说：「我要摧毁你。」");
  t.push("核心表面的嘴全部停住了。然后它发出一声——你能感受到的——叹息。");
  t.push("「你……确定吗？摧毁我……释放的能量……会炸掉……整个北方。」");
  t.push("「我知道。」");
  t.push("「而且……其他六份……会感受到我的消失。它们会……变得更饿。」");
  t.push("你握紧了武器。「我知道。但我宁愿冒险，也不愿继续喂养一个随时会醒来的怪物。」");
  t.push("核心沉默了。然后它说：「那就……来吧。但我不会……束手就擒。」");
  t.push("核心开始剧烈震动。洞穴顶部的碎石大量落下。一股巨大的吸力从核心传来，整个洞穴都在被它吞噬。");
  t.push("你需要在被吞噬之前，找到摧毁它的方法。");
  return t;
},options:[
  {t:"用全部力量攻击核心的裂痕",check:{a:"INT",sk:"magic",label:"法术"},go:"seal1_act4_destroy_win",fail:"seal1_act4_destroy_fail"},
  {t:"触发第七层自毁符文，和它同归于尽",check:{a:"SPR",sk:"will",label:"意志"},go:"seal1_act4_self_destruct",fail:"seal1_act4_destroy_fail"},
  {t:"你犹豫了。撤退，再想想",go:"seal1_act4_retreat",effect:{time:1,flag:"seal1_destroy_hesitated"}}
]}};

N["seal1_act4_destroy_win"]=function(){return{place:"封印坑底",text:function(){
  var t=[];
  t.push("你聚集全部魔力，瞄准核心表面那道你之前留下的裂痕，发出了全力一击。");
  t.push("你的能量击中了裂痕。核心发出一声震耳欲聋的尖叫——这次你真的听到了，像是整个宇宙都在悲鸣。");
  t.push("裂痕开始扩大。核心表面的嘴一张一合，发出无声的哀嚎。黑色的雾气从裂痕里涌出，充满了整个洞穴。");
  t.push("你转身就跑。你冲上维护通道，拼命往上爬。身后传来越来越大的轰鸣声——核心在崩溃。");
  t.push("你跑出关隘的那一刻，身后传来了一声巨响。你被气浪掀飞，摔在地上。你回头看——");
  t.push("铁门关消失了。不是被炸毁，是被——吞噬了。核心崩溃时释放的能量将整座关隘、周围的山体、甚至天空都撕开了一个大洞。然后那个洞慢慢愈合，什么都没留下。");
  t.push("第一印。彻底消失了。");
  t.push("你躺在地上，大口喘气。你做到了。但你不知道，这是对是错。");
  return t;
},options:[
  {t:"检查周围的情况",go:"seal1_act4_aftermath",effect:{time:1,hp:-30,sanLoss:20,flag:"seal1_destroyed",flag2:"seal1_north_saved"}},
  {t:"你需要休息。先离开这里",go:"seal1_act4_aftermath",effect:{time:2,hp:-30,sanLoss:20,flag:"seal1_destroyed"}}
]}};

N["seal1_act4_destroy_fail"]=function(){return{place:"封印坑底",text:function(){
  var t=[];
  t.push("你的攻击没能摧毁核心。相反，核心的反击将你掀飞，撞在洞穴壁上。");
  t.push("你吐出一口血，肋骨断了至少两根。核心的吸力越来越强，你感到自己的身体在被拉向核心。");
  t.push("就在这时，一道圣光从上方射下。加百列——他跟了下来。他挡在你和核心之间，用圣光盾顶住了吸力。");
  t.push("「走！」他喊道，「我来挡住它！」");
  t.push("「你——」");
  t.push("「我守了十年，也该做个了断了。」他回头看了你一眼，笑了，「告诉世人真相。别让我的牺牲白费。」");
  t.push("他将全部圣光注入核心。核心发出一声尖叫，吸力暂时消失了。你趁机爬起来，冲上维护通道。");
  t.push("你跑出关隘的时候，身后传来了一声巨响。然后是——寂静。");
  t.push("加百列牺牲了自己，暂时压制了核心。但你知道，这只是暂时的。核心还会苏醒。");
  return t;
},options:[
  {t:"带着加百列的剑，离开铁门关",go:"seal1_act4_aftermath",effect:{time:1,hp:-40,sanLoss:15,item:"加百列的圣剑",flag:"seal1_gabriel_sacrificed",flag2:"seal1_destroy_failed"}},
  {t:"你不能让他白死。再试一次",go:"seal1_act4_destroy",effect:{time:1,hp:-40,sanLoss:15,flag:"seal1_gabriel_sacrificed"}}
]}};

N["seal1_act4_self_destruct"]=function(){return{place:"封印坑底",text:function(){
  var t=[];
  t.push("你将手放在第七层自毁符文上，注入全部魔力。");
  t.push("符文开始亮了。红光从你的手蔓延开，覆盖了整个符文圈。核心发出一声尖叫——它知道你要做什么。");
  t.push("「你……疯了……」");
  t.push("「也许吧。」你咬着牙，继续注入魔力，「但至少，你不会再吃人了。」");
  t.push("符文全部亮了。整个洞穴开始震动。你感到一股巨大的能量在符文下面聚集——那是黄林晶留下的、足以炸掉半个大陆的能量。");
  t.push("你闭上眼睛，等待终结。");
  t.push("但什么都没有发生。");
  t.push("你睁开眼。符文亮着，但没有爆炸。核心的声音响起，带着一丝——你不敢相信——笑意：「黄林晶……早就料到了。自毁符文……需要两个人的生命……才能触发。一个人……不行。」");
  t.push("你瘫倒在地。你连自杀式袭击都做不到。");
  return t;
},options:[
  {t:"撤退。你需要帮助",go:"seal1_act4_retreat",effect:{time:1,hp:-20,sanLoss:20,flag:"seal1_self_destruct_failed"}},
  {t:"再试一次攻击核心",go:"seal1_act4_destroy",effect:{time:1,hp:-20,sanLoss:20}}
]}};

N["seal1_act4_exploit"]=function(){return{place:"封印坑底",text:function(){
  var t=[];
  t.push("你深吸一口气，对核心说：「我想和你做个交易。」");
  t.push("核心的嘴全部转向你。「交易？」");
  t.push("「我帮你找到更多『食物』——那些该死的人、那些该被吞噬的灵魂。作为交换，你给我力量。」");
  t.push("核心沉默了很久。然后它的声音响起，带着一丝——兴趣：「你……愿意……喂养我？」");
  t.push("「不是喂养。是合作。你给我力量，我帮你找到你需要的东西。公平交易。」");
  t.push("核心表面的嘴开始一张一合，像是在思考。然后，一股黑色的能量从核心涌出，缠绕上你的手臂。");
  t.push("你感到一阵冰冷——然后是力量。巨大的、几乎要撑破你身体的力量。你的眼睛开始变黑，视野里的一切都蒙上了一层灰色。");
  t.push("「协议……达成。」核心的声音在你脑子里响起，「但记住……饥饿……永远不会满足。总有一天……你也会……成为我的食物。」");
  t.push("你抽回手。你的手臂上多了一道黑色的纹路——和老兵身上的蚀痕一样，但更粗、更深。");
  t.push("你获得了力量。但你也付出了代价。");
  return t;
},options:[
  {t:"带着力量离开",go:"seal1_act4_aftermath",effect:{time:1,skillUp:"magic",skillUp2:"martial",sanLoss:20,karma:-20,flag:"seal1_exploit_path",flag2:"seal1_hunger_pact",item:"饥饿印记"}},
  {t:"你后悔了。尝试切断联系",check:{a:"SPR",sk:"will",label:"意志"},go:"seal1_act4_regret",fail:"seal1_act4_aftermath"}
]}};

N["seal1_act4_regret"]=function(){return{place:"封印坑底",text:function(){
  var t=[];
  t.push("你试图切断和核心的联系。你聚集全部意志，对抗手臂上的黑色纹路。");
  t.push("纹路开始发烫。你感到一阵剧痛——像是有什么东西在你的灵魂里撕扯。核心的声音在你脑子里咆哮：「你……背叛我？」");
  t.push("「我没有背叛。我只是——不想被你控制。」");
  t.push("你和核心的力量对抗了整整十分钟。你的鼻子、耳朵、眼睛都开始流血。但你没有放弃。");
  t.push("终于，纹路暗淡了一些。联系没有完全切断——你不可能完全切断——但你重新获得了控制权。核心的声音变得遥远：「你会……后悔的。饥饿……永远在你体内。」");
  t.push("你瘫倒在地。你保留了一部分力量，也保留了一部分——自由。但你知道，这只是暂时的。总有一天，你需要做出最终的选择。");
  return t;
},options:[
  {t:"离开铁门关",go:"seal1_act4_aftermath",effect:{time:1,hp:-30,sanLoss:15,skillUp:"magic",flag:"seal1_partial_pact",flag2:"seal1_regret"}}
]}};

N["seal1_act4_retreat"]=function(){return{entry:{from:{"seal1_act2_painting":["墙上的画你还记得。画里那些人的表情，和刚才那个东西的眼神，是同一副。", "你把这个发现，记在了心里。有些画，不是画给人看的。"],"seal1_act3_attack":["你把那东西甩在了身后，但它一直追到洞口才停。你喘着气，回头看了一眼——洞口黑黢黢的，像一张没合上的嘴。", "你走了。你没有跑。你知道，跑，会让它记住你的味道。"],"seal1_act3_madness":["你从里面退出来的时候，手还在抖。不是怕——是你看见了不该看见的东西。", "你闭上眼睛，把它们压到记忆最深处，才继续走。"]},default:[]},/*v46entry:s1ret_painting+s1ret_madness*/place:"铁门关外",text:function(){
  var t=[];
  t.push("你离开了铁门关。");
  t.push("走出去很远，你才敢回头看。关隘还在那里，像一道伤疤刻在大地上。你知道，你还会回来的。在你变得更强之后。");
  t.push("你在附近的小溪边洗了把脸。水里的倒影让你愣了一下——你的眼睛里有一丝极淡的黑色。是核心留下的痕迹。");
  t.push("你揉了揉眼睛，黑色消失了。但你知道，它还在。");
  t.push("你整理了一下收集到的线索和物品。铁门关的真相，你已经知道了大半。剩下的，需要你去更多的地方寻找答案。");
  if(S.flags.seal1_choice_repair) t.push("· 你选择了修复之路。下一步：去圣城找艾米丽。");
  if(S.flags.seal1_choice_destroy) t.push("· 你选择了破坏之路。但你失败了（或者犹豫了）。你需要变得更强。");
  if(S.flags.seal1_choice_exploit) t.push("· 你和饥饿达成了协议。力量在你体内，但代价也在。");
  if(S.flags.seal1_destroyed) t.push("· 第一印已被摧毁。北方暂时安全了，但其他六印可能受到了影响。");
  t.push("");
  t.push("你骑上马（如果还在的话），向交汇城的方向走去。");
  return t;
},options:[
  {t:"返回交汇城，整理线索",go:"seal1_act4_aftermath",effect:{time:5}},
  {t:"不回交汇城，直接去下一个目的地",go:"seal1_transition",effect:{time:1}}
]}};

N["seal1_act4_clue"]=function(){return{place:"铁门关 · 将军府",text:function(){
  var t=[];
  t.push("你回到将军府，想再找找有没有遗漏的线索。");
  t.push("在霍夫曼的书房里，你发现了一个之前没注意到的暗格——在画像的后面。暗格里有一个小盒子，盒子里是一枚戒指。");
  t.push("戒指上刻着霍夫曼家族的纹章——一只鹰抓着一把剑。戒指内侧刻着一行字：「艾米丽，我的小星星。」");
  t.push("你把戒指戴在手上。戒指微微发热，然后你听到了一个声音——不是核心的声音，是一个小女孩的声音：");
  t.push("「爸爸？是你吗？」");
  t.push("你愣住了。这枚戒指是一个通讯器——霍夫曼用某种魔法把它和艾米丽的戒指连在了一起。十年了，她还在等他的电话。");
  t.push("「你是谁？」小女孩的声音带着警惕，「爸爸在哪里？」");
  return t;
},options:[
  {t:"告诉她你是谁，以及她爸爸的事",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal1_act4_emily_talk",fail:"seal1_act4_emily_scared"},
  {t:"不说话，先听她想说什么",go:"seal1_act4_emily_listen",effect:{time:1,item:"霍夫曼的戒指"}}
]}};

N["seal1_act4_emily_talk"]=function(){return{place:"将军府",text:function(){
  var t=[];
  t.push("你深吸一口气：「我不是你爸爸。我是一个……调查者。你爸爸十年前就——」");
  t.push("「我知道。」小女孩的声音很平静，平静得不像一个孩子，「教会的人告诉我了。他们说爸爸是叛徒。」");
  t.push("「他不是叛徒。他是为了救你。」");
  t.push("沉默了很久。然后艾米丽说：「我知道。我记得。我记得他打开门的那一刻，我记得他眼里的泪水。」她的声音开始发抖，「我也记得——门后面的东西。它现在还在我脑子里。每天晚上，它都在和我说话。」");
  t.push("「你在哪里？我来帮你。」");
  t.push("「圣城。圣光神学院的地下病房。教会的人说我在『治病』，但其实——他们在研究我。」她的声音突然压低，「你要来救我吗？」");
  return t;
},options:[
  {t:"答应她，一定会去救她",go:"seal1_act4_aftermath",effect:{time:1,item:"霍夫曼的戒指",flag:"seal1_emily_contacted",flag2:"seal1_emily_location"}},
  {t:"问她更多关于碎片的事",go:"seal1_act4_aftermath",effect:{time:1,item:"霍夫曼的戒指",flag:"seal1_emily_contacted",flag2:"seal1_emily_knowledge"}}
]}};

N["seal1_act4_emily_scared"]=function(){return{place:"将军府",text:function(){
  var t=[];
  t.push("你试图告诉她真相，但你的措辞不够谨慎。艾米丽听完后，沉默了很久。");
  t.push("「你是教会的人吗？」她的声音突然变得冰冷，「他们又派人来试探我了？」");
  t.push("「不是——」");
  t.push("「别骗我。上一个来『调查』的人，也是这么说的。然后他想给我打针。」她的声音开始发抖，「别来找我。我不想再被『研究』了。」");
  t.push("戒指的光芒暗了下去。通讯断了。");
  t.push("你握着戒指，叹了口气。你搞砸了。艾米丽对你产生了戒心。下次再联系她，需要更小心。");
  return t;
},options:[
  {t:"记下教训，离开铁门关",go:"seal1_act4_aftermath",effect:{time:1,item:"霍夫曼的戒指",flag:"seal1_emily_distrusts"}}
]}};

N["seal1_act4_emily_listen"]=function(){return{place:"将军府",text:function(){
  var t=[];
  t.push("你没有说话，只是静静地听着。");
  t.push("艾米丽等了一会儿，然后开始自言自语——她以为通讯断了，或者你已经走了。");
  t.push("「爸爸，我今天又做了那个梦。梦到门打开了，梦到那些影子。它们说我是『新的门』。」");
  t.push("「教会的人说我病了，但我知道我没病。我只是——能听到它。它每天都在叫我，让我『打开』。」");
  t.push("「我快撑不住了，爸爸。如果我真的打开了，你会怪我吗？」");
  t.push("她的声音越来越小，最后变成了啜泣。");
  t.push("你握着戒指，心里五味杂陈。这个女孩——她现在应该十八岁了。十年了，她一个人扛着这个秘密，扛着脑子里的那个声音。");
  t.push("你必须去救她。不是为了修复封印——是为了她。");
  return t;
},options:[
  {t:"下定决心，去圣城",go:"seal1_act4_aftermath",effect:{time:1,item:"霍夫曼的戒指",flag:"seal1_emily_resolve",flag2:"seal1_emily_location"}}
]}};

N["seal1_act4_aftermath"]=function(){return{place:"返回交汇城的路上",text:function(){
  var t=[];
  t.push("你踏上了归途。");
  t.push("路上，你遇到了一支向北行进的车队。是商队，运送粮食和药品去北方公国。商队队长告诉你，最近北方的难民越来越多——铁门关附近的村庄都空了，人们往南逃。");
  t.push("「听说那边闹瘟疫。」队长压低声音，「但我看不像瘟疫。瘟疫会死人流血，那边的人——是凭空消失的。」");
  t.push("你没有说话。你知道真相。但你不能说——至少现在不能。");
  t.push("五天后，你回到了交汇城。城市还是老样子，喧闹、拥挤、充满了烟火气。但你看它的眼光不一样了——你知道，在这座城市的北方，有一个东西正在苏醒。而这座城市的人，对此一无所知。");
  t.push("你回到酒馆。那个独臂老兵还在那里。他看到你，愣了一下，然后点了点头。");
  t.push("「你去了。」他说。不是问句。");
  t.push("「我去了。」");
  t.push("他推过来一杯酒。「喝吧。你需要它。」");
  return t;
},options:[
  {t:"和老兵聊聊你的发现",go:"seal1_act4_vet_return",effect:{time:1}},
  {t:"去找墨丘利，汇报你的发现",go:"seal1_act4_mercury_return",effect:{time:1}},
  {t:"先休息，整理一下思路",go:"seal1_transition",effect:{time:1}}
]}};

N["seal1_act4_vet_return"]=function(){return{place:"锈锚酒馆",text:function(){
  var t=[];
  t.push("你告诉老兵你在铁门关看到的一切。他静静地听着，一杯接一杯地喝酒。");
  t.push("等你说完，他沉默了很久。然后他说：「所以霍夫曼不是叛徒。」");
  t.push("「不是。他是为了救女儿。」");
  t.push("老兵笑了。笑得很苦。「十年了。我恨了他十年。我以为是他害死了我的兄弟们。」他举起独臂，「原来他也是受害者。」");
  t.push("「那你现在还恨他吗？」");
  t.push("他想了想。「不恨了。但我也不原谅他。」他喝了一口酒，「他打开门的时候，有没有想过我们这些士兵？有没有想过，我们会被影子吃掉？」");
  t.push("你没有回答。你也不知道答案。");
  t.push("老兵站起来，拍了拍你的肩膀。「你做了件好事。至少，真相被人知道了。」他走到门口，回过头，「如果你要去救那个女孩——算我一个。我这条命，本来就该留在铁门关的。」");
  return t;
},options:[
  {t:"答应他，一起去圣城",go:"seal1_transition",effect:{time:1,flag:"seal1_vet_joins",flag2:"seal1_vet_forgives"}},
  {t:"婉拒，你不想让他再冒险",go:"seal1_transition",effect:{time:1,flag:"seal1_vet_stays"}}
]}};

N["seal1_act4_mercury_return"]=function(){return{place:"墨丘利研究室",text:function(){
  var t=[];
  t.push("墨丘利看到你回来，并不惊讶。他给你倒了一杯茶，然后坐在你对面。");
  t.push("「你看到了。」他说。不是问句。");
  t.push("「我看到了。饥饿。原初之物。黄林晶的真相。」");
  t.push("墨丘利点点头。「你现在知道，为什么守望者存在了三千年。不是为了对抗深渊——是为了看着七印。确保它们不会碎。」");
  t.push("「但第一印还是碎了。」");
  t.push("「因为教会。」墨丘利的语气冷了下来，「本尼迪克特——那个红衣主教——他想利用饥饿的力量。他诱导霍夫曼打开封印，以为自己能控制它。他失败了。然后他掩盖了真相。」");
  t.push("「你早就知道？」");
  t.push("「我猜到了。但我没有证据。」墨丘利看着你，「现在你有证据了。教会密令、霍夫曼的笔记、老兵的证词——足够了。」");
  t.push("「那我们该怎么办？」");
  t.push("墨丘利站起来，走到窗边。「先救艾米丽。她是关键。然后——」他转过身，眼神锐利，「是时候让教会付出代价了。」");
  return t;
},options:[
  {t:"同意墨丘利的计划",go:"seal1_transition",effect:{time:1,flag:"seal1_mercury_plan",flag2:"seal1_church_evidence"}},
  {t:"问他守望者会不会介入",go:"seal1_transition",effect:{time:1,flag:"seal1_mercury_plan"}}
]}};

/* ---- 第一印过渡到第二印 ---- */
N["seal1_transition"]=function(){return{place:"交汇城",text:function(){
  var t=[];
  t.push("铁门关的事告一段落。但你知道，这只是开始。");
  t.push("七印。你只看了第一道。还有六道。每一道下面都压着一份原初之物。每一道都可能碎裂。");
  t.push("你站在交汇城的城墙上，看着北方。铁门关的方向。天空很蓝，什么都看不到。但你知道，在那片蓝天下面，有一个东西正在沉睡——或者说，正在苏醒。");
  t.push("你需要去更多的地方。兽人草原——第二印。精灵王国——第三印。矮人王国——第四印。南方深海——第五印。东部王国——第六印。死亡沙漠——第七印。");
  t.push("每一道印，都有它的故事。每一道印，都需要你去面对。");
  t.push("你深吸一口气，转身走下城墙。");
  t.push("你的旅程——才刚刚开始。");
  return t;
},options:[
  {t:"前往兽人草原（第二印）",go:"seal2_act1_intro",effect:{time:7}},
  {t:"先在交汇城休整，处理其他事务",go:"fc_jiaohui_entry",effect:{time:1}},
  {t:"查看你的线索和物品",go:"fc_jiaohui_entry",effect:{time:1}}
]}};

/* ================================================================
   第二印 · 兽人草原（松动）— 四幕完整章节
   ================================================================ */

/* ---- 第一幕：线索追寻 ---- */
N["seal2_act1_intro"]=function(){return{place:"兽人草原 · 边缘",where:"黄昏",text:function(){
  var t=[];
  t.push("草原的风是咸的。不是海水的咸，是——血的咸。");
  t.push("你站在兽人草原的边缘，看着一望无际的金色草海。夕阳把草尖染成了血红色，风吹过时，草浪翻滚，像是一片流动的血海。");
  t.push("你听说过兽人草原。这里是兽人的家园，部落林立，强者为王。但最近几年，草原上出了怪事——兽人部落开始统一。一个自称『大汗』的兽人，用了三年时间，统一了分散的部落。");
  t.push("有人说他是天才。有人说他被恶魔附身了。");
  t.push("你在边缘的一个小酒馆里停下。酒馆老板是个半兽人，他看了你一眼，语气不善：「人类？来草原干什么？这里不欢迎你们。」");
  return t;
},options:[
  {t:"说明你在调查七印的事",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal2_act1_tavern",fail:"seal2_act1_tavern_fail"},
  {t:"假装是商人，来做皮毛生意",check:{a:"CHA",sk:"trade",label:"商术"},go:"seal2_act1_merchant",fail:"seal2_act1_tavern_fail"},
  {t:"不说话，放下酒钱就走",go:"seal2_act1_alone",effect:{time:1}}
]}};

N["seal2_act1_tavern"]=function(){return{place:"边缘酒馆",text:function(){
  var t=[];
  t.push("半兽人老板的表情变了。他放下手里的酒杯，凑近你，压低声音：「你知道七印？」");
  t.push("「我知道一些。」");
  t.push("他环顾四周，确认没人注意，然后说：「跟我来。」");
  t.push("你跟着他走进酒馆后面的小屋。屋里很暗，只有一盏油灯。墙上挂着一张兽皮地图，地图上标着草原上的各个部落。");
  t.push("「我叫格鲁。」他说，「我父亲是萨满。十年前，他去了『圣山』，然后就没回来。」");
  t.push("「圣山？」");
  t.push("「兽人草原的中心。第二印的所在地。」格鲁的声音低沉，「萨满世代守护那道印。但最近——出事了。」");
  t.push("他指着地图上一个红色的标记：「大汗的部落就在圣山脚下。他统一草原之后，做的第一件事，就是封锁了圣山。任何人不得靠近。」");
  t.push("「你觉得他在做什么？」");
  t.push("格鲁沉默了一会儿。「我觉得他在——打开第二印。」");
  return t;
},options:[
  {t:"问他大汗是谁，为什么要打开第二印",go:"seal2_act1_khan_info",effect:{time:1,flag:"seal2_grub_ally"}},
  {t:"问他萨满守护第二印的具体方式",go:"seal2_act1_shaman_info",effect:{time:1,flag:"seal2_grub_ally"}},
  {t:"请他带你去圣山",go:"seal2_act1_guide",effect:{time:1,flag:"seal2_grub_ally"}}
]}};

N["seal2_act1_tavern_fail"]=function(){return{place:"边缘酒馆",text:function(){
  var t=[];
  t.push("半兽人老板冷笑一声：「人类都一个样。说谎都不会。」");
  t.push("他一拍桌子，酒馆里的几个兽人站了起来。他们的手都放在刀柄上。");
  t.push("「滚。」老板说，「下次再来，打断你的腿。」");
  t.push("你被推出了酒馆。草原的风吹在脸上，带着沙尘。");
  t.push("你需要换个方式进入草原。硬闯是不行的——兽人对人类的敌意很深。");
  return t;
},options:[
  {t:"在外面等，看看有没有商队可以混进去",go:"seal2_act1_caravan",effect:{time:2}},
  {t:"绕开酒馆，独自深入草原",go:"seal2_act1_alone",effect:{time:1,flag:"seal2_hostile_start"}}
]}};

N["seal2_act1_merchant"]=function(){return{place:"边缘酒馆",text:function(){
  var t=[];
  t.push("半兽人老板上下打量了你一番。「商人？」他哼了一声，「商人不会一个人来草原。商队至少有二十个护卫。」");
  t.push("「我是先遣。商队后面就到。」");
  t.push("他盯着你看了很久，然后突然笑了。「行吧。不管你是干什么的，只要付得起酒钱，就是客人。」");
  t.push("他给你倒了一杯酒。酒很烈，像是用某种草原植物酿的。");
  t.push("「不过我提醒你一句，」他压低声音，「最近草原不太平。大汗在征兵，所有成年兽人都要去圣山。人类在这个时候出现——很容易被当成探子。」");
  t.push("「大汗为什么征兵？」");
  t.push("老板耸耸肩。「谁知道呢。有人说他要打人类。有人说他在准备什么仪式。」他看了你一眼，「你要是真的商人，就赶紧做完生意走人。别往圣山方向去。」");
  return t;
},options:[
  {t:"打听更多关于大汗和圣山的消息",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal2_act1_khan_info",fail:"seal2_act1_alone"},
  {t:"假装买皮毛，打听商路",go:"seal2_act1_trade_route",effect:{time:1}},
  {t:"离开酒馆，独自深入草原",go:"seal2_act1_alone",effect:{time:1}}
]}};

N["seal2_act1_khan_info"]=function(){return{place:"边缘酒馆/小屋",text:function(){
  var t=[];
  t.push("「大汗叫铁木真。」格鲁（或老板）告诉你，「三年前，他还是一个小部落的首领。然后——他变了。」");
  t.push("「怎么变的？」");
  t.push("「他去了一趟圣山。回来之后，眼睛变成了金色。」他的声音压低，「然后他就开始打仗。每战必胜。他的战士像是不知道疼一样，砍断了胳膊还在往前冲。」");
  t.push("「有人说他和圣山里的『东西』做了交易。用兽人的灵魂，换力量。」");
  t.push("你想起了第一印的饥饿。原初之物的七分之一。如果第二印下面是另一份原初之物——比如『愤怒』或者『狂暴』——那铁木真的变化就说得通了。");
  t.push("「他统一草原之后，做了什么？」");
  t.push("「他把所有萨满都召集到圣山。然后——大部分萨满都死了。」格鲁的声音发抖，「包括我父亲。只有少数几个萨满活了下来，他们成了大汗的『国师』。」");
  t.push("「他在清除守护者。」你说。");
  t.push("格鲁点头。「他在为打开第二印做准备。」");
  return t;
},options:[
  {t:"问他第二印下面是什么",go:"seal2_act1_seal_truth",effect:{time:1,flag:"seal2_khan_known"}},
  {t:"问他怎么才能接近圣山",go:"seal2_act1_approach",effect:{time:1,flag:"seal2_khan_known"}},
  {t:"问他有没有幸存的萨满可以联系",go:"seal2_act1_survivor",effect:{time:1,flag:"seal2_khan_known"}}
]}};

N["seal2_act1_shaman_info"]=function(){return{place:"小屋",text:function(){
  var t=[];
  t.push("格鲁从箱子里翻出一本旧书。书是用兽皮做的，上面画满了奇怪的符号。");
  t.push("「这是我父亲的萨满笔记。」他说，「萨满守护第二印的方式，和其他印不一样。」");
  t.push("「怎么不一样？」");
  t.push("「第二印下面压着的是『愤怒』。原初之物的七分之一——纯粹的、没有理性的愤怒。它不像饥饿那样需要喂养，它需要——『冷却』。」");
  t.push("「冷却？」");
  t.push("「萨满用仪式，将草原上的『平和』注入封印，压制愤怒。每年春分，所有萨满聚集在圣山，举行『平息仪式』。仪式持续七天七夜，用歌声、舞蹈和草药，让愤怒继续沉睡。」");
  t.push("「但如果仪式中断——」");
  t.push("「愤怒就会苏醒。」格鲁的脸色苍白，「大汗杀了大部分萨满，就是为了让仪式无法举行。今年的春分，没有萨满举行仪式。第二印——已经开始松动了。」");
  t.push("你算了算日子。春分已经过去三个月了。第二印的松动，已经持续了三个月。");
  return t;
},options:[
  {t:"问他现在还能不能举行仪式",go:"seal2_act1_ritual",effect:{time:1,flag:"seal2_shaman_knowledge"}},
  {t:"问他愤怒苏醒会有什么后果",go:"seal2_act1_anger_consequence",effect:{time:1,flag:"seal2_shaman_knowledge"}},
  {t:"记下这些信息，准备去圣山",go:"seal2_act1_guide",effect:{time:1,flag:"seal2_shaman_knowledge"}}
]}};

N["seal2_act1_seal_truth"]=function(){return{place:"小屋",text:function(){
  var t=[];
  t.push("格鲁翻出一张古老的兽皮地图。地图上画着七道印的位置，每道印旁边都写着一个词。");
  t.push("「这是萨满世代相传的七印图。」他指着第二印的位置，「第二印——愤怒。」");
  t.push("「原初之物的七分之一。宇宙诞生时的第一个情绪。它没有理性，没有目的，只有纯粹的、毁灭一切的愤怒。」");
  t.push("「黄林晶把它分成七份，分别封印。第二印下面的这一份，是最暴烈的。如果它完全苏醒——」");
  t.push("「会怎样？」");
  t.push("格鲁深吸一口气。「所有靠近它的生物，都会被愤怒感染。变成没有理智的战争机器。兽人已经被感染了——你以为大汗为什么能统一草原？不是他的能力，是愤怒在扩散。草原上的兽人，已经有一半被愤怒影响了。他们变得好战、嗜血、不知疼痛。」");
  t.push("你想起了酒馆老板说的话——大汗的战士砍断了胳膊还在往前冲。那不是勇敢，是被愤怒控制了。");
  t.push("「如果第二印完全碎裂，愤怒会扩散到整个大陆。到那时候——所有生物都会变成战争机器。永无止境的战争，直到一切都被毁灭。」");
  return t;
},options:[
  {t:"问他修复第二印的方法",go:"seal2_act1_repair_method",effect:{time:1,sanLoss:5,flag:"seal2_anger_known"}},
  {t:"问他大汗的具体位置和兵力",go:"seal2_act1_khan_military",effect:{time:1,flag:"seal2_anger_known"}}
]}};

N["seal2_act1_ritual"]=function(){return{place:"小屋",text:function(){
  var t=[];
  t.push("「理论上可以。」格鲁翻着笔记，「但仪式需要至少七个萨满，同时在圣山的七个方位吟唱。现在——」");
  t.push("他苦笑了一下。「整个草原，活着的萨满不超过三个。还都被大汗控制了。」");
  t.push("「没有别的方法吗？」");
  t.push("「有。」他翻到笔记的最后一页，「黄林晶留下了一个『紧急仪式』。如果萨满不足，可以用一个『愤怒容器』来代替——一个自愿承载愤怒的人。他站在封印中心，用自己的身体作为导管，将愤怒重新导回封印。」");
  t.push("「但这个仪式的代价是——」他的声音低了下去，「容器会被愤怒吞噬。活下来的概率，不到一成。」");
  t.push("你沉默了。这和第一印的修复条件类似——都需要一个自愿的牺牲者。");
  t.push("「还有一个方法。」格鲁补充，「找到大汗，让他停止干扰。如果他能让幸存的萨满举行仪式，第二印就能重新稳定。但——他为什么要这么做？他从愤怒中获得了力量。」");
  return t;
},options:[
  {t:"问他大汗的弱点",go:"seal2_act1_khan_weakness",effect:{time:1,flag:"seal2_ritual_method"}},
  {t:"问他能不能找到幸存的萨满",go:"seal2_act1_survivor",effect:{time:1,flag:"seal2_ritual_method"}},
  {t:"你愿意成为容器（如果需要的话）",go:"seal2_act1_volunteer",effect:{time:1,flag:"seal2_ritual_method",flag2:"seal2_willing_vessel"}}
]}};

N["seal2_act1_guide"]=function(){return{place:"小屋",text:function(){
  var t=[];
  t.push("格鲁看着你，眼神复杂。「你真的要去圣山？」");
  t.push("「我必须去。第二印如果碎了，整个大陆都完了。」");
  t.push("他沉默了很久，然后站起来，从墙上取下一把刀。刀是用某种野兽的骨头做的，上面刻着萨满符文。");
  t.push("「这是我父亲的刀。」他说，「它能让你在草原上不被愤怒影响——至少，不那么容易被影响。」");
  t.push("他把刀递给你。「我不能陪你去。大汗的人认识我，我一靠近圣山就会被杀。但我可以告诉你路线。」");
  t.push("他在地图上画了一条线。「从这里出发，走三天，到『枯骨河』。过河之后，再走两天，就是圣山。但你要小心——枯骨河附近有大汗的巡逻队。」");
  t.push("「还有，」他压低声音，「草原上有一个『流浪者部落』。他们不服从大汗，躲在草原深处。如果你能找到他们，他们可能会帮你。他们的首领叫——白发婆婆。据说她是最老的萨满，已经活了两百岁了。」");
  return t;
},options:[
  {t:"按照格鲁的路线出发",go:"seal2_act2_journey",effect:{time:1,item:"萨满骨刀",flag:"seal2_grub_guide"}},
  {t:"先去找流浪者部落",go:"seal2_act1_wanderers",effect:{time:2,item:"萨满骨刀",flag:"seal2_grub_guide"}},
  {t:"问他更多关于白发婆婆的事",go:"seal2_act1_grandma",effect:{time:1,item:"萨满骨刀"}}
]}};

N["seal2_act1_wanderers"]=function(){return{place:"草原深处",text:function(){
  var t=[];
  t.push("你按照格鲁的提示，在草原深处寻找流浪者部落。");
  t.push("找了两天，你开始怀疑是不是被骗了。草原上除了草还是草，连个帐篷都看不到。");
  t.push("第三天傍晚，你在一个小湖边停下来喝水。水面倒映着夕阳，你看到了——倒影里，你身后站着一个人。");
  t.push("你猛地转身。一个老妇人站在那里，头发全白，脸上的皱纹像树皮一样深。她拄着一根木杖，正笑眯眯地看着你。");
  t.push("「人类。」她说，声音像是风吹过枯木，「你在找我？」");
  t.push("「你是——白发婆婆？」");
  t.push("她笑了。「别人都这么叫我。来吧，孩子。我的部落就在附近。」");
  t.push("她转身走向湖边的芦苇丛。你跟上去，发现芦苇丛后面有一个隐蔽的入口——通向地下。");
  return t;
},options:[
  {t:"跟着她下去",go:"seal2_act1_wanderer_camp",effect:{time:1}},
  {t:"警惕，先问她几个问题",check:{a:"INT",sk:"detect",label:"侦查"},go:"seal2_act1_wanderer_camp",fail:"seal2_act1_wanderer_trap"}
]}};

N["seal2_act1_wanderer_camp"]=function(){return{place:"流浪者部落 · 地下营地",text:function(){
  var t=[];
  t.push("地下营地比你想象的大。几十个帐篷分布在一个巨大的天然洞穴里，洞顶有裂缝透进光线。");
  t.push("部落里的人看到你，都露出了警惕的表情。但白发婆婆挥了挥手，他们就散开了。");
  t.push("「坐吧，孩子。」白发婆婆给你倒了一杯草药茶，「你从交汇城来？调查七印的？」");
  t.push("「你怎么知道？」");
  t.push("「风告诉我的。」她笑了，「草原上的风，什么都知道。」");
  t.push("她的表情突然严肃起来。「第二印的情况，比你想象的更糟。大汗不只是在干扰仪式——他在主动『喂养』愤怒。他每天都在圣山举行血祭，用战俘的血，让愤怒变得更强。」");
  t.push("「为什么？他疯了吗？」");
  t.push("「他没疯。」白发婆婆的声音很低，「他是被愤怒控制了。但他保留了一部分理智——他想用愤怒的力量，征服整个大陆。他以为自己能控制愤怒。但他不知道——当愤怒完全苏醒的那一刻，他会是第一个被吞噬的。」");
  return t;
},options:[
  {t:"问她有没有办法阻止大汗",go:"seal2_act1_stop_khan",effect:{time:1,flag:"seal2_grandma_ally"}},
  {t:"问她流浪者部落有多少战力",go:"seal2_act1_wanderer_power",effect:{time:1,flag:"seal2_grandma_ally"}},
  {t:"问她修复第二印的方法",go:"seal2_act1_repair_method",effect:{time:1,flag:"seal2_grandma_ally"}}
]}};

N["seal2_act1_wanderer_trap"]=function(){return{place:"湖边",text:function(){
  var t=[];
  t.push("你没有立刻跟她走，而是后退了一步，手放在武器上。");
  t.push("白发婆婆看着你，笑了。「警惕是好事。在草原上，不警惕的人活不长。」");
  t.push("她把木杖插在地上，举起双手。「我没有恶意。你看——」");
  t.push("她的手心里浮现出一个符号。是萨满的标记——和格鲁给你的骨刀上的符号一样。");
  t.push("「我是萨满。最后的萨满之一。」她说，「大汗杀了我的徒弟们，我带着幸存者躲在这里。如果你是来修复第二印的——我们是盟友。」");
  t.push("你放下了武器。");
  return t;
},options:[
  {t:"跟她去营地",go:"seal2_act1_wanderer_camp",effect:{time:1,flag:"seal2_cautious_bonus"}}
]}};

N["seal2_act1_stop_khan"]=function(){return{place:"地下营地",text:function(){
  var t=[];
  t.push("白发婆婆沉默了很久。然后她说：「有两个办法。」");
  t.push("「第一个，杀了他。但大汗被愤怒强化了，他的力量接近传奇境。普通的攻击对他无效。你需要找到他的『锚点』——他和愤怒连接的媒介。切断那个连接，他就会变回普通人。」");
  t.push("「锚点是什么？」");
  t.push("「他的王座。用圣山的石头做的，上面刻着愤怒的符文。他每天坐在上面，吸收愤怒的力量。毁掉王座，就能切断连接。」");
  t.push("「第二个办法呢？」");
  t.push("「唤醒他的人性。」白发婆婆的声音很轻，「大汗不是天生的坏人。三年前，他还是一个爱护部落的好首领。他去圣山，是为了救他的儿子——他儿子得了重病，他以为愤怒能治好他。」");
  t.push("「但愤怒没有治好他儿子。他儿子死了。然后大汗就——变了。」");
  t.push("「如果你能让他想起他是谁，让他主动放弃愤怒的力量——那比杀了他更好。因为杀了他，愤怒会找下一个宿主。但如果他主动放弃，愤怒就会失去方向，更容易被重新封印。」");
  return t;
},options:[
  {t:"选择刺杀路线——毁掉王座",go:"seal2_act1_assassin_plan",effect:{time:1,flag:"seal2_assassin_route"}},
  {t:"选择唤醒路线——找到他儿子的遗物",go:"seal2_act1_awaken_plan",effect:{time:1,flag:"seal2_awaken_route"}},
  {t:"两条路线都准备，随机应变",go:"seal2_act1_both_plan",effect:{time:1,flag:"seal2_both_routes"}}
]}};

N["seal2_act1_repair_method"]=function(){return{place:"地下营地/小屋",text:function(){
  var t=[];
  t.push("白发婆婆（或格鲁）告诉你修复第二印的方法：");
  t.push("「第二印的修复，和第一印不同。第一印需要把碎片放回核心，第二印需要——『平息』。」");
  t.push("「具体来说，需要三样东西：第一，七个萨满同时举行平息仪式。第二，一个自愿的『愤怒容器』，站在封印中心承受愤怒。第三——」");
  t.push("她顿了顿。「第三，大汗的同意。第二印的封印上，有黄林晶留下的一个『锁』。这个锁需要当时的守护者后裔的血脉才能打开。大汗是守护者的直系后裔——他的血脉，是打开封印的钥匙。」");
  t.push("「如果他不同意，你就无法进入封印核心，也就无法修复。」");
  t.push("你皱起眉头。「所以不管是杀了他还是唤醒他，最终都需要他的配合？」");
  t.push("「是的。」白发婆婆点头，「或者——你可以用他的血。只要有他的血，就能打开锁。但这需要你能伤到他。」");
  return t;
},options:[
  {t:"记下方法，准备去圣山",go:"seal2_act2_journey",effect:{time:1,flag:"seal2_repair_known"}},
  {t:"问他大汗的儿子葬在哪里",go:"seal2_act1_son_grave",effect:{time:1,flag:"seal2_repair_known"}}
]}};

N["seal2_act1_clue_gathered"]=function(){return{place:"草原边缘",text:function(){
  var t=[];
  t.push("你整理了一下收集到的信息。");
  if(S.flags.seal2_khan_known) t.push("· 大汗铁木真：三年前从圣山回来后变了，眼睛金色，被愤怒控制。");
  if(S.flags.seal2_anger_known) t.push("· 第二印下面是『愤怒』：纯粹的毁灭情绪，会感染周围生物变成战争机器。");
  if(S.flags.seal2_shaman_knowledge) t.push("· 萨满用『平息仪式』守护第二印，大汗杀了大部分萨满，仪式已中断三个月。");
  if(S.flags.seal2_ritual_method) t.push("· 修复方法：七萨满仪式+愤怒容器+大汗血脉/同意。");
  if(S.flags.seal2_grub_ally) t.push("· 格鲁：半兽人酒馆老板，萨满之子，给了你萨满骨刀和路线。");
  if(S.flags.seal2_grandma_ally) t.push("· 白发婆婆：最后的萨满，流浪者部落首领，知道大汗的过去。");
  if(S.flags.seal2_assassin_route) t.push("· 刺杀路线：毁掉大汗的愤怒王座，切断他和愤怒的连接。");
  if(S.flags.seal2_awaken_route) t.push("· 唤醒路线：找到大汗儿子的遗物，唤醒他的人性。");
  t.push("");
  t.push("圣山在草原中心。从这里出发，大约需要五天。路上有大汗的巡逻队。");
  return t;
},options:[
  {t:"出发前往圣山",go:"seal2_act2_journey",effect:{time:5}},
  {t:"先去找流浪者部落寻求帮助",go:"seal2_act1_wanderers",effect:{time:2}},
  {t:"再打听一下路上的情况",go:"seal2_act1_road_info",effect:{time:1}}
]}};

/* ---- 第二幕：抵达与探索 ---- */
N["seal2_act2_journey"]=function(){return{entry:{from:{"seal2_act1_wanderer":["那个独行者走得比你快，也比你安静。你们偶尔同行，偶尔分开。", "他教了你一些野外的东西，没说为什么。你没问。路上的人，各有各的不说的理由。"],"seal2_act1_volunteer":["是你自己要求跟上来的。路不好走，可你没后悔——你知道，有些门，只有自己推开，才叫自己的路。", "同行的人看你的眼神，从一开始的打量，慢慢变成点头。你记下了那几个点头的人。"],"seal2_act1_caravan":["商队的人待你不坏，但也仅止于此。几天的路，你把他们的底细摸了个大概——他们也在看你，各怀心思。", "夜里扎营的时候，你总把背靠向火堆。火光照不亮的地方，你睁着一只眼。"]},default:[]},/*v46entry:s2j_wanderer+s2j_volunteer+s2j_caravan*/place:"兽人草原 · 前往圣山",text:function(){
  var t=[];
  t.push("你深入草原。");
  t.push("第一天，一切正常。草海、蓝天、偶尔掠过的鹰。你甚至看到了一群野马在远处奔跑。");
  t.push("第二天，情况变了。草开始变黄——不是秋天的黄，是那种失去生机的枯黄。你看到了动物的尸体。不是被猎杀的，是——互相攻击致死的。两匹狼，咬断了彼此的喉咙。一群羚羊，用角互相刺穿。");
  t.push("愤怒在扩散。这些动物被影响了。");
  t.push("第三天，你遇到了巡逻队。五个兽人骑兵，正在草原上巡逻。他们的眼睛都是金色的——和大汗一样。");
  t.push("你蹲在草丛里，屏住呼吸。萨满骨刀在你怀里微微发热，帮你掩盖了人类的气息。");
  return t;
},options:[
  {t:"趁他们没发现，绕过去",check:{a:"AGI",sk:"stealth",label:"潜行"},go:"seal2_act2_arrive",fail:"seal2_act2_spotted"},
  {t:"主动出击，解决他们",check:{a:"STR",sk:"martial",label:"武技"},go:"seal2_act2_fight_patrol",fail:"seal2_act2_fight_fail"},
  {t:"等他们过去，然后跟踪他们找到圣山",check:{a:"AGI",sk:"stealth",label:"潜行"},go:"seal2_act2_track_patrol",fail:"seal2_act2_spotted"}
]}};

N["seal2_act2_spotted"]=function(){return{place:"草原",text:function(){
  var t=[];
  t.push("你被发现了。");
  t.push("一个兽人骑兵指向你，大喊了一声。五个骑兵同时转向，抽出弯刀，朝你冲过来。");
  t.push("他们的速度很快——比普通兽人快一倍。眼睛里的金色在阳光下闪烁，像是两团燃烧的火。");
  t.push("你转身就跑。但草原上没有遮蔽物，你跑不过骑兵。");
  t.push("就在他们要追上你的时候，地面突然震动。你脚下的草地裂开了一道缝——不是地震，是某种更大的东西在地下移动。");
  t.push("骑兵们勒住马，警惕地看着裂缝。然后，一只巨大的手从裂缝里伸出来——是土元素？不，是某种被愤怒唤醒的远古生物。");
  t.push("骑兵们被吸引了注意力，朝那个生物冲过去。你趁机跑掉了。");
  return t;
},options:[
  {t:"趁乱继续前往圣山",go:"seal2_act2_arrive",effect:{time:1,hp:-10,flag:"seal2_patrol_escape"}},
  {t:"躲起来，等战斗结束",go:"seal2_act2_hide",effect:{time:2,flag:"seal2_patrol_escape"}}
]}};

N["seal2_act2_fight_patrol"]=function(){return{place:"草原",text:function(){
  var t=[];
  t.push("你拔出武器，迎了上去。");
  t.push("第一个骑兵冲到你面前，弯刀带着风声劈下。你侧身躲过，反手一剑，刺中了他的腰侧。");
  t.push("但他没有倒下。他甚至没有皱眉——愤怒让他感觉不到疼痛。他继续挥刀，像是一台不知疲倦的机器。");
  t.push("你后退一步，重新评估形势。五个被愤怒强化的兽人骑兵，每一个都有接近化意境的战力。正面硬拼，你赢不了。");
  t.push("但你注意到了一个细节——他们的动作虽然快，但很僵硬。像是被线提着的木偶。愤怒给了他们力量，但也剥夺了他们的灵活性。");
  t.push("你利用这一点，游击作战。打一下，退一步，再打一下。十分钟后，五个骑兵全部倒下。不是被你杀死的——是他们自己的身体承受不住愤怒的强化，心脏爆裂而死。");
  t.push("你站在尸体中间，大口喘气。他们的眼睛还在发光，金色的光芒慢慢暗淡下去。");
  return t;
},options:[
  {t:"检查尸体，找有用的东西",go:"seal2_act2_loot",effect:{time:1,hp:-15,flag:"seal2_patrol_killed"}},
  {t:"不检查了，赶紧走",go:"seal2_act2_arrive",effect:{time:1,hp:-15}}
]}};

N["seal2_act2_fight_fail"]=function(){return{place:"草原",text:function(){
  var t=[];
  t.push("你低估了他们。");
  t.push("第一个骑兵的弯刀劈中了你的肩膀。你感到一阵剧痛，然后是——愤怒。不是你的愤怒，是他的。通过武器，他的愤怒在传染给你。");
  t.push("你感到自己的心跳在加速，视野在变红。你想杀人——不是为了自卫，是纯粹的、没有理由的杀戮欲望。");
  t.push("你咬着舌头，用疼痛保持清醒，然后转身就跑。");
  t.push("你跑了很久，直到确认他们没有追上来。你跪在地上，大口喘气。肩膀的伤口在流血，但更可怕的是——你心里的那股杀意还在。");
  t.push("萨满骨刀发出微光，那股杀意慢慢消退了。");
  t.push("你差点被愤怒感染。");
  return t;
},options:[
  {t:"处理伤口，继续前进",go:"seal2_act2_arrive",effect:{time:2,hp:-25,sanLoss:5,flag:"seal2_anger_infected"}},
  {t:"先休息，稳定情绪",go:"seal2_act2_rest",effect:{time:1,hp:-25,sanLoss:5}}
]}};

N["seal2_act2_track_patrol"]=function(){return{place:"草原",text:function(){
  var t=[];
  t.push("你远远地跟着巡逻队。他们走的路线很规律——沿着一条看不见的边界，来回巡逻。");
  t.push("跟了半天，你发现了规律：他们在守卫一条通往圣山的『圣道』。圣道上没有草，地面是暗红色的——被血浸透的。");
  t.push("你沿着圣道的方向望去，远处的地平线上，出现了一座山。");
  t.push("圣山。");
  t.push("它不像普通的山。它是黑色的，山顶有一根巨大的石柱，直插云霄。石柱上缠绕着红色的光芒——那是愤怒的能量。");
  t.push("山脚下，你看到了帐篷。成千上万个帐篷。大汗的军队驻扎在那里。");
  t.push("你数了数——至少有五万兽人。");
  return t;
},options:[
  {t:"从侧面绕过去，避开大军",go:"seal2_act2_side_approach",effect:{time:2,flag:"seal2_army_size"}},
  {t:"先观察，找破绽",check:{a:"INT",sk:"detect",label:"侦查"},go:"seal2_act2_observe_camp",fail:"seal2_act2_side_approach"},
  {t:"混进后勤队伍里",check:{a:"AGI",sk:"stealth",label:"潜行"},go:"seal2_act2_infiltrate",fail:"seal2_act2_spotted"}
]}};

N["seal2_act2_arrive"]=function(){return{place:"圣山脚下",text:function(){
  var t=[];
  t.push("你到达了圣山脚下。");
  t.push("近距离看，圣山比你想象的更壮观。它不是天然形成的山——它是一个巨大的封印构造。山体是黑色的岩石，上面刻满了符文。那些符文在缓慢地闪烁，红色的光芒沿着符文流动，像是血管里的血。");
  t.push("山顶的石柱有百米高，上面刻着一个巨大的符号——你认出了，那是黄林晶的封印标记。");
  t.push("山脚下是大汗的营地。五万兽人，密密麻麻的帐篷。营地中央是一个巨大的王座——用圣山的石头做的，上面刻着愤怒的符文。王座上空无一人——大汗应该在山上。");
  t.push("你注意到，营地的一角有一个『祭坛』。祭坛上绑着几个人类战俘——他们是血祭的祭品。他们的血顺着祭坛的沟槽流下，汇入一条通向山顶的管道。");
  t.push("大汗在用战俘的血，喂养愤怒。");
  return t;
},options:[
  {t:"先救那些战俘",check:{a:"AGI",sk:"stealth",label:"潜行"},go:"seal2_act2_rescue",fail:"seal2_act2_rescue_fail"},
  {t:"先毁掉王座",check:{a:"INT",sk:"magic",label:"法术"},go:"seal2_act2_throne",fail:"seal2_act2_throne_fail"},
  {t:"直接上山，找大汗",go:"seal2_act2_climb",effect:{time:1}}
]}};

N["seal2_act2_loot"]=function(){return{place:"草原",text:function(){
  var t=[];
  t.push("你检查了骑兵的尸体。");
  t.push("他们身上没有多少钱——兽人不怎么用人类的货币。但你找到了一些有用的东西：");
  t.push("· 一块令牌：大汗巡逻队的身份证明。有了这个，你可以在一定程度上混入营地。");
  t.push("· 一张地图：圣山周边的布防图。标注了巡逻路线、哨塔位置、以及——一条秘密通道。");
  t.push("· 一瓶药剂：红色的液体，闻起来有血腥味。这应该是『愤怒药剂』——大汗的军队用这个来临时提升战斗力，但副作用是加速愤怒感染。");
  t.push("你把东西收好。令牌和地图尤其有用。");
  return t;
},options:[
  {t:"用令牌混进营地",go:"seal2_act2_infiltrate",effect:{time:1,item:"巡逻令牌",item2:"圣山布防图",item3:"愤怒药剂"}},
  {t:"从秘密通道上山",go:"seal2_act2_secret_path",effect:{time:1,item:"巡逻令牌",item2:"圣山布防图"}}
]}};

N["seal2_act2_observe_camp"]=function(){return{place:"圣山附近",text:function(){
  var t=[];
  t.push("你在远处观察了很久，找到了几个破绽：");
  t.push("第一，营地的防守有盲区。东侧是一片沼泽，兽人不喜欢潮湿，那里只有两个哨兵。");
  t.push("第二，换班时间是黄昏和黎明。换班的时候有大约十分钟的空档，大部分守卫都在交接。");
  t.push("第三，大汗每天傍晚会在王座上坐一个小时，接受血祭。那个时候他的注意力全在仪式上，是潜入的最好时机。");
  t.push("第四，你注意到营地西侧有一个『伤员帐篷』。被愤怒感染过度的兽人会被送到那里——他们已经失去了利用价值，被丢弃等死。那个帐篷守卫很少。");
  t.push("你把这些信息记在心里。");
  return t;
},options:[
  {t:"黄昏换班时，从东侧沼泽潜入",go:"seal2_act2_infiltrate",effect:{time:3,flag:"seal2_camp_intel"}},
  {t:"假装伤员，混入西侧帐篷",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal2_act2_injured_tent",fail:"seal2_act2_spotted"},
  {t:"直接上山，避开营地",go:"seal2_act2_climb",effect:{time:1,flag:"seal2_camp_intel"}}
]}};

N["seal2_act2_infiltrate"]=function(){return{place:"大汗营地",text:function(){
  var t=[];
  t.push("你混进了营地。");
  t.push("如果你有巡逻令牌，你就大摇大摆地走进去，守卫只是看了你一眼就放行了。如果没有，你就趁着黄昏换班的空档，从东侧沼泽溜了进去。");
  t.push("营地内部比外面看起来更混乱。兽人们在喝酒、打架、磨刀。空气中弥漫着血腥味和酒味。你注意到，几乎所有兽人的眼睛都是金色的——愤怒已经感染了整支军队。");
  t.push("你低着头，快步穿过营地。目标很明确——上山。");
  t.push("但在经过中央广场的时候，你停住了。");
  t.push("王座上坐着一个人。不，不是人——是一个被愤怒撑大的兽人。他有三米高，肌肉虬结，皮肤是暗红色的。眼睛里的金色像是两团燃烧的太阳。");
  t.push("大汗。铁木真。");
  t.push("他正在举行血祭。祭坛上的战俘被割开喉咙，血顺着沟槽流下，汇入王座。他闭上眼睛，享受地吸了一口气——像是在品尝鲜血的味道。");
  t.push("你感到一阵恶心。");
  return t;
},options:[
  {t:"趁他专注仪式，偷偷上山",check:{a:"AGI",sk:"stealth",label:"潜行"},go:"seal2_act2_climb",fail:"seal2_act2_khan_notice"},
  {t:"观察他的弱点",check:{a:"INT",sk:"detect",label:"侦查"},go:"seal2_act2_khan_weakness",fail:"seal2_act2_climb"},
  {t:"先去救祭坛上的战俘",go:"seal2_act2_rescue",effect:{time:1}}
]}};

N["seal2_act2_climb"]=function(){return{place:"圣山 · 上山路上",text:function(){
  var t=[];
  t.push("你开始爬山。");
  t.push("圣山的山路很陡，而且——它是活的。你每走一步，都能感受到山体在震动。不是地震，是某种巨大的心跳。第二印的核心在跳动。");
  t.push("符文在你脚下闪烁。红色的光芒沿着山路蔓延，像是在警告你：回去。");
  t.push("你继续往上走。萨满骨刀在你怀里发热，帮你抵抗着愤怒的侵蚀。但你还是能感受到——心里的杀意在一点点增强。你想破坏，想杀戮，想——");
  t.push("你摇摇头，把这些念头压下去。");
  t.push("爬到半山腰，你看到了一个山洞。洞口有萨满的标记。这应该是守护者的居所。");
  t.push("山洞里传来了声音——不是人声，是某种低沉的吟唱。");
  return t;
},options:[
  {t:"走进山洞",check:{a:"SPR",sk:"will",label:"意志"},go:"seal2_act2_cave",fail:"seal2_act2_cave_fail"},
  {t:"不进去，继续爬山",go:"seal2_act2_summit",effect:{time:1,sanLoss:5}},
  {t:"在洞口听一会儿",go:"seal2_act2_listen",effect:{time:1}}
]}};

N["seal2_act2_cave"]=function(){return{place:"圣山 · 萨满洞穴",text:function(){
  var t=[];
  t.push("你走进山洞。");
  t.push("洞里很暗，但墙壁上的符文发出微弱的红光，照亮了周围。洞的深处，有一个老人坐在那里。他穿着萨满的法袍，正在吟唱。");
  t.push("他听到你的脚步声，停了下来。「人类？」他的声音很虚弱，「你怎么上来的？」");
  t.push("「我是来修复第二印的。」");
  t.push("老人苦笑了一下。「修复？太晚了。」他指了指自己的腿——他的双腿已经变成了石头。「愤怒在吞噬我。我是最后的守护者之一。三个月前，大汗杀了其他萨满，我躲在这里，用最后的力量维持着封印的最后一层。」");
  t.push("「但我撑不了多久了。」他看着你，「你既然来了——就替我完成最后的任务吧。」");
  t.push("他从怀里掏出一个头骨。头骨上刻满了符文。「这是『平息之颅』——第一代萨满的头骨。它能暂时压制愤怒，给你争取时间。带着它，去山顶。」");
  t.push("「山顶有什么？」");
  t.push("「第二印的核心。还有——大汗。他在那里。」");
  return t;
},options:[
  {t:"接过头骨，问他更多关于大汗的事",go:"seal2_act2_old_shaman",effect:{time:1,item:"平息之颅",flag:"seal2_old_shaman"}},
  {t:"带他一起走",check:{a:"STR",sk:"athletic",label:"运动"},go:"seal2_act2_carry_shaman",fail:"seal2_act2_summit"},
  {t:"接过头骨，继续上山",go:"seal2_act2_summit",effect:{time:1,item:"平息之颅"}}
]}};

N["seal2_act2_old_shaman"]=function(){return{place:"萨满洞穴",text:function(){
  var t=[];
  t.push("老人告诉你关于大汗的真相。");
  t.push("「铁木真不是坏人。三年前，他的儿子得了一种怪病——身体会自己燃烧。所有萨满都治不好。」");
  t.push("「他听说圣山里的『愤怒』能赐予力量，就偷偷上了山。他以为愤怒能治好他儿子。但愤怒没有——它只是给了他力量，然后吞噬了他的理智。」");
  t.push("「他儿子死了。从那以后，他就变了。他不再是铁木真——他是愤怒的容器。」");
  t.push("「但他心底还保留着一样东西。」老人从怀里掏出一个小包裹，「这是他儿子的玩具——一个木雕的小马。他儿子生前最喜欢的东西。我一直留着。」");
  t.push("「如果你能让他看到这个——也许，能唤醒他最后一点人性。」");
  t.push("你接过木雕小马。它很粗糙，明显是一个父亲亲手刻的。");
  return t;
},options:[
  {t:"带着木雕小马上山",go:"seal2_act2_summit",effect:{time:1,item:"平息之颅",item2:"木雕小马",flag:"seal2_awaken_item"}},
  {t:"问他有没有别的办法",go:"seal2_act2_summit",effect:{time:1,item:"平息之颅",item2:"木雕小马"}}
]}};

N["seal2_act2_summit"]=function(){return{place:"圣山 · 山顶",text:function(){
  var t=[];
  t.push("你到达了山顶。");
  t.push("山顶是一个巨大的平台。平台中央是第二印的核心——一个红色的漩涡，在空中缓慢旋转。漩涡里，你能看到无数张脸——都是被愤怒吞噬的人的脸。他们在尖叫，在咆哮，在——笑。");
  t.push("漩涡前面，站着一个人。");
  t.push("大汗。铁木真。");
  t.push("他比你在营地看到的更高大。三米半的身高，皮肤是暗红色的，血管在皮肤下面跳动，像是有岩浆在流动。他的眼睛——你不敢直视。那不是金色了，是纯粹的红。");
  t.push("他转过身，看到了你。");
  t.push("「人类。」他的声音像是雷鸣，「你居然能爬到这里。不错。」");
  t.push("他举起手。红色的能量在他掌心聚集。「但你不该来。这里——是我的圣地。」");
  return t;
},options:[
  {t:"和他对话，尝试唤醒他的人性",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal2_act3_talk",fail:"seal2_act3_combat"},
  {t:"用平息之颅压制愤怒，趁机攻击",check:{a:"SPR",sk:"will",label:"意志"},go:"seal2_act3_skull_attack",fail:"seal2_act3_combat"},
  {t:"直接攻击",check:{a:"STR",sk:"martial",label:"武技"},go:"seal2_act3_combat",fail:"seal2_act3_combat_fail"}
]}};

/* ---- 第三幕：真相与抉择 ---- */
N["seal2_act3_talk"]=function(){return{place:"圣山山顶",text:function(){
  var t=[];
  t.push("你没有拔出武器。你举起双手，示意自己没有敌意。");
  t.push("「铁木真。我知道你是谁。我知道你儿子的事。」");
  t.push("他的动作停了一下。只是一下，但你捕捉到了。");
  t.push("「你知道什么？」他的声音低沉，带着压抑的怒火。");
  t.push("「我知道他叫什么。我知道你给他刻了一个木雕小马。我知道——你不是天生的怪物。」");
  t.push("他咆哮了一声。红色的能量从他身上爆发，吹得你几乎站不稳。「闭嘴！你什么都不知道！」");
  t.push("但你注意到——他的眼睛里，红色的深处，有一丝金色。那是他本来的颜色。人性还在。");
  if(S.flags.seal2_awaken_item) {
    t.push("你从怀里掏出木雕小马，举到他面前。「这是你儿子的。对吗？」");
    t.push("他看到木雕的一瞬间，全身都僵住了。红色的能量开始不稳定地闪烁。「你……你从哪里得到的？」");
    t.push("「一个老萨满给我的。他说，这是你儿子最喜欢的东西。」");
    t.push("大汗的手在发抖。他伸出手，想要接过木雕——但又缩了回去，像是怕被烫到。「别给我……我……我会把它捏碎的……」");
  }
  return t;
},options:[
  {t:"继续劝说，让他想起自己是谁",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal2_act3_awaken",fail:"seal2_act3_combat"},
  {t:"趁他动摇，用平息之颅压制愤怒",check:{a:"SPR",sk:"will",label:"意志"},go:"seal2_act3_skull_attack",fail:"seal2_act3_combat"},
  {t:"问他为什么要打开第二印",go:"seal2_act3_why",effect:{time:1}}
]}};

N["seal2_act3_awaken"]=function(){return{place:"圣山山顶",text:function(){
  var t=[];
  t.push("你一步一步走近他。每走一步，你都能感受到愤怒的灼烧——像是有无数根针在扎你的灵魂。");
  t.push("「铁木真。你儿子叫什么名字？」");
  t.push("「……巴图。」他的声音在发抖，「他叫巴图。他五岁，最喜欢骑马。他说他长大了要像爸爸一样，成为最强的战士。」");
  t.push("「他会为你现在的样子骄傲吗？」");
  t.push("大汗猛地抬头。他的眼睛里，红色在消退，金色在回来。他的身体在缩小——从三米半缩到三米，再到两米五。愤怒在离开他。");
  t.push("「我……我做了什么……」他跪在地上，双手抱头。「我杀了多少人……我……」");
  t.push("红色的漩涡开始不稳定。愤怒失去了宿主，开始狂暴。整个山顶都在震动。");
  t.push("「封印要失控了！」老萨满的声音从你怀里的平息之颅里传出，「快——用平息之颅，举行仪式！」");
  return t;
},options:[
  {t:"用平息之颅举行平息仪式",check:{a:"SPR",sk:"will",label:"意志"},go:"seal2_act3_ritual",fail:"seal2_act3_ritual_fail"},
  {t:"让铁木真帮忙——他是守护者后裔",go:"seal2_act3_khan_help",effect:{time:1,flag:"seal2_khan_awaken"}},
  {t:"你成为愤怒容器，承受愤怒",go:"seal2_act3_vessel",effect:{time:1,flag:"seal2_khan_awaken"}}
]}};

N["seal2_act3_why"]=function(){return{place:"圣山山顶",text:function(){
  var t=[];
  t.push("「为什么？」大汗笑了。笑声里充满了痛苦。「因为这个世界不公平。」");
  t.push("「我儿子病了。我求遍了所有萨满，所有牧师，所有法师。他们都说——治不好。」");
  t.push("「然后我听说了圣山里的东西。它说它能治好我儿子。它说——只要我打开封印，它就给我力量，给我治愈一切的能力。」");
  t.push("「我信了。我打开了封印。然后——它吞噬了我。我儿子还是死了。而我——变成了这个东西。」");
  t.push("他指着红色的漩涡。「既然它骗了我，那我就用它的力量，毁灭这个不公平的世界。让所有人都尝尝——失去一切的滋味。」");
  t.push("你看着他。他的愤怒是真实的。他的痛苦也是真实的。但他的方法——是错的。");
  return t;
},options:[
  {t:"理解他的痛苦，但告诉他这样做不对",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal2_act3_awaken",fail:"seal2_act3_combat"},
  {t:"不再废话，准备战斗",go:"seal2_act3_combat",effect:{time:1}}
]}};

N["seal2_act3_skull_attack"]=function(){return{place:"圣山山顶",text:function(){
  var t=[];
  t.push("你举起平息之颅。头骨上的符文亮了起来，白色的光芒从骷髅的眼窝里射出，照向大汗。");
  t.push("白色光芒碰到大汗的一瞬间，他发出了一声痛苦的咆哮。红色的能量从他身上被剥离，像是被剥皮一样。");
  t.push("「你——！」他愤怒地朝你冲过来。但平息之颅的光芒形成了一道屏障，挡住了他。");
  t.push("你感到一阵虚弱。平息之颅在消耗你的灵魂力量——它是用第一代萨满的灵魂驱动的，而你在替它供能。");
  t.push("大汗在屏障外面疯狂地攻击，每一击都让地面震动。屏障在变薄。你撑不了多久。");
  t.push("但你注意到——在白色光芒的照射下，大汗的身体在缩小。愤怒在被剥离。他的眼睛从红色变回金色，再变回——棕色。普通兽人的棕色。");
  t.push("他快恢复了。再坚持一会儿。");
  return t;
},options:[
  {t:"坚持住，直到愤怒被完全剥离",check:{a:"SPR",sk:"will",label:"意志"},go:"seal2_act3_awaken",fail:"seal2_act3_skull_fail"},
  {t:"一边维持屏障，一边和他说话",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal2_act3_awaken",fail:"seal2_act3_combat"}
]}};

N["seal2_act3_skull_fail"]=function(){return{place:"圣山山顶",text:function(){
  var t=[];
  t.push("你撑不住了。");
  t.push("平息之颅的光芒暗了下去。屏障碎裂。大汗一拳砸在你胸口，你像断线的风筝一样飞了出去，撞在山顶的石柱上。");
  t.push("你吐出一口血。肋骨断了至少三根。");
  t.push("但你不是没有收获——大汗的愤怒被剥离了大半。他现在只有两米高，眼睛是金色的。他还在愤怒，但已经不是之前那个不可阻挡的怪物了。");
  t.push("「你……」他看着自己的手，像是在确认什么。然后他抬头看你，眼神复杂。「你为什么不杀我？」");
  t.push("「因为你不是敌人。愤怒才是。」");
  t.push("他沉默了。红色的漩涡还在旋转，但比之前弱了一些。");
  return t;
},options:[
  {t:"继续劝说他",go:"seal2_act3_awaken",effect:{time:1,hp:-30,sanLoss:10}},
  {t:"趁他虚弱，发起最后攻击",check:{a:"STR",sk:"martial",label:"武技"},go:"seal2_act3_combat",fail:"seal2_act3_combat_fail"}
]}};

N["seal2_act3_combat"]=function(){return{place:"圣山山顶",text:function(){
  var t=[];
  t.push("谈判破裂了。");
  t.push("大汗咆哮着冲过来。他的拳头带着红色的能量，每一击都能在地面砸出一个坑。你不断闪避，寻找反击的机会。");
  t.push("他的速度很快，但——你注意到了，他的动作有规律。愤怒让他只会正面强攻，不会迂回。你利用这一点，不断游击。");
  t.push("战斗持续了十分钟。你身上添了好几道伤，但他也不好受——你的每一次反击都精准地命中他的关节和穴位。");
  t.push("终于，你抓住了一个机会。他一拳砸空，重心前倾。你侧身闪过，同时用尽全力，一掌拍在他的后心。");
  t.push("他踉跄了几步，然后——跪下了。不是因为受伤，是因为——他在哭。");
  t.push("「巴图……」他喃喃地说，「爸爸对不起你……」");
  t.push("愤怒在离开他。红色的能量从他身上飘散，被漩涡吸收。他的身体在缩小，从两米缩到正常兽人的身高。");
  return t;
},options:[
  {t:"趁他虚弱，用平息之颅完成仪式",check:{a:"SPR",sk:"will",label:"意志"},go:"seal2_act3_ritual",fail:"seal2_act3_ritual_fail"},
  {t:"让他自己选择——是帮忙修复封印，还是继续",go:"seal2_act3_khan_choice",effect:{time:1,hp:-20}}
]}};

N["seal2_act3_combat_fail"]=function(){return{place:"圣山山顶",text:function(){
  var t=[];
  t.push("你输了。");
  t.push("大汗的拳头砸在你的胸口，你飞了出去，重重地摔在地上。你感到自己的视线在模糊，生命在流逝。");
  t.push("他走到你面前，举起手。红色的能量在他掌心聚集。「结束了。」");
  t.push("但就在他要下手的时候，他停住了。");
  t.push("他看着你的脸——你脸上没有恐惧，只有怜悯。");
  t.push("「你……为什么不恨我？」他的声音在发抖。");
  t.push("「因为我知道你不是坏人。你只是——一个失去了儿子的父亲。」");
  t.push("他的手在抖。红色的能量开始不稳定。然后——他跪了下来。");
  t.push("「我……我都做了什么……」他抱头痛哭。愤怒在离开他。");
  return t;
},options:[
  {t:"忍着伤，用平息之颅举行仪式",check:{a:"SPR",sk:"will",label:"意志"},go:"seal2_act3_ritual",fail:"seal2_act3_ritual_fail"},
  {t:"先处理伤口，再做打算",go:"seal2_act3_khan_help",effect:{time:1,hp:-40,sanLoss:10}}
]}};

N["seal2_act3_ritual"]=function(){return{place:"圣山山顶",text:function(){
  var t=[];
  t.push("你举起平息之颅，开始吟唱。");
  t.push("你不知道萨满的语言，但平息之颅在引导你。古老的音节从你嘴里流出，白色的光芒从头骨中涌出，笼罩了整个山顶。");
  t.push("红色的漩涡开始收缩。愤怒在反抗——你能感受到它的咆哮，它的愤怒，它的——恐惧。");
  t.push("是的，恐惧。原初之物也会恐惧。它害怕被重新封印，害怕继续沉睡。");
  t.push("你咬着牙，加大了输出。你的鼻子开始流血，耳朵开始嗡嗡作响。平息之颅在消耗你的生命力。");
  t.push("就在你快要撑不住的时候，一双手放在了你的肩上。");
  t.push("是铁木真。他恢复了正常的样子，一个普通的兽人。他用自己的力量，帮你支撑仪式。");
  t.push("「让我来。」他说，「这是我的责任。」");
  t.push("他的守护者血脉和平息之颅产生了共鸣。白色的光芒暴涨，红色的漩涡开始——凝固。");
  return t;
},options:[
  {t:"和铁木真一起完成仪式",check:{a:"SPR",sk:"will",label:"意志"},go:"seal2_act4_repair",fail:"seal2_act3_ritual_fail"},
  {t:"让铁木真一个人完成——你已经撑不住了",go:"seal2_act3_khan_alone",effect:{time:1,hp:-20,sanLoss:15}}
]}};

N["seal2_act3_ritual_fail"]=function(){return{place:"圣山山顶",text:function(){
  var t=[];
  t.push("仪式失败了。");
  t.push("愤怒的反扑太强烈了。平息之颅的光芒碎裂，你被震飞出去，摔在地上。平息之颅从你手里飞出，摔在石头上，裂开了一道缝。");
  t.push("红色的漩涡开始扩大。愤怒在暴走——失去了宿主和仪式的压制，它开始无差别地攻击一切。");
  t.push("山顶的石柱开始碎裂。你感到一股巨大的吸力从漩涡中传来——它在吞噬周围的一切。");
  t.push("铁木真冲过来，一把抓住你的手。「抓紧我！」");
  t.push("他用自己的身体挡住了吸力。你看到他的皮肤在被撕裂——愤怒在吞噬他。但他没有松手。");
  t.push("「我欠这个世界的。」他说，「让我还。」");
  return t;
},options:[
  {t:"和他一起，用最后的力量重新尝试仪式",check:{a:"SPR",sk:"will",label:"意志"},go:"seal2_act4_sacrifice",fail:"seal2_act4_partial"},
  {t:"不能让他牺牲——你跳起来，用自己的身体挡住",go:"seal2_act4_vessel_sacrifice",effect:{time:1,hp:-30,sanLoss:20}}
]}};

N["seal2_act3_khan_help"]=function(){return{place:"圣山山顶",text:function(){
  var t=[];
  t.push("铁木真看着你，眼神复杂。");
  t.push("「你救了我。」他说，「或者说——你让我想起了我是谁。」");
  t.push("他站起来，走到红色的漩涡前面。「这是我的错。我打开了封印，让愤怒扩散。现在——该我来收拾。」");
  t.push("他转过身，看着你。「修复第二印，需要守护者的血脉。我就是守护者的后裔。让我来。」");
  t.push("「但仪式需要一个愤怒容器——」");
  t.push("「我来当。」他的语气很平静，「我已经被愤怒感染了三年。我的身体，是最好的容器。让我把愤怒导回封印——哪怕代价是我的生命。」");
  t.push("你看着他。这个曾经毁灭了无数生命的兽人，现在愿意用自己的命来赎罪。");
  return t;
},options:[
  {t:"同意他的计划，和他一起举行仪式",go:"seal2_act4_khan_sacrifice",effect:{time:1,flag:"seal2_khan_redemption"}},
  {t:"不同意——一定有别的办法",go:"seal2_act3_other_way",effect:{time:1,flag:"seal2_khan_redemption"}}
]}};

N["seal2_act3_khan_alone"]=function(){return{place:"圣山山顶",text:function(){
  var t=[];
  t.push("你退到一边，把平息之颅交给铁木真。");
  t.push("他接过头骨，站在漩涡前面。他深吸一口气，然后开始吟唱。");
  t.push("他的声音和你不一样——低沉、浑厚，带着草原的苍凉。白色的光芒从他身上涌出，和平息之颅的光芒合为一体。");
  t.push("红色的漩涡开始收缩。你看到铁木真的身体在发光——他在用自己的生命力驱动仪式。");
  t.push("十分钟后，漩涡完全凝固了。第二印重新稳定了。红色的光芒消失了，山顶恢复了平静。");
  t.push("铁木真跪在地上。他的头发全白了。他的身体在快速衰老——刚才的仪式，消耗了他几十年的寿命。");
  t.push("「完成了。」他笑了，笑容里有释然，也有疲惫，「第二印……稳定了。至少……几十年内不会再出问题。」");
  return t;
},options:[
  {t:"走过去，扶住他",go:"seal2_act4_aftermath",effect:{time:1,flag:"seal2_repaired",flag2:"seal2_khan_alive"}},
  {t:"检查封印的状态",go:"seal2_act4_aftermath",effect:{time:1,flag:"seal2_repaired"}}
]}};

N["seal2_act3_khan_choice"]=function(){return{place:"圣山山顶",text:function(){
  var t=[];
  t.push("铁木真跪在地上，看着自己的手。愤怒离开了他，但他的手上还沾着血——无数人的血。");
  t.push("「我杀了很多人。」他说，「萨满、战俘、不服从我的部落。这些……都不会因为我恢复理智就消失。」");
  t.push("「你可以赎罪。」你说。");
  t.push("他抬头看你。「怎么赎？」");
  t.push("「帮我修复第二印。然后——用你的余生，守护它。不再是被愤怒控制的守护者，而是——自愿的守护者。」");
  t.push("他沉默了很久。然后他站起来，走到漩涡前面。");
  t.push("「好。」他说，「我欠这个世界的。我用余生来还。」");
  return t;
},options:[
  {t:"和他一起举行修复仪式",go:"seal2_act4_repair",effect:{time:1,flag:"seal2_khan_guardian"}},
  {t:"先问他修复仪式的具体步骤",go:"seal2_act4_repair",effect:{time:1,flag:"seal2_khan_guardian"}}
]}};

N["seal2_act3_other_way"]=function(){return{place:"圣山山顶",text:function(){
  var t=[];
  t.push("「一定有别的办法。」你说，「不需要牺牲的办法。」");
  t.push("铁木真苦笑。「黄林晶留下的封印，哪有不需要代价的？七印的本质，就是用代价换稳定。」");
  t.push("但你没有放弃。你开始思考——第一印的修复需要碎片和自愿的灵魂。第二印的修复需要仪式和容器。但——如果容器不需要是活人呢？");
  t.push("你想起了平息之颅。第一代萨满的头骨。它本身就是一个『容器』——它已经承载了三千年的愤怒压制。");
  t.push("「用平息之颅。」你说，「它已经是容器了。我们不需要再找一个活人。我们只需要——用它完成仪式。」");
  t.push("铁木真眼睛一亮。「你说得对。平息之颅本身就能承受愤怒。我们只需要用我的血脉激活它，然后——」");
  t.push("「然后让它重新成为第二印的核心。」");
  return t;
},options:[
  {t:"用平息之颅作为容器，举行仪式",check:{a:"INT",sk:"magic",label:"法术"},go:"seal2_act4_repair_no_sacrifice",fail:"seal2_act4_khan_sacrifice"}
]}};

/* ---- 第四幕：后果与余波 ---- */
N["seal2_act4_repair"]=function(){return{place:"圣山山顶",text:function(){
  var t=[];
  t.push("仪式完成了。");
  t.push("红色的漩涡凝固了，变成了一块红色的水晶。水晶悬浮在山顶的石柱上，表面的符文重新亮了起来——这一次，是稳定的光芒。");
  t.push("第二印修复了。");
  t.push("你感到一阵疲惫。刚才的仪式消耗了你大量的灵魂力量。但你也感到——草原上的某种东西变了。空气里的暴戾气息在消退，草开始恢复绿色。");
  t.push("铁木真站在你旁边。他的身体还在，但你能看到他的头发在变白——仪式消耗了他的生命力。");
  t.push("「从今天起，」他说，「我会守在这里。不再是被愤怒控制的大汗，而是——第二印的守护者。」");
  t.push("他看着远方。「我的军队……他们被愤怒感染了。愤怒消退之后，他们会恢复理智。但他们做过的事——不会消失。」");
  t.push("「我会承担责任。」他说，「我会解散军队，向被我伤害过的部落道歉。然后——我会回到这里，守着第二印，直到我死。」");
  return t;
},options:[
  {t:"支持他的决定",go:"seal2_act4_aftermath",effect:{time:1,flag:"seal2_repaired",flag2:"seal2_khan_guardian"}},
  {t:"问他愿不愿意和你一起去修复其他印",go:"seal2_act4_aftermath",effect:{time:1,flag:"seal2_repaired",flag2:"seal2_khan_ally"}}
]}};

N["seal2_act4_repair_no_sacrifice"]=function(){return{place:"圣山山顶",text:function(){
  var t=[];
  t.push("你将平息之颅放在封印中心，用铁木真的血脉激活了它。");
  t.push("头骨亮了起来。白色的光芒和红色的漩涡交织在一起，然后——融合了。平息之颅成为了新的封印核心，它承载了愤怒，同时压制着它。");
  t.push("没有任何人牺牲。");
  t.push("红色的漩涡凝固了，变成了一块红白相间的水晶。水晶表面，平息之颅的符文和黄林晶的封印符文合为一体，形成了一种新的、更稳定的封印。");
  t.push("铁木真看着这一切，露出了笑容。「你做到了。」他说，「你找到了不需要牺牲的方法。」");
  t.push("「是我们一起做到的。」");
  t.push("草原上的风变了。不再是灼热的、带着杀意的风，而是——清凉的、带着草香的风。愤怒消退了。");
  return t;
},options:[
  {t:"和铁木真一起下山",go:"seal2_act4_aftermath",effect:{time:1,flag:"seal2_repaired",flag2:"seal2_no_sacrifice",flag3:"seal2_khan_ally"}},
  {t:"检查封印的稳定性",go:"seal2_act4_aftermath",effect:{time:1,flag:"seal2_repaired",flag2:"seal2_no_sacrifice"}}
]}};

N["seal2_act4_khan_sacrifice"]=function(){return{place:"圣山山顶",text:function(){
  var t=[];
  t.push("铁木真站在封印中心。他回头看了你一眼，笑了。");
  t.push("「告诉草原上的人——铁木真不是怪物。他只是一个，失去了儿子的父亲。」");
  t.push("然后他转过身，将双手按在红色的漩涡上。");
  t.push("白色的光芒从他身上涌出。他的身体开始发光——不是愤怒的红光，是守护者的金光。他的血脉在觉醒，在燃烧。");
  t.push("红色的漩涡开始收缩。愤怒在咆哮，在反抗，但铁木真的意志比它更强。他用自己的灵魂作为容器，将愤怒一点一点地导回封印。");
  t.push("十分钟后，一切结束了。");
  t.push("第二印修复了。红色的水晶悬浮在石柱上。但铁木真——消失了。他的身体化为了光，融入了封印。他成为了第二印的一部分，永远地守护着它。");
  t.push("你站在山顶，风吹过你的脸。你手里还握着那个木雕小马——他儿子的玩具。");
  return t;
},options:[
  {t:"把木雕小马放在山顶，作为纪念",go:"seal2_act4_aftermath",effect:{time:1,flag:"seal2_repaired",flag2:"seal2_khan_dead",flag3:"seal2_khan_hero"}},
  {t:"带着木雕小马上路",go:"seal2_act4_aftermath",effect:{time:1,flag:"seal2_repaired",flag2:"seal2_khan_dead",item:"木雕小马"}}
]}};

N["seal2_act4_sacrifice"]=function(){return{place:"圣山山顶",text:function(){
  var t=[];
  t.push("你和铁木真一起，用最后的力量重新尝试仪式。");
  t.push("这一次，你们没有保留。你将全部的灵魂力量注入平息之颅，铁木真将全部的血脉力量注入封印。");
  t.push("白色和红色的光芒交织，形成了一道巨大的光柱，直冲云霄。");
  t.push("愤怒在咆哮，在反抗，但它已经失去了宿主——铁木真自愿将它导回了封印。");
  t.push("仪式成功了。但代价是——");
  t.push("铁木真的身体开始透明。他在化为光。");
  t.push("「谢谢你。」他对你说，「让我在最后，做了一件正确的事。」");
  t.push("他消失了。第二印修复了。红色的水晶稳定地悬浮在石柱上。");
  t.push("你跪在地上，大口喘气。你的灵魂力量几乎耗尽了，但你还活着。");
  return t;
},options:[
  {t:"休息一下，然后下山",go:"seal2_act4_aftermath",effect:{time:2,hp:-30,sanLoss:20,flag:"seal2_repaired",flag2:"seal2_khan_dead"}},
  {t:"检查封印状态",go:"seal2_act4_aftermath",effect:{time:1,hp:-30,sanLoss:20,flag:"seal2_repaired"}}
]}};

N["seal2_act4_partial"]=function(){return{place:"圣山山顶",text:function(){
  var t=[];
  t.push("仪式只完成了一半。");
  t.push("愤怒没有被完全封印，但它被削弱了。红色的漩涡缩小了一半，不再暴走，但也没有完全稳定。");
  t.push("铁木真用身体挡住了大部分吸力，但他受了重伤。你也一样——灵魂力量几乎耗尽。");
  t.push("「至少……暂时安全了。」铁木真喘着气说，「几年内，它不会再扩散。但几年后——」");
  t.push("「几年后，我会回来。」你说，「带着更强的力量，完成修复。」");
  t.push("他点点头。「我会守在这里。替你看着它。」");
  t.push("你看着他。这个曾经的大汗，现在成了第二印的临时守护者。他的眼睛已经恢复了棕色——普通兽人的棕色。");
  t.push("第二印的问题，暂时解决了。但没有完全解决。你需要变得更强，然后回来。");
  return t;
},options:[
  {t:"约定好，然后下山",go:"seal2_act4_aftermath",effect:{time:1,hp:-40,sanLoss:15,flag:"seal2_partial",flag2:"seal2_khan_guardian"}},
  {t:"再试一次仪式",check:{a:"SPR",sk:"will",label:"意志"},go:"seal2_act4_repair",fail:"seal2_act4_aftermath"}
]}};

N["seal2_act4_vessel_sacrifice"]=function(){return{place:"圣山山顶",text:function(){
  var t=[];
  t.push("你跳了起来，用自己的身体挡住了吸力。");
  t.push("愤怒涌入你的身体。你感到自己的意识在被撕裂——无数的愤怒、杀意、毁灭欲，灌进你的灵魂。");
  t.push("你咬紧牙关，用全部意志对抗着。你想起了你的朋友，你的目标，你走过的路。你不能在这里被吞噬。");
  t.push("萨满骨刀在你怀里发出耀眼的光芒。它在帮你——格鲁父亲的灵魂，通过这把刀，在支撑着你。");
  t.push("你将愤怒导回了封印。用你自己的身体作为导管。");
  t.push("仪式完成了。第二印修复了。");
  t.push("你倒在地上，大口喘气。你的身体没有被吞噬——但你留下了后遗症。你的眼睛里，有一丝极淡的红色。愤怒的碎片，留在了你体内。");
  t.push("它会成为你的力量，也会成为你的隐患。");
  return t;
},options:[
  {t:"接受这个代价，下山",go:"seal2_act4_aftermath",effect:{time:1,hp:-50,sanLoss:25,skillUp:"martial",flag:"seal2_repaired",flag2:"seal2_anger_fragment",flag3:"seal2_player_vessel"}},
  {t:"检查自己的状态",go:"seal2_act4_aftermath",effect:{time:1,hp:-50,sanLoss:25,flag:"seal2_repaired",flag2:"seal2_anger_fragment"}}
]}};

N["seal2_act4_aftermath"]=function(){return{place:"圣山脚下",text:function(){
  var t=[];
  t.push("你下了山。");
  t.push("草原变了。不再是枯黄的、带着杀意的草原。草开始恢复绿色，空气中的暴戾气息消退了。你甚至看到了几只兔子在草丛里跳跃——它们已经很久没有出现在这里了。");
  t.push("大汗的军队正在解散。兽人们茫然地站在营地里，不知道发生了什么。愤怒离开他们之后，他们恢复了理智——然后，他们想起了自己做过的事。");
  t.push("有人在哭。有人在发呆。有人开始收拾东西，准备回家。");
  if(S.flags.seal2_khan_dead) {
    t.push("你听到了消息——大汗消失了。有人说他死了，有人说他成神了。但你知道真相。他成为了第二印的一部分，永远地守护着草原。");
  }
  if(S.flags.seal2_khan_alive || S.flags.seal2_khan_guardian) {
    t.push("铁木真站在山顶，你能看到他的身影。他在守着第二印。他的头发全白了，但他的背挺得很直。");
  }
  t.push("你走到边缘的那个小酒馆。格鲁还在那里。他看到你，愣了一下，然后笑了。");
  t.push("「成了？」");
  t.push("「成了。」");
  t.push("他给你倒了一杯酒。「喝吧。你 deserve it。」");
  return t;
},options:[
  {t:"和格鲁聊聊后续",go:"seal2_act4_grub",effect:{time:1}},
  {t:"去找白发婆婆，告诉她结果",go:"seal2_act4_grandma",effect:{time:2}},
  {t:"休息一晚，明天出发",go:"seal2_transition",effect:{time:1}}
]}};

N["seal2_act4_grub"]=function(){return{place:"边缘酒馆",text:function(){
  var t=[];
  t.push("你和格鲁喝了很久。");
  t.push("你告诉他圣山上发生的一切——大汗的真相，仪式的过程，第二印的修复。他静静地听着，一杯接一杯地喝酒。");
  t.push("等你说完，他沉默了很久。然后说：「我父亲……如果他知道第二印修复了，一定会很高兴。」");
  t.push("「他是个好萨满。」");
  t.push("「是啊。」格鲁笑了，「他一直是。」");
  t.push("他从柜台下面拿出一个包裹。「这是我父亲留下的。他说，如果有一天第二印修复了，就把这个给修复它的人。」");
  t.push("你打开包裹。里面是一本书——萨满的仪式全书。记载了所有七印的守护仪式和修复方法。");
  t.push("「这会对你有用的。」格鲁说，「其他六道印，应该也需要类似的仪式。」");
  return t;
},options:[
  {t:"收下书，感谢格鲁",go:"seal2_transition",effect:{time:1,item:"萨满仪式全书",flag:"seal2_grub_gift"}},
  {t:"问他接下来的打算",go:"seal2_transition",effect:{time:1,item:"萨满仪式全书"}}
]}};

N["seal2_act4_grandma"]=function(){return{place:"流浪者部落",text:function(){
  var t=[];
  t.push("你找到了流浪者部落。白发婆婆看到你，笑了。");
  t.push("「我就知道你能做到。」她说，「风告诉我的。」");
  t.push("你告诉她第二印修复的经过。她听完后，沉默了一会儿。");
  t.push("「铁木真……是个好人。」她说，「被愤怒控制之前是，之后也是。只是走错了路。」");
  t.push("她从怀里掏出一个护身符。「这个给你。用草原上最古老的草编的，能保护你不被其他印的力量影响。」");
  t.push("「其他六道印，每一道都有自己的『原初之物』。」她的语气严肃，「饥饿、愤怒——你已经见过了。还有傲慢、嫉妒、贪婪、懒惰、色欲。每一个都比前一个更难对付。」");
  t.push("「你确定要继续吗？」");
  return t;
},options:[
  {t:"确定。继续前往第三印",go:"seal2_transition",effect:{time:1,item:"草原护身符",flag:"seal2_grandma_gift",flag2:"seal2_other_sins"}},
  {t:"先休息，再做打算",go:"seal2_transition",effect:{time:1,item:"草原护身符"}}
]}};

/* ---- 第二印过渡到第三印 ---- */
N["seal2_transition"]=function(){return{place:"兽人草原 · 边缘",text:function(){
  var t=[];
  t.push("你离开了兽人草原。");
  t.push("回头看，圣山的轮廓在夕阳下显得格外宁静。山顶的石柱上，红色的水晶稳定地发着光。");
  t.push("第二印。修复了。");
  t.push("但你知道，这只是开始。还有五道印。每一道下面都压着一份原初之物。每一道都需要你去面对。");
  t.push("你翻开萨满仪式全书。第三印——精灵王国，世界树根。下面压着的是——『傲慢』。");
  t.push("傲慢。比愤怒更难对付。因为愤怒是外在的，你可以对抗它。但傲慢是内在的——它会让你觉得自己是对的，让你拒绝一切帮助，让你——孤立无援。");
  t.push("精灵王国。一个以傲慢著称的种族。他们的女王，活了三千年的半神。她会让你接近第三印吗？");
  t.push("你不知道。但你必须去。");
  t.push("风吹过草原，带着草香。你踏上了前往精灵王国的路。");
  return t;
},options:[
  {t:"前往精灵王国（第三印）",go:"seal3_act1_intro",effect:{time:10}},
  {t:"先回交汇城休整",go:"fc_jiaohui_entry",effect:{time:5}},
  {t:"查看你的物品和线索",go:"fc_jiaohui_entry",effect:{time:1}}
]}};

/* ================================================================
   第三印 · 精灵王国世界树根（傲慢）— 四幕完整章节
   ================================================================ */

/* ---- 第一幕：线索追寻 ---- */
N["seal3_act1_intro"]=function(){return{place:"精灵王国边境 · 银叶森林",where:"晨",text:function(){
  var t=[];
  t.push("银叶森林的树，会唱歌。");
  t.push("你站在森林边缘，听着风吹过树叶发出的声音——不是普通的沙沙声，是一种低沉的、有旋律的吟唱。像是有无数个声音，在唱一首古老的歌。");
  t.push("精灵王国。大陆上最古老的文明之一。精灵们在这里生活了上万年，他们的城市建在树上，他们的魔法与自然融为一体。");
  t.push("但你也听说过——精灵们很傲慢。他们认为自己是大陆上最高贵的种族，其他种族都是『短命的凡人』。人类在他们眼里，和猴子差不多。");
  t.push("你深吸一口气，走进了森林。");
  t.push("刚走了几步，你就被拦住了。两个精灵守卫从树上跳下来，弓箭指着你。他们的动作很优雅——即使是拿弓指着你，也像是在跳舞。");
  t.push("「人类。」其中一个说，语气里带着毫不掩饰的轻蔑，「这里不是你该来的地方。滚。」");
  return t;
},options:[
  {t:"说明来意——你在调查七印",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal3_act1_guardian",fail:"seal3_act1_guardian_fail"},
  {t:"拿出墨丘利或守望者的信物",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal3_act1_letter",fail:"seal3_act1_guardian_fail"},
  {t:"转身离开，找别的入口",go:"seal3_act1_sneak",effect:{time:2}},
  {t:"硬闯",check:{a:"STR",sk:"martial",label:"武技"},go:"seal3_act1_force",fail:"seal3_act1_captured"}
]}};

N["seal3_act1_guardian"]=function(){return{place:"银叶森林边境",text:function(){
  var t=[];
  t.push("你告诉他们你在调查七印的事。");
  t.push("两个精灵守卫对视了一眼。他们的表情变了——从轻蔑变成了——警惕。");
  t.push("「七印？」年长的那个说，「你怎么会知道七印？」");
  t.push("「我已经修复了第一印和第二印。」");
  t.push("他们愣住了。然后年长的那个仔细打量了你一番。「你？修复了铁门关和兽人草原的印？」他的语气里有怀疑，但也有一丝——你不敢确定——敬意。");
  t.push("「在这里等着。」他说，「我去通报女王。」");
  t.push("他转身消失在树林里。另一个守卫继续用弓指着你，但他的手放松了一些。");
  t.push("等了大约一个小时，年长的守卫回来了。他的表情很复杂。");
  t.push("「女王愿意见你。」他说，「但我警告你——女王的脾气不好。她说的话，你最好认真听。」");
  return t;
},options:[
  {t:"跟着守卫去见女王",go:"seal3_act1_queen",effect:{time:1,flag:"seal3_queen_audience"}},
  {t:"问他更多关于女王和第三印的事",go:"seal3_act1_guardian_info",effect:{time:1}}
]}};

N["seal3_act1_guardian_fail"]=function(){return{place:"银叶森林边境",text:function(){
  var t=[];
  t.push("「七印？」守卫冷笑了一声，「人类也配对七印指手画脚？」");
  t.push("他拉紧了弓弦。「我再说一遍——滚。否则我就把你钉在这棵树上，让你成为森林的肥料。」");
  t.push("你知道他不是在开玩笑。精灵的箭术是大陆第一，你不可能在他射出箭之前躲开。");
  t.push("你后退了几步。守卫没有追上来，但他的箭一直指着你，直到你消失在森林边缘。");
  t.push("你需要换个方式进入精灵王国。硬闯是不行的。");
  return t;
},options:[
  {t:"找别的入口——从森林深处绕过去",go:"seal3_act1_sneak",effect:{time:2}},
  {t:"在边境等，看有没有商队可以混进去",go:"seal3_act1_caravan",effect:{time:3}},
  {t:"用魔法/潜行偷偷潜入",check:{a:"AGI",sk:"stealth",label:"潜行"},go:"seal3_act1_sneak_in",fail:"seal3_act1_captured"}
]}};

N["seal3_act1_letter"]=function(){return{place:"银叶森林边境",text:function(){
  var t=[];
  t.push("你拿出了信物——墨丘利的信，或者守望者的徽章。");
  t.push("守卫看到信物的一瞬间，表情变了。他放下弓，仔细检查信物的真伪。");
  t.push("「墨丘利·星辰之眼……」他喃喃地说，「或者——守望者的标记。」");
  t.push("他抬头看你，眼神里的轻蔑消失了，取而代之的是——复杂。「你和他们有关系？」");
  t.push("「墨丘利是我的导师。/守望者派我来的。」");
  t.push("守卫沉默了一会儿。「跟我来。」他说，「女王会见你的。但——」他顿了顿，「做好心理准备。女王对人类……没有好感。尤其是和墨丘利有关系的人类。」");
  t.push("你跟着他走进了森林。你注意到他说的是『和墨丘利有关系的人类』——墨丘利和精灵女王之间，有什么过去？");
  return t;
},options:[
  {t:"问他墨丘利和女王的关系",go:"seal3_act1_mercury_past",effect:{time:1,flag:"seal3_mercury_connection"}},
  {t:"不多问，跟着走",go:"seal3_act1_queen",effect:{time:1}}
]}};

N["seal3_act1_mercury_past"]=function(){return{place:"银叶森林",text:function(){
  var t=[];
  t.push("守卫犹豫了一下，然后压低声音说：「那是五百年前的事了。」");
  t.push("「墨丘利那时候还年轻，刚成为守望者的执灯人。他来精灵王国，调查一起深渊渗透事件。然后——他遇到了女王。」");
  t.push("「那时候女王还不是女王，是王储。他们……」守卫的表情很微妙，「走得很近。近到精灵长老会都开始反对了。」");
  t.push("「后来呢？」");
  t.push("「后来墨丘利走了。守望者的职责在身，他不能留下来。」守卫叹了口气，「女王等了他一百年。然后——她变了。不再相信任何人，尤其是人类。她把所有的精力都放在了守护第三印上。」");
  t.push("「五百年了。她还在等他。或者说——还在恨他。」");
  t.push("你想起了墨丘利研究室里的那幅画——一个精灵女子的背影。原来那是女王。");
  return t;
},options:[
  {t:"记下这个信息，继续去见女王",go:"seal3_act1_queen",effect:{time:1,flag:"seal3_mercury_romance"}},
  {t:"问他第三印的具体情况",go:"seal3_act1_seal_info",effect:{time:1,flag:"seal3_mercury_romance"}}
]}};

N["seal3_act1_sneak"]=function(){return{place:"银叶森林深处",text:function(){
  var t=[];
  t.push("你绕开了边境守卫，从森林深处潜入。");
  t.push("银叶森林比你想象的大。你走了整整两天，还没有看到精灵的城市。但你注意到了一些奇怪的事——");
  t.push("森林里的树，越往深处走，越高大。有些树有百米高，树干需要十几个人才能合抱。而且这些树——是活的。你能感受到它们的意识，古老的、缓慢的意识。");
  t.push("它们在看你。");
  t.push("第二天傍晚，你找到了世界树。");
  t.push("它不是一棵树——它是一座山。树干的直径有一公里，树冠遮天蔽日。它的根须深入地下，你能感受到——第三印就在它的根部。");
  t.push("但你也感受到了——傲慢。从世界树根部散发出来的，纯粹的、压倒性的傲慢。它让你觉得自己很渺小，很——卑微。");
  t.push("你摇摇头，把这种感觉压下去。然后你听到了脚步声。");
  return t;
},options:[
  {t:"躲起来",check:{a:"AGI",sk:"stealth",label:"潜行"},go:"seal3_act1_hide",fail:"seal3_act1_captured"},
  {t:"主动现身，说明来意",go:"seal3_act1_encounter",effect:{time:1}},
  {t:"继续向世界树根部前进",check:{a:"SPR",sk:"will",label:"意志"},go:"seal3_act2_root",fail:"seal3_act1_captured"}
]}};

N["seal3_act1_captured"]=function(){return{place:"银叶森林",text:function(){
  var t=[];
  t.push("你被抓住了。");
  t.push("十几个精灵守卫从树上跳下来，把你团团围住。他们的动作太快了，你根本来不及反应。");
  t.push("你被绑了起来，蒙住眼睛，带到了某个地方。走了大约一个小时，眼罩被取下。");
  t.push("你在一个巨大的树洞里。树洞被改造成了宫殿——墙壁是活的木头，上面长着发光的苔藓，提供柔和的照明。");
  t.push("王座上坐着一个人。");
  t.push("精灵女王。艾萨拉。");
  t.push("她看起来只有二十多岁，但你知道她已经活了三千年。她的美是超凡脱俗的——不像是人类的美，更像是一种自然现象，像是日出、像是星空、像是——你不配欣赏的东西。");
  t.push("她看着你，眼神里没有任何情绪。或者说——只有一种情绪：傲慢。");
  t.push("「人类。」她说，声音像是泉水叮咚，「你居然敢潜入我的森林。」");
  return t;
},options:[
  {t:"说明来意，请求原谅",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal3_act1_queen",fail:"seal3_act1_banished"},
  {t:"不卑不亢，告诉她你在修复七印",go:"seal3_act1_queen",effect:{time:1,flag:"seal3_captured_audience"}},
  {t:"沉默，等她发问",go:"seal3_act1_queen",effect:{time:1}}
]}};

N["seal3_act1_queen"]=function(){return{place:"精灵王宫 · 世界树殿",text:function(){
  var t=[];
  t.push("你站在精灵女王面前。");
  t.push("她仔细打量着你，目光像是在审视一件物品。「你说你修复了第一印和第二印？」");
  t.push("「是的。」");
  t.push("「证明给我看。」");
  t.push("你拿出了证据——霍夫曼的笔记、萨满仪式全书、或者你身上的印记。女王看了很久，然后她的表情变了。");
  t.push("不是变得友好——是变得更加警惕。");
  t.push("「你知道第三印下面是什么吗？」她问。");
  t.push("「傲慢。原初之物的七分之一。」");
  t.push("女王站了起来。她走到你面前，你能感受到她的力量——半神级的力量，像是一座山压在你肩上。");
  t.push("「傲慢是所有原初之物中最危险的。」她的声音很低，「饥饿会吞噬你的身体，愤怒会吞噬你的理智——但傲慢会吞噬你的灵魂。它会让你觉得自己是神。然后——你就会变成下一个黄林晶。」");
  t.push("「黄林晶？」");
  t.push("女王的眼神变得遥远。「黄林晶就是被傲慢吞噬的。他以为自己能控制原初之物，以为自己能拯救世界。结果——他把世界变成了现在这个样子。」");
  return t;
},options:[
  {t:"问她黄林晶和第三印的关系",go:"seal3_act1_huanglinjing",effect:{time:1,flag:"seal3_queen_talks"}},
  {t:"请求她让你接近第三印",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal3_act1_request",fail:"seal3_act1_refuse"},
  {t:"提起墨丘利",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal3_act1_mercury_name",fail:"seal3_act1_refuse"}
]}};

N["seal3_act1_huanglinjing"]=function(){return{place:"世界树殿",text:function(){
  var t=[];
  t.push("女王沉默了很久。然后她开始说话——声音很轻，像是在讲一个很久远的故事。");
  t.push("「三千年前，黄林晶来到精灵王国。那时候我还是王储，刚刚成年。」");
  t.push("「他说他要加固七印。他说原初之物正在苏醒，如果不做什么，世界会毁灭。精灵长老会不相信他——但我信了。」");
  t.push("「我带他去了世界树根部，第三印的所在地。他在那里待了七天七夜，研究封印。然后他告诉我——第三印的封印有缺陷，需要用『活的锚点』来加固。」");
  t.push("「活的锚点？」");
  t.push("「一个自愿与封印融合的灵魂。」女王的声音在发抖，「他说，需要一个精灵——因为精灵的灵魂最纯净，最适合做锚点。」");
  t.push("「我自愿了。」");
  t.push("你愣住了。「你？」");
  t.push("女王点点头。「我和第三印融合了。我的灵魂成为了封印的一部分。这就是为什么我能活三千年——也是为什么，我能感受到傲慢的每一次呼吸。」");
  t.push("「但黄林晶骗了我。」她的声音突然变得冰冷，「融合之后，我才发现——第三印不是在封印傲慢。是在喂养它。用我的灵魂，喂养傲慢。三千年了，我一直在被傲慢侵蚀。」");
  return t;
},options:[
  {t:"问她为什么不解除融合",go:"seal3_act1_why_not",effect:{time:1,flag:"seal3_queen_anchor"}},
  {t:"问她黄林晶为什么要这么做",go:"seal3_act1_hlj_reason",effect:{time:1,flag:"seal3_queen_anchor"}},
  {t:"告诉她你可以帮她解除",go:"seal3_act1_offer_help",effect:{time:1,flag:"seal3_queen_anchor"}}
]}};

N["seal3_act1_request"]=function(){return{place:"世界树殿",text:function(){
  var t=[];
  t.push("你请求女王让你接近第三印。");
  t.push("女王看着你，眼神里的傲慢更浓了。「你？一个人类？你知道第三印的傲慢有多强吗？你靠近它不到十步，就会被它吞噬。你会觉得自己是神，然后——你会毁灭一切。」");
  t.push("「我已经面对过饥饿和愤怒了。我能撑住。」");
  t.push("「饥饿和愤怒是外在的。傲慢是内在的。」女王的声音尖锐起来，「你以为你很强？你以为你修复了两道印就很了不起？在我眼里，你就是一个——」");
  t.push("她停住了。因为她看到了你的眼睛。你的眼睛里没有恐惧，没有愤怒——只有平静。");
  t.push("她沉默了很久。然后她说：「好吧。我让你去。但我有一个条件。」");
  t.push("「什么条件？」");
  t.push("「如果你被傲慢吞噬了——我会亲手杀了你。」");
  return t;
},options:[
  {t:"同意她的条件",go:"seal3_act2_root",effect:{time:1,flag:"seal3_queen_agrees"}},
  {t:"问她有没有别的办法",go:"seal3_act1_other_way",effect:{time:1,flag:"seal3_queen_agrees"}},
  {t:"要求她和你一起去",go:"seal3_act1_queen_joins",effect:{time:1,flag:"seal3_queen_agrees"}}
]}};

N["seal3_act1_refuse"]=function(){return{place:"世界树殿",text:function(){
  var t=[];
  t.push("女王冷笑了一声。「你以为你是谁？一个人类，也配对第三印指手画脚？」");
  t.push("她挥了挥手。守卫冲上来，把你架了出去。");
  t.push("「滚出我的森林。」她的声音从身后传来，「如果再让我看到你——我就把你变成树，种在森林边上。」");
  t.push("你被扔出了精灵王国的边境。");
  t.push("你坐在森林外面，思考着对策。女王的傲慢比你想象的更深。她不会轻易让你接近第三印。");
  t.push("但你注意到了——她提到黄林晶的时候，眼神里有一丝痛苦。她不是纯粹的傲慢——她是被傲慢伤害过的人。");
  t.push("也许，你可以从这一点入手。");
  return t;
},options:[
  {t:"找墨丘利帮忙——他和女王有旧情",go:"seal3_act1_mercury_help",effect:{time:5,flag:"seal3_banished"}},
  {t:"偷偷潜入，直接去世界树根部",check:{a:"AGI",sk:"stealth",label:"潜行"},go:"seal3_act2_root",fail:"seal3_act1_captured"},
  {t:"在边境等，找机会再进去",go:"seal3_act1_wait",effect:{time:3}}
]}};

N["seal3_act1_mercury_name"]=function(){return{place:"世界树殿",text:function(){
  var t=[];
  t.push("你提到了墨丘利的名字。");
  t.push("女王的表情瞬间变了。不是愤怒——是痛苦。五百年的时光，在她脸上一闪而过。");
  t.push("「墨丘利。」她喃喃地说，「他还活着？」");
  t.push("「他活着。他在艾尔达魔法学院当教授。」");
  t.push("女王沉默了很久。然后她笑了——笑得很苦。「五百年了。他连一封信都没有写过。」");
  t.push("「他有他的苦衷——守望者的职责——」");
  t.push("「不要替他说话。」女王打断你，声音冰冷，「他选择了守望者，选择了世界，放弃了我。这是他的选择。」");
  t.push("但你注意到——她的手在发抖。");
  t.push("过了一会儿，她深吸一口气。「好吧。看在墨丘利的面子上——我让你去第三印。但你要替我带一句话给他。」");
  t.push("「什么话？」");
  t.push("「告诉他——我还在等。」");
  return t;
},options:[
  {t:"答应她，然后去第三印",go:"seal3_act2_root",effect:{time:1,flag:"seal3_queen_message",flag2:"seal3_queen_agrees"}},
  {t:"问她更多关于墨丘利的事",go:"seal3_act1_mercury_story",effect:{time:1,flag:"seal3_queen_message"}}
]}};

N["seal3_act1_offer_help"]=function(){return{place:"世界树殿",text:function(){
  var t=[];
  t.push("你告诉女王，你可以帮她解除和第三印的融合。");
  t.push("女王愣住了。然后她笑了——笑得很凄凉。「解除？你知道解除融合意味着什么吗？意味着第三印会失去锚点，傲慢会立刻苏醒。到时候——整个精灵王国都会被傲慢吞噬。」");
  t.push("「但如果我们先修复第三印，再解除融合——」");
  t.push("「修复？」女王的眼神锐利起来，「你知道怎么修复吗？第三印的修复，需要替换锚点。需要一个新的灵魂，自愿和封印融合。你愿意吗？」");
  t.push("你沉默了。");
  t.push("「所以，不要说这种话。」女王的声音软了下来，「三千年了，我已经习惯了。这是我的选择，我的责任。」");
  t.push("但你看到了——她的眼睛里，有一丝渴望。渴望自由。渴望不再被傲慢侵蚀。");
  return t;
},options:[
  {t:"承诺会找到不需要牺牲的修复方法",go:"seal3_act2_root",effect:{time:1,flag:"seal3_promise_queen",flag2:"seal3_queen_agrees"}},
  {t:"问她第三印的具体结构",go:"seal3_act1_seal_structure",effect:{time:1,flag:"seal3_promise_queen"}}
]}};

N["seal3_act1_clue_gathered"]=function(){return{place:"精灵王国边境",text:function(){
  var t=[];
  t.push("你整理了一下收集到的信息。");
  if(S.flags.seal3_queen_anchor) t.push("· 女王艾萨拉是第三印的『活锚点』，三千年前与封印融合，灵魂一直在被傲慢侵蚀。");
  if(S.flags.seal3_mercury_romance) t.push("· 墨丘利和女王五百年前有过一段感情，墨丘利离开后，女王等了他五百年。");
  if(S.flags.seal3_queen_talks) t.push("· 第三印下面是『傲慢』，所有原初之物中最危险的——它会吞噬灵魂，让人觉得自己是神。");
  if(S.flags.seal3_queen_agrees) t.push("· 女王同意让你接近第三印，但条件是：如果你被傲慢吞噬，她会亲手杀了你。");
  if(S.flags.seal3_queen_message) t.push("· 女王让你带话给墨丘利：『我还在等。』");
  t.push("");
  t.push("世界树的根部。第三印的所在地。你需要去那里，面对傲慢。");
  return t;
},options:[
  {t:"前往世界树根部",go:"seal3_act2_root",effect:{time:1}},
  {t:"再准备一下",go:"seal3_act1_prepare",effect:{time:1}}
]}};

/* ---- 第二幕：抵达与探索 ---- */
N["seal3_act2_root"]=function(){return{place:"世界树 · 根部",text:function(){
  var t=[];
  t.push("你来到了世界树的根部。");
  t.push("如果说世界树的树冠是天空，那么它的根部就是——地下世界。根须像一条条巨龙，在地下蜿蜒，有的根须有几十米粗。");
  t.push("在根须的最中心，你看到了第三印。");
  t.push("它不是一个漩涡，也不是一块水晶——它是一面镜子。一面巨大的、立在根须中心的镜子。镜面不是玻璃，是某种你看不懂的物质，里面倒映着——你自己。");
  t.push("但镜子里的你，和真实的你不一样。镜子里的你，更高大、更威严、更——完美。镜子里的你，像是一个神。");
  t.push("「这就是傲慢。」女王的声音从你身后传来。她不知道什么时候跟了过来。「它会让你看到你最想成为的样子。然后——它会让你觉得，你已经是那个样子了。」");
  t.push("你感到一阵眩晕。镜子里的你在对你笑。那个笑容里，有无限的诱惑。");
  return t;
},options:[
  {t:"直视镜子，面对傲慢",check:{a:"SPR",sk:"will",label:"意志"},go:"seal3_act2_mirror",fail:"seal3_act2_mirror_fail"},
  {t:"不看镜子，研究周围的符文",check:{a:"INT",sk:"magic",label:"法术"},go:"seal3_act2_runes",fail:"seal3_act2_mirror"},
  {t:"问女王怎么修复第三印",go:"seal3_act2_queen_method",effect:{time:1}}
]}};

N["seal3_act2_mirror"]=function(){return{place:"世界树根部",text:function(){
  var t=[];
  t.push("你直视着镜子。");
  t.push("镜子里的你开始说话。不是用声音，是直接在你脑子里说话。");
  t.push("「你很强。」它说，「你修复了两道印。你拯救了无数人。你知道吗？你已经不是普通人了。你是——英雄。」");
  t.push("你感到一阵愉悦。被赞美的感觉，很好。");
  t.push("「你可以更强。」镜子里的你继续说，「你可以成为神。不需要再听任何人的命令，不需要再向任何人低头。你可以统治这个世界——不，你可以拯救这个世界。以神的身份。」");
  t.push("你的心跳在加速。统治世界？拯救世界？以神的身份？");
  t.push("「黄林晶就是这么想的。」女王的声音在你耳边响起，像是一盆冷水，「他觉得自己能拯救世界，觉得自己是神。结果——他把世界变成了现在这个样子。」");
  t.push("你猛地清醒过来。镜子里的你还在笑，但那个笑容现在看起来——很虚伪。");
  t.push("「你不是神。」你对镜子里的自己说，「你只是我想要成为的样子。但我不是你。」");
  t.push("镜子里的你笑容消失了。镜面开始波动。");
  return t;
},options:[
  {t:"继续对抗傲慢的诱惑",check:{a:"SPR",sk:"will",label:"意志"},go:"seal3_act2_resist",fail:"seal3_act2_fall"},
  {t:"问女王下一步怎么做",go:"seal3_act2_next",effect:{time:1,flag:"seal3_resisted_first"}},
  {t:"尝试用魔法攻击镜子",check:{a:"INT",sk:"magic",label:"法术"},go:"seal3_act2_attack",fail:"seal3_act2_attack_fail"}
]}};

N["seal3_act2_mirror_fail"]=function(){return{place:"世界树根部",text:function(){
  var t=[];
  t.push("你没能抵抗住。");
  t.push("镜子里的你太有诱惑力了。你看到了自己成为神的样子——万人敬仰，世界和平，所有问题都迎刃而解。");
  t.push("你向前走了一步。然后又一步。你离镜子越来越近。");
  t.push("就在你的手要碰到镜面的时候，女王一把拉住了你。");
  t.push("「清醒一点！」她的声音带着力量，半神级的力量灌入你的身体，将傲慢的诱惑暂时驱散。");
  t.push("你猛地回过神来。你的手离镜面只有一寸。镜面里，那个『神化』的你正在冷笑。");
  t.push("「差一点。」女王的声音在发抖，「差一点你就被它吞噬了。」");
  t.push("你后退了几步，大口喘气。你的额头上全是冷汗。");
  t.push("「现在你知道了吧。」女王说，「傲慢比饥饿和愤怒都危险。它不会伤害你——它会让你觉得，伤害自己是对的。」");
  return t;
},options:[
  {t:"休息一下，再试一次",go:"seal3_act2_mirror",effect:{time:1,hp:-10,sanLoss:10}},
  {t:"问女王有没有别的方法",go:"seal3_act2_other_method",effect:{time:1,sanLoss:10}},
  {t:"让女王帮你——她有经验",go:"seal3_act2_queen_help",effect:{time:1,sanLoss:10}}
]}};

N["seal3_act2_resist"]=function(){return{place:"世界树根部",text:function(){
  var t=[];
  t.push("你闭上眼睛，将全部意志集中在一个念头上：");
  t.push("「我不是神。我只是一个人。一个会犯错、会失败、会受伤的人。」");
  t.push("镜子里的你开始咆哮。不是声音——是直接在你脑子里的咆哮。「你撒谎！你是特别的！你是天选之人！你可以拯救世界！」");
  t.push("「也许我可以。」你说，「但不是以神的身份。是以人的身份。」");
  t.push("你睁开眼睛。镜子里的你开始扭曲。那个完美的、神化的形象在碎裂——露出了下面真正的东西。");
  t.push("傲慢。一团没有形状的、金色的雾气。它在镜子里翻滚，发出无声的尖叫。");
  t.push("你做到了。你看穿了傲慢的伪装。");
  t.push("女王在你身后，露出了惊讶的表情。「三千年了……」她喃喃地说，「你是第一个看穿它的人。」");
  return t;
},options:[
  {t:"趁傲慢虚弱，尝试修复封印",check:{a:"INT",sk:"magic",label:"法术"},go:"seal3_act3_repair",fail:"seal3_act3_repair_fail"},
  {t:"问女王修复的具体方法",go:"seal3_act3_method",effect:{time:1,flag:"seal3_pride_weakened"}},
  {t:"和傲慢对话",check:{a:"SPR",sk:"will",label:"意志"},go:"seal3_act3_talk_pride",fail:"seal3_act3_repair_fail"}
]}};

N["seal3_act2_fall"]=function(){return{place:"世界树根部",text:function(){
  var t=[];
  t.push("你被傲慢吞噬了。");
  t.push("不是身体被吞噬——是灵魂。你开始觉得自己无所不能。你觉得女王很可怜——她居然被一个小小的封印困了三千年。你觉得黄林晶很蠢——他居然没能控制原初之物。");
  t.push("你觉得，你可以做到他们都做不到的事。");
  t.push("你举起手，开始聚集力量。你要打碎镜子，释放傲慢——然后和它融合，成为真正的神。");
  t.push("「住手！」女王冲上来。但你一挥手，她就飞了出去，撞在根须上。半神级的力量，在你面前——不堪一击。");
  t.push("你笑了。这就是力量。这就是——神。");
  t.push("但就在你要碰到镜子的时候，你脑子里闪过了一个画面。");
  t.push("是你的朋友。是你走过的路。是你帮助过的人。是——你作为『人』的记忆。");
  t.push("你停住了。");
  return t;
},options:[
  {t:"用记忆对抗傲慢，找回自我",check:{a:"SPR",sk:"will",label:"意志"},go:"seal3_act2_recover",fail:"seal3_act2_queen_kill"},
  {t:"继续——成为神",go:"seal3_act3_become_god",effect:{time:1,flag:"seal3_pride_corrupted"}},
  {t:"女王会杀了你——但你不在乎",go:"seal3_act2_queen_kill",effect:{time:1,flag:"seal3_pride_corrupted"}}
]}};

N["seal3_act2_recover"]=function(){return{place:"世界树根部",text:function(){
  var t=[];
  t.push("你用全部的意志力，将那些记忆——作为人的记忆——拽了回来。");
  t.push("你想起了第一次施法成功时的喜悦。想起了朋友的笑容。想起了你帮助过的人对你说『谢谢』时的温暖。");
  t.push("你想起了——你不是神。你只是一个人。一个普通人。");
  t.push("傲慢在你体内咆哮。它不想离开。但你比它更强——不是力量上的强，是意志上的强。");
  t.push("你张开嘴，将傲慢从体内吐了出来。它化作一团金色的雾气，回到了镜子里。");
  t.push("你跪在地上，大口喘气。你的身体在发抖——不是因为冷，是因为后怕。你差点就变成了——你最不想成为的那种人。");
  t.push("女王走过来，扶你起来。她的眼神变了。不再是傲慢，是——敬意。");
  t.push("「你做到了。」她说，「三千年了，第一个从傲慢手中回来的人。」");
  return t;
},options:[
  {t:"趁傲慢虚弱，修复封印",go:"seal3_act3_repair",effect:{time:1,hp:-20,sanLoss:15,flag:"seal3_recovered_from_pride"}},
  {t:"先休息，恢复一下",go:"seal3_act2_rest",effect:{time:1,hp:-20,sanLoss:15}}
]}};

N["seal3_act2_queen_kill"]=function(){return{place:"世界树根部",text:function(){
  var t=[];
  t.push("女王举起了手。");
  t.push("她的眼睛里有痛苦，但更多的是——决绝。「我说过，如果你被傲慢吞噬，我会亲手杀了你。」");
  t.push("半神级的力量在她掌心聚集。你知道，你挡不住。");
  t.push("但就在她要出手的时候，她停住了。");
  t.push("因为她看到了——你的眼睛里，有一丝清明。你还在和傲慢对抗。你还没有完全被吞噬。");
  t.push("「你还在。」她喃喃地说，「你还在。」");
  t.push("她收回了力量，冲到你面前，将手按在你的额头上。半神级的力量灌入你的身体，帮你将傲慢压制了下去。");
  t.push("你恢复了理智。你跪在地上，大口喘气。");
  t.push("「下次——」女王的声音在发抖，「下次我不会再犹豫了。」");
  return t;
},options:[
  {t:"感谢她，然后修复封印",go:"seal3_act3_repair",effect:{time:1,hp:-30,sanLoss:20,flag:"seal3_queen_mercy"}},
  {t:"道歉，然后休息",go:"seal3_act2_rest",effect:{time:1,hp:-30,sanLoss:20}}
]}};

/* ---- 第三幕：真相与抉择 ---- */
N["seal3_act3_repair"]=function(){return{place:"世界树根部",text:function(){
  var t=[];
  t.push("你开始修复第三印。");
  t.push("按照萨满仪式全书记载的方法，你需要将新的能量注入封印，替换掉被傲慢污染的部分。但第三印的情况特殊——它有一个活的锚点：女王。");
  t.push("「如果我修复封印，」女王说，「我和封印的融合会被切断。我会——变回普通人。寿命也会变回普通精灵的寿命。」");
  t.push("「你不怕吗？」");
  t.push("「怕。」女王笑了，「三千年了，我已经习惯了永生。但——」她看着镜子，「我更怕继续被傲慢侵蚀。再过一千年，我可能就不是我了。」");
  t.push("你开始注入能量。白色的光芒从你手中涌出，覆盖了镜面。傲慢在镜子里咆哮，反抗，但它已经被你削弱了。");
  t.push("女王的身体开始发光。她和封印的连接在断裂。你能感受到她的痛苦——三千年的连接，不是说断就能断的。");
  t.push("「坚持住。」你说。");
  t.push("「我没事。」她咬着牙说，「继续。」");
  return t;
},options:[
  {t:"继续注入能量，完成修复",check:{a:"SPR",sk:"will",label:"意志"},go:"seal3_act4_repair_success",fail:"seal3_act4_repair_fail"},
  {t:"用萨满仪式全书辅助",check:{a:"INT",sk:"magic",label:"法术"},go:"seal3_act4_repair_success",fail:"seal3_act4_repair_fail"},
  {t:"让女王也帮忙——她最了解封印",go:"seal3_act4_queen_help",effect:{time:1}}
]}};

N["seal3_act3_talk_pride"]=function(){return{place:"世界树根部",text:function(){
  var t=[];
  t.push("你决定和傲慢对话。");
  t.push("「你为什么要存在？」你问镜子里的金色雾气，「你为什么要让人变成神？」");
  t.push("傲慢沉默了一会儿。然后它说话了——不是诱惑的语气，是很平静的语气。");
  t.push("「因为这是宇宙的本质。」它说，「存在的意义，就是超越。每一个生命，都想变得更强、更好、更——完美。这就是我。我是超越的欲望。」");
  t.push("「但超越不等于成为神。」");
  t.push("「是吗？」傲慢的语气里有一丝嘲讽，「黄林晶不这么想。他觉得自己能超越一切，能拯救世界。他错了——但他的欲望本身，没有错。」");
  t.push("你沉默了。傲慢说的——有一定道理。追求进步、追求超越，本身没有错。错的是——追求到忘记了自己是谁。");
  t.push("「所以，」你说，「我不需要消灭你。我只需要——让你回到正确的位置。你是动力，不是主人。」");
  t.push("傲慢沉默了很久。然后它笑了。「有意思。三千年了，你是第一个这么说的人。」");
  return t;
},options:[
  {t:"和傲慢达成协议——它做动力，你做主人",go:"seal3_act3_agreement",effect:{time:1,flag:"seal3_pride_talked"}},
  {t:"不，还是修复封印比较安全",go:"seal3_act3_repair",effect:{time:1,flag:"seal3_pride_talked"}},
  {t:"问它黄林晶的真相",go:"seal3_act3_hlj_truth",effect:{time:1,flag:"seal3_pride_talked"}}
]}};

N["seal3_act3_agreement"]=function(){return{place:"世界树根部",text:function(){
  var t=[];
  t.push("你和傲慢达成了协议。");
  t.push("「你可以留在我体内。」你说，「作为我前进的动力。但你不能控制我。我才是主人。」");
  t.push("傲慢沉默了很久。然后——它同意了。");
  t.push("金色的雾气从镜子里涌出，缠绕上你的身体。你感到一阵温暖——不是灼烧，是一种……鼓励。像是有一个声音在说：『前进吧。变得更强吧。但别忘了你是谁。』");
  t.push("镜子碎了。第三印的核心消失了——因为傲慢不再需要被封印。它成为了你的一部分。");
  t.push("女王看着这一切，目瞪口呆。「你……你把傲慢吸收了？」");
  t.push("「不是吸收。是合作。」你笑了，「它是动力，我是方向。」");
  t.push("你感到自己的力量在增长——但不是那种膨胀的、神化的增长。是一种……踏实的、有根基的增长。你知道自己的极限在哪里，也知道自己可以变得更强。");
  t.push("这就是傲慢的正确用法。");
  return t;
},options:[
  {t:"检查自己的状态",go:"seal3_act4_aftermath",effect:{time:1,skillUp:"magic",skillUp2:"martial",sanLoss:10,flag:"seal3_pride_ally",flag2:"seal3_broken"}},
  {t:"问女王怎么样了",go:"seal3_act4_queen_freed",effect:{time:1,flag:"seal3_pride_ally"}}
]}};

N["seal3_act3_hlj_truth"]=function(){return{place:"世界树根部",text:function(){
  var t=[];
  t.push("你问傲慢，黄林晶的真相。");
  t.push("傲慢沉默了很久。然后它说：「黄林晶是我的孩子。」");
  t.push("「什么？」");
  t.push("「三千年前，黄林晶只是一个普通的人类。但他有——超越一切的欲望。那种欲望太强了，强到我注意到了他。我给了他力量。」");
  t.push("「他用我给的力量，加固了七印。他以为自己在拯救世界。但实际上——他是在帮我。七印不是封印原初之物，是在喂养它们。用整个世界的生命力，喂养我们七个。」");
  t.push("「黄林晶知道吗？」");
  t.push("「他后来知道了。」傲慢的声音很低，「但那时候已经晚了。他已经被我吞噬了一半。他做了最后一件事——将自己的灵魂分成十二份，封印在十二件神器里。他希望，有一天有人能集齐神器，揭开真相。」");
  t.push("你愣住了。十二神器。黄林晶遗产。原来——那是他留给后人的线索。");
  t.push("「所以，集齐十二神器，就能知道全部真相？」");
  t.push("「是的。」傲慢说，「但我警告你——真相可能比你想象的更残酷。」");
  return t;
},options:[
  {t:"记下这个信息，继续修复封印",go:"seal3_act3_repair",effect:{time:1,flag:"seal3_hlj_truth",flag2:"seal3_twelve_relics_clue"}},
  {t:"问它怎么才能真正打败原初之物",go:"seal3_act3_defeat_method",effect:{time:1,flag:"seal3_hlj_truth"}}
]}};

/* ---- 第四幕：后果与余波 ---- */
N["seal3_act4_repair_success"]=function(){return{place:"世界树根部",text:function(){
  var t=[];
  t.push("修复完成了。");
  t.push("镜面恢复了平静。金色的雾气被重新封印在镜子里，但这一次——封印更稳定了。你用自己的能量，替换掉了被污染的部分。");
  t.push("女王的身体在发光。她和封印的连接断了。她的头发开始变色——从银色变成了金色。她的脸上出现了——皱纹。");
  t.push("三千年的寿命，在一瞬间消失了。她变回了一个普通的精灵。虽然她依然很强——半神级的力量不会因为失去锚点就消失——但她的寿命，只剩下几百年了。");
  t.push("她摸了摸自己的脸，然后笑了。「终于。」她说，「终于自由了。」");
  t.push("她转过身，看着你。她的眼神里没有傲慢了——只有感激。");
  t.push("「谢谢你。」她说，「三千年了，我终于可以——做回自己了。」");
  t.push("世界树开始发光。不是那种压抑的、傲慢的光，是温暖的、生命的光。森林里的树开始唱歌——比以前更欢快的歌。");
  return t;
},options:[
  {t:"恭喜她",go:"seal3_act4_aftermath",effect:{time:1,flag:"seal3_repaired",flag2:"seal3_queen_freed"}},
  {t:"问她接下来打算怎么办",go:"seal3_act4_queen_future",effect:{time:1,flag:"seal3_repaired",flag2:"seal3_queen_freed"}}
]}};

N["seal3_act4_repair_fail"]=function(){return{place:"世界树根部",text:function(){
  var t=[];
  t.push("修复失败了。");
  t.push("傲慢的反抗比你想象的更强。你的能量注入到一半，就被反弹了回来。你飞了出去，撞在根须上，吐出一口血。");
  t.push("镜面开始碎裂。傲慢在往外涌——金色的雾气充满了整个根部空间。");
  t.push("「不行！」女王冲上来，将自己的身体挡在镜子前面。她重新和封印连接，用自己的灵魂压制傲慢。");
  t.push("「你快走！」她喊道，「我撑不了多久！」");
  t.push("你看着她的背影。三千年了，她一直在守护这道印。即使被傲慢侵蚀，即使痛苦不堪，她也没有放弃。");
  t.push("你不能让她一个人承担。");
  return t;
},options:[
  {t:"冲上去，和她一起压制傲慢",check:{a:"SPR",sk:"will",label:"意志"},go:"seal3_act4_together",fail:"seal3_act4_partial"},
  {t:"用萨满仪式全书中的紧急仪式",check:{a:"INT",sk:"magic",label:"法术"},go:"seal3_act4_emergency",fail:"seal3_act4_partial"},
  {t:"撤退——保存实力，下次再来",go:"seal3_act4_retreat",effect:{time:1,hp:-30,sanLoss:15,flag:"seal3_failed"}}
]}};

N["seal3_act4_together"]=function(){return{place:"世界树根部",text:function(){
  var t=[];
  t.push("你冲上去，站在女王身边，将自己的力量注入封印。");
  t.push("两个灵魂，一起对抗傲慢。你的意志加上她三千年的经验，终于将傲慢压了回去。");
  t.push("镜面重新合拢。金色的雾气被重新封印。但你知道——这只是暂时的。封印没有被修复，只是被重新压制了。");
  t.push("女王瘫坐在地上。她的脸色苍白，但她笑了。「我们做到了。」");
  t.push("「只是暂时的。」你说，「封印还需要彻底修复。」");
  t.push("「我知道。」女王点点头，「但至少——我们争取到了时间。」");
  t.push("她看着你，眼神里有了敬意。「你比我想象的更强。不是力量上的强——是心性上的强。」");
  t.push("第三印的问题，暂时解决了。但没有完全解决。你需要变得更强，然后回来完成修复。");
  return t;
},options:[
  {t:"约定好，然后离开",go:"seal3_act4_aftermath",effect:{time:1,hp:-40,sanLoss:20,flag:"seal3_partial",flag2:"seal3_queen_ally"}},
  {t:"再试一次修复",check:{a:"SPR",sk:"will",label:"意志"},go:"seal3_act4_repair_success",fail:"seal3_act4_partial"}
]}};

N["seal3_act4_queen_freed"]=function(){return{place:"世界树根部",text:function(){
  var t=[];
  t.push("女王自由了。");
  t.push("她不再是第三印的锚点。她的灵魂不再被傲慢侵蚀。她可以——做任何她想做的事。");
  t.push("「三千年了。」她说，「我都忘了，自由是什么感觉。」");
  t.push("她走到世界树的边缘，看着森林。风吹过她的头发——金色的头发，在阳光下闪闪发光。");
  t.push("「我想去看看世界。」她说，「三千年了，我一直守在这里。我想去看看人类的城市，看看矮人的熔炉，看看兽人的草原。」");
  t.push("她转过身，看着你。「你愿意——带我一起走吗？」");
  t.push("你愣住了。精灵女王，活了三千年的半神，要和你一起旅行？");
  t.push("她笑了——不是那种傲慢的笑，是真正的、开心的笑。「怎么？不欢迎？」");
  return t;
},options:[
  {t:"欢迎她加入",go:"seal3_act4_aftermath",effect:{time:1,flag:"seal3_queen_joins",flag2:"seal3_queen_freed"}},
  {t:"婉拒——你的旅途太危险",go:"seal3_act4_aftermath",effect:{time:1,flag:"seal3_queen_stays",flag2:"seal3_queen_freed"}}
]}};

N["seal3_act4_aftermath"]=function(){return{place:"精灵王国 · 银叶城",text:function(){
  var t=[];
  t.push("你回到了银叶城。");
  t.push("精灵们都出来了。他们感受到了世界树的变化——那种压抑的、傲慢的气息消失了，取而代之的是温暖的、生命的气息。");
  t.push("他们看着女王——现在的女王，头发是金色的，脸上有了皱纹，但她的眼睛里，有了三千年没有过的——光。");
  t.push("「第三印修复了。」女王对她的子民说，「我不再是你们的女王了——我不再是半神，不再是锚点。我只是一个普通的精灵。」");
  t.push("精灵们沉默了。然后——他们开始鼓掌。不是那种礼节性的鼓掌，是发自内心的、感激的鼓掌。");
  t.push("一个老精灵走出来，向女王鞠躬。「您永远是我们的女王。不管您是不是半神。」");
  t.push("女王的眼睛红了。三千年了，她第一次——哭了。");
  t.push("你站在一旁，看着这一切。你知道，你做了一件正确的事。");
  return t;
},options:[
  {t:"向女王告别，继续旅程",go:"seal3_transition",effect:{time:1}},
  {t:"在精灵王国休息几天",go:"seal3_act4_rest",effect:{time:3}},
  {t:"问女王关于其他印的事",go:"seal3_act4_other_seals",effect:{time:1}}
]}};

N["seal3_act4_other_seals"]=function(){return{place:"银叶城",text:function(){
  var t=[];
  t.push("女王告诉你关于其他印的事。");
  t.push("「第四印在矮人王国，永恒熔炉的心脏。下面压着的是——贪婪。矮人们世代守护它，但他们自己也被贪婪影响了——他们对财富的渴望，比其他种族都强。」");
  t.push("「第五印在南方深海。下面压着的是——嫉妒。海底有一个被遗忘的种族，他们世代守护那道印，但他们嫉妒大陆上的种族，一直在等待机会复仇。」");
  t.push("「第六印在东部王国，时光裂隙。下面压着的是——懒惰。黄林晶在那里留了一个『后门』，可以穿越时间。但懒惰会让你觉得——一切都可以等，明天再做也来得及。」");
  t.push("「第七印在死亡沙漠，深渊神殿。下面压着的是——色欲。那是所有原初之物中最神秘的一个，也是最危险的一个。它会让你沉溺于快乐，忘记一切。」");
  t.push("她看着你。「你确定要继续吗？每一道印，都比前一道更难对付。」");
  return t;
},options:[
  {t:"确定。继续前往第四印",go:"seal3_transition",effect:{time:1,flag:"seal3_other_seals_known"}},
  {t:"先休息，再做打算",go:"seal3_act4_rest",effect:{time:1,flag:"seal3_other_seals_known"}}
]}};

/* ---- 第三印过渡到第四印 ---- */
N["seal3_transition"]=function(){return{place:"精灵王国边境",text:function(){
  var t=[];
  t.push("你离开了精灵王国。");
  t.push("回头看，世界树的轮廓在夕阳下显得格外温暖。森林里的树在唱歌——欢快的歌。");
  t.push("第三印。修复了。女王自由了。");
  t.push("但你知道，这只是开始。还有四道印。贪婪、嫉妒、懒惰、色欲——每一个都比前一个更难对付。");
  t.push("你摸了摸怀里的萨满仪式全书。下一站——矮人王国。永恒熔炉。第四印。");
  t.push("矮人。一个以贪婪著称的种族。他们的国王，传奇战士索林。他会让你接近第四印吗？");
  t.push("你不知道。但你必须去。");
  t.push("风吹过森林，带着树叶的清香。你踏上了前往矮人王国的路。");
  return t;
},options:[
  {t:"前往矮人王国（第四印）",go:"seal4_act1_intro",effect:{time:8}},
  {t:"先回交汇城休整",go:"fc_jiaohui_entry",effect:{time:5}},
  {t:"查看你的物品和线索",go:"fc_jiaohui_entry",effect:{time:1}}
]}};

/* ================================================================
   第四印 · 矮人王国永恒熔炉心（贪婪）— 四幕完整章节
   ================================================================ */

/* ---- 第一幕：线索追寻 ---- */
N["seal4_act1_intro"]=function(){return{place:"矮人王国 · 铁峰堡城门",where:"正午",text:function(){
  var t=[];
  t.push("铁峰堡的门，是用一整块铁做的。");
  t.push("你站在山脚下，仰头看着这座矮人城市。它不是建在山上——它是从山里挖出来的。整座山被掏空，变成了一座巨大的地下城市。城门高三十米，厚五米，上面刻满了矮人的符文。");
  t.push("城门旁边，排着长长的队伍。商人们在等待入城检查——矮人对货物的检查很严格，尤其是贵金属。");
  t.push("你排在队伍里，听着前面的商人聊天。");
  t.push("「最近铁峰堡的税收又涨了。」一个商人抱怨，「索林王不知道在搞什么，天天加税。」");
  t.push("「听说他在挖什么东西。」另一个商人压低声音，「在最深的矿层下面。已经挖了三年了，死了不少矿工。」");
  t.push("「挖什么？」");
  t.push("「谁知道呢。有人说是金子，有人说是——别的东西。」");
  t.push("你皱起眉头。别的东西？第四印？");
  return t;
},options:[
  {t:"排队入城",go:"seal4_act1_enter",effect:{time:1}},
  {t:"和商人打听更多消息",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal4_act1_merchant_info",fail:"seal4_act1_enter"},
  {t:"找别的入口——矿工通道",go:"seal4_act1_miner_entrance",effect:{time:2}}
]}};

N["seal4_act1_enter"]=function(){return{place:"铁峰堡 · 城内",text:function(){
  var t=[];
  t.push("你进入了铁峰堡。");
  t.push("和你想象的不一样。铁峰堡不是阴暗潮湿的地下洞穴——它是一座辉煌的地下城市。天花板上镶嵌着发光的宝石，提供柔和的照明。街道是用打磨过的花岗岩铺的，两旁是商店、酒馆、工坊。");
  t.push("到处都是矮人。他们个子不高，但很壮实，胡子编得整整齐齐，上面挂着各种金属饰品。你注意到——几乎每个矮人身上都戴着金子。戒指、项链、耳环、腰带扣——金闪闪的一片。");
  t.push("贪婪。你能感受到它。不是傲慢那种精神上的压迫，是一种——物质上的诱惑。你看着那些金子，心里涌起一股强烈的渴望。你想拥有它们。全部。");
  t.push("你摇摇头，把这种感觉压下去。");
  t.push("你需要找到索林王，或者——找到第四印的入口。");
  return t;
},options:[
  {t:"去王宫求见索林王",go:"seal4_act1_palace",effect:{time:1}},
  {t:"先去酒馆打听消息",go:"seal4_act1_tavern",effect:{time:1}},
  {t:"去矿区看看",go:"seal4_act1_mine",effect:{time:1}}
]}};

N["seal4_act1_merchant_info"]=function(){return{place:"铁峰堡城门外",text:function(){
  var t=[];
  t.push("你和商人聊了起来。");
  t.push("「你是外地来的？」商人上下打量你，「想买矿？最近铁峰堡的矿价涨得厉害。」");
  t.push("「我听说索林王在挖什么东西？」");
  t.push("商人的表情变了。他环顾四周，压低声音：「你也听说了？」");
  t.push("「三年前，索林王在最深的矿层下面，发现了一个——东西。没人知道是什么。但从那以后，他就变了。」");
  t.push("「怎么变了？」");
  t.push("「他以前是个好国王。减税、修路、保护商队。但现在——他只关心挖矿。税收一加再加，矿工一批一批地死，他都不管。」");
  t.push("「有人说，他挖到了『宝藏』。一个无底的宝藏。他越挖越多，但永远挖不完。」");
  t.push("「也有人说——他挖到的不是宝藏，是某种——会吃人的东西。」");
  return t;
},options:[
  {t:"问他那个东西在哪里",go:"seal4_act1_location",effect:{time:1,flag:"seal4_merchant_info"}},
  {t:"问他有没有矿工可以联系",go:"seal4_act1_miner_contact",effect:{time:1,flag:"seal4_merchant_info"}},
  {t:"谢过他，入城",go:"seal4_act1_enter",effect:{time:1,flag:"seal4_merchant_info"}}
]}};

N["seal4_act1_tavern"]=function(){return{place:"铁峰堡 · 铁锤酒馆",text:function(){
  var t=[];
  t.push("酒馆里很吵。矮人们在喝酒、唱歌、吵架。空气中弥漫着麦酒和烤肉的味道。");
  t.push("你找了个角落坐下，点了一杯麦酒。酒很烈，但很香——矮人酿酒的技术确实一流。");
  t.push("你听着周围的对话。大部分是关于矿的——哪个矿层出了好矿，哪个矿工发了财，哪个矿洞又塌了。");
  t.push("然后你听到了一个词——『深渊矿层』。");
  t.push("「深渊矿层又死人了。」一个老矮人喝着酒说，「这个月第三个了。」");
  t.push("「谁让他们去的？那地方不是被封了吗？」");
  t.push("「封了？国王亲自开的封。他说那里有『国家需要的资源』。」老矮人冷笑，「国家需要的资源？我看是他自己需要。」");
  t.push("你走过去，在老矮人旁边坐下。「深渊矿层是什么地方？」");
  t.push("老矮人看了你一眼。「人类？你问这个干什么？」");
  return t;
},options:[
  {t:"请他喝酒，打听消息",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal4_act1_old_miner",fail:"seal4_act1_tavern_kicked"},
  {t:"说你是来调查矿难的",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal4_act1_old_miner",fail:"seal4_act1_tavern_kicked"},
  {t:"不再问了，自己去矿区",go:"seal4_act1_mine",effect:{time:1}}
]}};

N["seal4_act1_old_miner"]=function(){return{place:"铁锤酒馆",text:function(){
  var t=[];
  t.push("老矮人喝了你请的酒，话多了起来。");
  t.push("「我叫铜须。当了四十年矿工。深渊矿层——我去过一次。」");
  t.push("「三年前，国王下令打开最深的矿层。我们挖了三个月，终于挖穿了。然后——我们看到了它。」");
  t.push("「看到了什么？」");
  t.push("铜须的手在发抖。「一个湖。金色的湖。不是水——是液态的金子。无边无际的金子。」");
  t.push("「我们都疯了。所有人都冲上去，用手捧金子。但——金子是活的。它会钻进你的皮肤，钻进你的血管。然后——你就会想要更多。更多。更多。」");
  t.push("「和我一起去的二十个人，只有我一个回来了。其他十九个——他们跳进了金湖里。再也没有出来。」");
  t.push("「国王也去了。他在金湖边站了一天。回来之后，他就变了。他开始疯狂地挖矿，挖更多的金子，挖更深的矿层。」");
  t.push("「那不是金子。」铜须的声音很低，「那是——贪婪。它会吃掉你。」");
  return t;
},options:[
  {t:"问他深渊矿层的入口在哪里",go:"seal4_act1_abyss_entrance",effect:{time:1,flag:"seal4_copperbeard_ally",flag2:"seal4_gold_lake"}},
  {t:"问他索林王现在的状态",go:"seal4_act1_thorin_state",effect:{time:1,flag:"seal4_copperbeard_ally"}},
  {t:"问他有没有办法抵抗贪婪的诱惑",go:"seal4_act1_resist_method",effect:{time:1,flag:"seal4_copperbeard_ally"}}
]}};

N["seal4_act1_palace"]=function(){return{place:"铁峰堡 · 王宫",text:function(){
  var t=[];
  t.push("你来到了王宫。");
  t.push("矮人的王宫和人类的不一样——没有华丽的装饰，只有厚重的石墙和铁门。但你注意到，每一扇门、每一根柱子，都是用纯金包裹的。");
  t.push("贪婪。连王宫都在炫耀财富。");
  t.push("你被守卫拦了下来。「人类？求见国王？」守卫冷笑，「国王不见人类。尤其是——不送礼的人类。」");
  t.push("他伸出手，搓了搓手指。");
  t.push("你明白了。需要贿赂。");
  return t;
},options:[
  {t:"贿赂守卫（50金龙）",check:{a:"CHA",sk:"trade",label:"商术"},go:"seal4_act1_audience",fail:"seal4_act1_palace_fail",effect:{gold:-50}},
  {t:"不贿赂，硬闯",check:{a:"STR",sk:"martial",label:"武技"},go:"seal4_act1_force_enter",fail:"seal4_act1_jailed"},
  {t:"转身离开，找别的办法",go:"seal4_act1_tavern",effect:{time:1}}
]}};

N["seal4_act1_audience"]=function(){return{place:"铁峰堡 · 王宫大殿",text:function(){
  var t=[];
  t.push("你被带进了大殿。");
  t.push("大殿比你想象的更大。天花板有五十米高，上面镶嵌着一颗巨大的宝石——散发着温暖的光芒。大殿的尽头，是王座。");
  t.push("王座上坐着一个矮人。");
  t.push("索林王。他比普通矮人更高大，几乎有人类的身高。他的胡子是金色的——不是染的，是真的金色。他的眼睛——也是金色的。和大汗一样的金色。");
  t.push("被贪婪感染了。");
  t.push("他坐在王座上，手里把玩着一块金子——一块有人头大的纯金。他的手指在金子上摩挲，像是在抚摸情人的脸。");
  t.push("「人类。」他头也不抬，「你找我什么事？」");
  t.push("「我在调查七印。第四印——就在你的王国里。」");
  t.push("索林王的手停了一下。然后他抬起头，看着你。他的眼睛里，有贪婪，有警惕，还有——一丝你不敢确定的——恐惧。");
  return t;
},options:[
  {t:"直接问他第四印的事",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal4_act1_thorin_talk",fail:"seal4_act1_thorin_refuse"},
  {t:"先夸他的财富，拉近距离",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal4_act1_thorin_flatter",fail:"seal4_act1_thorin_refuse"},
  {t:"提起铜须和深渊矿层",go:"seal4_act1_thorin_confront",effect:{time:1}}
]}};

N["seal4_act1_thorin_talk"]=function(){return{place:"王宫大殿",text:function(){
  var t=[];
  t.push("你直接问索林王关于第四印的事。");
  t.push("他沉默了很久。然后他挥了挥手，大殿里的守卫都退了出去。");
  t.push("「你知道第四印？」他的声音很低，「你知道它下面是什么？」");
  t.push("「贪婪。原初之物的七分之一。」");
  t.push("索林王苦笑了一下。「贪婪。」他重复了一遍，「你知道吗？矮人的祖先，就是被贪婪选中的守护者。我们世代守护第四印——但我们也被它影响了。我们对金子的渴望，比任何种族都强。这就是——代价。」");
  t.push("「三年前，我打开了深渊矿层。我以为——我能控制它。我以为我能利用贪婪的力量，让矮人王国变得更强大。」");
  t.push("他低下头，看着手里的金子。「但我错了。贪婪不是工具——它是主人。我现在——已经不是我了。」");
  t.push("你看着他。这个曾经的传奇战士，现在被贪婪折磨得——不成样子。");
  return t;
},options:[
  {t:"问他第四印的具体位置和状态",go:"seal4_act1_seal_location",effect:{time:1,flag:"seal4_thorin_talks"}},
  {t:"问他有没有办法修复",go:"seal4_act1_repair_method",effect:{time:1,flag:"seal4_thorin_talks"}},
  {t:"告诉他你可以帮他",go:"seal4_act1_offer_help",effect:{time:1,flag:"seal4_thorin_talks"}}
]}};

N["seal4_act1_thorin_refuse"]=function(){return{place:"王宫大殿",text:function(){
  var t=[];
  t.push("索林王的脸色变了。");
  t.push("「第四印？」他猛地站起来，金色的眼睛里充满了警惕，「你知道什么？谁告诉你的？」");
  t.push("「我——」");
  t.push("「够了！」他一拍王座的扶手，「人类，我不管你从哪里听来的谣言。第四印不存在。深渊矿层也不存在。你——给我滚。」");
  t.push("守卫冲了进来，把你架了出去。");
  t.push("你被扔在王宫外面。但你注意到——索林王刚才的反应，不是愤怒，是——恐惧。他害怕你知道第四印的事。");
  t.push("为什么？因为他知道第四印已经失控了。他不想让任何人知道。");
  return t;
},options:[
  {t:"去找铜须，从矿工通道进入深渊矿层",go:"seal4_act1_miner_path",effect:{time:1,flag:"seal4_thorin_refused"}},
  {t:"在王宫外等，找机会再进去",go:"seal4_act1_wait",effect:{time:2}},
  {t:"去酒馆，找更多线索",go:"seal4_act1_tavern",effect:{time:1}}
]}};

N["seal4_act1_seal_location"]=function(){return{place:"王宫大殿",text:function(){
  var t=[];
  t.push("索林王告诉你第四印的位置。");
  t.push("「第四印就在深渊矿层的最底部。那个金色的湖——就是第四印的核心。贪婪以液态金子的形态存在，诱惑一切靠近它的生物。」");
  t.push("「三年前我打开它的时候，它还只是一个小水洼。但现在——它已经变成了一个湖。而且还在扩大。」");
  t.push("「它在吞噬矿工。每死一个矿工，它就扩大一分。我——我没有阻止。因为我需要它。」");
  t.push("「需要它？」");
  t.push("「贪婪给了我力量。」索林王举起手，他的手在发光——金色的光，「我的力量比以前强了十倍。但代价是——我永远都觉得不够。我想要更多的金子，更多的力量，更多的——一切。」");
  t.push("「如果第四印完全苏醒——」");
  t.push("「整个矮人王国都会被贪婪吞噬。」他的声音在发抖，「所有矮人都会变成——只知道收集金子的怪物。然后，贪婪会扩散到整个大陆。」");
  return t;
},options:[
  {t:"问他修复的方法",go:"seal4_act1_repair_method",effect:{time:1,flag:"seal4_seal_known"}},
  {t:"问他为什么不自己修复",go:"seal4_act1_why_not",effect:{time:1,flag:"seal4_seal_known"}}
]}};

N["seal4_act1_repair_method"]=function(){return{place:"王宫大殿",text:function(){
  var t=[];
  t.push("索林王告诉你修复第四印的方法。");
  t.push("「第四印的修复，和其他印不一样。贪婪是——『积累型』的原初之物。它越积累越强。要修复它，需要——『散财』。」");
  t.push("「散财？」");
  t.push("「将贪婪积累的财富，全部分散出去。金子、宝石、珍贵的矿石——所有被贪婪『污染』的财富，都要还给大地，还给人民。」");
  t.push("「但这意味着——矮人王国三千年积累的财富，全部归零。」");
  t.push("索林王的手在发抖。「我做不到。」他说，「那些财富——是我的。是我辛辛苦苦攒下来的。让我把它们全部分出去——不如杀了我。」");
  t.push("你看着他。这就是贪婪的可怕之处——它让你把财富看得比生命还重。即使知道那是毒药，你也舍不得放手。");
  t.push("「还有一个办法。」索林王补充，「找到『贪婪之心』——第四印的核心结晶。把它从金湖里取出来，然后封印。但贪婪之心在湖的最底部，靠近它的人——都会被吞噬。」");
  return t;
},options:[
  {t:"选择散财路线——说服索林王",go:"seal4_act1_scatter_route",effect:{time:1,flag:"seal4_scatter_method"}},
  {t:"选择取心路线——潜入深渊矿层",go:"seal4_act1_heart_route",effect:{time:1,flag:"seal4_heart_method"}},
  {t:"两条路线都准备",go:"seal4_act1_both_routes",effect:{time:1,flag:"seal4_both_methods"}}
]}};

N["seal4_act1_clue_gathered"]=function(){return{place:"铁峰堡",text:function(){
  var t=[];
  t.push("你整理了一下收集到的信息。");
  if(S.flags.seal4_gold_lake) t.push("· 深渊矿层底部有一个金色的湖——液态金子，是贪婪的具象化。");
  if(S.flags.seal4_copperbeard_ally) t.push("· 铜须：老矿工，去过深渊矿层，二十人只有他一个回来。");
  if(S.flags.seal4_thorin_talks) t.push("· 索林王被贪婪感染了，金色的眼睛，对财富有病态的渴望。");
  if(S.flags.seal4_seal_known) t.push("· 第四印在深渊矿层最底部，贪婪以液态金子形态存在，正在扩大。");
  if(S.flags.seal4_scatter_method) t.push("· 修复方法一：散财——将所有被污染的财富分散出去。");
  if(S.flags.seal4_heart_method) t.push("· 修复方法二：取心——取出贪婪之心，然后封印。");
  t.push("");
  t.push("你需要做出选择：是说服索林王散财，还是自己潜入深渊矿层取心？");
  return t;
},options:[
  {t:"散财路线——去说服索林王",go:"seal4_act2_scatter",effect:{time:1}},
  {t:"取心路线——去深渊矿层",go:"seal4_act2_abyss",effect:{time:1}},
  {t:"先去找铜须了解更多",go:"seal4_act1_copperbeard_more",effect:{time:1}}
]}};

/* ---- 第二幕：抵达与探索 ---- */
N["seal4_act2_abyss"]=function(){return{place:"铁峰堡 · 深渊矿层入口",text:function(){
  var t=[];
  t.push("你来到了深渊矿层的入口。");
  t.push("入口是一个垂直的矿井，有一部古老的升降梯。升降梯是用铁做的，上面刻满了矮人的符文——但那些符文已经暗淡了。");
  t.push("铜须站在你旁边。他的脸色很苍白。「我带你下去。」他说，「但我警告你——下去之后，不管看到什么，都不要碰金子。一碰，你就完了。」");
  t.push("你点点头。");
  t.push("升降梯开始下降。一分钟、两分钟、五分钟——你不知道有多深，只知道空气越来越热，越来越——粘稠。");
  t.push("然后你看到了光。金色的光。");
  t.push("升降梯停了。你走出升降梯，看到了——地狱。");
  t.push("一个巨大的地下洞穴。洞穴的底部，是一个金色的湖。液态的金子，在缓慢地流动，发出诱人的光芒。湖面上，漂浮着——尸体。几十个矿工的尸体，脸上都带着满足的笑容。");
  t.push("他们是笑着死的。被贪婪吞噬，笑着死去。");
  return t;
},options:[
  {t:"沿着湖边走，寻找贪婪之心",check:{a:"SPR",sk:"will",label:"意志"},go:"seal4_act2_lakeside",fail:"seal4_act2_tempted"},
  {t:"用法术探测湖底",check:{a:"INT",sk:"magic",label:"法术"},go:"seal4_act2_scan",fail:"seal4_act2_tempted"},
  {t:"让铜须在入口等，你一个人去",go:"seal4_act2_alone",effect:{time:1,flag:"seal4_alone"}}
]}};

N["seal4_act2_lakeside"]=function(){return{place:"深渊矿层 · 金湖边",text:function(){
  var t=[];
  t.push("你沿着湖边走。");
  t.push("每走一步，你都能感受到贪婪的诱惑。金子在召唤你。它在你脑子里说话——『过来吧。你值得拥有这些。你辛苦了这么久，应该得到回报。这些金子——都是你的。』");
  t.push("你咬着牙，继续往前走。萨满骨刀和草原护身符在你身上发热，帮你抵抗着诱惑。");
  t.push("走了大约半个小时，你看到了——一个平台。");
  t.push("平台从湖边延伸出去，悬在湖面上。平台的尽头，有一个基座。基座上——空的。");
  t.push("「贪婪之心原来在这里。」铜须的声音从你身后传来，他的声音在发抖，「但三年前，索林王把它取走了。」");
  t.push("「取走了？放到哪里了？」");
  t.push("铜须指了指湖的中心。「那里。他把贪婪之心沉到了湖底。他说——这样贪婪就能永远存在，永远为他提供力量。」");
  t.push("你看着湖面。金色的湖水深不见底。贪婪之心就在下面。");
  return t;
},options:[
  {t:"潜入湖底，取出贪婪之心",check:{a:"STR",sk:"athletic",label:"运动"},go:"seal4_act2_dive",fail:"seal4_act2_dive_fail"},
  {t:"用法术把贪婪之心吸上来",check:{a:"INT",sk:"magic",label:"法术"},go:"seal4_act2_pull",fail:"seal4_act2_pull_fail"},
  {t:"在湖边做仪式，净化湖水",check:{a:"SPR",sk:"will",label:"意志"},go:"seal4_act2_purify",fail:"seal4_act2_purify_fail"}
]}};

N["seal4_act2_tempted"]=function(){return{place:"深渊矿层 · 金湖边",text:function(){
  var t=[];
  t.push("你被诱惑了。");
  t.push("金子太美了。太诱人了。你不由自主地蹲下来，伸出手——");
  t.push("「别碰！」铜须一把拉住你。他的力气很大，把你拽了回来。");
  t.push("你猛地清醒过来。你的手离湖面只有一寸。湖面上，你的倒影在笑——贪婪的笑。");
  t.push("「差一点。」铜须的声音在发抖，「差一点你就变成他们了。」他指了指湖面上的尸体。");
  t.push("你后退了几步，大口喘气。你的心跳得很快——不是因为恐惧，是因为——渴望。你还想碰那些金子。");
  t.push("「集中精神。」铜须说，「想想你为什么来这里。想想那些被贪婪杀死的人。」");
  t.push("你闭上眼睛，深吸一口气。然后你睁开眼睛，眼神恢复了清明。");
  return t;
},options:[
  {t:"继续前进，寻找贪婪之心",go:"seal4_act2_lakeside",effect:{time:1,sanLoss:10,flag:"seal4_tempted_once"}},
  {t:"先退回去，调整状态",go:"seal4_act2_retreat",effect:{time:1,sanLoss:10}}
]}};

N["seal4_act2_dive"]=function(){return{place:"深渊矿层 · 金湖底",text:function(){
  var t=[];
  t.push("你深吸一口气，跳进了金湖。");
  t.push("液态金子比你想象的更粘稠——像是在融化的黄油里游泳。而且它是热的，烫得你皮肤发疼。");
  t.push("但更可怕的是——诱惑。金子从你的毛孔里钻进去，在你血管里流动。你感到一阵狂喜——你拥有了无穷的财富，你是世界上最富有的人。");
  t.push("你差点就沉溺在这种感觉里了。但你想起了铜须的话，想起了湖面上的尸体。你咬着舌头，用疼痛保持清醒，继续往下游。");
  t.push("湖底比你想象的更深。你游了大约五分钟，终于看到了——光。");
  t.push("一颗心脏。金色的、跳动的心脏。它有一人高，悬浮在湖底，每一次跳动，都让整个湖面泛起涟漪。");
  t.push("贪婪之心。");
  t.push("你伸出手，抓住了它。");
  return t;
},options:[
  {t:"把它带出湖面",check:{a:"STR",sk:"athletic",label:"运动"},go:"seal4_act3_heart_obtained",fail:"seal4_act2_dive_fail"},
  {t:"在湖底就尝试封印它",check:{a:"INT",sk:"magic",label:"法术"},go:"seal4_act3_seal_heart",fail:"seal4_act2_dive_fail"}
]}};

N["seal4_act2_dive_fail"]=function(){return{place:"深渊矿层 · 金湖",text:function(){
  var t=[];
  t.push("你没能撑住。");
  t.push("金子的诱惑太强了。你在湖底，感到自己的意识在模糊。你想放弃——放弃挣扎，放弃任务，就——沉浸在金子里，永远快乐。");
  t.push("然后你感到有人在拉你。是铜须。他在湖面上，用一根绳子把你往上拽。");
  t.push("你被拉出了湖面，瘫在岸边，大口喘气。你的皮肤变成了淡金色——金子已经渗入了你的身体。");
  t.push("「你还好吗？」铜须扶着你，他的手在发抖。");
  t.push("「我……还好。」你说。但你知道，你被贪婪感染了。你现在——比以前更渴望财富。");
  t.push("这会成为你的力量，也会成为你的隐患。");
  return t;
},options:[
  {t:"休息一下，再试一次",go:"seal4_act2_abyss",effect:{time:1,hp:-20,sanLoss:15,flag:"seal4_greedy_infected"}},
  {t:"放弃取心路线，改用散财路线",go:"seal4_act2_scatter",effect:{time:1,hp:-20,sanLoss:15,flag:"seal4_greedy_infected"}}
]}};

/* ---- 散财路线 ---- */
N["seal4_act2_scatter"]=function(){return{place:"铁峰堡 · 王宫",text:function(){
  var t=[];
  t.push("你决定走散财路线。");
  t.push("你再次来到王宫。这一次，索林王同意见你——也许是因为他知道，你是唯一能帮他的人。");
  t.push("「散财？」他苦笑，「你知道那意味着什么吗？矮人王国三千年的积累——全部归零。我的子民会恨我。贵族会造反。我——会变成一个穷光蛋。」");
  t.push("「但如果不散财，贪婪会吞噬整个王国。到那时候——你们连命都没有了，还要金子干什么？」");
  t.push("索林王沉默了。他看着自己手里的金子，看了很久。");
  t.push("「你说得对。」他终于说，「但我——我做不到。我一想到要把这些金子分出去，我的心就像被刀割一样。」");
  t.push("他抬起头，看着你。「你能帮我吗？帮我——做这个决定。」");
  return t;
},options:[
  {t:"帮他制定散财计划",go:"seal4_act2_scatter_plan",effect:{time:1,flag:"seal4_scatter_route"}},
  {t:"用意志帮他抵抗贪婪",check:{a:"SPR",sk:"will",label:"意志"},go:"seal4_act2_will_help",fail:"seal4_act2_scatter_fail"},
  {t:"让他自己决定——这是他的责任",go:"seal4_act2_thorin_choice",effect:{time:1,flag:"seal4_scatter_route"}}
]}};

N["seal4_act2_scatter_plan"]=function(){return{place:"王宫",text:function(){
  var t=[];
  t.push("你帮索林王制定了散财计划。");
  t.push("第一步：将王宫的黄金储备，分发给铁峰堡的居民。每个矮人家庭都能分到一笔钱。");
  t.push("第二步：将矿山的所有权，从王室收归国有——不，归矿工所有。矿工们自己管理矿山，自己分配收益。");
  t.push("第三步：将被贪婪污染的『深渊金』——也就是从金湖里挖出来的金子——全部重新沉入湖底，不再开采。");
  t.push("「这三步做完，贪婪失去了积累的来源，就会慢慢萎缩。然后——第四印就能重新稳定。」");
  t.push("索林王听着，脸色越来越苍白。「你知道第一步要分出去多少金子吗？」");
  t.push("「知道。大约是王室储备的三分之二。」");
  t.push("他闭上眼睛。过了很久，他睁开眼，眼神里有了决断。「好。」他说，「就按你说的做。」");
  t.push("他站起来，走向大殿的门口。「传我的命令——开仓放粮。不，开仓放金。」");
  return t;
},options:[
  {t:"和他一起执行散财",go:"seal4_act3_scatter_execution",effect:{time:1,flag:"seal4_scatter_plan"}},
  {t:"在旁边观察，看他是否真的会执行",go:"seal4_act3_scatter_observe",effect:{time:1,flag:"seal4_scatter_plan"}}
]}};

/* ---- 第三幕：真相与抉择 ---- */
N["seal4_act3_heart_obtained"]=function(){return{place:"深渊矿层 · 岸边",text:function(){
  var t=[];
  t.push("你把贪婪之心带出了湖面。");
  t.push("它在你手里跳动。金色的光芒照亮了整个洞穴。你能感受到它的力量——无穷的财富，无穷的欲望，无穷的——可能。");
  t.push("「你拿到了。」铜须的声音在发抖，「快——封印它。不要被它诱惑。」");
  t.push("但你看着手里的心脏，心里涌起了一个念头。");
  t.push("如果你不封印它呢？如果你——利用它呢？");
  t.push("贪婪之心可以给你无穷的财富。你可以成为大陆上最富有的人。你可以用钱买到一切——权力、军队、甚至——神的力量。");
  t.push("你知道这个念头是贪婪在诱惑你。但——它说的也有道理。为什么要封印它？为什么不利用它？");
  return t;
},options:[
  {t:"封印贪婪之心——修复第四印",check:{a:"SPR",sk:"will",label:"意志"},go:"seal4_act4_seal_success",fail:"seal4_act4_seal_fail"},
  {t:"利用贪婪之心——获得财富和力量",go:"seal4_act3_exploit",effect:{time:1,flag:"seal4_greedy_choice"}},
  {t:"把它交给索林王——让他决定",go:"seal4_act3_give_thorin",effect:{time:1}}
]}};

N["seal4_act3_exploit"]=function(){return{place:"深渊矿层",text:function(){
  var t=[];
  t.push("你决定利用贪婪之心。");
  t.push("你将自己的力量注入心脏。金色的光芒暴涨——你感到无穷的力量涌入你的身体。你的口袋里开始出现金子——一块、两块、一堆、一座山。");
  t.push("你笑了。这就是力量。这就是——财富。");
  t.push("但然后你感到了——空虚。金子越来越多，但你越来越不满足。你想要更多。更多。更多。");
  t.push("你开始觉得铜须很碍眼。他在看着你，眼神里有恐惧。你想——杀了他。他不配拥有这些。这些都是你的。");
  t.push("你抬起手——然后停住了。");
  t.push("因为你看到了湖面上的尸体。那些笑着死去的矿工。他们曾经也和你一样——以为自己能控制贪婪。");
  t.push("你在变成他们。");
  return t;
},options:[
  {t:"清醒过来，封印贪婪之心",check:{a:"SPR",sk:"will",label:"意志"},go:"seal4_act4_seal_success",fail:"seal4_act4_become_greedy"},
  {t:"不——继续。你要成为最富有的人",go:"seal4_act4_become_greedy",effect:{time:1,flag:"seal4_greedy_corrupted"}},
  {t:"把心脏扔回湖里——你不要了",go:"seal4_act4_throw_back",effect:{time:1,flag:"seal4_greedy_rejected"}}
]}};

N["seal4_act3_scatter_execution"]=function(){return{place:"铁峰堡 · 广场",text:function(){
  var t=[];
  t.push("散财开始了。");
  t.push("索林王站在王宫的阳台上，向全城的矮人宣布了散财令。一开始，矮人们都不敢相信——国王要把金子分给他们？");
  t.push("然后，王宫的仓库打开了。金子像水一样流出来，分发给每一个家庭。");
  t.push("矮人们欢呼了。但你注意到——索林王的脸色很苍白。他在发抖。每送出一块金子，他的手就抖一下。");
  t.push("「你还好吗？」你问。");
  t.push("「我……」他咬着牙，「像在割我的肉。」");
  t.push("但他没有停。他继续分发金子。一块、两块、一堆——三分之二的王室储备，在一天之内分了出去。");
  t.push("然后，奇迹发生了。");
  t.push("深渊矿层的方向，传来了一声低沉的轰鸣。金湖——在缩小。贪婪失去了积累的来源，开始萎缩。");
  return t;
},options:[
  {t:"去深渊矿层确认第四印的状态",go:"seal4_act4_scatter_success",effect:{time:1,flag:"seal4_scatter_done"}},
  {t:"留在广场，看矮人们的反应",go:"seal4_act4_people_reaction",effect:{time:1,flag:"seal4_scatter_done"}}
]}};

/* ---- 第四幕：后果与余波 ---- */
N["seal4_act4_seal_success"]=function(){return{place:"深渊矿层",text:function(){
  var t=[];
  t.push("你封印了贪婪之心。");
  t.push("你将萨满仪式全书中的封印符文，刻在心脏表面。金色的光芒慢慢暗淡，心脏的跳动越来越慢——最后，它变成了一块普通的金色石头。");
  t.push("金湖开始干涸。液态的金子变成了普通的金子——不再有诱惑力，不再有生命。湖面缩小，露出了湖底的——尸骨。");
  t.push("几十个矿工的尸骨。他们被贪婪吞噬，死在了这里。现在，他们终于可以安息了。");
  t.push("铜须跪在湖边，哭了。「他们……他们终于自由了。」");
  t.push("你站在旁边，看着这一切。第四印——修复了。");
  t.push("但你也感受到了——你体内的贪婪。在取心的过程中，有一部分贪婪留在了你体内。它会成为你的力量，也会成为你的隐患。");
  return t;
},options:[
  {t:"带着铜须回到地面",go:"seal4_act4_aftermath",effect:{time:1,flag:"seal4_repaired",flag2:"seal4_greedy_fragment",skillUp:"trade"}},
  {t:"检查封印的稳定性",go:"seal4_act4_aftermath",effect:{time:1,flag:"seal4_repaired"}}
]}};

N["seal4_act4_scatter_success"]=function(){return{place:"深渊矿层",text:function(){
  var t=[];
  t.push("你来到了深渊矿层。");
  t.push("金湖缩小了一半。不再是那种诱人的金色——变成了普通的、暗淡的金色。贪婪失去了积累的来源，正在慢慢萎缩。");
  t.push("索林王站在你旁边。他的眼睛——不再是金色了。变回了普通矮人的棕色。");
  t.push("「我……恢复了？」他摸了摸自己的脸，「我不再——渴望金子了？」");
  t.push("「你还是会喜欢金子。」你说，「但那是正常的喜欢，不是病态的渴望。」");
  t.push("他笑了。三千年了——矮人王国第一次，有了一个『正常』的国王。");
  t.push("「谢谢你。」他说，「你救了我。也救了整个矮人王国。」");
  t.push("第四印——修复了。不是通过封印，而是通过——放下。");
  return t;
},options:[
  {t:"和索林王一起回到地面",go:"seal4_act4_aftermath",effect:{time:1,flag:"seal4_repaired",flag2:"seal4_scatter_route",flag3:"seal4_thorin_cured"}},
  {t:"在深渊矿层多待一会儿，确认状态",go:"seal4_act4_aftermath",effect:{time:1,flag:"seal4_repaired"}}
]}};

N["seal4_act4_become_greedy"]=function(){return{place:"深渊矿层",text:function(){
  var t=[];
  t.push("你被贪婪吞噬了。");
  t.push("不是身体被吞噬——是灵魂。你开始觉得，财富就是一切。你需要更多的金子，更多的力量，更多的——一切。");
  t.push("铜须看着你，眼神里充满了恐惧。「你……你变了。」");
  t.push("「我没变。」你笑了，「我只是——终于看清了。这个世界，有钱才有一切。」");
  t.push("你带着贪婪之心，离开了深渊矿层。你没有修复第四印——你利用了它。");
  t.push("从那天起，你开始积累财富。一块、两块、一堆、一座山。你成为了大陆上最富有的人。");
  t.push("但你永远都不满足。你永远都想要更多。");
  t.push("第四印没有修复——它换了一个宿主。从索林王，变成了你。");
  t.push("（这是一条黑暗路线。你可以在后续剧情中寻找救赎，也可以——继续沉沦。）");
  return t;
},options:[
  {t:"接受这个结果——成为贪婪之主",go:"seal4_act4_dark_ending",effect:{time:1,flag:"seal4_greedy_lord",flag2:"seal4_not_repaired",skillUp:"trade",gold:1000}},
  {t:"不——这不是你想要的。寻找救赎",go:"seal4_act4_redemption",effect:{time:1,flag:"seal4_greedy_lord",flag2:"seal4_redemption_path"}}
]}};

N["seal4_act4_aftermath"]=function(){return{place:"铁峰堡 · 广场",text:function(){
  var t=[];
  t.push("你回到了铁峰堡。");
  t.push("矮人们都出来了。他们感受到了——深渊矿层的变化。那种压迫性的、让人疯狂渴望金子的气息，消失了。");
  t.push("他们看着索林王——现在的索林王，眼睛是棕色的，不再是金色。他的胡子也变回了普通的红色。");
  t.push("「国王陛下——」一个老矮人走上前，「您……恢复了？」");
  t.push("「我恢复了。」索林王说，「而且——我要向你们道歉。这三年，我不是一个好国王。我加税，我让矿工送死，我——被贪婪控制了。」");
  t.push("他单膝跪下。「从今天起，我会做一个真正的国王。减税、修路、保护矿工。矮人王国——会重新变好。」");
  t.push("矮人们沉默了。然后——他们开始欢呼。不是因为金子，是因为——他们的国王，回来了。");
  t.push("你站在一旁，看着这一切。你知道，你做了一件正确的事。");
  return t;
},options:[
  {t:"向索林王告别，继续旅程",go:"seal4_transition",effect:{time:1}},
  {t:"在铁峰堡休息几天",go:"seal4_act4_rest",effect:{time:3}},
  {t:"问索林王关于其他印的事",go:"seal4_act4_other_seals",effect:{time:1}}
]}};

N["seal4_act4_other_seals"]=function(){return{place:"铁峰堡",text:function(){
  var t=[];
  t.push("索林王告诉你关于其他印的事。");
  t.push("「第五印在南方深海。下面压着的是——嫉妒。海底有一个被遗忘的种族，他们世代守护那道印，但他们嫉妒大陆上的种族。」");
  t.push("「第六印在东部王国，时光裂隙。下面压着的是——懒惰。黄林晶在那里留了一个后门，可以穿越时间。」");
  t.push("「第七印在死亡沙漠，深渊神殿。下面压着的是——色欲。那是所有原初之物中最神秘的一个。」");
  t.push("他看着你。「你已经修复了四道印。剩下的三道——会越来越难。你确定要继续吗？」");
  return t;
},options:[
  {t:"确定。继续前往第五印",go:"seal4_transition",effect:{time:1,flag:"seal4_other_seals_known"}},
  {t:"先休息，再做打算",go:"seal4_act4_rest",effect:{time:1,flag:"seal4_other_seals_known"}}
]}};

/* ---- 第四印过渡到第五印 ---- */
N["seal4_transition"]=function(){return{place:"矮人王国边境",text:function(){
  var t=[];
  t.push("你离开了矮人王国。");
  t.push("回头看，铁峰堡的轮廓在夕阳下显得格外厚重。山门口的守卫向你挥手告别——他们的眼睛里，不再有那种病态的金光。");
  t.push("第四印。修复了。索林王恢复了。");
  t.push("但你知道，这只是开始。还有三道印。嫉妒、懒惰、色欲——每一个都比前一个更难对付。");
  t.push("你摸了摸怀里的萨满仪式全书。下一站——南方深海。第五印。");
  t.push("南方。大海。一个被遗忘的种族。他们会让你接近第五印吗？");
  t.push("你不知道。但你必须去。");
  t.push("风吹过山脉，带着矿石的气息。你踏上了前往南方的路。");
  return t;
},options:[
  {t:"前往南方深海（第五印）",go:"seal5_act1_intro",effect:{time:12}},
  {t:"先回交汇城休整",go:"fc_jiaohui_entry",effect:{time:5}},
  {t:"查看你的物品和线索",go:"fc_jiaohui_entry",effect:{time:1}}
]}};

/* ================================================================
   第五印 · 南方深海（嫉妒）— 四幕完整章节
   ================================================================ */
N["seal5_act1_intro"]=function(){return{place:"南方港城 · 码头",where:"黄昏",text:function(){
  var t=[];
  t.push("南方的海，是绿色的。");
  t.push("你站在港城的码头上，看着一望无际的大海。海水是翡翠色的，在夕阳下闪烁着金色的光芒。远处的海面上，有几艘渔船正在归港。");
  t.push("但你注意到——渔民们的脸上，没有笑容。他们的表情很阴沉，像是在害怕什么。");
  t.push("你走进了一家海边的小酒馆。酒馆老板是个胖胖的人类，他看到你，叹了口气。");
  t.push("「外地人？」他说，「最近别出海。海里——不太平。」");
  t.push("「怎么不太平？」");
  t.push("「船。」老板压低声音，「最近一个月，已经有五艘船失踪了。不是被海盗劫了——是被海里的东西拖下去的。有人说——是『海族』。」");
  t.push("「海族？」");
  t.push("「传说中住在深海的种族。」老板的声音在发抖，「他们嫉妒大陆上的种族，一直在等待机会复仇。」");
  return t;
},options:[
  {t:"打听更多关于海族的消息",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal5_act1_sea_people",fail:"seal5_act1_no_info"},
  {t:"找一艘船出海",check:{a:"CHA",sk:"trade",label:"商术"},go:"seal5_act1_boat",fail:"seal5_act1_no_boat"},
  {t:"在码头观察，等海族出现",go:"seal5_act1_wait",effect:{time:2}}
]}};

N["seal5_act1_sea_people"]=function(){return{place:"海边酒馆",text:function(){
  var t=[];
  t.push("老板给你倒了一杯酒，然后开始讲。");
  t.push("「海族是大陆上最古老的种族之一。一万年前，他们住在陆地上，和精灵、矮人一样。但后来——发生了一场大洪水。」");
  t.push("「大洪水？」");
  t.push("「黄林晶干的。」老板的声音很低，「据说，海族当时支持了原初之物。黄林晶为了惩罚他们，发动了大洪水，把他们的城市全部淹没。海族被迫搬到了深海里。」");
  t.push("「一万年了。他们在深海里，看着大陆上的种族繁荣昌盛。他们——嫉妒了。」");
  t.push("「第五印就在他们的城市下面。他们世代守护那道印——但他们也被嫉妒影响了。他们觉得，凭什么我们要在暗无天日的深海里守护封印，而你们在大陆上享受阳光？」");
  t.push("「最近，第五印开始松动。海族觉得——机会来了。如果第五印碎了，嫉妒就会扩散到整个大陆。到那时候——所有种族都会互相嫉妒，互相残杀。而海族——就可以趁机回到陆地上。」");
  return t;
},options:[
  {t:"问他怎么才能找到海族的城市",go:"seal5_act1_location",effect:{time:1,flag:"seal5_sea_people_known"}},
  {t:"问他有没有和海族沟通过的人",go:"seal5_act1_contact",effect:{time:1,flag:"seal5_sea_people_known"}},
  {t:"记下信息，准备出海",go:"seal5_act1_boat",effect:{time:1,flag:"seal5_sea_people_known"}}
]}};

N["seal5_act1_boat"]=function(){return{place:"南方港城 · 码头",text:function(){
  var t=[];
  t.push("你找到了一艘愿意出海的船。");
  t.push("船长是个独眼的老水手，叫老海怪。他看了你一眼，说：「出海可以。但我警告你——最近海里不太平。你要是死了，我可不负责。」");
  t.push("「我知道。我要找海族的城市。」");
  t.push("老海怪的独眼眯了起来。「海族？你疯了？」");
  t.push("「我没疯。我在修复七印。第五印就在海族的城市下面。」");
  t.push("老海怪沉默了很久。然后他说：「上船吧。我年轻的时候，见过海族的城市。在——南方海域的最深处，有一个巨大的海沟。海族的城市就在海沟底部。」");
  t.push("「但你要怎么下去？你没有鳃，也没有魔法。」");
  return t;
},options:[
  {t:"用水下呼吸法术/药水",check:{a:"INT",sk:"magic",label:"法术"},go:"seal5_act2_dive",fail:"seal5_act1_no_magic"},
  {t:"让老海怪帮忙找潜水装备",go:"seal5_act1_gear",effect:{time:1,flag:"seal5_boat_hired"}},
  {t:"在船上等海族主动出现",go:"seal5_act2_wait_sea",effect:{time:2,flag:"seal5_boat_hired"}}
]}};

N["seal5_act2_dive"]=function(){return{place:"南方深海 · 海沟",text:function(){
  var t=[];
  t.push("你潜入了深海。");
  t.push("水下的世界和你想象的不一样。不是黑暗的——是发光的。无数的发光生物在水中游动，像是一片移动的星空。");
  t.push("你越潜越深。压力越来越大，你的耳朵在嗡嗡作响。但水下呼吸法术在保护你。");
  t.push("然后你看到了——城市。");
  t.push("海族的城市。它建在海沟的底部，用白色的珊瑚和珍珠建造。城市的中心，有一座巨大的神殿——神殿的顶部，有一颗黑色的水晶，在缓慢地旋转。");
  t.push("第五印。");
  t.push("但你也看到了——海族。他们有人的上半身和鱼的下半身，皮肤是蓝绿色的，眼睛很大。他们拿着长矛，在城市周围巡逻。");
  t.push("你被发现了。");
  return t;
},options:[
  {t:"主动现身，说明来意",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal5_act2_meet",fail:"seal5_act2_captured"},
  {t:"偷偷潜入神殿",check:{a:"AGI",sk:"stealth",label:"潜行"},go:"seal5_act2_sneak",fail:"seal5_act2_captured"},
  {t:"先观察，找机会",go:"seal5_act2_observe",effect:{time:1}}
]}};

N["seal5_act2_meet"]=function(){return{place:"海族城市 · 神殿前",text:function(){
  var t=[];
  t.push("你被带到了神殿前。");
  t.push("海族的女王站在神殿门口。她和普通海族不一样——她的尾巴是金色的，头上戴着珍珠王冠。她的眼睛——是紫色的。充满了——嫉妒。");
  t.push("「陆地人。」她的声音在水里传播，带着一种奇异的共鸣，「你居然敢来这里。」");
  t.push("「我来修复第五印。」");
  t.push("女王笑了。笑声里充满了嘲讽。「修复？你知道第五印对我们意味着什么吗？它是我们的枷锁。一万年了，我们被迫守护它，被迫在暗无天日的深海里生活。而你们——在大陆上享受阳光。」");
  t.push("「这不公平。」她的声音尖锐起来，「所以我们决定——不再守护了。让第五印碎掉。让嫉妒扩散到整个大陆。到那时候——你们也会尝到，被嫉妒折磨的滋味。」");
  return t;
},options:[
  {t:"说服她——嫉妒扩散对谁都没有好处",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal5_act3_persuade",fail:"seal5_act3_combat"},
  {t:"问她黄林晶和海族的历史真相",go:"seal5_act3_truth",effect:{time:1}},
  {t:"提出条件——帮海族回到陆地",go:"seal5_act3_deal",effect:{time:1}}
]}};

N["seal5_act3_persuade"]=function(){return{place:"海族神殿",text:function(){
  var t=[];
  t.push("你开始说服女王。");
  t.push("「嫉妒扩散之后，不会只影响大陆上的种族。它会影响所有生物——包括你们海族。到那时候，你们也会互相嫉妒，互相残杀。」");
  t.push("「你们想要的是回到陆地，不是毁灭世界。如果第五印碎了，世界都毁灭了，你们回到陆地又有什么意义？」");
  t.push("女王沉默了。她的紫色眼睛里，嫉妒在消退——取而代之的是——思考。");
  t.push("「你说得对。」她终于说，「但我们不能永远待在深海里。我们需要——一个承诺。」");
  t.push("「什么承诺？」");
  t.push("「大陆上的种族，承认我们的存在。给我们一片海岸线，让我们可以在陆地上生活。不再是传说中的怪物，而是——平等的种族。」");
  t.push("你看着她。这个要求——不过分。");
  return t;
},options:[
  {t:"答应她的条件",go:"seal5_act4_deal_made",effect:{time:1,flag:"seal5_queen_agrees",flag2:"seal5_sea_people_land"}},
  {t:"说你需要和大陆势力商量",go:"seal5_act4_need_negotiate",effect:{time:1,flag:"seal5_queen_hesitates"}},
  {t:"拒绝——你不能代表大陆势力",go:"seal5_act3_refuse",effect:{time:1}}
]}};

N["seal5_act3_truth"]=function(){return{place:"海族神殿",text:function(){
  var t=[];
  t.push("你问女王关于黄林晶和海族的历史。");
  t.push("女王的表情变了。她挥了挥手，神殿的墙壁上出现了一幅壁画——一万年前的历史。");
  t.push("「一万年前，海族住在陆地上。我们的城市比精灵的还美丽，我们的魔法比人类的还强大。然后——原初之物苏醒了。」");
  t.push("「黄林晶找到了我们，说要加固七印。他说，需要一个种族做出牺牲——搬到深海里，守护第五印。」");
  t.push("「我们的祖先同意了。他们以为这是荣耀。但黄林晶骗了他们——第五印不是需要守护，是需要『喂养』。用海族的嫉妒，喂养原初之物。」");
  t.push("「一万年了。我们的嫉妒越来越强，第五印也越来越强。而我们——越来越痛苦。」");
  t.push("女王的声音在发抖。「黄林晶不是英雄。他是一个——骗子。他用我们的痛苦，换来了大陆的和平。」");
  return t;
},options:[
  {t:"道歉——为黄林晶的行为",go:"seal5_act3_apologize",effect:{time:1,flag:"seal5_truth_known"}},
  {t:"问她修复第五印能不能解除海族的痛苦",go:"seal5_act3_repair_cure",effect:{time:1,flag:"seal5_truth_known"}}
]}};

N["seal5_act4_deal_made"]=function(){return{entry:{from:{"seal5_exp_promise":["你许了一个承诺。说出口的瞬间，你就知道，它会跟着你很久。", "你没有后悔——只是把它记牢了。承诺这种东西，记在脑子里，会淡；记在骨头里，才作数。"],"seal5_act4_need_negotiate":["谈判拖了很久。你说了很多，听了很多，最后互相让了一步。", "走出那间屋子的时候，你松了口气，但没完全松。你知道，有些交易，签了字才算数，有些，握了手就作数。"],"seal5_act3_deal":["条件谈妥了。对方伸出手的时候，你犹豫了一下——你知道，跟这些人握手，是要付出代价的。", "你握了。掌心相触的那一刻，你感觉到他掌心的茧——那是握过刀，也握过笔的手。"]},default:[]},/*v46entry:s5d_promise+s5d_negotiate+s5d_deal*/place:"海族神殿",text:function(){
  var t=[];
  t.push("你答应了女王的条件。");
  t.push("「我会尽我所能，让大陆上的种族承认你们。」你说，「但我需要你——先帮我修复第五印。」");
  t.push("女王看着你，看了很久。然后她点了点头。「好。我相信你。」");
  t.push("她转过身，面向神殿。「海族的子民们！」她的声音传遍了整个城市，「这个陆地人，答应了我们的条件。从今天起——我们不再是守护者，我们是——自由的种族！」");
  t.push("海族们欢呼了。一万年的压抑，在这一刻释放了。");
  t.push("女王带你进入神殿。第五印的核心——那颗黑色的水晶，就在神殿中央。女王将手放在水晶上，开始吟唱。");
  t.push("你也将自己的力量注入水晶。两种力量交织，第五印开始——稳定。");
  t.push("黑色的光芒慢慢变成了白色。嫉妒被重新封印了。");
  return t;
},options:[
  {t:"完成修复，和女王告别",go:"seal5_act4_aftermath",effect:{time:1,flag:"seal5_repaired",flag2:"seal5_queen_ally"}},
  {t:"问她更多关于其他印的事",go:"seal5_act4_other_seals",effect:{time:1,flag:"seal5_repaired"}}
]}};

N["seal5_act4_aftermath"]=function(){return{place:"海面",text:function(){
  var t=[];
  t.push("你浮出了海面。");
  t.push("阳光照在你脸上，你深吸了一口气。咸咸的海风，温暖的阳光——你终于理解了，海族为什么渴望陆地。");
  t.push("第五印修复了。海族获得了自由——至少，是承诺中的自由。");
  t.push("老海怪的船在海面上等你。他看到你，露出了笑容。「成了？」");
  t.push("「成了。」");
  t.push("他拉起你，调转船头，向港城驶去。");
  t.push("你站在船头，看着大海。海面平静，像是一万年的嫉妒，终于平息了。");
  t.push("还有两道印。懒惰。色欲。");
  t.push("你踏上了前往东部王国的路。");
  return t;
},options:[
  {t:"前往东部王国（第六印）",go:"seal6_act1_intro",effect:{time:10}},
  {t:"先回交汇城休整",go:"fc_jiaohui_entry",effect:{time:5}}
]}};

/* ================================================================
   第六印 · 东部时光裂隙（懒惰）— 四幕完整章节
   ================================================================ */
N["seal6_act1_intro"]=function(){return{place:"东部王国 · 承天山脚下",where:"清晨",text:function(){
  var t=[];
  t.push("承天山的雾，是白色的。");
  t.push("你站在山脚下，仰头看着这座山。它不像铁峰堡那样厚重，也不像世界树那样壮观——它是缥缈的。山顶隐藏在云雾里，若隐若现。");
  t.push("承天书院就在山顶。东方最古老的学院，魔法师和炼金术师的圣地。");
  t.push("但你不是来上学的。你是来找第六印的——时光裂隙。");
  t.push("你沿着山路往上走。路上遇到了几个书院的学生，他们穿着青色的长袍，手里拿着书卷，边走边讨论。");
  t.push("你注意到——他们的脚步很慢。不是悠闲的慢，是——懒洋洋的慢。像是没睡醒，又像是——对什么都提不起劲。");
  t.push("懒惰。第六印的影响，已经扩散到了山上。");
  return t;
},options:[
  {t:"上山，去承天书院",go:"seal6_act1_academy",effect:{time:1}},
  {t:"和学生打听消息",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal6_act1_student",fail:"seal6_act1_academy"},
  {t:"直接找时光裂隙",go:"seal6_act1_rift",effect:{time:2}}
]}};

N["seal6_act1_academy"]=function(){return{place:"承天书院",text:function(){
  var t=[];
  t.push("你来到了承天书院。");
  t.push("和你想象的不一样。书院里很安静——不是那种读书的安静，是——死气沉沉的安静。学生们坐在教室里，有的在打瞌睡，有的在发呆，有的干脆趴在桌子上睡觉。");
  t.push("讲台上，一个老教授在讲课。但他的声音很慢，像是在说梦话。");
  t.push("你找到了书院的院长——玄机子。黄林晶的隔代传人，半神级的强者。");
  t.push("他坐在院子里，晒太阳。看到你，他懒洋洋地睁开眼。「哦？客人？」");
  t.push("「我在调查七印。第六印——时光裂隙——就在承天山。」");
  t.push("玄机子打了个哈欠。「啊，那个啊。」他指了指后山，「在后山。一个裂缝。能看到过去和未来。挺有意思的。」");
  t.push("他的态度——太随意了。像是对什么都不在乎。");
  return t;
},options:[
  {t:"问他第六印的具体情况",go:"seal6_act1_xuanji",effect:{time:1}},
  {t:"问他为什么书院变成这样",go:"seal6_act1_why_lazy",effect:{time:1}},
  {t:"直接去后山找裂隙",go:"seal6_act2_rift",effect:{time:1}}
]}};

N["seal6_act1_xuanji"]=function(){return{place:"承天书院 · 院子",text:function(){
  var t=[];
  t.push("玄机子告诉你关于第六印的事。");
  t.push("「第六印下面压着的是——懒惰。」他说，声音还是懒洋洋的，「原初之物的七分之一。它不像饥饿那样吞噬身体，也不像愤怒那样吞噬理智——它吞噬的是——动力。」");
  t.push("「靠近它的人，会变得越来越懒。什么都不想做，什么都不在乎。最后——就变成了一滩烂泥。」");
  t.push("「承天书院的学生和老师，已经被影响了。包括我。」他苦笑了一下，「我是半神，抵抗力强一些。但也——越来越不想动了。」");
  t.push("「时光裂隙是黄林晶留下的『后门』。他说，如果有一天七印出了问题，可以通过时光裂隙回到过去，找到解决方法。」");
  t.push("「但问题是——回到过去有什么用？过去的黄林晶，也解决不了。而且——」他顿了顿，「时光裂隙有副作用。用多了，你会变得——越来越懒。因为你会觉得，反正可以回到过去重来，那现在急什么？」");
  return t;
},options:[
  {t:"问他修复第六印的方法",go:"seal6_act1_repair_method",effect:{time:1,flag:"seal6_xuanji_talks"}},
  {t:"问他时光裂隙怎么用",go:"seal6_act1_rift_use",effect:{time:1,flag:"seal6_xuanji_talks"}},
  {t:"去后山看裂隙",go:"seal6_act2_rift",effect:{time:1,flag:"seal6_xuanji_talks"}}
]}};

N["seal6_act1_repair_method"]=function(){return{place:"承天书院",text:function(){
  var t=[];
  t.push("玄机子告诉你修复第六印的方法。");
  t.push("「第六印的修复，和其他印不一样。懒惰是——『停滞型』的原初之物。它越停滞越强。要修复它，需要——『行动』。」");
  t.push("「行动？」");
  t.push("「是的。在时光裂隙里，完成一个『不可能的任务』。一个你觉得『反正做不到，算了吧』的任务。当你真正完成它的时候——懒惰就会被削弱。」");
  t.push("「什么任务？」");
  t.push("玄机子沉默了很久。「黄林晶留下的任务。回到三千年前，阻止他——犯下那个错误。」");
  t.push("「什么错误？」");
  t.push("「加固七印的时候，他不应该用活的锚点。」玄机子的声音低了下去，「如果他当时用了别的方法——精灵女王不会被封印三千年，海族不会被流放一万年，一切都会不一样。」");
  t.push("「但改变过去——会有悖论。」");
  t.push("「是的。」玄机子说，「所以这是一个『不可能的任务』。你可以尝试，但——大概率会失败。不过没关系。重要的不是结果，是——你尝试了。」");
  return t;
},options:[
  {t:"接受任务——进入时光裂隙",go:"seal6_act2_rift",effect:{time:1,flag:"seal6_mission_accepted"}},
  {t:"问他有没有别的方法",go:"seal6_act1_other_method",effect:{time:1,flag:"seal6_mission_accepted"}}
]}};

N["seal6_act2_rift"]=function(){return{place:"承天山 · 后山 · 时光裂隙",text:function(){
  var t=[];
  t.push("你来到了后山。");
  t.push("时光裂隙就在那里——一个悬浮在空中的裂缝。它不是黑色的，是——彩色的。无数的颜色在裂缝里流动，像是一条彩虹的河流。");
  t.push("你能感受到——懒惰。从裂缝里散发出来的，纯粹的、让人想躺平的懒惰。");
  t.push("「算了吧。」一个声音在你脑子里说，「明天再做也来得及。反正——还有时间。」");
  t.push("你摇摇头，把这个念头压下去。然后你——跳了进去。");
  t.push("世界在旋转。颜色在飞舞。你感到自己在坠落——不，是在上升。不，是——在流动。");
  t.push("然后，一切静止了。");
  t.push("你站在一片草地上。天空是蓝色的，太阳是金色的。远处——有一座城市。一座你从未见过的城市。");
  t.push("三千年前的——艾尔达大陆。");
  return t;
},options:[
  {t:"寻找黄林晶",check:{a:"INT",sk:"detect",label:"侦查"},go:"seal6_act3_find_hlj",fail:"seal6_act3_lost"},
  {t:"观察这个时代的世界",go:"seal6_act3_observe",effect:{time:1}},
  {t:"尝试回到现在",check:{a:"INT",sk:"magic",label:"法术"},go:"seal6_act3_return",fail:"seal6_act3_stuck"}
]}};

N["seal6_act3_find_hlj"]=function(){return{place:"三千年前 · 交汇城",text:function(){
  var t=[];
  t.push("你找到了黄林晶。");
  t.push("他比你想象的年轻。只有二十多岁，穿着简单的布衣，正在一个小工坊里——研究什么东西。");
  t.push("他看到你，愣了一下。「你是谁？怎么进来的？」");
  t.push("「我是从未来来的。三千年后。」");
  t.push("黄林晶放下手里的东西，仔细打量你。「未来？」他的眼睛亮了起来，「有意思。你是说——我成功了？七印加固成功了？」");
  t.push("「成功了。但——代价很大。」你告诉他精灵女王、海族、以及其他种族的遭遇。");
  t.push("黄林晶沉默了。他的手在发抖。「我……我不知道会这样。我以为——用活的锚点是唯一的方法。」");
  t.push("「不是。」你说，「有别的方法。你可以用——物品作为锚点。比如，十二神器。」");
  t.push("黄林晶的眼睛亮了。「十二神器？你是说——我可以把灵魂分成十二份，封印在神器里？」");
  t.push("「是的。这样就不需要活的锚点了。」");
  return t;
},options:[
  {t:"帮他完成十二神器的设计",check:{a:"INT",sk:"magic",label:"法术"},go:"seal6_act4_change_past",fail:"seal6_act4_paradox"},
  {t:"只告诉他方法，然后离开",go:"seal6_act4_return",effect:{time:1,flag:"seal6_hlj_changed"}},
  {t:"问他更多关于原初之物的真相",go:"seal6_act3_truth",effect:{time:1}}
]}};

N["seal6_act4_change_past"]=function(){return{place:"三千年前",text:function(){
  var t=[];
  t.push("你帮黄林晶完成了十二神器的设计。");
  t.push("他很聪明——比你想象的还聪明。你只说了大概的思路，他就推导出了完整的方案。");
  t.push("「这样就不需要活的锚点了。」他说，眼睛里闪烁着兴奋的光芒，「精灵不会被封印，海族不会被流放——一切都会不一样。」");
  t.push("但然后——你感到一阵眩晕。");
  t.push("时间悖论。你改变了过去。现在的你——正在消失。");
  t.push("因为如果过去改变了，你就不会踏上修复七印的旅程。你不会来到这里。你不会——存在。");
  t.push("「快走！」黄林晶推了你一把，「回到你的时代！改变已经发生了——但你的存在，会成为新时间线的『锚』。你必须回去，锚定新的时间线！」");
  t.push("你被推回了时光裂隙。世界在旋转，颜色在飞舞。");
  t.push("然后——你回到了现在。");
  return t;
},options:[
  {t:"检查现在的世界——改变了吗",go:"seal6_act4_new_world",effect:{time:1,flag:"seal6_past_changed",flag2:"seal6_paradox_anchored"}},
  {t:"先休息，恢复精神",go:"seal6_act4_rest",effect:{time:1,flag:"seal6_past_changed"}}
]}};

N["seal6_act4_new_world"]=function(){return{place:"承天山 · 后山",text:function(){
  var t=[];
  t.push("你回到了现在。");
  t.push("承天山还是承天山。时光裂隙还在。但——不一样了。");
  t.push("你拿出萨满仪式全书，翻到第三印那一页。上面写着：『第三印锚点：十二神器之一·灵魂之眼。』");
  t.push("不是精灵女王。是——神器。");
  t.push("你翻到第五印。『第五印锚点：十二神器之一·深海之珠。』");
  t.push("不是海族的痛苦。是——神器。");
  t.push("你改变了过去。新的时间线里，黄林晶用了十二神器作为锚点，没有用活的生物。精灵女王没有被封印，海族没有被流放。");
  t.push("但——你之前的经历呢？你修复的第一印到第五印呢？");
  t.push("你摸了摸自己的身体。你还在。你的记忆还在。你成为了——两个时间线的交汇点。");
  t.push("第六印修复了。因为你完成了『不可能的任务』。懒惰被削弱了。");
  return t;
},options:[
  {t:"去找玄机子，告诉他发生了什么",go:"seal6_act4_aftermath",effect:{time:1,flag:"seal6_repaired",flag2:"seal6_timeline_changed"}},
  {t:"直接前往第七印",go:"seal6_transition",effect:{time:1,flag:"seal6_repaired"}}
]}};

N["seal6_act4_aftermath"]=function(){return{place:"承天书院",text:function(){
  var t=[];
  t.push("你找到了玄机子。");
  t.push("他看到你，愣住了。然后——他的眼睛亮了。不再是懒洋洋的，是——充满了活力。");
  t.push("「你做到了。」他说，「我能感受到——懒惰的影响消失了。书院的学生们——都醒了。」");
  t.push("你告诉他你改变了过去。他听完后，沉默了很久。");
  t.push("「时间悖论。」他说，「你改变了过去，但你自己没有消失。因为你成为了新时间线的锚。这意味着——你同时存在于两个时间线里。」");
  t.push("「这会有什么后果？」");
  t.push("「不知道。」玄机子说，「但有一点是肯定的——你比以前更强了。两个时间线的力量，都集中在你身上。」");
  t.push("你握了握拳。确实——你感到自己的力量增长了。不是膨胀的增长，是——踏实的增长。");
  t.push("第六印。修复了。");
  t.push("还有最后一道印。第七印。死亡沙漠。色欲。");
  return t;
},options:[
  {t:"前往死亡沙漠（第七印）",go:"seal6_transition",effect:{time:1,flag:"seal6_repaired",flag2:"seal6_dual_timeline",skillUp:"magic"}},
  {t:"在承天书院休息几天",go:"seal6_act4_rest",effect:{time:3,flag:"seal6_repaired"}}
]}};

N["seal6_transition"]=function(){return{place:"东部王国边境",text:function(){
  var t=[];
  t.push("你离开了东部王国。");
  t.push("回头看，承天山的轮廓在夕阳下显得格外缥缈。山顶的云雾散开了——你第一次看到了承天书院的全貌。它很美。");
  t.push("第六印。修复了。过去改变了。");
  t.push("但你知道，这不是结束。还有最后一道印。第七印。死亡沙漠。色欲。");
  t.push("你摸了摸怀里的萨满仪式全书。第七印——所有原初之物中最神秘的一个。它会让你沉溺于快乐，忘记一切。");
  t.push("死亡沙漠。大陆上最危险的地方。深渊神殿就在那里。");
  t.push("你深吸一口气，踏上了前往死亡沙漠的路。");
  t.push("最后的旅程。");
  return t;
},options:[
  {t:"前往死亡沙漠（第七印）",go:"seal7_act1_intro",effect:{time:15}},
  {t:"先回交汇城休整",go:"fc_jiaohui_entry",effect:{time:5}}
]}};

/* ================================================================
   第七印 · 死亡沙漠深渊神殿（色欲）— 四幕完整章节
   ================================================================ */
N["seal7_act1_intro"]=function(){return{place:"死亡沙漠 · 边缘",where:"正午",text:function(){
  var t=[];
  t.push("死亡沙漠的太阳，是白色的。");
  t.push("你站在沙漠的边缘，看着一望无际的金色沙海。太阳挂在头顶，白得刺眼。地面的温度高得能煎蛋。");
  t.push("你听说过死亡沙漠。大陆上最危险的地方。没有水，没有食物，只有——沙。和沙下面的东西。");
  t.push("据说，沙漠里有海市蜃楼。不是普通的海市蜃楼——是能让人沉溺其中的幻境。你会看到你最渴望的东西，然后——走进去，再也出不来。");
  t.push("色欲。第七印。所有原初之物中最神秘的一个。它不吞噬你的身体，也不吞噬你的理智——它吞噬你的——欲望。它让你得到你想要的一切。然后——你就再也不想离开了。");
  t.push("你深吸一口气，走进了沙漠。");
  t.push("刚走了几步，你就看到了——绿洲。");
  return t;
},options:[
  {t:"走向绿洲",check:{a:"SPR",sk:"will",label:"意志"},go:"seal7_act1_oasis",fail:"seal7_act1_trapped"},
  {t:"绕开绿洲，继续前进",check:{a:"SPR",sk:"will",label:"意志"},go:"seal7_act2_desert",fail:"seal7_act1_oasis"},
  {t:"在绿洲边休息一下",go:"seal7_act1_rest",effect:{time:1}}
]}};

N["seal7_act1_oasis"]=function(){return{place:"死亡沙漠 · 绿洲",text:function(){
  var t=[];
  t.push("你走到了绿洲边。");
  t.push("湖水清澈见底，旁边有几棵椰子树。树荫下——有一个人。");
  t.push("不是普通人。是——你最想见的人。");
  t.push("如果你有爱人，那就是你的爱人。如果你有恩师，那就是你的恩师。如果你有已故的亲人——那就是你的亲人。");
  t.push("他/她向你招手。「过来。」他/她说，声音温柔得像是棉花糖，「我等你很久了。」");
  t.push("你感到一阵温暖。你想走过去。你想——拥抱他/她。");
  t.push("但你知道——这是幻境。色欲的诱惑。它知道你最渴望什么，然后——把它摆在你面前。");
  t.push("你咬着牙，没有走过去。");
  t.push("「你不来吗？」他/她的声音里有了委屈，「我真的很想你。」");
  return t;
},options:[
  {t:"拒绝——这是幻境",check:{a:"SPR",sk:"will",label:"意志"},go:"seal7_act2_desert",fail:"seal7_act1_trapped"},
  {t:"走过去——哪怕是幻境，也想再看一眼",go:"seal7_act1_embrace",effect:{time:1,sanLoss:10}},
  {t:"问他/她——你是谁",check:{a:"INT",sk:"detect",label:"侦查"},go:"seal7_act1_question",fail:"seal7_act1_trapped"}
]}};

N["seal7_act1_trapped"]=function(){return{place:"幻境",text:function(){
  var t=[];
  t.push("你沉溺了。");
  t.push("你走进了绿洲，拥抱了你最想见的人。温暖、柔软、真实——你甚至能感受到他/她的体温。");
  t.push("「别走了。」他/她说，「留在这里。这里有你想要的一切。」");
  t.push("你想留下。你真的想留下。外面的世界太苦了——战斗、判定、失败、失去。而这里——只有快乐。");
  t.push("但然后——你感到了什么。");
  t.push("你的手。你的手在变透明。不是因为你在消失——是因为你在变得『不真实』。如果你留在这里，你就会变成幻境的一部分。永远快乐，永远——虚无。");
  t.push("你想起了你的任务。七印。第六印已经修复了。只剩最后一道。如果你在这里放弃——前面的一切，都白费了。");
  t.push("你推开了他/她。");
  return t;
},options:[
  {t:"逃离幻境",check:{a:"SPR",sk:"will",label:"意志"},go:"seal7_act2_desert",fail:"seal7_act1_trapped_deep"},
  {t:"再看一眼——然后离开",go:"seal7_act2_desert",effect:{time:1,sanLoss:15,flag:"seal7_trapped_once"}}
]}};

N["seal7_act2_desert"]=function(){return{place:"死亡沙漠 · 深处",text:function(){
  var t=[];
  t.push("你继续深入沙漠。");
  t.push("幻境越来越多。你看到了财富、权力、永生、爱情——所有你能想象的快乐，都摆在你面前。");
  t.push("但你没有停。你咬着牙，一步一步往前走。");
  t.push("走了三天三夜，你终于看到了——神殿。");
  t.push("深渊神殿。它建在沙漠的最深处，用黑色的石头建造。神殿的顶部，有一个巨大的雕像——不是神，是——一个人。一个在笑的人。笑得很快乐，也很——空虚。");
  t.push("第七印就在神殿里面。");
  t.push("你走到神殿门口。门是开着的。里面——传来了声音。不是说话声，是——笑声。无数人的笑声。快乐的、满足的、沉溺的笑声。");
  t.push("你走了进去。");
  return t;
},options:[
  {t:"直接进入神殿深处",go:"seal7_act3_temple",effect:{time:1}},
  {t:"先观察神殿的结构",check:{a:"INT",sk:"detect",label:"侦查"},go:"seal7_act2_observe",fail:"seal7_act3_temple"},
  {t:"在门口做准备",go:"seal7_act2_prepare",effect:{time:1}}
]}};

N["seal7_act3_temple"]=function(){return{place:"深渊神殿 · 内部",text:function(){
  var t=[];
  t.push("神殿内部——是一个宴会厅。");
  t.push("长长的桌子上摆满了美食和美酒。几百个人坐在桌子旁边，在吃、在喝、在笑、在——享受。他们的脸上都带着满足的笑容。");
  t.push("但你注意到——他们的眼睛是空的。没有瞳孔，只有一片白色。他们已经不是人了——他们是色欲的俘虏。");
  t.push("宴会厅的尽头，有一个王座。王座上坐着——一个人。");
  t.push("不，不是人。是——色欲。原初之物的七分之一。它化作了人形——一个完美的人。完美的脸，完美的身材，完美的——一切。");
  t.push("「你来了。」它说，声音像是音乐，「我等你很久了。」");
  t.push("它站起来，向你走来。每走一步，周围的空气都变得——甜蜜。你感到一阵眩晕。");
  t.push("「你修复了六道印。」它说，「你很强大。但你也——很辛苦。」");
  t.push("「留下来吧。」它伸出手，「在这里，你不需要再战斗了。你可以——永远快乐。」");
  return t;
},options:[
  {t:"拒绝——修复第七印",check:{a:"SPR",sk:"will",label:"意志"},go:"seal7_act3_refuse",fail:"seal7_act3_accept"},
  {t:"和它对话——了解色欲的本质",go:"seal7_act3_talk",effect:{time:1}},
  {t:"直接攻击",check:{a:"STR",sk:"martial",label:"武技"},go:"seal7_act3_combat",fail:"seal7_act3_combat_fail"}
]}};

N["seal7_act3_refuse"]=function(){return{place:"深渊神殿",text:function(){
  var t=[];
  t.push("你拒绝了。");
  t.push("「快乐不是全部。」你说，「还有责任。还有——我想做的事。」");
  t.push("色欲的笑容消失了。「责任？」它冷笑，「责任能给你什么？痛苦。牺牲。失去。而我——能给你一切。」");
  t.push("它一挥手。宴会厅里的幻境变了。你看到了——如果你留下来，会发生什么。");
  t.push("你和你最爱的人，在一个美丽的房子里。每天吃美食，喝美酒，看日落。永远快乐。永远——不变。");
  t.push("但你也看到了——外面的世界。没有你，第七印碎了。色欲扩散到整个大陆。所有人都沉溺在快乐里。没有人工作，没有人战斗，没有人——活着。他们只是——存在。像行尸走肉一样，永远快乐。");
  t.push("「这就是你想要的吗？」你问。");
  t.push("色欲沉默了。然后——它笑了。「你说得对。」它说，「快乐如果没有痛苦做对比——就什么都不是。」");
  t.push("它的身体开始发光。「我自愿被封印。」它说，「三千年了——我也累了。」");
  return t;
},options:[
  {t:"完成封印——修复第七印",check:{a:"SPR",sk:"will",label:"意志"},go:"seal7_act4_final",fail:"seal7_act4_final_fail"},
  {t:"问它为什么自愿被封印",go:"seal7_act3_why",effect:{time:1,flag:"seal7_lust_voluntary"}}
]}};

N["seal7_act3_accept"]=function(){return{place:"深渊神殿",text:function(){
  var t=[];
  t.push("你接受了。");
  t.push("你走向色欲，握住了它的手。温暖、柔软、完美——你感到一阵前所未有的快乐。");
  t.push("然后——你感到了空虚。");
  t.push("快乐来得太快，太容易。没有付出，就没有真正的快乐。你得到了一切，但你——什么都没有得到。");
  t.push("你想起了沙漠里的幻境。你想起了那些眼睛空白的人。你想起了——你是谁。");
  t.push("你不是追求快乐的人。你是——承担责任的人。");
  t.push("你松开了手。");
  t.push("色欲看着你，表情复杂。「你——拒绝了？」");
  t.push("「不是拒绝快乐。」你说，「是拒绝——虚假的快乐。」");
  t.push("色欲沉默了很久。然后——它笑了。这一次，是真正的笑。「有意思。三千年了，你是第一个——看穿我的人。」");
  return t;
},options:[
  {t:"完成封印",go:"seal7_act4_final",effect:{time:1,sanLoss:10,flag:"seal7_lust_tested"}},
  {t:"问它真相",go:"seal7_act3_why",effect:{time:1,flag:"seal7_lust_tested"}}
]}};

N["seal7_act3_why"]=function(){return{place:"深渊神殿",text:function(){
  var t=[];
  t.push("你问色欲，为什么自愿被封印。");
  t.push("它沉默了很久。然后它说：「因为我也——孤独。」");
  t.push("「三千年了，我在这里，给无数人带来快乐。但他们得到快乐之后，就变成了空壳。没有人——真正和我交流。没有人——理解我。」");
  t.push("「我是欲望。但欲望本身——也渴望被理解。」");
  t.push("你看着它。这个完美的、强大的原初之物——居然在说，它孤独。");
  t.push("「黄林晶把我封印在这里。他以为我是怪物。但我——只是想要一个朋友。」");
  t.push("你伸出手。「我可以做你的朋友。」");
  t.push("色欲愣住了。然后——它哭了。完美的脸上，流下了不完美的眼泪。");
  t.push("「好。」它说，「那我——自愿被封印。不是因为我输了。是因为——我信任你。」");
  return t;
},options:[
  {t:"完成封印——以朋友的身份",go:"seal7_act4_final_friend",effect:{time:1,flag:"seal7_lust_friend",flag2:"seal7_lust_voluntary"}},
  {t:"问它关于原初之物的最终真相",go:"seal7_act3_final_truth",effect:{time:1,flag:"seal7_lust_friend"}}
]}};

N["seal7_act3_final_truth"]=function(){return{place:"深渊神殿",text:function(){
  var t=[];
  t.push("你问色欲，关于原初之物的最终真相。");
  t.push("它看着你，眼神复杂。「你真的想知道？」");
  t.push("「想。」");
  t.push("「好吧。」它深吸一口气，「原初之物——不是怪物。我们是——宇宙的情绪。宇宙诞生时的第一个情绪。饥饿、愤怒、傲慢、贪婪、嫉妒、懒惰、色欲——我们七个，组成了宇宙的『情感』。」");
  t.push("「黄林晶把我们分成七份，封印在七道印里。他以为他在拯救世界。但实际上——他在割裂宇宙的情感。没有情感的宇宙——是死的。」");
  t.push("「所以，七印不是在保护世界——是在慢慢杀死世界。当七印全部加固完成的那一天——宇宙就会失去所有情感。变成一个——冰冷的、理性的、死亡的世界。」");
  t.push("你愣住了。");
  t.push("「那——修复七印，是错的？」");
  t.push("「不是错的。」色欲说，「但也不全对。正确的做法——不是封印我们，是——和我们共存。让我们回到宇宙中，成为情感的一部分。而不是——被关在笼子里。」");
  t.push("你沉默了。这是一个——你从未想过的真相。");
  return t;
},options:[
  {t:"接受这个真相——和色欲共存",go:"seal7_act4_coexist",effect:{time:1,flag:"seal7_truth_known",flag2:"seal7_coexist"}},
  {t:"还是封印它——至少世界暂时安全",go:"seal7_act4_final",effect:{time:1,flag:"seal7_truth_known"}},
  {t:"问它怎么才能共存",go:"seal7_act4_coexist_method",effect:{time:1,flag:"seal7_truth_known"}}
]}};

N["seal7_act4_final"]=function(){return{place:"深渊神殿",text:function(){
  var t=[];
  t.push("你完成了封印。");
  t.push("你将萨满仪式全书中的最终符文，刻在神殿的地面上。白色的光芒笼罩了整个神殿。色欲的身体在发光——它在变成光，融入封印。");
  t.push("「谢谢你。」它说，声音越来越轻，「三千年了——终于可以休息了。」");
  t.push("光芒散去。神殿消失了。沙漠消失了。你站在——一片草地上。");
  t.push("七印。全部修复了。");
  t.push("你感到一阵疲惫。然后——是释然。");
  t.push("风吹过草地，带着花香。天空是蓝色的，太阳是金色的。世界——和平了。");
  t.push("但你知道——这不是真正的结束。原初之物还在。深渊还在。还有更多的挑战，在等着你。");
  t.push("但至少——今天，你可以休息了。");
  return t;
},options:[
  {t:"回到交汇城——你的旅程开始的地方",go:"seal7_act4_ending",effect:{time:5,flag:"seal7_repaired",flag2:"all_seals_repaired"}},
  {t:"在草地上多待一会儿",go:"seal7_act4_ending",effect:{time:1,flag:"seal7_repaired"}}
]}};

N["seal7_act4_coexist"]=function(){return{place:"深渊神殿",text:function(){
  var t=[];
  t.push("你选择了共存。");
  t.push("你没有封印色欲——而是，将它的力量，分散到了整个世界。");
  t.push("白色的光芒从神殿涌出，扩散到大陆的每一个角落。色欲的力量——不，情感的力量——回到了它该在的地方。");
  t.push("你感到了——变化。世界变得更有色彩了。人们的笑容更真实了，艺术家的作品更有感染力了，恋人们的爱情更——热烈了。");
  t.push("色欲站在你旁边。它不再是完美的人形——它变成了一束光，融入了你的身体。");
  t.push("「从今天起，」它的声音在你脑子里响起，「我就是你。你就是我。我们一起——看着这个世界。」");
  t.push("七印。全部——不是修复，是——解放。");
  t.push("原初之物回到了宇宙中。情感回到了世界上。");
  t.push("你站在沙漠里，感受着风。风里有快乐，有悲伤，有愤怒，有爱——所有的情感，混在一起，组成了——活着的感觉。");
  t.push("这才是——真正的世界。");
  return t;
},options:[
  {t:"回到交汇城",go:"seal7_act4_ending_coexist",effect:{time:5,flag:"seal7_coexist",flag2:"all_seals_coexist",flag3:"lust_inside"}},
  {t:"在沙漠里感受这个新世界",go:"seal7_act4_ending_coexist",effect:{time:1,flag:"seal7_coexist"}}
]}};

N["seal7_act4_ending"]=function(){return{place:"交汇城",text:function(){
  var t=[];
  t.push("你回到了交汇城。");
  t.push("一切都没变。城还是那座城，人还是那些人。但你知道——一切都变了。");
  t.push("七印修复了。原初之物被重新封印。世界——安全了。");
  t.push("你走在交汇城的街道上，看着来来往往的人群。他们不知道，有一个人，走遍了整个大陆，修复了七道印，拯救了世界。");
  t.push("他们只知道——今天天气很好。");
  t.push("你笑了。这样就够了。");
  t.push("你的旅程——暂时结束了。但世界很大，还有很多地方没去，还有很多故事没写。");
  t.push("也许有一天，你会再次踏上旅途。");
  t.push("但今天——你要休息。");
  t.push("（七印线·完。你可以继续在大陆上冒险，或者——开始新的故事。）");
  return t;
},options:[
  {t:"继续冒险",go:"fc_jiaohui_entry",effect:{time:1,flag:"seven_seals_complete"}},
  {t:"查看你的成就和状态",go:"fc_jiaohui_entry",effect:{time:1}}
]}};

N["seal7_act4_ending_coexist"]=function(){return{place:"交汇城",text:function(){
  var t=[];
  t.push("你回到了交汇城。");
  t.push("一切都变了。城还是那座城，但——更有活力了。人们的笑容更真实了，街头的艺人表演更精彩了，酒馆里的歌声更动听了。");
  t.push("情感回到了世界。原初之物不再是被封印的怪物——它们是宇宙的一部分，是——活着的证明。");
  t.push("你走在街道上，感受着周围的情感。快乐、悲伤、愤怒、爱——所有的一切，都在你身边流动。");
  t.push("你知道——这个世界，不再需要『拯救』了。它需要的是——体验。去感受，去爱，去恨，去——活着。");
  t.push("你的旅程——结束了。但也是——开始。");
  t.push("因为从今天起，你和原初之物一起，看着这个世界。看着它成长，看着它变化，看着它——越来越好。");
  t.push("（七印线·真结局。你解放了原初之物，让情感回归世界。这是最困难的路线，也是——最真实的路线。）");
  return t;
},options:[
  {t:"继续冒险——以新的身份",go:"fc_jiaohui_entry",effect:{time:1,flag:"seven_seals_coexist",flag2:"true_ending"}},
  {t:"查看你的成就",go:"fc_jiaohui_entry",effect:{time:1}}
]}};



/* ================================================================
   v20 方向一：旅行事件链式化（触发→判定→后果，三节点链）
   ================================================================ */

/* ---- 事件链：山崩落石 ---- */
N["evt_rockfall_trigger"]=function(){return{place:"山道",where:"午后",text:function(){
  var t=[];
  t.push("山道很窄。左边是峭壁，右边是深渊。");
  t.push("你走得很小心，每一步都踩实了再迈下一步。山里很静，只有风吹过岩石的呜呜声，和你自己的脚步声。");
  t.push("然后你听到了——不对劲的声音。");
  t.push("不是风。是石头摩擦石头的声音。从头顶传来的。");
  t.push("你猛地抬头。峭壁上，一块脸盆大的石头正在松动，碎石簌簌往下掉。");
  t.push("要落石了。");
  return t;
},options:[
  {t:"纵身跃出落石区",check:{a:"AGI",sk:"athletic",label:"闪避"},go:"evt_rockfall_check",fail:"evt_rockfall_fail"},
  {t:"贴紧峭壁，等落石过去",check:{a:"STR",sk:"athletic",label:"体魄"},go:"evt_rockfall_hug",fail:"evt_rockfall_fail"},
  {t:"往回跑，退出危险区",check:{a:"AGI",sk:"stealth",label:"敏捷"},go:"evt_rockfall_retreat",fail:"evt_rockfall_fail"}
]}};

N["evt_rockfall_check"]=function(){return{place:"山道",text:function(){
  var t=[];
  t.push("你蹬地，纵身跃出。");
  t.push("身体在空中的那一瞬，你听到了身后的巨响——轰隆！石头砸在你刚才站的位置，碎石四溅。");
  t.push("你落地，打了个滚，卸掉冲力。站起来的时候，膝盖在发抖，但人没事。");
  t.push("你回头看。落石区已经被碎石覆盖了，如果慢半拍——你不敢想。");
  t.push("山风还在吹。你拍了拍身上的灰，继续往前走。经过这件事，你对山路的危险有了更深的体会。");
  return t;
},options:[
  {t:"继续赶路",go:"travel_resolve",effect:{time:1,fatigue:1,xp:15,flag:"evt_rockfall_survived"}},
  {t:"在安全处歇一会儿",go:"travel_resolve",effect:{time:1,fatigue:1,xp:15,hp:5}}
]}};

N["evt_rockfall_hug"]=function(){return{place:"山道",text:function(){
  var t=[];
  t.push("你贴紧峭壁，双手抠住岩石的缝隙，把身体压成一张纸。");
  t.push("石头从你面前滚落，擦着你的鼻尖飞过去。你能感受到石头带起的风，和碎石打在脸上的刺痛。");
  t.push("轰隆声持续了十几秒。然后——安静了。");
  t.push("你慢慢松开手，从峭壁上滑下来。后背全是冷汗，但人没事。脸上被碎石划了几道小口子，不严重。");
  t.push("你深吸一口气。这种事，经历一次就够了。");
  return t;
},options:[
  {t:"继续赶路",go:"travel_resolve",effect:{time:1,fatigue:1,hp:-3,flag:"evt_rockfall_survived"}}
]}};

N["evt_rockfall_fail"]=function(){return{place:"山道",text:function(){
  var t=[];
  t.push("你慢了一步。");
  t.push("一块碎石砸中了你的腿。你踉跄着往前扑，勉强逃出了落石区，但腿已经使不上劲了。");
  t.push("你坐在地上，卷起裤腿。小腿肿了一大块，青紫青紫的。动一下就钻心地疼。");
  t.push("你从包里翻出绷带，简单包扎了一下。还好不是骨折，但接下来的路，有的受了。");
  t.push("你咬着牙站起来，一瘸一拐地继续走。山里的风似乎更冷了。");
  return t;
},options:[
  {t:"忍着疼继续赶路",go:"travel_resolve",effect:{time:2,hp:-15,fatigue:2,wound:"腿伤",flag:"evt_rockfall_injured"}},
  {t:"找个地方休息一天再走",go:"travel_resolve",effect:{time:2,hp:-8,fatigue:1,wound:"腿伤"}}
]}};

/* ---- 事件链：暴雪封山 ---- */
N["evt_blizzard_trigger"]=function(){return{place:"山口",where:"黄昏",text:function(){
  var t=[];
  t.push("天说变就变。");
  t.push("刚才还好好的，突然就阴了。风里开始夹着雪粒，打在脸上生疼。");
  t.push("你站在山口，往前看是白茫茫的一片，往后看也是。雪越下越大，能见度不到十米。");
  t.push("你知道这种天气——在山里，暴风雪是会死人的。");
  t.push("你必须做出选择。");
  return t;
},options:[
  {t:"顶着风雪强行过山",check:{a:"CON",sk:"survival",label:"生存"},go:"evt_blizzard_push",fail:"evt_blizzard_lost"},
  {t:"找个背风处扎营，等雪停",check:{a:"INT",sk:"survival",label:"生存"},go:"evt_blizzard_camp",fail:"evt_blizzard_cold"},
  {t:"原路返回，等天气好转",go:"evt_blizzard_return",effect:{time:1}}
]}};

N["evt_blizzard_push"]=function(){return{place:"暴风雪中",text:function(){
  var t=[];
  t.push("你用围巾遮住口鼻，低着头，一步一步往前挪。");
  t.push("风雪像刀子一样割在脸上。你几乎睁不开眼，只能凭着感觉往前走。脚下的雪越来越深，每一步都要费很大的劲才能拔出来。");
  t.push("不知道走了多久——也许是一个时辰，也许是三个。你终于看到了山口的轮廓。");
  t.push("你走出了暴风雪。");
  t.push("山的另一边，天是晴的。你回头看，身后的山口还在咆哮，但你已经出来了。");
  t.push("你靠在一块石头上，大口喘气。手脚都冻僵了，但你活着。");
  return t;
},options:[
  {t:"活动一下手脚，继续赶路",go:"travel_resolve",effect:{time:1,fatigue:3,hp:-5,xp:20,flag:"evt_blizzard_survived"}},
  {t:"生堆火，暖和一下再走",go:"travel_resolve",effect:{time:2,fatigue:2,hp:5,gold:-3}}
]}};

N["evt_blizzard_lost"]=function(){return{place:"暴风雪中",text:function(){
  var t=[];
  t.push("你迷路了。");
  t.push("风雪太大，你根本分不清方向。走了半天，你发现自己在原地转圈——脚印绕了一圈又回到了原点。");
  t.push("干粮快吃完了。水也喝完了——你只能抓把雪塞进嘴里，等它融化。");
  t.push("第二天，雪终于停了。你找到了方向，但两天的路白走了，人也冻得半死。");
  t.push("你清点了一下物资：干粮少了一半，钱袋里的钱在慌乱中掉了几个，手指冻得发紫。");
  t.push("但至少——你还活着。");
  return t;
},options:[
  {t:"重新出发",go:"travel_resolve",effect:{time:3,hp:-12,fatigue:4,gold:-5,flag:"evt_blizzard_lost"}}
]}};

N["evt_blizzard_camp"]=function(){return{place:"背风处",text:function(){
  var t=[];
  t.push("你找到了一处背风的岩壁，在下面搭了个简易的庇护所。");
  t.push("生了堆火——虽然湿柴很难点，但你有火石，费了半天劲终于点着了。火光照着岩壁，暖洋洋的。");
  t.push("你靠在火边，吃了点干粮，喝了口热水。风雪在外面咆哮，但庇护所里很安静。");
  t.push("你睡了一觉。醒来的时候，雪停了。");
  t.push("你收拾好东西，继续上路。虽然耽误了一天，但人精神饱满。");
  return t;
},options:[
  {t:"继续赶路",go:"travel_resolve",effect:{time:2,fatigue:-1,hp:5,gold:-3,flag:"evt_blizzard_camped"}}
]}};

N["evt_blizzard_cold"]=function(){return{place:"背风处",text:function(){
  var t=[];
  t.push("你找了个背风处，但——火没生起来。");
  t.push("柴太湿了，火石打了半天，只冒了点烟。你缩在岩壁下面，用毯子把自己裹紧，但还是冷。");
  t.push("那一夜，你几乎没睡。手脚冻得生疼，后来就麻了。你只能不停地搓手跺脚，让血液流动。");
  t.push("天亮的时候，雪停了。你站起来，发现手脚都生了冻疮，又痒又痛。");
  t.push("你咬着牙收拾东西，继续赶路。这一夜，你永远不会忘。");
  return t;
},options:[
  {t:"继续赶路",go:"travel_resolve",effect:{time:2,hp:-8,fatigue:2,wound:"冻疮",flag:"evt_blizzard_frostbite"}}
]}};

N["evt_blizzard_return"]=function(){return{place:"山脚下",text:function(){
  var t=[];
  t.push("你决定不冒险。");
  t.push("原路返回，在山脚下的小镇找了家客栈住下。客栈老板是个热心的矮人，给你端了热汤和面包。");
  t.push("「这种天气，」他说，「过山就是找死。等两天吧，雪停了再走。」");
  t.push("你在客栈待了两天。第三天，天放晴了。你结了房钱，重新出发。");
  t.push("虽然耽误了时间，但你养足了精神，而且——从客栈老板那里听到了不少山里的传闻。");
  return t;
},options:[
  {t:"重新出发",go:"travel_resolve",effect:{time:3,fatigue:-2,hp:10,gold:-8,xp:10,flag:"evt_blizzard_waited"}}
]}};

/* ---- 事件链：逃犯求助 ---- */
N["evt_fugitive_trigger"]=function(){return{place:"林间小路",where:"傍晚",text:function(){
  var t=[];
  t.push("你走在林间小路上，突然——灌木丛里冲出来一个人。");
  t.push("是个男人，浑身是血，衣服破破烂烂的。他看到你，眼睛一亮，踉跄着跑过来，扑通一声跪下。");
  t.push("「求求你……救救我……」他的声音很虚弱，「有人在追我……他们要杀了我……」");
  t.push("你往他身后看。林子里，隐约有火把的光在晃动。还有人声——在喊什么。");
  t.push("你只有几秒钟的时间做决定。");
  return t;
},options:[
  {t:"帮他——给他包扎，给他指条活路",check:{a:"CHA",sk:"medicine",label:"医术"},go:"evt_fugitive_help",fail:"evt_fugitive_help_fail"},
  {t:"拒绝——你不想惹麻烦",go:"evt_fugitive_refuse",effect:{time:1}},
  {t:"抓住他，交给追他的人",check:{a:"STR",sk:"martial",label:"武技"},go:"evt_fugitive_capture",fail:"evt_fugitive_escape"}
]}};

N["evt_fugitive_help"]=function(){return{place:"林间小路",text:function(){
  var t=[];
  t.push("你蹲下来，快速检查他的伤口。刀伤，在腰侧，不算太深，但流血很多。");
  t.push("你从包里翻出绷带和草药，迅速给他包扎。他咬着牙，一声不吭，但额头上全是冷汗。");
  t.push("「往那边走。」你指了指林子深处的一条小路，「走半个时辰，有个猎户的小屋。你可以在那里躲几天。」");
  t.push("他感激地看着你。「谢谢……谢谢你。」他从怀里掏出一枚徽章，塞给你，「这个……给你。以后如果遇到麻烦，拿着它去自由城邦的『银鹰酒馆』，会有人帮你的。」");
  t.push("然后他站起来，踉跄着跑进了林子。");
  t.push("几分钟后，几个穿着骑士团制服的人追了过来。「你看到一个受伤的男人了吗？」");
  return t;
},options:[
  {t:"说没看到",check:{a:"CHA",sk:"persu",label:"说服"},go:"evt_fugitive_lie",fail:"evt_fugitive_suspected"},
  {t:"说看到了，往另一个方向跑了",check:{a:"CHA",sk:"persu",label:"说服"},go:"evt_fugitive_misdirect",fail:"evt_fugitive_suspected"}
]}};

N["evt_fugitive_lie"]=function(){return{place:"林间小路",text:function(){
  var t=[];
  t.push("「没看到。」你面不改色地说。");
  t.push("骑士团的人上下打量了你一番，然后点了点头。「打扰了。」他们转身，继续往另一个方向追去。");
  t.push("你松了一口气。");
  t.push("你低头看了看手里的徽章。银质的，上面刻着一只展翅的鹰。你不知道这是什么组织的标记，但——以后总会知道的。");
  t.push("你把徽章收好，继续赶路。心里有一种奇怪的感觉——你刚才做了一件好事，但也可能——惹上了一个大麻烦。");
  return t;
},options:[
  {t:"继续赶路",go:"travel_resolve",effect:{time:1,karma:3,item:"银鹰徽章",flag:"helped_fugitive",flag2:"silver_eagle_contact"}}
]}};

N["evt_fugitive_misdirect"]=function(){return{place:"林间小路",text:function(){
  var t=[];
  t.push("「看到了。」你说，「他往东边跑了，浑身是血，跑得很快。」");
  t.push("骑士团的人道了声谢，急匆匆地往东追去。你看着他们的背影消失在林子里，然后松了口气。");
  t.push("你低头看了看手里的徽章。银鹰。你不知道这意味着什么，但那个逃犯的眼神——不像是个坏人。");
  t.push("也许有一天，你会知道真相。也许不会。但至少今天，你救了一个人。");
  t.push("你把徽章收好，继续赶路。");
  return t;
},options:[
  {t:"继续赶路",go:"travel_resolve",effect:{time:1,karma:3,item:"银鹰徽章",flag:"helped_fugitive",flag2:"silver_eagle_contact"}}
]}};

N["evt_fugitive_suspected"]=function(){return{place:"林间小路",text:function(){
  var t=[];
  t.push("骑士团的人盯着你看了很久。");
  t.push("「你确定？」为首的那个说，「我们追踪他的血迹，就到这里。」");
  t.push("「也许他往别的方向跑了。」你尽量让自己的声音听起来平静。");
  t.push("他又看了你一会儿，然后哼了一声。「走吧。」他带着人继续往前搜，但你注意到——他留了一个人在后面，盯着你。");
  t.push("你被监视了。接下来的路，你得小心点。");
  t.push("不过至少——那个逃犯安全了。");
  return t;
},options:[
  {t:"甩掉跟踪的人，继续赶路",go:"travel_resolve",effect:{time:2,karma:2,item:"银鹰徽章",flag:"helped_fugitive",flag2:"knights_suspicious"}},
  {t:"和跟踪的人对峙",check:{a:"CHA",sk:"intimidate",label:"威吓"},go:"travel_resolve",fail:"travel_resolve",effect:{time:1,karma:1}}
]}};

N["evt_fugitive_help_fail"]=function(){return{place:"林间小路",text:function(){
  var t=[];
  t.push("你手忙脚乱地给他包扎，但——伤口比你想象的深。血止不住。");
  t.push("他的脸色越来越苍白。「没事……」他虚弱地笑了笑，「我这辈子……欠的债太多了……今天该还了……」");
  t.push("他从怀里掏出一枚徽章，塞给你。「拿着……去银鹰酒馆……告诉他们……老灰……死了……」");
  t.push("然后他的手垂了下去。");
  t.push("你愣在原地。一个人死在你面前，而你——没能救他。");
  t.push("追他的人越来越近了。你必须做出选择。");
  return t;
},options:[
  {t:"拿走徽章，离开这里",go:"travel_resolve",effect:{time:1,karma:1,san:-5,item:"银鹰徽章",flag:"fugitive_died",flag2:"silver_eagle_contact"}},
  {t:"留下来，告诉追他的人他死了",go:"travel_resolve",effect:{time:2,karma:2,san:-3,flag:"fugitive_died"}}
]}};

N["evt_fugitive_refuse"]=function(){return{place:"林间小路",text:function(){
  var t=[];
  t.push("「抱歉。」你说，「我帮不了你。」");
  t.push("他看着你，眼神里有失望，但没有怨恨。「我理解……」他说，「没人想惹麻烦。」");
  t.push("他挣扎着站起来，踉跄着跑进了林子。你站在原地，看着他的背影消失。");
  t.push("几分钟后，骑士团的人追了过来。「你看到一个受伤的男人了吗？」");
  t.push("你指了指他跑的方向。骑士团的人道了声谢，追了上去。");
  t.push("你继续赶路。但心里——有些不是滋味。你不知道他最后怎么样了。也许活下来了，也许没有。");
  t.push("但那是他的命，不是你的。你这样告诉自己。");
  return t;
},options:[
  {t:"继续赶路",go:"travel_resolve",effect:{time:1,karma:-2,san:-2,flag:"refused_fugitive"}}
]}};

N["evt_fugitive_capture"]=function(){return{place:"林间小路",text:function(){
  var t=[];
  t.push("你冲上去，一把按住了他。");
  t.push("他太虚弱了，根本无力反抗。你把他的手反绑在背后，等追他的人过来。");
  t.push("骑士团的人赶到了。为首的那个看了看你，又看了看被绑的逃犯，点了点头。「干得好。这个人是教会通缉的要犯。」");
  t.push("他从钱袋里掏出几个金龙，递给你。「这是赏金。」");
  t.push("你接过钱。逃犯被架起来带走的时候，回头看了你一眼。那个眼神——你说不上来是什么。不是恨，也不是怨。像是——理解。");
  t.push("你握着手里的金龙，站在原地。风从林子里吹过来，带着血腥味。");
  return t;
},options:[
  {t:"继续赶路",go:"travel_resolve",effect:{time:1,gold:20,karma:-3,church_rep:5,flag:"captured_fugitive"}}
]}};

N["evt_fugitive_escape"]=function(){return{place:"林间小路",text:function(){
  var t=[];
  t.push("你冲上去想抓住他，但——他比你想象的灵活。");
  t.push("他侧身一闪，你扑了个空。然后他一脚踹在你膝盖上，你跪了下去。");
  t.push("「对不住了。」他说，然后转身跑进了林子。");
  t.push("你站起来的时候，骑士团的人刚好赶到。「人呢？」");
  t.push("「跑了。」你揉着膝盖说。");
  t.push("为首的骑士皱了皱眉，但没说什么，带着人追了上去。你站在原地，膝盖还在疼。");
  t.push("赏金没拿到，还挨了一脚。今天真是倒霉。");
  return t;
},options:[
  {t:"继续赶路",go:"travel_resolve",effect:{time:1,hp:-5,karma:-1,flag:"fugitive_escaped"}}
]}};

/* ---- 事件链：神秘老者 ---- */
N["evt_elder_trigger"]=function(){return{place:"岔路口",where:"正午",text:function(){
  var t=[];
  t.push("岔路口的石头上，坐着一个老者。");
  t.push("白胡子，白眉毛，穿着一件洗得发白的灰袍。他闭着眼睛，像是在晒太阳，又像是在——等什么人。");
  t.push("你经过的时候，他突然开口了。");
  t.push("「年轻人。」他的声音很平静，像是从很远的地方传来的，「过来坐。」");
  t.push("你愣了一下。你不认识他，但——他的声音里有一种奇怪的力量，让你不由自主地走了过去。");
  return t;
},options:[
  {t:"坐下来，听他说什么",go:"evt_elder_listen",effect:{time:1}},
  {t:"礼貌地拒绝，继续赶路",go:"evt_elder_refuse",effect:{time:1}},
  {t:"警惕地观察他",check:{a:"INT",sk:"detect",label:"侦查"},go:"evt_elder_observe",fail:"evt_elder_listen"}
]}};

N["evt_elder_listen"]=function(){return{place:"岔路口",text:function(){
  var t=[];
  t.push("你在他对面坐下。");
  t.push("他睁开眼睛。你愣住了——他的眼睛是全白的，没有瞳孔。是个盲人。");
  t.push("「我等了你很久。」他说，「或者说——等了一个像你这样的人。」");
  t.push("「你是谁？」");
  t.push("「一个活了太久的人。」他笑了笑，「久到已经忘了自己的名字。但我记得一些事——关于这个大陆的真相。关于七印。关于黄林晶。」");
  t.push("你的心跳漏了一拍。「你知道七印？」");
  t.push("「我知道的比你想象的多。」他从怀里掏出一枚古币，放在你面前的石头上，「这个给你。上面刻着第一道印的坐标——不，不是坐标，是『钥匙』。当你走到铁门关的时候，你会用到它。」");
  t.push("然后他站起来，拍了拍袍子上的灰。「时候到了，我该走了。」");
  return t;
},options:[
  {t:"问他更多关于七印的事",check:{a:"CHA",sk:"persu",label:"说服"},go:"evt_elder_more",fail:"evt_elder_leave"},
  {t:"拿起古币，谢过他",go:"evt_elder_leave",effect:{time:1,item:"神秘古币",xp:30,flag:"mysterious_elder",flag2:"seal1_key"}}
]}};

N["evt_elder_more"]=function(){return{place:"岔路口",text:function(){
  var t=[];
  t.push("「七印不是封印。」老者说，「是枷锁。黄林晶用七道枷锁，把原初之物分成了七份，分别锁在大陆的七个地方。」");
  t.push("「但枷锁不是永久的。时间越长，枷锁越松。现在——第一道已经碎了，第二道在松动。剩下的五道，也撑不了多久了。」");
  t.push("「那怎么办？」");
  t.push("「修复枷锁，或者——打碎所有枷锁，让原初之物重归一体。」他的声音很轻，「前者是维持现状，后者是——赌一把。」");
  t.push("「赌什么？」");
  t.push("「赌原初之物不是怪物。」他看着你——虽然他看不见，但你觉得他在『看』你，「赌它们是宇宙的一部分，是——情感本身。」");
  t.push("然后他笑了。「好了，说太多了。你自己去看吧。」");
  return t;
},options:[
  {t:"拿起古币，告别老者",go:"evt_elder_leave",effect:{time:1,item:"神秘古币",xp:50,san:-5,flag:"mysterious_elder",flag2:"seal_truth_hint",flag3:"seal1_key"}}
]}};

N["evt_elder_observe"]=function(){return{place:"岔路口",text:function(){
  var t=[];
  t.push("你没有立刻过去，而是站在远处观察他。");
  t.push("他的袍子很旧，但很干净。手指修长，指甲修剪得整整齐齐——不像是普通的流浪者。他的呼吸很均匀，很慢——像是某种高深的吐纳法。");
  t.push("然后你注意到了——他的影子。");
  t.push("正午的太阳下，他应该有影子。但——他没有。石头上只有他坐着的痕迹，没有影子。");
  t.push("你倒吸一口凉气。这个人——不是普通人。");
  t.push("「看够了？」他突然说，声音里带着笑意，「过来吧。我不会害你。」");
  return t;
},options:[
  {t:"走过去，听他说",go:"evt_elder_listen",effect:{time:1,flag:"elder_no_shadow"}},
  {t:"转身就跑",go:"travel_resolve",effect:{time:1,san:-3,flag:"elder_fled"}}
]}};

N["evt_elder_refuse"]=function(){return{place:"岔路口",text:function(){
  var t=[];
  t.push("「抱歉，我赶时间。」你说。");
  t.push("他笑了笑。「没关系。该遇到的，总会遇到。」");
  t.push("你继续赶路。走了大约半个时辰，你突然觉得——好像忘了什么重要的事。");
  t.push("你回头看。岔路口空空荡荡的，那个老者已经不见了。石头上——什么都没有。好像他从来没有存在过一样。");
  t.push("你揉了揉眼睛。是幻觉吗？还是——真的遇到了什么？");
  t.push("你摇摇头，继续赶路。但那个老者的声音，一直在你脑海里回响。");
  return t;
},options:[
  {t:"继续赶路",go:"travel_resolve",effect:{time:1,san:-2,flag:"elder_refused"}}
]}};

N["evt_elder_leave"]=function(){return{place:"岔路口",text:function(){
  var t=[];
  t.push("你拿起古币。");
  t.push("古币很旧，铜质的，上面刻着奇怪的符号。你翻到背面——上面刻着一个数字：『壹』。");
  t.push("你抬头想再问他什么——但他已经不见了。");
  t.push("不是走了，是——消失了。就像从来没有存在过一样。石头上干干净净，连坐过的痕迹都没有。");
  t.push("你握着古币，站在原地。风从岔路口吹过，带着远方的气息。");
  t.push("你不知道这个老者是谁，也不知道他为什么给你这枚古币。但你有一种预感——这枚古币，会在未来的某一天，救你的命。");
  t.push("你把古币收好，继续赶路。");
  return t;
},options:[
  {t:"继续赶路",go:"travel_resolve",effect:{time:1,item:"神秘古币",xp:30,flag:"mysterious_elder"}}
]}};

/* ---- 事件链：古战场遗址 ---- */
N["evt_battlefield_trigger"]=function(){return{place:"荒野",where:"黄昏",text:function(){
  var t=[];
  t.push("你走到了一片荒地。");
  t.push("地上到处都是锈迹斑斑的兵器和铠甲碎片。有的还能看出形状——剑、盾、头盔，有的已经烂得不成样子了。");
  t.push("风从荒地上吹过，带着一股——说不上来的味道。像是铁锈，又像是——血。");
  t.push("你认出了这个地方。这是古战场——三百年前，自由城邦和北方公国在这里打了一场大仗，死了上万人。");
  t.push("当地人说，这里晚上会闹鬼。但现在是白天，应该——没事吧？");
  return t;
},options:[
  {t:"进去翻找，看有没有值钱的东西",check:{a:"INT",sk:"detect",label:"侦查"},go:"evt_battlefield_search",fail:"evt_battlefield_curse"},
  {t:"绕过去，不碰这些东西",go:"evt_battlefield_avoid",effect:{time:1}},
  {t:"在战场边缘默哀，然后离开",go:"evt_battlefield_mourn",effect:{time:1,karma:2}}
]}};

N["evt_battlefield_search"]=function(){return{place:"古战场",text:function(){
  var t=[];
  t.push("你走进了古战场。");
  t.push("地上的东西比你想象的多。你翻找了一会儿，在一堆铠甲碎片下面，找到了一把短剑。");
  t.push("剑虽然锈了，但剑格上的宝石还在——一颗小指头大的红宝石，在夕阳下闪着光。");
  t.push("你把宝石抠下来，又找了一会儿，找到了几枚古币和一个还算完整的头盔。");
  t.push("这些东西，拿到城里应该能卖个好价钱。");
  t.push("你把东西装进包里，准备离开。但就在你转身的时候——你听到了一个声音。");
  t.push("很轻，像是有人在叹气。从地底下传来的。");
  return t;
},options:[
  {t:"不管它，赶紧离开",go:"travel_resolve",effect:{time:1,gold:15,item:"红宝石",item2:"古剑",flag:"battlefield_loot"}},
  {t:"停下来，仔细听",check:{a:"SPR",sk:"will",label:"意志"},go:"evt_battlefield_voice",fail:"evt_battlefield_curse"}]}};

N["evt_battlefield_voice"]=function(){return{place:"古战场",text:function(){
  var t=[];
  t.push("你停下来，仔细听。");
  t.push("那个声音又响了。不是叹气——是说话。很轻，很远，像是从很深很深的地下传来的。");
  t.push("「……为什么……战争……」");
  t.push("你浑身一激灵。这是——亡灵的低语？");
  t.push("你握紧了武器，环顾四周。荒地上空空荡荡的，什么都没有。但那个声音还在继续。");
  t.push("「……死了……都死了……为什么……」");
  t.push("你深吸一口气。这是古战场的怨念——三百年了，还没有消散。");
  t.push("你闭上眼睛，在心里默念：「安息吧。战争已经结束了。」");
  t.push("那个声音停了。然后——你感到一阵微风拂过脸颊，像是有人在感谢你。");
  return t;
},options:[
  {t:"离开古战场",go:"travel_resolve",effect:{time:1,gold:15,item:"红宝石",san:5,karma:3,flag:"battlefield_ghost_peace"}}
]}};

N["evt_battlefield_curse"]=function(){return{place:"古战场",text:function(){
  var t=[];
  t.push("你在古战场里翻找了半天，什么值钱的都没找到——倒是被一把锈剑划破了手。");
  t.push("你包扎了一下，准备离开。但就在你走出古战场的时候——你感到一阵寒意。");
  t.push("从后背窜上来的寒意。你回头看——什么都没有。但你总觉得，有什么东西在跟着你。");
  t.push("接下来的几天，你总是做噩梦。梦到古战场，梦到死人，梦到——你自己也躺在那些尸体中间。");
  t.push("你知道，你被古战场的怨念缠上了。需要找个牧师或者萨满净化一下。");
  t.push("但至少——你还活着。");
  return t;
},options:[
  {t:"继续赶路，找机会净化",go:"travel_resolve",effect:{time:1,hp:-5,san:-8,flag:"battlefield_cursed",wound:"怨念缠身"}}
]}};

N["evt_battlefield_avoid"]=function(){return{place:"古战场边缘",text:function(){
  var t=[];
  t.push("你决定绕过去。");
  t.push("死人的东西，不碰为妙。这是老人们常说的话。");
  t.push("你绕了一个大圈，多走了半个时辰，但心里踏实。");
  t.push("走在路上，你回头看了一眼古战场。夕阳下，那些锈迹斑斑的兵器闪着暗红色的光，像是在——提醒你什么。");
  t.push("你摇了摇头，继续赶路。");
  return t;
},options:[
  {t:"继续赶路",go:"travel_resolve",effect:{time:1,fatigue:1,karma:1}}
]}};

N["evt_battlefield_mourn"]=function(){return{place:"古战场边缘",text:function(){
  var t=[];
  t.push("你在古战场边缘站定，闭上眼睛，默哀了一分钟。");
  t.push("三百年前，上万人在这里死去。他们有家人，有朋友，有梦想。但一场战争，把一切都带走了。");
  t.push("你不知道他们是哪一方的，也不知道这场战争是为了什么。但你知道——他们都是人。和你一样的人。");
  t.push("默哀完毕，你睁开眼睛。");
  t.push("然后你看到了——古战场的中央，有什么东西在发光。很微弱，像是萤火虫的光。");
  t.push("你走过去，发现是一枚徽章。铁质的，锈得很厉害，但上面的图案还能辨认——一朵玫瑰。");
  t.push("你把它捡起来。徽章入手的一瞬间，你感到一阵温暖。像是——有人在感谢你。");
  return t;
},options:[
  {t:"收好徽章，继续赶路",go:"travel_resolve",effect:{time:1,karma:5,san:5,item:"玫瑰徽章",flag:"battlefield_blessed"}}
]}};

/* ================================================================
   v20 方向六：过渡与余波节点（全局连贯性补全）
   ================================================================ */

/* ---- 通用过渡节点 ---- */
N["transition_three_days"]=function(){return{place:"旅途中",text:function(){
  var t=[];
  t.push("三天过去了。");
  t.push("这三天很平静。没有遇到强盗，没有遇到野兽，甚至连恶劣天气都没有。你每天日出而行，日落而息，在路边的客栈或者野外的篝火旁过夜。");
  t.push("你利用这段时间，整理了一下之前收集的线索和物品。有些事情，你需要好好想想。");
  if(S.flags.seal1_repaired) t.push("· 第一印已经修复，但铁门关的局势还不稳定。霍夫曼的女儿艾米丽还在圣城，她体内的饥饿碎片——是个隐患。");
  if(S.flags.seal2_repaired) t.push("· 第二印修复了。大汗铁木真——不管是死是活，草原上的局势正在慢慢恢复。");
  if(S.flags.seal3_repaired) t.push("· 第三印修复了。精灵女王自由了，但她和墨丘利之间的事——还没有了结。");
  if(S.flags.helped_fugitive) t.push("· 你救了一个逃犯，得到了一枚银鹰徽章。他说去自由城邦的银鹰酒馆会有人帮你。");
  if(S.flags.mysterious_elder) t.push("· 你遇到了一个神秘的老者，得到了一枚古币。他知道七印的真相——但他到底是谁？");
  t.push("");
  t.push("路还很长。你深吸一口气，继续往前走。");
  return t;
},options:[
  {t:"继续前进",go:"travel_resolve",effect:{time:3,fatigue:-2,hp:5}},
  {t:"在最近的城镇停留一天",go:"travel_resolve",effect:{time:1,gold:-5,fatigue:-3,hp:10}}
]}};

N["transition_after_battle"]=function(){return{place:"战斗后",text:function(){
  var t=[];
  t.push("战斗结束了。");
  t.push("你站在原地，大口喘气。身上的伤口在疼，手里的武器在发抖——不是因为冷，是因为刚才的战斗太激烈了。");
  t.push("你低头看了看自己。衣服破了好几处，血浸透了绷带。但至少——你还活着。");
  t.push("你开始打扫战场。检查敌人的尸体，看有没有有用的东西。然后——处理自己的伤口。");
  t.push("这种事，经历多了就麻木了。但每一次，你都会在心里问自己：这样的日子，什么时候是个头？");
  t.push("没有答案。你只能——继续走。");
  return t;
},options:[
  {t:"包扎伤口，继续前进",go:"travel_resolve",effect:{time:1,hp:-5,fatigue:2}},
  {t:"找个安全的地方休息一天",go:"travel_resolve",effect:{time:2,hp:15,fatigue:-3,gold:-5}}
]}};

N["transition_night_camp"]=function(){return{place:"野外营地",where:"夜晚",text:function(){
  var t=[];
  t.push("天黑了。");
  t.push("你在路边找了个背风的地方，生了堆火。火不大，但够暖和。你坐在火边，烤了点干粮，喝了口水。");
  t.push("夜很静。只有柴火噼啪的声音，和远处偶尔传来的虫鸣。");
  t.push("你抬头看天。星星很亮，密密麻麻地铺在天上。你想起了小时候——那时候你也喜欢看星星，觉得每一颗星星都是一个故事。");
  t.push("现在你知道了——有些星星，可能真的是故事。比如黄林晶，比如那些半神，比如——你正在经历的这一切。");
  t.push("你往火里添了根柴，然后躺下来，裹紧毯子。");
  t.push("明天，又是新的一天。");
  return t;
},options:[
  {t:"睡觉，明天继续赶路",go:"travel_resolve",effect:{time:1,fatigue:-3,hp:8,san:3}},
  {t:"守夜，想想接下来的计划",go:"travel_resolve",effect:{time:1,fatigue:-1,san:5,xp:5}}
]}};

/* ---- 余波节点：第一印修复后 ---- */
N["aftermath_seal1"]=function(){return{place:"交汇城",text:function(){
  var t=[];
  t.push("铁门关的事，在交汇城传开了。");
  t.push("有人说你是英雄，独自深入铁门关，修复了第一道印。有人说你是疯子，居然敢靠近那种地方。还有人说——你是教会的人，或者守望者的人。");
  t.push("你走在街上，能感受到别人的目光。有好奇的，有敬畏的，也有——警惕的。");
  t.push("你在酒馆里听到了一些消息：");
  t.push("· 教会已经派人去铁门关调查了。他们对『修复封印』这件事，态度很微妙——既不承认，也不否认。");
  t.push("· 北方公国在铁门关增兵了。他们担心封印修复后，兽人会再次南下。");
  t.push("· 艾米丽——霍夫曼的女儿——被送到了圣城的圣光神学院。据说她体内的饥饿碎片，正在被教会研究。");
  t.push("这些消息，不知道是真是假。但你知道——你的行动，已经开始影响这个世界了。");
  return t;
},options:[
  {t:"去酒馆打听更多消息",go:"fc_jiaohui_entry",effect:{time:1,flag:"seal1_aftermath"}},
  {t:"低调行事，准备下一段旅程",go:"fc_jiaohui_entry",effect:{time:1,flag:"seal1_aftermath"}}
]}};

/* ---- 余波节点：第二印修复后 ---- */
N["aftermath_seal2"]=function(){return{place:"兽人草原边缘",text:function(){
  var t=[];
  t.push("草原上的风，变了。");
  t.push("不再是灼热的、带着杀意的风，而是——清凉的、带着草香的风。愤怒消退了，草原上的兽人开始恢复理智。");
  t.push("你听说了一些消息：");
  if(S.flags.seal2_khan_dead) {
    t.push("· 大汗铁木真死了。他的死讯传开后，草原上出现了权力真空。各个部落开始争夺大汗的位置，小规模的冲突不断。");
    t.push("· 但没有大规模的战争——愤怒消退之后，兽人们也不想打了。他们更想——回家。");
  }
  if(S.flags.seal2_khan_alive || S.flags.seal2_khan_guardian) {
    t.push("· 大汗铁木真还活着。他解散了军队，向被他伤害过的部落道歉，然后回到圣山，继续守护第二印。");
    t.push("· 草原上的兽人们对他的态度很复杂——有人恨他，有人原谅他，有人——尊敬他的赎罪。");
  }
  t.push("· 白发婆婆的流浪者部落走出了草原深处。他们开始和其他部落接触，试图建立新的秩序。");
  t.push("· 铜须——那个带你进入深渊矿层的老矿工——回到了铁峰堡。他把你的故事告诉了每一个愿意听的人。");
  t.push("草原正在慢慢恢复。但伤口还在，需要时间来愈合。");
  return t;
},options:[
  {t:"继续你的旅程",go:"fc_jiaohui_entry",effect:{time:1,flag:"seal2_aftermath"}},
  {t:"在草原多待几天，看看情况",go:"fc_jiaohui_entry",effect:{time:3,flag:"seal2_aftermath",karma:2}}
]}};

/* ---- 余波节点：第三印修复后 ---- */
N["aftermath_seal3"]=function(){return{place:"精灵王国边境",text:function(){
  var t=[];
  t.push("精灵王国变了。");
  t.push("世界树不再散发那种压抑的、傲慢的气息。森林里的树开始唱歌——欢快的歌。精灵们的脸上，有了笑容。");
  if(S.flags.seal3_queen_freed) {
    t.push("· 女王艾萨拉自由了。她不再是半神，不再是第三印的锚点。她变成了一个普通的精灵——虽然依然强大，但寿命只有几百年了。");
    t.push("· 她宣布退位，将王位传给了长老会推选的新王。然后——她离开了精灵王国。没有人知道她去了哪里。");
    t.push("· 有人说她去了交汇城，去找一个人。一个叫墨丘利的人。");
  }
  if(S.flags.seal3_pride_ally) {
    t.push("· 你吸收了傲慢——不是被吞噬，是达成了协议。傲慢成为了你的动力，你成为了它的方向。");
    t.push("· 你能感受到它的存在。在你想要放弃的时候，它会推你一把。在你骄傲自满的时候，它会——提醒你。");
  }
  t.push("· 精灵长老会开始重新评估和人类的关系。三千年的傲慢，在女王自由之后，开始松动了。");
  t.push("· 银叶学院宣布，将招收更多的人类学生。这在以前——是不可想象的。");
  t.push("精灵王国正在打开国门。慢慢地，但确实在打开。");
  return t;
},options:[
  {t:"继续你的旅程",go:"fc_jiaohui_entry",effect:{time:1,flag:"seal3_aftermath"}},
  {t:"在精灵王国多待几天",go:"fc_jiaohui_entry",effect:{time:3,flag:"seal3_aftermath",elf_rep:5}}
]}};

/* ---- 旅行结算节点（通用） ---- */
N["travel_resolve"]=function(){return{place:"旅途中",text:function(){
  var t=[];
  t.push("你继续赶路。");
  t.push("经过刚才的事，你对这段路有了更深的认识。旅行不只是从A点到B点——路上遇到的每一个人、每一件事，都在改变你。");
  t.push("你看了看前方的路。还很长。但你已经准备好了。");
  return t;
},options:[
  {t:"继续前进",go:"fc_jiaohui_entry",effect:{time:1}},
  {t:"查看地图，确认方向",go:"fc_jiaohui_entry",effect:{time:1}}
]}};



/* ================================================================
   第五印 · 南方深海（嫉妒）— 扩充完整版
   入口：seal5_exp_intro（从seal4_transition进入）
   ================================================================ */

/* ---- 第一幕：线索追寻 ---- */
N["seal5_exp_intro"]=function(){return{place:"南方港城 · 潮汐港",where:"黄昏",text:function(){
  var t=[];
  t.push("潮汐港的风，是咸的。");
  t.push("你站在码头上，看着一艘艘渔船归港。渔民们的脸上没有笑容——他们的眼神里，有恐惧。");
  t.push("你走进了港城最大的酒馆『浪花』。酒馆里很吵，但你能听到人们在窃窃私语。");
  t.push("「又一艘船没回来。」「第五艘了。」「海里的东西……越来越嚣张了。」");
  t.push("你找了个角落坐下，点了一杯麦酒。酒保是个独眼的老水手，他看了你一眼，说：「外地人？最近别出海。海里不太平。」");
  t.push("「怎么个不太平法？」");
  t.push("老酒保压低声音：「船。一艘接一艘地失踪。不是被海盗劫了——是被海里的东西拖下去的。有人说，是『海族』。」");
  return t;
},options:[
  {t:"打听更多关于海族的消息",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal5_exp_tavern_talk",fail:"seal5_exp_tavern_none"},
  {t:"找一艘愿意出海的船",check:{a:"CHA",sk:"trade",label:"商术"},go:"seal5_exp_find_boat",fail:"seal5_exp_no_boat"},
  {t:"在码头观察，等异常出现",go:"seal5_exp_dock_watch",effect:{time:2}},
  {t:"去教堂打听，教会怎么看这件事",go:"seal5_exp_church",effect:{time:1}}
]}};

N["seal5_exp_tavern_talk"]=function(){return{place:"浪花酒馆",text:function(){
  var t=[];
  t.push("你请老酒保喝了一杯，他的话多了起来。");
  t.push("「海族啊……那是老辈人讲的故事了。一万年前，他们住在陆地上，和我们一样。后来——发了大洪水，他们的城市全被淹了，就搬到海里去了。」");
  t.push("「大洪水？谁造成的？」");
  t.push("「黄林晶。」老酒保的声音更低了，「据说，海族当时支持了原初之物。黄林晶为了惩罚他们，发动了大洪水。把他们的城市全淹了。」");
  t.push("「所以海族恨我们？」");
  t.push("「恨？」老酒保苦笑，「何止是恨。一万年了，他们在暗无天日的深海里，看着我们在陆地上享受阳光。你说他们恨不恨？」");
  t.push("「最近第五印开始松动，海族觉得——机会来了。如果第五印碎了，嫉妒会扩散到整个大陆。到那时候，我们也会互相嫉妒，互相残杀。而海族——就可以趁机回到陆地上。」");
  return t;
},options:[
  {t:"问他怎么才能找到海族的城市",go:"seal5_exp_location",effect:{time:1,flag:"seal5_exp_tavern_info"}},
  {t:"问他有没有见过海族",go:"seal5_exp_seen",effect:{time:1,flag:"seal5_exp_tavern_info"}},
  {t:"记下信息，去找船",go:"seal5_exp_find_boat",effect:{time:1,flag:"seal5_exp_tavern_info"}}
]}};

N["seal5_exp_tavern_none"]=function(){return{place:"浪花酒馆",text:function(){
  var t=[];
  t.push("老酒保上下打量了你一番，然后哼了一声。「问这么多干什么？我劝你别多管闲事。」");
  t.push("他转身去招呼别的客人了，不再理你。");
  t.push("你坐在角落里，听着周围人的窃窃私语。信息不多，但你拼凑出了一些：最近有船失踪，据说和海族有关。第五印在南方深海。");
  t.push("你需要更多信息。也许——该去码头看看。");
  return t;
},options:[
  {t:"去码头看看",go:"seal5_exp_dock_watch",effect:{time:1}},
  {t:"找一艘船出海",go:"seal5_exp_find_boat",effect:{time:1}}
]}};

N["seal5_exp_location"]=function(){return{place:"浪花酒馆",text:function(){
  var t=[];
  t.push("老酒保从柜台下面翻出一张旧地图。地图都泛黄了，边角卷了起来。");
  t.push("「这是我年轻的时候，一个老船长给我的。」他指着地图上南方海域的一个标记，「海族的城市，就在这里——南方海域的最深处，『深渊海沟』的底部。」");
  t.push("「深渊海沟？」");
  t.push("「大陆架最深的地方。有一万多米深。普通的船根本到不了。你需要——特殊的装备。」");
  t.push("「什么装备？」");
  t.push("「水下呼吸的法术，或者——『深海珍珠』。」老酒保说，「深海珍珠是海族的东西，能让人在水下自由呼吸。但这东西在陆地上很稀有，价格不菲。」");
  t.push("「或者，你可以找一个叫『老海怪』的船长。他年轻的时候，据说去过海族的城市。他知道怎么下去。」");
  return t;
},options:[
  {t:"去找老海怪船长",go:"seal5_exp_old_captain",effect:{time:1,item:"海族地图",flag:"seal5_exp_map"}},
  {t:"去魔法商店买水下呼吸药剂",go:"seal5_exp_magic_shop",effect:{time:1,item:"海族地图"}},
  {t:"问他深海珍珠在哪里能找到",go:"seal5_exp_pearl_info",effect:{time:1,item:"海族地图"}}
]}};

N["seal5_exp_find_boat"]=function(){return{place:"潮汐港 · 码头",text:function(){
  var t=[];
  t.push("你在码头上找船。");
  t.push("大部分船长一听说你要出海，都摇头。「最近不太平，不出海。」「给多少钱都不去。」");
  t.push("就在你快要放弃的时候，一个独眼的老水手拦住了你。");
  t.push("「你要出海？」他上下打量你，「我叫老海怪。这条码头，只有我敢出海。」");
  t.push("「为什么？」");
  t.push("「因为我年轻的时候，去过海族的城市。」他拍了拍自己的独眼，「这只眼睛，就是在那里丢的。但我也——看到了一些东西。一些别人没见过的东西。」");
  t.push("「你要去哪里？」");
  t.push("「深渊海沟。第五印。」");
  t.push("老海怪的脸色变了。「你疯了？」他说，「但——我也一直在等一个敢去的人。上船吧。」");
  return t;
},options:[
  {t:"上船，出发",go:"seal5_exp_sail",effect:{time:1,flag:"seal5_exp_old_haiguai"}},
  {t:"先问他更多关于海族的事",go:"seal5_exp_old_haiguai_story",effect:{time:1,flag:"seal5_exp_old_haiguai"}}
]}};

N["seal5_exp_old_haiguai_story"]=function(){return{place:"老海怪的船",text:function(){
  var t=[];
  t.push("老海怪给你倒了一杯朗姆酒，然后开始讲。");
  t.push("「三十年前，我还是个年轻的水手。我们的船在南方海域遇到了风暴，船沉了。我掉进海里，以为自己死定了。」");
  t.push("「然后——我看到了光。蓝色的光，从深海里照上来。我往下沉，然后——我看到了城市。」");
  t.push("「海族的城市。用白色的珊瑚和珍珠建造，比任何人类城市都美丽。海族的人——上半身是人，下半身是鱼。他们看到了我，把我救了上去。」");
  t.push("「我在那里待了三个月。他们的女王——一个金色尾巴的女人——亲自见了我。她告诉我，他们在等一个机会。一个回到陆地的机会。」");
  t.push("「三个月后，他们把我送回了岸边。但——我的一只眼睛，留在了那里。」他指了指自己的独眼，「作为『纪念』。或者说——作为警告。」");
  t.push("「他们不是怪物。」老海怪说，「他们只是——被遗忘了太久的人。」");
  return t;
},options:[
  {t:"出发，去深渊海沟",go:"seal5_exp_sail",effect:{time:1,flag:"seal5_exp_old_haiguai_story"}},
  {t:"问他海族女王的名字",go:"seal5_exp_queen_name",effect:{time:1,flag:"seal5_exp_old_haiguai_story"}}
]}};

N["seal5_exp_sail"]=function(){return{place:"南方海域",where:"航行中",text:function(){
  var t=[];
  t.push("船出发了。");
  t.push("老海怪的船不大，但很结实。他扬帆的动作很熟练——三十年的航海经验，都在这双手上。");
  t.push("第一天，风平浪静。你站在船头，看着一望无际的大海。海水是翡翠色的，在阳光下闪闪发光。");
  t.push("第二天，情况变了。海水的颜色变深了——从翡翠色变成了深蓝色，然后是墨蓝色。你知道，你正在接近深渊海沟。");
  t.push("「就是这里了。」老海怪说，「深渊海沟。往下一万多米，就是海族的城市。」");
  t.push("他从船舱里拿出一个包裹。「这是『深海珍珠』。我当年从海族那里带回来的。含在嘴里，就能在水下呼吸。」");
  t.push("他把珍珠递给你。「你一个人下去。我在船上等你。如果三天内你不回来——我就走了。」");
  return t;
},options:[
  {t:"含上珍珠，潜入深海",go:"seal5_exp_dive",effect:{time:1,item:"深海珍珠"}},
  {t:"问他下去之后该注意什么",go:"seal5_exp_dive_tips",effect:{time:1,item:"深海珍珠"}},
  {t:"太危险了，再想想",go:"seal5_exp_hesitate",effect:{time:1}}
]}};

N["seal5_exp_dive"]=function(){return{place:"深渊海沟",where:"深海",text:function(){
  var t=[];
  t.push("你含上深海珍珠，跳进了海里。");
  t.push("珍珠在你嘴里化开，一股清凉的感觉从喉咙蔓延到全身。你发现——你能在水里呼吸了。");
  t.push("你往下潜。十米、五十米、一百米。光线越来越暗，水压越来越大。但深海珍珠在保护你。");
  t.push("然后你看到了——光。");
  t.push("蓝色的光，从深海里照上来。无数的发光生物在水中游动，像是一片移动的星空。");
  t.push("你继续往下潜。五百米、一千米、三千米。然后——你看到了城市。");
  t.push("海族的城市。它建在海沟的底部，用白色的珊瑚和珍珠建造。城市的中心，有一座巨大的神殿——神殿的顶部，有一颗黑色的水晶，在缓慢地旋转。");
  t.push("第五印。");
  t.push("但你也被发现了。十几个海族战士拿着长矛，从四面八方围了过来。");
  return t;
},options:[
  {t:"主动现身，说明来意",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal5_exp_meet",fail:"seal5_exp_captured"},
  {t:"偷偷潜入神殿",check:{a:"AGI",sk:"stealth",label:"潜行"},go:"seal5_exp_sneak",fail:"seal5_exp_captured"},
  {t:"先观察，找机会",go:"seal5_exp_observe",effect:{time:1}}
]}};

/* ---- 第二幕：抵达与探索 ---- */
N["seal5_exp_meet"]=function(){return{place:"海族城市 · 神殿前",text:function(){
  var t=[];
  t.push("你被带到了神殿前。");
  t.push("海族的女王站在神殿门口。她和普通海族不一样——她的尾巴是金色的，头上戴着珍珠王冠。她的眼睛——是紫色的。充满了——嫉妒。");
  t.push("「陆地人。」她的声音在水里传播，带着一种奇异的共鸣，「你居然敢来这里。」");
  t.push("「我来修复第五印。」");
  t.push("女王笑了。笑声里充满了嘲讽。「修复？你知道第五印对我们意味着什么吗？它是我们的枷锁。一万年了，我们被迫守护它，被迫在暗无天日的深海里生活。而你们——在大陆上享受阳光。」");
  t.push("「这不公平。」她的声音尖锐起来，「所以我们决定——不再守护了。让第五印碎掉。让嫉妒扩散到整个大陆。到那时候——你们也会尝到，被嫉妒折磨的滋味。」");
  return t;
},options:[
  {t:"说服她——嫉妒扩散对谁都没有好处",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal5_exp_persuade",fail:"seal5_exp_combat"},
  {t:"问她黄林晶和海族的历史真相",go:"seal5_exp_truth",effect:{time:1}},
  {t:"提出条件——帮海族回到陆地",go:"seal5_exp_deal",effect:{time:1}},
  {t:"站在大陆种族的立场，警告她",go:"seal5_exp_warn",effect:{time:1}}
]}};

N["seal5_exp_captured"]=function(){return{place:"海族城市 · 监狱",text:function(){
  var t=[];
  t.push("你被抓住了。");
  t.push("海族战士把你拖进了城市，关进了一个珊瑚做的监狱里。监狱在城市的边缘，又冷又暗。");
  t.push("你坐在监狱里，思考着对策。海族对你很警惕——他们不相信陆地人。");
  t.push("过了大约一天，一个海族少女来到了监狱门口。她和其他海族不一样——她的眼睛不是紫色的，是蓝色的。她看着你，眼神里没有敌意，只有——好奇。");
  t.push("「你是陆地人？」她小声说，「我从来没见过陆地人。」");
  t.push("「你是谁？」");
  t.push("「我叫小蓝。」她说，「女王是我姐姐。我——不赞同她的做法。我觉得，我们应该和陆地人和解。」");
  return t;
},options:[
  {t:"请她帮你逃出去",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal5_exp_escape",fail:"seal5_exp_escape_fail"},
  {t:"请她带你去见女王",go:"seal5_exp_meet",effect:{time:1,flag:"seal5_exp_xiaolan_ally"}},
  {t:"问她更多关于海族的事",go:"seal5_exp_xiaolan_story",effect:{time:1}}
]}};

N["seal5_exp_xiaolan_story"]=function(){return{place:"海族监狱",text:function(){
  var t=[];
  t.push("小蓝告诉你关于海族的事。");
  t.push("「我们海族，本来住在陆地上。那时候，我们的城市比精灵的还美丽，我们的魔法比人类的还强大。」");
  t.push("「然后，原初之物苏醒了。黄林晶找到了我们，说要加固七印。他说，需要一个种族做出牺牲——搬到深海里，守护第五印。」");
  t.push("「我们的祖先同意了。他们以为这是荣耀。但黄林晶骗了他们——第五印不是需要守护，是需要『喂养』。用我们的嫉妒，喂养原初之物。」");
  t.push("「一万年了。我们的嫉妒越来越强，第五印也越来越强。而我们——越来越痛苦。」");
  t.push("小蓝的眼睛红了。「我姐姐——她被嫉妒吞噬了。她不再是我认识的那个姐姐了。她现在只想——复仇。」");
  t.push("「但我不想复仇。我想——回家。回到陆地上。」");
  return t;
},options:[
  {t:"承诺帮她回到陆地",go:"seal5_exp_promise",effect:{time:1,flag:"seal5_exp_xiaolan_ally",flag2:"seal5_exp_land_promise"}},
  {t:"问她怎么才能见到女王",go:"seal5_exp_meet",effect:{time:1,flag:"seal5_exp_xiaolan_ally"}},
  {t:"问她第五印的具体情况",go:"seal5_exp_seal_detail",effect:{time:1,flag:"seal5_exp_xiaolan_ally"}}
]}};

N["seal5_exp_persuade"]=function(){return{place:"海族神殿",text:function(){
  var t=[];
  t.push("你开始说服女王。");
  t.push("「嫉妒扩散之后，不会只影响大陆上的种族。它会影响所有生物——包括你们海族。到那时候，你们也会互相嫉妒，互相残杀。」");
  t.push("「你们想要的是回到陆地，不是毁灭世界。如果第五印碎了，世界都毁灭了，你们回到陆地又有什么意义？」");
  t.push("女王沉默了。她的紫色眼睛里，嫉妒在消退——取而代之的是——思考。");
  t.push("「你说得对。」她终于说，「但我们不能永远待在深海里。我们需要——一个承诺。」");
  t.push("「什么承诺？」");
  t.push("「大陆上的种族，承认我们的存在。给我们一片海岸线，让我们可以在陆地上生活。不再是传说中的怪物，而是——平等的种族。」");
  t.push("你看着她。这个要求——不过分。");
  return t;
},options:[
  {t:"答应她的条件",go:"seal5_exp_deal_made",effect:{time:1,flag:"seal5_exp_queen_agrees",flag2:"seal5_exp_sea_land"}},
  {t:"说你需要和大陆势力商量",go:"seal5_exp_need_negotiate",effect:{time:1,flag:"seal5_exp_queen_hesitates"}},
  {t:"拒绝——你不能代表大陆势力",go:"seal5_exp_refuse",effect:{time:1}}
]}};

N["seal5_exp_truth"]=function(){return{place:"海族神殿",text:function(){
  var t=[];
  t.push("你问女王关于黄林晶和海族的历史。");
  t.push("女王的表情变了。她挥了挥手，神殿的墙壁上出现了一幅壁画——一万年前的历史。");
  t.push("「一万年前，海族住在陆地上。我们的城市比精灵的还美丽，我们的魔法比人类的还强大。然后——原初之物苏醒了。」");
  t.push("「黄林晶找到了我们，说要加固七印。他说，需要一个种族做出牺牲——搬到深海里，守护第五印。」");
  t.push("「我们的祖先同意了。他们以为这是荣耀。但黄林晶骗了他们——第五印不是需要守护，是需要『喂养』。用海族的嫉妒，喂养原初之物。」");
  t.push("「一万年了。我们的嫉妒越来越强，第五印也越来越强。而我们——越来越痛苦。」");
  t.push("女王的声音在发抖。「黄林晶不是英雄。他是一个——骗子。他用我们的痛苦，换来了大陆的和平。」");
  return t;
},options:[
  {t:"道歉——为黄林晶的行为",go:"seal5_exp_apologize",effect:{time:1,flag:"seal5_exp_truth_known"}},
  {t:"问她修复第五印能不能解除海族的痛苦",go:"seal5_exp_repair_cure",effect:{time:1,flag:"seal5_exp_truth_known"}},
  {t:"问她想怎么解决",go:"seal5_exp_queen_plan",effect:{time:1,flag:"seal5_exp_truth_known"}}
]}};

N["seal5_exp_deal"]=function(){return{place:"海族神殿",text:function(){
  var t=[];
  t.push("你提出了一个条件。");
  t.push("「如果我修复了第五印，并且帮你们回到陆地——你们愿意，放弃复仇吗？」");
  t.push("女王愣住了。「你能帮我们回到陆地？」");
  t.push("「我不能保证什么。但我可以——在大陆的势力面前，为你们说话。自由城邦、精灵王国、矮人王国——他们都会听我的。至少，会听一听。」");
  t.push("女王沉默了很久。然后她说：「如果是真的——我愿意。」");
  t.push("「但我有一个条件。」她说，「你要在这里，留下一个『信物』。一个你最珍贵的东西。作为——承诺的保证。」");
  t.push("你摸了摸身上的东西。最珍贵的是什么？");
  return t;
},options:[
  {t:"留下你的武器",go:"seal5_exp_deal_weapon",effect:{time:1,flag:"seal5_exp_deal_made"}},
  {t:"留下你的一件物品",go:"seal5_exp_deal_item",effect:{time:1,flag:"seal5_exp_deal_made"}},
  {t:"留下你的名字——作为承诺",go:"seal5_exp_deal_name",effect:{time:1,flag:"seal5_exp_deal_made"}}
]}};

N["seal5_exp_warn"]=function(){return{place:"海族神殿",text:function(){
  var t=[];
  t.push("你站在大陆种族的立场，警告女王。");
  t.push("「如果第五印碎了，嫉妒扩散到整个大陆。大陆上的种族不会坐以待毙——他们会联合起来，对抗海族。到那时候，你们面对的，是整个大陆的怒火。」");
  t.push("「精灵、矮人、人类、兽人——所有种族，都会把你们当成敌人。你们确定，能赢吗？」");
  t.push("女王的脸色变了。「你在威胁我？」");
  t.push("「不是威胁。是事实。」你说，「我不想看到战争。我想看到——和解。」");
  t.push("女王沉默了。她的紫色眼睛里，嫉妒和理智在交战。");
  t.push("过了很久，她说：「你和其他陆地人不一样。」");
  return t;
},options:[
  {t:"趁热打铁，提出和解方案",go:"seal5_exp_deal",effect:{time:1,flag:"seal5_exp_warn_works"}},
  {t:"继续说服她",go:"seal5_exp_persuade",effect:{time:1,flag:"seal5_exp_warn_works"}}
]}};

/* ---- 第三幕：真相与抉择 ---- */
N["seal5_exp_deal_made"]=function(){return{place:"海族神殿",text:function(){
  var t=[];
  t.push("你答应了女王的条件。");
  t.push("「我会尽我所能，让大陆上的种族承认你们。」你说，「但我需要你——先帮我修复第五印。」");
  t.push("女王看着你，看了很久。然后她点了点头。「好。我相信你。」");
  t.push("她转过身，面向神殿。「海族的子民们！」她的声音传遍了整个城市，「这个陆地人，答应了我们的条件。从今天起——我们不再是守护者，我们是——自由的种族！」");
  t.push("海族们欢呼了。一万年的压抑，在这一刻释放了。");
  t.push("女王带你进入神殿。第五印的核心——那颗黑色的水晶，就在神殿中央。女王将手放在水晶上，开始吟唱。");
  t.push("你也将自己的力量注入水晶。两种力量交织，第五印开始——稳定。");
  t.push("黑色的光芒慢慢变成了白色。嫉妒被重新封印了。");
  return t;
},options:[
  {t:"完成修复，和女王告别",go:"seal5_exp_aftermath",effect:{time:1,flag:"seal5_exp_repaired",flag2:"seal5_exp_queen_ally"}},
  {t:"问她更多关于其他印的事",go:"seal5_exp_other_seals",effect:{time:1,flag:"seal5_exp_repaired"}}
]}};

N["seal5_exp_refuse"]=function(){return{place:"海族神殿",text:function(){
  var t=[];
  t.push("你拒绝了女王的条件。");
  t.push("「我不能代表大陆势力。」你说，「我只是一个人。我不能替他们做决定。」");
  t.push("女王的脸色沉了下来。「那你来这里干什么？」");
  t.push("「来修复第五印。」");
  t.push("「没有我们的帮助，你修不了第五印。」女王冷笑，「第五印的封印上，有我们海族先祖的血脉锁。没有我们的同意，你连神殿都进不去。」");
  t.push("你沉默了。她说的是真的——你确实需要海族的帮助。");
  t.push("「但你可以——用我的血。」你说，「只要有你的血，就能打开血脉锁。」");
  t.push("女王的眼睛眯了起来。「你想强取？」");
  return t;
},options:[
  {t:"强取——攻击女王",check:{a:"STR",sk:"martial",label:"武技"},go:"seal5_exp_combat",fail:"seal5_exp_combat_fail"},
  {t:"重新考虑——答应她的条件",go:"seal5_exp_deal_made",effect:{time:1,flag:"seal5_exp_changed_mind"}},
  {t:"离开，另想办法",go:"seal5_exp_leave",effect:{time:1,flag:"seal5_exp_refused"}}
]}};

N["seal5_exp_combat"]=function(){return{place:"海族神殿",text:function(){
  var t=[];
  t.push("战斗爆发了。");
  t.push("女王的尾巴一甩，无数的水箭朝你射来。你侧身躲过，拔出武器，冲了上去。");
  t.push("在水下战斗，你很不适应。水的阻力让你的动作慢了半拍，而海族女王——如鱼得水。");
  t.push("但你有你的优势。你的力量、你的技巧、你的——意志。");
  t.push("战斗持续了很久。你身上添了好几道伤，但女王也不好受——你的每一次攻击，都精准地命中她的关节和穴位。");
  t.push("终于，你抓住了一个机会。她的尾巴横扫过来，你侧身躲过，同时用武器的平面拍在她的后颈上。");
  t.push("她踉跄了一下，然后——停住了。");
  t.push("「你赢了。」她说，声音里有疲惫，也有——释然。「杀了我吧。」");
  return t;
},options:[
  {t:"不杀她——再给她一次机会",go:"seal5_exp_mercy",effect:{time:1,hp:-20,flag:"seal5_exp_combat_won"}},
  {t:"取她的血，打开血脉锁",check:{a:"INT",sk:"magic",label:"法术"},go:"seal5_exp_blood_unlock",fail:"seal5_exp_blood_fail"},
  {t:"杀了她",go:"seal5_exp_kill_queen",effect:{time:1,hp:-20,karma:-5,flag:"seal5_exp_queen_dead"}}
]}};

N["seal5_exp_mercy"]=function(){return{place:"海族神殿",text:function(){
  var t=[];
  t.push("你放下了武器。");
  t.push("「我不杀你。」你说，「杀了你，解决不了任何问题。海族和陆地种族之间的仇恨，只会更深。」");
  t.push("女王愣住了。「你……不杀我？」");
  t.push("「我想和你谈谈。真正的谈谈。不是作为敌人，而是作为——两个都想解决问题的人。」");
  t.push("女王看着你，看了很久。然后她笑了——不是嘲讽的笑，是真正的、释然的笑。");
  t.push("「你和黄林晶不一样。」她说，「他只把我们当成工具。而你——把我们当成人。」");
  t.push("「好。」她说，「我帮你修复第五印。但你要答应我——帮我们回到陆地。」");
  t.push("「我答应你。」");
  return t;
},options:[
  {t:"一起修复第五印",go:"seal5_exp_deal_made",effect:{time:1,hp:-20,flag:"seal5_exp_mercy_works"}}
]}};

/* ---- 第四幕：后果与余波 ---- */
N["seal5_exp_aftermath"]=function(){return{place:"海面",text:function(){
  var t=[];
  t.push("你浮出了海面。");
  t.push("阳光照在你脸上，你深吸了一口气。咸咸的海风，温暖的阳光——你终于理解了，海族为什么渴望陆地。");
  t.push("第五印修复了。海族获得了自由——至少，是承诺中的自由。");
  t.push("老海怪的船在海面上等你。他看到你，露出了笑容。「成了？」");
  t.push("「成了。」");
  t.push("他拉起你，调转船头，向港城驶去。");
  t.push("你站在船头，看着大海。海面平静，像是一万年的嫉妒，终于平息了。");
  t.push("还有两道印。懒惰。色欲。");
  t.push("你踏上了前往东部王国的路。");
  return t;
},options:[
  {t:"前往东部王国（第六印）",go:"seal6_exp_intro",effect:{time:10}},
  {t:"先回交汇城休整",go:"fc_jiaohui_entry",effect:{time:5}},
  {t:"查看你的物品和线索",go:"fc_jiaohui_entry",effect:{time:1}}
]}};

N["seal5_exp_other_seals"]=function(){return{place:"海族神殿",text:function(){
  var t=[];
  t.push("女王告诉你关于其他印的事。");
  t.push("「第六印在东部王国，时光裂隙。下面压着的是——懒惰。黄林晶在那里留了一个『后门』，可以穿越时间。但懒惰会让你觉得——一切都可以等，明天再做也来得及。」");
  t.push("「第七印在死亡沙漠，深渊神殿。下面压着的是——色欲。那是所有原初之物中最神秘的一个，也是最危险的一个。它会让你沉溺于快乐，忘记一切。」");
  t.push("她看着你。「你已经修复了五道印。剩下的两道——会越来越难。你确定要继续吗？」");
  return t;
},options:[
  {t:"确定。继续前往第六印",go:"seal5_exp_aftermath",effect:{time:1,flag:"seal5_exp_other_seals_known"}},
  {t:"先休息，再做打算",go:"seal5_exp_aftermath",effect:{time:1,flag:"seal5_exp_other_seals_known"}}
]}};

/* ================================================================
   第六印 · 东部时光裂隙（懒惰）— 扩充完整版
   ================================================================ */
N["seal6_exp_intro"]=function(){return{place:"东部王国 · 承天山脚下",where:"清晨",text:function(){
  var t=[];
  t.push("承天山的雾，是白色的。");
  t.push("你站在山脚下，仰头看着这座山。它不像铁峰堡那样厚重，也不像世界树那样壮观——它是缥缈的。山顶隐藏在云雾里，若隐若现。");
  t.push("承天书院就在山顶。东方最古老的学院，魔法师和炼金术师的圣地。");
  t.push("但你不是来上学的。你是来找第六印的——时光裂隙。");
  t.push("你沿着山路往上走。路上遇到了几个书院的学生，他们穿着青色的长袍，手里拿着书卷，边走边讨论。");
  t.push("你注意到——他们的脚步很慢。不是悠闲的慢，是——懒洋洋的慢。像是没睡醒，又像是——对什么都提不起劲。");
  t.push("懒惰。第六印的影响，已经扩散到了山上。");
  return t;
},options:[
  {t:"上山，去承天书院",go:"seal6_exp_academy",effect:{time:1}},
  {t:"和学生打听消息",check:{a:"CHA",sk:"persu",label:"说服"},go:"seal6_exp_student",fail:"seal6_exp_academy"},
  {t:"直接找时光裂隙",go:"seal6_exp_rift_direct",effect:{time:2}}
]}};

N["seal6_exp_academy"]=function(){return{place:"承天书院",text:function(){
  var t=[];
  t.push("你来到了承天书院。");
  t.push("和你想象的不一样。书院里很安静——不是那种读书的安静，是——死气沉沉的安静。学生们坐在教室里，有的在打瞌睡，有的在发呆，有的干脆趴在桌子上睡觉。");
  t.push("讲台上，一个老教授在讲课。但他的声音很慢，像是在说梦话。");
  t.push("你找到了书院的院长——玄机子。黄林晶的隔代传人，半神级的强者。");
  t.push("他坐在院子里，晒太阳。看到你，他懒洋洋地睁开眼。「哦？客人？」");
  t.push("「我在调查七印。第六印——时光裂隙——就在承天山。」");
  t.push("玄机子打了个哈欠。「啊，那个啊。」他指了指后山，「在后山。一个裂缝。能看到过去和未来。挺有意思的。」");
  t.push("他的态度——太随意了。像是对什么都不在乎。");
  return t;
},options:[
  {t:"问他第六印的具体情况",go:"seal6_exp_xuanji_detail",effect:{time:1}},
  {t:"问他为什么书院变成这样",go:"seal6_exp_why_lazy",effect:{time:1}},
  {t:"去后山看裂隙",go:"seal6_exp_rift",effect:{time:1}}
]}};

N["seal6_exp_xuanji_detail"]=function(){return{place:"承天书院 · 院子",text:function(){
  var t=[];
  t.push("玄机子告诉你关于第六印的事。");
  t.push("「第六印下面压着的是——懒惰。」他说，声音还是懒洋洋的，「原初之物的七分之一。它不像饥饿那样吞噬身体，也不像愤怒那样吞噬理智——它吞噬的是——动力。」");
  t.push("「靠近它的人，会变得越来越懒。什么都不想做，什么都不在乎。最后——就变成了一滩烂泥。」");
  t.push("「承天书院的学生和老师，已经被影响了。包括我。」他苦笑了一下，「我是半神，抵抗力强一些。但也——越来越不想动了。」");
  t.push("「时光裂隙是黄林晶留下的『后门』。他说，如果有一天七印出了问题，可以通过时光裂隙回到过去，找到解决方法。」");
  t.push("「但问题是——回到过去有什么用？过去的黄林晶，也解决不了。而且——」他顿了顿，「时光裂隙有副作用。用多了，你会变得——越来越懒。因为你会觉得，反正可以回到过去重来，那现在急什么？」");
  return t;
},options:[
  {t:"问他修复第六印的方法",go:"seal6_exp_repair_method",effect:{time:1,flag:"seal6_exp_xuanji_talks"}},
  {t:"问他时光裂隙怎么用",go:"seal6_exp_rift_use",effect:{time:1,flag:"seal6_exp_xuanji_talks"}},
  {t:"去后山看裂隙",go:"seal6_exp_rift",effect:{time:1,flag:"seal6_exp_xuanji_talks"}}
]}};

N["seal6_exp_repair_method"]=function(){return{place:"承天书院",text:function(){
  var t=[];
  t.push("玄机子告诉你修复第六印的方法。");
  t.push("「第六印的修复，和其他印不一样。懒惰是——『停滞型』的原初之物。它越停滞越强。要修复它，需要——『行动』。」");
  t.push("「行动？」");
  t.push("「是的。在时光裂隙里，完成一个『不可能的任务』。一个你觉得『反正做不到，算了吧』的任务。当你真正完成它的时候——懒惰就会被削弱。」");
  t.push("「什么任务？」");
  t.push("玄机子沉默了很久。「黄林晶留下的任务。回到三千年前，阻止他——犯下那个错误。」");
  t.push("「什么错误？」");
  t.push("「加固七印的时候，他不应该用活的锚点。」玄机子的声音低了下去，「如果他当时用了别的方法——精灵女王不会被封印三千年，海族不会被流放一万年，一切都会不一样。」");
  t.push("「但改变过去——会有悖论。」");
  t.push("「是的。」玄机子说，「所以这是一个『不可能的任务』。你可以尝试，但——大概率会失败。不过没关系。重要的不是结果，是——你尝试了。」");
  return t;
},options:[
  {t:"接受任务——进入时光裂隙",go:"seal6_exp_rift",effect:{time:1,flag:"seal6_exp_mission_accepted"}},
  {t:"问他有没有别的方法",go:"seal6_exp_other_method",effect:{time:1,flag:"seal6_exp_mission_accepted"}}
]}};

N["seal6_exp_rift"]=function(){return{place:"承天山 · 后山 · 时光裂隙",text:function(){
  var t=[];
  t.push("你来到了后山。");
  t.push("时光裂隙就在那里——一个悬浮在空中的裂缝。它不是黑色的，是——彩色的。无数的颜色在裂缝里流动，像是一条彩虹的河流。");
  t.push("你能感受到——懒惰。从裂缝里散发出来的，纯粹的、让人想躺平的懒惰。");
  t.push("「算了吧。」一个声音在你脑子里说，「明天再做也来得及。反正——还有时间。」");
  t.push("你摇摇头，把这个念头压下去。然后你——跳了进去。");
  t.push("世界在旋转。颜色在飞舞。你感到自己在坠落——不，是在上升。不，是——在流动。");
  t.push("然后，一切静止了。");
  t.push("你站在一片草地上。天空是蓝色的，太阳是金色的。远处——有一座城市。一座你从未见过的城市。");
  t.push("三千年前的——艾尔达大陆。");
  return t;
},options:[
  {t:"寻找黄林晶",check:{a:"INT",sk:"detect",label:"侦查"},go:"seal6_exp_find_hlj",fail:"seal6_exp_lost"},
  {t:"观察这个时代的世界",go:"seal6_exp_observe_past",effect:{time:1}},
  {t:"尝试回到现在",check:{a:"INT",sk:"magic",label:"法术"},go:"seal6_exp_return",fail:"seal6_exp_stuck"}
]}};

N["seal6_exp_find_hlj"]=function(){return{place:"三千年前 · 交汇城",text:function(){
  var t=[];
  t.push("你找到了黄林晶。");
  t.push("他比你想象的年轻。只有二十多岁，穿着简单的布衣，正在一个小工坊里——研究什么东西。");
  t.push("他看到你，愣了一下。「你是谁？怎么进来的？」");
  t.push("「我是从未来来的。三千年后。」");
  t.push("黄林晶放下手里的东西，仔细打量你。「未来？」他的眼睛亮了起来，「有意思。你是说——我成功了？七印加固成功了？」");
  t.push("「成功了。但——代价很大。」你告诉他精灵女王、海族、以及其他种族的遭遇。");
  t.push("黄林晶沉默了。他的手在发抖。「我……我不知道会这样。我以为——用活的锚点是唯一的方法。」");
  t.push("「不是。」你说，「有别的方法。你可以用——物品作为锚点。比如，十二神器。」");
  t.push("黄林晶的眼睛亮了。「十二神器？你是说——我可以把灵魂分成十二份，封印在神器里？」");
  t.push("「是的。这样就不需要活的锚点了。」");
  return t;
},options:[
  {t:"帮他完成十二神器的设计",check:{a:"INT",sk:"magic",label:"法术"},go:"seal6_exp_change_past",fail:"seal6_exp_paradox"},
  {t:"只告诉他方法，然后离开",go:"seal6_exp_return_new",effect:{time:1,flag:"seal6_exp_hlj_changed"}},
  {t:"问他更多关于原初之物的真相",go:"seal6_exp_truth_past",effect:{time:1}}
]}};

N["seal6_exp_change_past"]=function(){return{place:"三千年前",text:function(){
  var t=[];
  t.push("你帮黄林晶完成了十二神器的设计。");
  t.push("他很聪明——比你想象的还聪明。你只说了大概的思路，他就推导出了完整的方案。");
  t.push("「这样就不需要活的锚点了。」他说，眼睛里闪烁着兴奋的光芒，「精灵不会被封印，海族不会被流放——一切都会不一样。」");
  t.push("但然后——你感到一阵眩晕。");
  t.push("时间悖论。你改变了过去。现在的你——正在消失。");
  t.push("因为如果过去改变了，你就不会踏上修复七印的旅程。你不会来到这里。你不会——存在。");
  t.push("「快走！」黄林晶推了你一把，「回到你的时代！改变已经发生了——但你的存在，会成为新时间线的『锚』。你必须回去，锚定新的时间线！」");
  t.push("你被推回了时光裂隙。世界在旋转，颜色在飞舞。");
  t.push("然后——你回到了现在。");
  return t;
},options:[
  {t:"检查现在的世界——改变了吗",go:"seal6_exp_new_world",effect:{time:1,flag:"seal6_exp_past_changed",flag2:"seal6_exp_paradox_anchored"}},
  {t:"先休息，恢复精神",go:"seal6_exp_rest",effect:{time:1,flag:"seal6_exp_past_changed"}}
]}};

N["seal6_exp_new_world"]=function(){return{place:"承天山 · 后山",text:function(){
  var t=[];
  t.push("你回到了现在。");
  t.push("承天山还是承天山。时光裂隙还在。但——不一样了。");
  t.push("你拿出萨满仪式全书，翻到第三印那一页。上面写着：『第三印锚点：十二神器之一·灵魂之眼。』");
  t.push("不是精灵女王。是——神器。");
  t.push("你翻到第五印。『第五印锚点：十二神器之一·深海之珠。』");
  t.push("不是海族的痛苦。是——神器。");
  t.push("你改变了过去。新的时间线里，黄林晶用了十二神器作为锚点，没有用活的生物。精灵女王没有被封印，海族没有被流放。");
  t.push("但——你之前的经历呢？你修复的第一印到第五印呢？");
  t.push("你摸了摸自己的身体。你还在。你的记忆还在。你成为了——两个时间线的交汇点。");
  t.push("第六印修复了。因为你完成了『不可能的任务』。懒惰被削弱了。");
  return t;
},options:[
  {t:"去找玄机子，告诉他发生了什么",go:"seal6_exp_aftermath",effect:{time:1,flag:"seal6_exp_repaired",flag2:"seal6_exp_timeline_changed"}},
  {t:"直接前往第七印",go:"seal6_exp_transition",effect:{time:1,flag:"seal6_exp_repaired"}}
]}};

N["seal6_exp_aftermath"]=function(){return{place:"承天书院",text:function(){
  var t=[];
  t.push("你找到了玄机子。");
  t.push("他看到你，愣住了。然后——他的眼睛亮了。不再是懒洋洋的，是——充满了活力。");
  t.push("「你做到了。」他说，「我能感受到——懒惰的影响消失了。书院的学生们——都醒了。」");
  t.push("你告诉他你改变了过去。他听完后，沉默了很久。");
  t.push("「时间悖论。」他说，「你改变了过去，但你自己没有消失。因为你成为了新时间线的锚。这意味着——你同时存在于两个时间线里。」");
  t.push("「这会有什么后果？」");
  t.push("「不知道。」玄机子说，「但有一点是肯定的——你比以前更强了。两个时间线的力量，都集中在你身上。」");
  t.push("你握了握拳。确实——你感到自己的力量增长了。不是膨胀的增长，是——踏实的增长。");
  t.push("第六印。修复了。");
  t.push("还有最后一道印。第七印。死亡沙漠。色欲。");
  return t;
},options:[
  {t:"前往死亡沙漠（第七印）",go:"seal6_exp_transition",effect:{time:1,flag:"seal6_exp_repaired",flag2:"seal6_exp_dual_timeline",skillUp:"magic"}},
  {t:"在承天书院休息几天",go:"seal6_exp_rest",effect:{time:3,flag:"seal6_exp_repaired"}}
]}};

N["seal6_exp_transition"]=function(){return{place:"东部王国边境",text:function(){
  var t=[];
  t.push("你离开了东部王国。");
  t.push("回头看，承天山的轮廓在夕阳下显得格外缥缈。山顶的云雾散开了——你第一次看到了承天书院的全貌。它很美。");
  t.push("第六印。修复了。过去改变了。");
  t.push("但你知道，这不是结束。还有最后一道印。第七印。死亡沙漠。色欲。");
  t.push("你摸了摸怀里的萨满仪式全书。第七印——所有原初之物中最神秘的一个。它会让你沉溺于快乐，忘记一切。");
  t.push("死亡沙漠。大陆上最危险的地方。深渊神殿就在那里。");
  t.push("你深吸一口气，踏上了前往死亡沙漠的路。");
  t.push("最后的旅程。");
  return t;
},options:[
  {t:"前往死亡沙漠（第七印）",go:"seal7_exp_intro",effect:{time:15}},
  {t:"先回交汇城休整",go:"fc_jiaohui_entry",effect:{time:5}}
]}};

/* ================================================================
   第七印 · 死亡沙漠（色欲）— 扩充完整版
   ================================================================ */
N["seal7_exp_intro"]=function(){return{place:"死亡沙漠 · 边缘",where:"正午",text:function(){
  var t=[];
  t.push("死亡沙漠的太阳，是白色的。");
  t.push("你站在沙漠的边缘，看着一望无际的金色沙海。太阳挂在头顶，白得刺眼。地面的温度高得能煎蛋。");
  t.push("你听说过死亡沙漠。大陆上最危险的地方。没有水，没有食物，只有——沙。和沙下面的东西。");
  t.push("据说，沙漠里有海市蜃楼。不是普通的海市蜃楼——是能让人沉溺其中的幻境。你会看到你最渴望的东西，然后——走进去，再也出不来。");
  t.push("色欲。第七印。所有原初之物中最神秘的一个。它不吞噬你的身体，也不吞噬你的理智——它吞噬你的——欲望。它让你得到你想要的一切。然后——你就再也不想离开了。");
  t.push("你深吸一口气，走进了沙漠。");
  t.push("刚走了几步，你就看到了——绿洲。");
  return t;
},options:[
  {t:"走向绿洲",check:{a:"SPR",sk:"will",label:"意志"},go:"seal7_exp_oasis",fail:"seal7_exp_trapped"},
  {t:"绕开绿洲，继续前进",check:{a:"SPR",sk:"will",label:"意志"},go:"seal7_exp_desert",fail:"seal7_exp_oasis"},
  {t:"在绿洲边休息一下",go:"seal7_exp_rest_oasis",effect:{time:1}}
]}};

N["seal7_exp_oasis"]=function(){return{place:"死亡沙漠 · 绿洲",text:function(){
  var t=[];
  t.push("你走到了绿洲边。");
  t.push("湖水清澈见底，旁边有几棵椰子树。树荫下——有一个人。");
  t.push("不是普通人。是——你最想见的人。");
  t.push("如果你有爱人，那就是你的爱人。如果你有恩师，那就是你的恩师。如果你有已故的亲人——那就是你的亲人。");
  t.push("他/她向你招手。「过来。」他/她说，声音温柔得像是棉花糖，「我等你很久了。」");
  t.push("你感到一阵温暖。你想走过去。你想——拥抱他/她。");
  t.push("但你知道——这是幻境。色欲的诱惑。它知道你最渴望什么，然后——把它摆在你面前。");
  t.push("你咬着牙，没有走过去。");
  t.push("「你不来吗？」他/她的声音里有了委屈，「我真的很想你。」");
  return t;
},options:[
  {t:"拒绝——这是幻境",check:{a:"SPR",sk:"will",label:"意志"},go:"seal7_exp_desert",fail:"seal7_exp_trapped"},
  {t:"走过去——哪怕是幻境，也想再看一眼",go:"seal7_exp_embrace",effect:{time:1,sanLoss:10}},
  {t:"问他/她——你是谁",check:{a:"INT",sk:"detect",label:"侦查"},go:"seal7_exp_question",fail:"seal7_exp_trapped"}
]}};

N["seal7_exp_trapped"]=function(){return{place:"幻境",text:function(){
  var t=[];
  t.push("你沉溺了。");
  t.push("你走进了绿洲，拥抱了你最想见的人。温暖、柔软、真实——你甚至能感受到他/她的体温。");
  t.push("「别走了。」他/她说，「留在这里。这里有你想要的一切。」");
  t.push("你想留下。你真的想留下。外面的世界太苦了——战斗、判定、失败、失去。而这里——只有快乐。");
  t.push("但然后——你感到了什么。");
  t.push("你的手。你的手在变透明。不是因为你在消失——是因为你在变得『不真实』。如果你留在这里，你就会变成幻境的一部分。永远快乐，永远——虚无。");
  t.push("你想起了你的任务。七印。第六印已经修复了。只剩最后一道。如果你在这里放弃——前面的一切，都白费了。");
  t.push("你推开了他/她。");
  return t;
},options:[
  {t:"逃离幻境",check:{a:"SPR",sk:"will",label:"意志"},go:"seal7_exp_desert",fail:"seal7_exp_trapped_deep"},
  {t:"再看一眼——然后离开",go:"seal7_exp_desert",effect:{time:1,sanLoss:15,flag:"seal7_exp_trapped_once"}}
]}};

N["seal7_exp_desert"]=function(){return{place:"死亡沙漠 · 深处",text:function(){
  var t=[];
  t.push("你继续深入沙漠。");
  t.push("幻境越来越多。你看到了财富、权力、永生、爱情——所有你能想象的快乐，都摆在你面前。");
  t.push("但你没有停。你咬着牙，一步一步往前走。");
  t.push("走了三天三夜，你终于看到了——神殿。");
  t.push("深渊神殿。它建在沙漠的最深处，用黑色的石头建造。神殿的顶部，有一个巨大的雕像——不是神，是——一个人。一个在笑的人。笑得很快乐，也很——空虚。");
  t.push("第七印就在神殿里面。");
  t.push("你走到神殿门口。门是开着的。里面——传来了声音。不是说话声，是——笑声。无数人的笑声。快乐的、满足的、沉溺的笑声。");
  t.push("你走了进去。");
  return t;
},options:[
  {t:"直接进入神殿深处",go:"seal7_exp_temple",effect:{time:1}},
  {t:"先观察神殿的结构",check:{a:"INT",sk:"detect",label:"侦查"},go:"seal7_exp_observe_temple",fail:"seal7_exp_temple"},
  {t:"在门口做准备",go:"seal7_exp_prepare",effect:{time:1}}
]}};

N["seal7_exp_temple"]=function(){return{place:"深渊神殿 · 内部",text:function(){
  var t=[];
  t.push("神殿内部——是一个宴会厅。");
  t.push("长长的桌子上摆满了美食和美酒。几百个人坐在桌子旁边，在吃、在喝、在笑、在——享受。他们的脸上都带着满足的笑容。");
  t.push("但你注意到——他们的眼睛是空的。没有瞳孔，只有一片白色。他们已经不是人了——他们是色欲的俘虏。");
  t.push("宴会厅的尽头，有一个王座。王座上坐着——一个人。");
  t.push("不，不是人。是——色欲。原初之物的七分之一。它化作了人形——一个完美的人。完美的脸，完美的身材，完美的——一切。");
  t.push("「你来了。」它说，声音像是音乐，「我等你很久了。」");
  t.push("它站起来，向你走来。每走一步，周围的空气都变得——甜蜜。你感到一阵眩晕。");
  t.push("「你修复了六道印。」它说，「你很强大。但你也——很辛苦。」");
  t.push("「留下来吧。」它伸出手，「在这里，你不需要再战斗了。你可以——永远快乐。」");
  return t;
},options:[
  {t:"拒绝——修复第七印",check:{a:"SPR",sk:"will",label:"意志"},go:"seal7_exp_refuse",fail:"seal7_exp_accept"},
  {t:"和它对话——了解色欲的本质",go:"seal7_exp_talk",effect:{time:1}},
  {t:"直接攻击",check:{a:"STR",sk:"martial",label:"武技"},go:"seal7_exp_combat",fail:"seal7_exp_combat_fail"}
]}};

N["seal7_exp_refuse"]=function(){return{place:"深渊神殿",text:function(){
  var t=[];
  t.push("你拒绝了。");
  t.push("「快乐不是全部。」你说，「还有责任。还有——我想做的事。」");
  t.push("色欲的笑容消失了。「责任？」它冷笑，「责任能给你什么？痛苦。牺牲。失去。而我——能给你一切。」");
  t.push("它一挥手。宴会厅里的幻境变了。你看到了——如果你留下来，会发生什么。");
  t.push("你和你最爱的人，在一个美丽的房子里。每天吃美食，喝美酒，看日落。永远快乐。永远——不变。");
  t.push("但你也看到了——外面的世界。没有你，第七印碎了。色欲扩散到整个大陆。所有人都沉溺在快乐里。没有人工作，没有人战斗，没有人——活着。他们只是——存在。像行尸走肉一样，永远快乐。");
  t.push("「这就是你想要的吗？」你问。");
  t.push("色欲沉默了。然后——它笑了。「你说得对。」它说，「快乐如果没有痛苦做对比——就什么都不是。」");
  t.push("它的身体开始发光。「我自愿被封印。」它说，「三千年了——我也累了。」");
  return t;
},options:[
  {t:"完成封印——修复第七印",check:{a:"SPR",sk:"will",label:"意志"},go:"seal7_exp_final",fail:"seal7_exp_final_fail"},
  {t:"问它为什么自愿被封印",go:"seal7_exp_why",effect:{time:1,flag:"seal7_exp_lust_voluntary"}}
]}};

N["seal7_exp_accept"]=function(){return{place:"深渊神殿",text:function(){
  var t=[];
  t.push("你接受了。");
  t.push("你走向色欲，握住了它的手。温暖、柔软、完美——你感到一阵前所未有的快乐。");
  t.push("然后——你感到了空虚。");
  t.push("快乐来得太快，太容易。没有付出，就没有真正的快乐。你得到了一切，但你——什么都没有得到。");
  t.push("你想起了沙漠里的幻境。你想起了那些眼睛空白的人。你想起了——你是谁。");
  t.push("你不是追求快乐的人。你是——承担责任的人。");
  t.push("你松开了手。");
  t.push("色欲看着你，表情复杂。「你——拒绝了？」");
  t.push("「不是拒绝快乐。」你说，「是拒绝——虚假的快乐。」");
  t.push("色欲沉默了很久。然后——它笑了。这一次，是真正的笑。「有意思。三千年了，你是第一个——看穿我的人。」");
  return t;
},options:[
  {t:"完成封印",go:"seal7_exp_final",effect:{time:1,sanLoss:10,flag:"seal7_exp_lust_tested"}}
]}};

N["seal7_exp_talk"]=function(){return{place:"深渊神殿",text:function(){
  var t=[];
  t.push("你决定和色欲对话。");
  t.push("「你到底是什么？」你问，「原初之物——到底是什么？」");
  t.push("色欲看着你，眼神复杂。「你真的想知道？」");
  t.push("「想。」");
  t.push("「好吧。」它深吸一口气，「原初之物——不是怪物。我们是——宇宙的情绪。宇宙诞生时的第一个情绪。饥饿、愤怒、傲慢、贪婪、嫉妒、懒惰、色欲——我们七个，组成了宇宙的『情感』。」");
  t.push("「黄林晶把我们分成七份，封印在七道印里。他以为他在拯救世界。但实际上——他在割裂宇宙的情感。没有情感的宇宙——是死的。」");
  t.push("「所以，七印不是在保护世界——是在慢慢杀死世界。当七印全部加固完成的那一天——宇宙就会失去所有情感。变成一个——冰冷的、理性的、死亡的世界。」");
  t.push("你愣住了。");
  t.push("「那——修复七印，是错的？」");
  t.push("「不是错的。」色欲说，「但也不全对。正确的做法——不是封印我们，是——和我们共存。让我们回到宇宙中，成为情感的一部分。而不是——被关在笼子里。」");
  return t;
},options:[
  {t:"接受这个真相——和色欲共存",go:"seal7_exp_coexist",effect:{time:1,flag:"seal7_exp_truth_known",flag2:"seal7_exp_coexist"}},
  {t:"还是封印它——至少世界暂时安全",go:"seal7_exp_final",effect:{time:1,flag:"seal7_exp_truth_known"}},
  {t:"问它怎么才能共存",go:"seal7_exp_coexist_method",effect:{time:1,flag:"seal7_exp_truth_known"}}
]}};

N["seal7_exp_why"]=function(){return{place:"深渊神殿",text:function(){
  var t=[];
  t.push("你问色欲，为什么自愿被封印。");
  t.push("它沉默了很久。然后它说：「因为我也——孤独。」");
  t.push("「三千年了，我在这里，给无数人带来快乐。但他们得到快乐之后，就变成了空壳。没有人——真正和我交流。没有人——理解我。」");
  t.push("「我是欲望。但欲望本身——也渴望被理解。」");
  t.push("你看着它。这个完美的、强大的原初之物——居然在说，它孤独。");
  t.push("你伸出手。「我可以做你的朋友。」");
  t.push("色欲愣住了。然后——它哭了。完美的脸上，流下了不完美的眼泪。");
  t.push("「好。」它说，「那我——自愿被封印。不是因为我输了。是因为——我信任你。」");
  return t;
},options:[
  {t:"完成封印——以朋友的身份",go:"seal7_exp_final_friend",effect:{time:1,flag:"seal7_exp_lust_friend",flag2:"seal7_exp_lust_voluntary"}}
]}};

N["seal7_exp_final"]=function(){return{place:"深渊神殿",text:function(){
  var t=[];
  t.push("你完成了封印。");
  t.push("你将萨满仪式全书中的最终符文，刻在神殿的地面上。白色的光芒笼罩了整个神殿。色欲的身体在发光——它在变成光，融入封印。");
  t.push("「谢谢你。」它说，声音越来越轻，「三千年了——终于可以休息了。」");
  t.push("光芒散去。神殿消失了。沙漠消失了。你站在——一片草地上。");
  t.push("七印。全部修复了。");
  t.push("你感到一阵疲惫。然后——是释然。");
  t.push("风吹过草地，带着花香。天空是蓝色的，太阳是金色的。世界——和平了。");
  t.push("但你知道——这不是真正的结束。原初之物还在。深渊还在。还有更多的挑战，在等着你。");
  t.push("但至少——今天，你可以休息了。");
  return t;
},options:[
  {t:"回到交汇城——你的旅程开始的地方",go:"seal7_exp_ending",effect:{time:5,flag:"seal7_exp_repaired",flag2:"all_seals_repaired"}},
  {t:"在草地上多待一会儿",go:"seal7_exp_ending",effect:{time:1,flag:"seal7_exp_repaired"}}
]}};

N["seal7_exp_coexist"]=function(){return{place:"深渊神殿",text:function(){
  var t=[];
  t.push("你选择了共存。");
  t.push("你没有封印色欲——而是，将它的力量，分散到了整个世界。");
  t.push("白色的光芒从神殿涌出，扩散到大陆的每一个角落。色欲的力量——不，情感的力量——回到了它该在的地方。");
  t.push("你感到了——变化。世界变得更有色彩了。人们的笑容更真实了，艺术家的作品更有感染力了，恋人们的爱情更——热烈了。");
  t.push("色欲站在你旁边。它不再是完美的人形——它变成了一束光，融入了你的身体。");
  t.push("「从今天起，」它的声音在你脑子里响起，「我就是你。你就是我。我们一起——看着这个世界。」");
  t.push("七印。全部——不是修复，是——解放。");
  t.push("原初之物回到了宇宙中。情感回到了世界上。");
  t.push("你站在沙漠里，感受着风。风里有快乐，有悲伤，有愤怒，有爱——所有的情感，混在一起，组成了——活着的感觉。");
  t.push("这才是——真正的世界。");
  return t;
},options:[
  {t:"回到交汇城",go:"seal7_exp_ending_coexist",effect:{time:5,flag:"seal7_exp_coexist",flag2:"all_seals_coexist",flag3:"lust_inside"}},
  {t:"在沙漠里感受这个新世界",go:"seal7_exp_ending_coexist",effect:{time:1,flag:"seal7_exp_coexist"}}
]}};

N["seal7_exp_ending"]=function(){return{place:"交汇城",text:function(){
  var t=[];
  t.push("你回到了交汇城。");
  t.push("一切都没变。城还是那座城，人还是那些人。但你知道——一切都变了。");
  t.push("七印修复了。原初之物被重新封印。世界——安全了。");
  t.push("你走在交汇城的街道上，看着来来往往的人群。他们不知道，有一个人，走遍了整个大陆，修复了七道印，拯救了世界。");
  t.push("他们只知道——今天天气很好。");
  t.push("你笑了。这样就够了。");
  t.push("你的旅程——暂时结束了。但世界很大，还有很多地方没去，还有很多故事没写。");
  t.push("也许有一天，你会再次踏上旅途。");
  t.push("但今天——你要休息。");
  t.push("（七印线·完。你可以继续在大陆上冒险，或者——开始新的故事。）");
  return t;
},options:[
  {t:"继续冒险",go:"fc_jiaohui_entry",effect:{time:1,flag:"seven_seals_complete"}},
  {t:"查看你的成就和状态",go:"fc_jiaohui_entry",effect:{time:1}}
]}};

N["seal7_exp_ending_coexist"]=function(){return{place:"交汇城",text:function(){
  var t=[];
  t.push("你回到了交汇城。");
  t.push("一切都变了。城还是那座城，但——更有活力了。人们的笑容更真实了，街头的艺人表演更精彩了，酒馆里的歌声更动听了。");
  t.push("情感回到了世界。原初之物不再是被封印的怪物——它们是宇宙的一部分，是——活着的证明。");
  t.push("你走在街道上，感受着周围的情感。快乐、悲伤、愤怒、爱——所有的一切，都在你身边流动。");
  t.push("你知道——这个世界，不再需要『拯救』了。它需要的是——体验。去感受，去爱，去恨，去——活着。");
  t.push("你的旅程——结束了。但也是——开始。");
  t.push("因为从今天起，你和原初之物一起，看着这个世界。看着它成长，看着它变化，看着它——越来越好。");
  t.push("（七印线·真结局。你解放了原初之物，让情感回归世界。这是最困难的路线，也是——最真实的路线。）");
  return t;
},options:[
  {t:"继续冒险——以新的身份",go:"fc_jiaohui_entry",effect:{time:1,flag:"seven_seals_coexist",flag2:"true_ending"}},
  {t:"查看你的成就",go:"fc_jiaohui_entry",effect:{time:1}}
]}};



/* ================================================================
   城市一：交汇城（自由城邦）— 深度剧情
   ================================================================ */

N["city_jiaohui_entry"]=function(){return{place:"交汇城",where:"午后",text:function(){
  var t=[];
  t.push("交汇城的城门，是用三种石头砌成的。");
  t.push("北方的花岗岩、南方的大理石、东方的青石——三种石头，三种颜色，代表着这座城市的身份：大陆的中心，所有人的交汇点。");
  t.push("你走进城门。人很多。有穿着长袍的魔法师，有披着铠甲的战士，有背着货箱的商人，有尖耳朵的精灵，有大胡子的矮人——甚至，你还看到了一个兽人，虽然他戴着兜帽，尽量不引人注目。");
  t.push("街道很宽，两边是密密麻麻的店铺。面包店的香味、铁匠铺的敲打声、酒馆里的喧哗——一切都充满了活力。");
  t.push("你深吸一口气。这里是交汇城。自由城邦的首都，大陆最繁华的城市。你的旅程——从这里开始，或者——回到这里。");
  if(S.flags.all_seals_repaired) t.push("你修复了七印。这座城市——因为你，而安全。");
  return t;
},options:[
  {t:"去酒馆——『银鹰酒馆』",go:"city_jiaohui_tavern",effect:{time:1}},
  {t:"去集市逛逛",go:"city_jiaohui_market",effect:{time:1}},
  {t:"去自由城邦议会大厦",go:"city_jiaohui_council",effect:{time:1}},
  {t:"去墨丘利的研究室",go:"city_jiaohui_mercury",effect:{time:1}},
  {t:"找家客栈住下",go:"city_jiaohui_inn",effect:{time:1,gold:-5}}
]}};

/* ---- 交汇城 · 银鹰酒馆 ---- */
;

N["city_jiaohui_tavern_rumor"]=function(){return{place:"银鹰酒馆",text:function(){
  var t=[];
  t.push("你点了一杯麦酒，坐在角落里，听着周围人的谈话。");
  t.push("「听说了吗？北方公国又在增兵了。铁门关那边，局势很紧张。」");
  t.push("「教会的净化令升级了。最近在查灵魂法师——说是异端。」");
  t.push("「银穗商路又断了。南方的粮食运不过来，粮价涨了三成。」");
  t.push("「精灵王国那边，女王退位了。新王是长老会选的，听说对人类的态度——很微妙。」");
  t.push("你默默记下了这些消息。大陆的局势，比你想象的更复杂。");
  t.push("然后你听到了一个让你在意的消息——");
  t.push("「你们知道吗？暗蚀会在交汇城有分部。据说，他们在招募新人。」");
  t.push("酒馆的角落里，永远坐着几个消息灵通的人。他们面前摆着半杯麦酒，不喝，只是用指腹在杯沿上画圈，眼睛却看着每一个进门的人。");t.push("你竖着耳朵听了一下午，拼凑出几则零碎的消息：北边铁门关的军粮又涨了价；南边港城来了一艘没有旗帜的船，卸下的货没人敢接；还有人说，死亡沙漠边上，有人看见过一座会发光的城。");t.push("最后一则消息，让整个角落安静了一瞬。说话的人立刻被同伴捅了一下，讪讪地闭上嘴，埋头喝酒。");t.push("你记下了那句话：死亡沙漠边上，会发光的城。");t.push("你放下酒杯，走出酒馆时，天已经黑了。街上的灯笼一盏一盏亮起来，把石板路照得明晃晃的。你忽然觉得，这座城白天和夜里，是两个世界。");return t;
} /*v45inj:city_jiaohui_tavern_rumor*/,options:[
  {t:"追问暗蚀会的事",check:{a:"CHA",sk:"persu",label:"说服"},go:"city_jiaohui_eclipse_hint",fail:"city_jiaohui_entry"},
  {t:"记下消息，离开酒馆",go:"city_jiaohui_entry",effect:{time:1,flag:"jiaohui_rumors_heard"}}
]}};

N["city_jiaohui_eclipse_hint"]=function(){return{place:"银鹰酒馆",text:function(){
  var t=[];
  t.push("你压低声音，问那个说暗蚀会的人。");
  t.push("他上下打量了你一番，然后凑近了说：「你问这个干什么？这可不是什么好事。」");
  t.push("「只是好奇。」");
  t.push("「好奇害死猫。」他喝了口酒，「不过——既然你问了，我就告诉你。暗蚀会在交汇城的分部，在『旧城区』的一个地下室里。入口是一家叫『黑猫』的杂货铺。」");
  t.push("「但我劝你别去。那地方——进去了就出不来。」");
  t.push("你记下了这个地址。暗蚀会。大陆上最神秘的组织。他们的最终目标——是深渊降临。");
  t.push("你可以选择去调查，也可以——假装没听到。");
  t.push("你在墙角坐了一会儿，面前摆着一碗还没喝完的汤。");t.push("一个戴兜帽的人在你对面坐下，没有说话，只是低头看着自己面前的空碗。过了一会儿，他忽然开口：「你听说过暗蚀会吗？」");t.push("你摇头，又点头。他笑了一下，声音很轻：「城里人人都说听说过，可没人愿意承认自己知道。」");t.push("他伸出手，在桌上用汤水画了一个圈：「暗蚀会不是一群人。它是一个——胃口。」他点了点那个圈，「它吃的东西，叫『不甘心』。」");t.push("「不甘心什么？」你问。");t.push("他没有回答，只是站起来，把兜帽压了压：「你以后会懂的。不甘心的人，最后都会找到我们——或者，我们找到他们。」");t.push("他走出店门，消失在人群里。你低头看着桌上那个圈——汤水已经干了，只剩下一道浅浅的印子。");return t;
} /*v45inj:city_jiaohui_eclipse_hint*/,options:[
  {t:"去旧城区调查暗蚀会",go:"eclipse_branch_intro",effect:{time:1,flag:"eclipse_location_known"}},
  {t:"先不打草惊蛇，以后再说",go:"city_jiaohui_entry",effect:{time:1,flag:"eclipse_location_known"}}
]}};

/* ---- 交汇城 · 集市 ---- */
N["city_jiaohui_market"]=function(){return{place:"交汇城 · 中央集市",text:function(){
  var t=[];
  t.push("中央集市是交汇城最热闹的地方。");
  t.push("几百个摊位挤在一起，卖什么的都有。食物、衣服、武器、魔法物品、甚至——你看到一个摊位在卖『龙鳞』，虽然你怀疑那是染色的鱼鳞。");
  t.push("人很多，摩肩接踵。你小心地护着自己的钱袋——这种地方，小偷最多。");
  t.push("你注意到了几个有意思的摊位：");
  t.push("· 一个老妇人在卖草药，据说有治愈的功效。");
  t.push("· 一个年轻的魔法师在卖自制的卷轴，价格不贵。");
  t.push("· 一个矮人在卖锻造的武器，看起来质量不错。");
  t.push("· 一个蒙面人在卖『神秘物品』，神神秘秘的。");
  t.push("交汇城的市场，从早到晚都是活的。");t.push("卖鱼的把鱼剖开，内脏随手一甩，扔给蹲在摊边的野猫；卖布的抖开一匹靛蓝的绸子，在阳光下晃得人眼花；还有卖唱的，抱着琴蹲在台阶上，扯着嗓子唱一首谁也没听过的歌。");t.push("你挤在人群里，能闻到鱼腥味、香料味、汗味，还有一丝若有若无的劣质酒味。这里的每一种味道都很诚实——不装，不藏，就这么明晃晃地摊在太阳底下。");t.push("一个卖糖人的老头叫住你：「小郎君，来串糖人？铜板一个，包甜。」");t.push("你摸了摸口袋。那枚铜板，是你今天挣的第五个。你忽然觉得，市井的日子虽然粗粝，却有它的好——每一枚铜板，都挣得实实在在。");return t;
} /*v45inj:city_jiaohui_market*/,options:[
  {t:"去老妇人的草药摊",go:"city_jiaohui_herb",effect:{time:1}},
  {t:"去魔法师的卷轴摊",go:"city_jiaohui_scroll",effect:{time:1}},
  {t:"去矮人的武器摊",go:"city_jiaohui_weapon",effect:{time:1}},
  {t:"去蒙面人的神秘摊位",check:{a:"INT",sk:"detect",label:"侦查"},go:"city_jiaohui_mystery",fail:"city_jiaohui_market"},
  {t:"离开集市",go:"city_jiaohui_entry",effect:{time:1}}
]}};

N["city_jiaohui_herb"]=function(){return{place:"草药摊",text:function(){
  var t=[];
  t.push("老妇人的草药摊上，摆着各种各样的草药。有的你认识，有的你不认识。");
  t.push("「年轻人，买点什么？」老妇人的声音很慈祥，「这些草药都是我自己上山采的。绝对新鲜。」");
  t.push("你看了看。有止血草、有安神花、有——你注意到角落里有一株黑色的草。");
  t.push("「那是什么？」");
  t.push("老妇人的脸色变了。「那个……不卖。」");
  t.push("「为什么？」");
  t.push("「那是『蚀魂草』。」她压低声音，「能腐蚀灵魂的东西。教会禁售的。我留着——是为了研究解药。」");
  t.push("你看着那株黑色的草。蚀魂草——暗蚀会的人，经常用这种东西。");
  t.push("你蹲下来，凑近那株蚀魂草。它黑得很安静，像一团凝固的夜。");t.push("「我见过用它的人。」你说，「他们用完之后，眼睛会变。」");t.push("老妇人看了你一眼，眼神复杂：「你见过？那你应该知道，那东西不该存在。」她叹了口气，「我研究了解药二十年。可蚀魂草的毒，是往魂里去的——解药只能让它慢一点，不能让它停。」");t.push("她捻了一片蚀魂草的叶子，在指尖碾碎。黑色的汁液渗出来，在阳光下，泛着一种不祥的光。");t.push("「教会说，这是暗蚀会的东西。」她说，「可我知道，它是从地底下长出来的。地底下有什么，教会从来不问。」");t.push("她把碎叶丢进炉子里。炉火腾起一瞬，黑烟升起，又消散。");t.push("「年轻人，」她看着你，「这世上有些东西，不是躲开就能没事的。你既然见过它——就多留个心眼。」");return t;
} /*v45inj:city_jiaohui_herb*/,options:[
  {t:"买一些普通草药",go:"city_jiaohui_market",effect:{time:1,gold:-10,item:"止血草",item2:"安神花"}},
  {t:"问她蚀魂草的事",check:{a:"CHA",sk:"persu",label:"说服"},go:"city_jiaohui_herb_secret",fail:"city_jiaohui_market"},
  {t:"离开",go:"city_jiaohui_market",effect:{time:1}}
]}};

N["city_jiaohui_herb_secret"]=function(){return{place:"草药摊",text:function(){
  var t=[];
  t.push("老妇人看了看周围，确认没人注意，然后小声说：");
  t.push("「蚀魂草，是暗蚀会的人用来控制别人的。他们把蚀魂草磨成粉，混在食物或者酒里。吃了的人——会变得听话。」");
  t.push("「我儿子——就是被他们控制了。」她的声音在发抖，「三年了。我一直在研究解药，但——一直没成功。」");
  t.push("你看着她。一个普通的老妇人，因为暗蚀会，失去了儿子。");
  t.push("「如果你能帮我——」她看着你，眼睛里有了希望，「我会感激不尽。」");
  return t;
},options:[
  {t:"答应帮她找解药",go:"city_jiaohui_herb_quest",effect:{time:1,karma:3,flag:"herb_lady_quest"}},
  {t:"说你会留意的",go:"city_jiaohui_market",effect:{time:1,karma:1,flag:"herb_lady_quest"}},
  {t:"爱莫能助",go:"city_jiaohui_market",effect:{time:1,karma:-1}}
]}};

/* ---- 交汇城 · 议会大厦 ---- */
;

N["city_jiaohui_speech"]=function(){return{place:"议会广场",text:function(){
  var t=[];
  t.push("广场上，几个人在演讲。");
  t.push("一个穿着华丽的年轻人在说：「美第奇家族是自由城邦的基石！没有美第奇，就没有今天的交汇城！」周围有几个人在鼓掌，但也有人在嘘。");
  t.push("另一边，一个穿着朴素的中年人在说：「美第奇家族垄断了商会！他们抬高物价，压榨平民！我们需要——改革！」这次鼓掌的人更多。");
  t.push("你站在人群里，听着他们的争论。自由城邦的政治——比你想象的更激烈。");
  t.push("然后你注意到了——广场的角落里，有几个人在低声交谈。他们的衣服很普通，但眼神——很锐利。");
  t.push("暗蚀会？还是守望者？");
  return t;
},options:[
  {t:"接近那几个人",check:{a:"INT",sk:"detect",label:"侦查"},go:"city_jiaohui_suspicious",fail:"city_jiaohui_entry"},
  {t:"继续听演讲",go:"city_jiaohui_entry",effect:{time:1,flag:"jiaohui_politics_known"}},
  {t:"离开广场",go:"city_jiaohui_entry",effect:{time:1}}
]}};

/* ---- 交汇城 · 墨丘利研究室 ---- */
N["city_jiaohui_mercury"]=function(){return{place:"墨丘利的研究室",text:function(){
  var t=[];
  t.push("墨丘利的研究室在交汇城的魔法区。一栋不起眼的小楼，门口挂着一块牌子：『灵魂魔法研究——非请勿入』。");
  t.push("你推开门。里面很暗，到处都是书和卷轴。空气中弥漫着一种——说不上来的味道，像是旧书，又像是——灵魂。");
  t.push("墨丘利坐在桌子后面，正在研究一个发光的水晶球。他抬起头，看到你，笑了笑。");
  t.push("「哦？是你。」他说，「我以为你不会来了。」");
  t.push("他的眼睛——你注意到了。他的眼睛里，有一丝疲惫。还有——一丝悲伤。");
  t.push("「坐吧。」他指了指对面的椅子，「你想知道什么？」");
  return t;
},options:[
  {t:"问他关于守望者的事",go:"city_jiaohui_mercury_watcher",effect:{time:1}},
  {t:"问他关于灵魂魔法的事",go:"city_jiaohui_mercury_soul",effect:{time:1}},
  {t:"问他关于精灵女王的事",go:"city_jiaohui_mercury_queen",effect:{time:1}},
  {t:"问他关于七印的事",go:"city_jiaohui_mercury_seals",effect:{time:1}},
  {t:"离开",go:"city_jiaohui_entry",effect:{time:1}}
]}};

N["city_jiaohui_mercury_watcher"]=function(){return{place:"墨丘利的研究室",text:function(){
  var t=[];
  t.push("「守望者？」墨丘利的表情变了。他放下手里的水晶球，沉默了很久。");
  t.push("「我曾经是守望者。执灯人。」他说，「但我——离开了。」");
  t.push("「为什么？」");
  t.push("「因为塞拉芬。」他的声音很低，「守望者把她封印了。在地下图书馆的最深层。因为她——接触了深渊。」");
  t.push("「但她没有背叛。她只是——想知道真相。守望者的那些人，太保守了。他们害怕真相。」");
  t.push("他看着你。「你想知道守望者的秘密吗？去地下图书馆。最深层。那里——有你想知道的一切。」");
  t.push("「但要小心。」他的声音严肃起来，「有些真相——知道了，就回不去了。」");
  return t;
},options:[
  {t:"问他塞拉芬的事",go:"city_jiaohui_mercury_seraph",effect:{time:1,flag:"watcher_secret_known"}},
  {t:"记下信息，以后去调查",go:"city_jiaohui_mercury",effect:{time:1,flag:"watcher_secret_known"}},
  {t:"离开",go:"city_jiaohui_entry",effect:{time:1,flag:"watcher_secret_known"}}
]}};

/* ================================================================
   城市二：圣城（光明教会）— 深度剧情
   ================================================================ */

N["city_holy_entry"]=function(){return{place:"圣城",where:"上午",text:function(){
  var t=[];
  t.push("圣城的城墙，是白色的。");
  t.push("不是普通的白色——是那种，在阳光下会发光的白色。据说，建造城墙的石头，是教会用神圣法术净化过的。任何黑暗生物，都无法靠近。");
  t.push("你走进城门。和交汇城不一样——这里很安静。街上的人都穿着朴素的衣服，走路的时候低着头，嘴里在默念着什么。");
  t.push("街道的尽头，是一座巨大的教堂。金色的穹顶，在阳光下闪闪发光。那是——光明教会的总坛。教皇的所在地。");
  t.push("你能感受到——这里的空气中，有一种神圣的力量。让你感到平静，但也——让你感到压抑。");
  t.push("净化令。教会正在清查异端。在这里，你需要小心。");
  t.push("你站在圣城的白色城墙下，仰头看了一会儿。城墙上那些净化过的石头，在日光下泛着温润的光，像一层薄薄的、永远不会化的雪。");t.push("有孩子从你身边跑过，咯咯地笑着。一个黑袍教士停下来，看了那孩子一眼，又走开了。孩子的母亲忙把孩子们拉回身边，脸上的笑意收得很快。");t.push("你忽然明白了这座城的规则：圣光之下，人人虔诚，可虔诚本身，也是一种小心翼翼。");t.push("你在城墙根下站了很久，直到日头偏西，才抬脚走进城门。");return t;
} /*v45inj:city_holy_entry*/,options:[
  {t:"去大教堂参观",go:"city_holy_cathedral",effect:{time:1}},
  {t:"去圣光神学院",go:"city_holy_academy",effect:{time:1}},
  {t:"去审判骑士团总部",go:"city_holy_inquisition",effect:{time:1}},
  {t:"找家客栈住下",go:"city_holy_inn",effect:{time:1,gold:-5}},
  {t:"离开圣城",go:"fc_jiaohui_entry",effect:{time:1}}
]}};

N["city_holy_cathedral"]=function(){return{place:"光明大教堂",text:function(){
  var t=[];
  t.push("大教堂内部——比你想象的更宏伟。");
  t.push("穹顶有几十米高，上面画着壁画——光明神创造世界的故事。彩色玻璃窗透进来的光，把整个教堂染成了五颜六色。");
  t.push("几百个人在祈祷。他们跪在长椅上，双手合十，嘴里默念着经文。");
  t.push("祭坛在教堂的最前方。一个穿着白色长袍的神父，正在主持弥撒。他的声音很洪亮，在整个教堂里回荡。");
  t.push("你站在后面，看着这一切。你不信神——但你不得不承认，这种场面，很有感染力。");
  t.push("然后你注意到了——教堂的侧面，有一扇门。门上刻着审判骑士团的徽章。那是——审判骑士团的入口。");
  t.push("你在长椅间慢慢走着，脚下是打磨了不知多少年的石板，被无数双膝盖磨得光滑发亮。");t.push("一个老嬷嬷跪在最前排，她没有念经，只是仰头看着穹顶的壁画，嘴唇翕动着，像在跟画里的人说话。你顺着她的目光看去——壁画上的光明神，正把光分给地上的人们。他的脸，画得很慈祥。");t.push("你忽然想起圣城街头的那些人——他们低着头走路，从不看天。可在这里，所有人都仰着头。");t.push("你走到侧面那扇刻着审判骑士团徽章的门前。门是铁做的，很厚，把手已经被摸得发亮。你伸手，又缩了回来。");t.push("一个年轻的神职人员走过来，微笑着问：「需要帮忙吗？」你摇头。他看了看那扇门，笑容淡了一点：「那里面，不是信徒该去的地方。」");t.push("他走开后，你又在门边站了一会儿。你忽然觉得，这扇铁门和教堂里的彩窗，是同一座建筑的两张脸。");return t;
} /*v45inj:city_holy_cathedral*/,options:[
  {t:"参加弥撒",go:"city_holy_mass",effect:{time:1,san:5}},
  {t:"找神父告解",go:"city_holy_confession",effect:{time:1}},
  {t:"偷偷进入审判骑士团的门",check:{a:"AGI",sk:"stealth",label:"潜行"},go:"city_holy_inquisition_sneak",fail:"city_holy_caught"},
  {t:"离开大教堂",go:"city_holy_entry",effect:{time:1}}
]}};

N["city_holy_confession"]=function(){return{place:"告解室",text:function(){
  var t=[];
  t.push("你走进了告解室。");
  t.push("里面很暗，只有一盏小灯。你坐在椅子上，对面是一个格栅——神父在格栅后面，你看不到他的脸。");
  t.push("「孩子，你有什么要忏悔的？」神父的声音很温和。");
  t.push("你想了想。你做过的事——战斗、杀戮、欺骗、甚至——和原初之物达成协议。这些，算罪吗？");
  t.push("「我……不确定我有没有罪。」你说，「我做了很多事。有些是对的，有些是错的。但我——不知道该怎么判断。」");
  t.push("神父沉默了一会儿。「孩子，」他说，「罪不是由你判断的。是由神判断的。但——神是仁慈的。只要你真心忏悔，神就会原谅你。」");
  t.push("你看着格栅后面的黑影。真心忏悔？你——真心吗？");
  t.push("告解室很小，木板隔成两半。你坐下来，听见另一边传来神父平稳的呼吸声。");t.push("「孩子，你有什么要告解的？」他的声音很温和，温和得像一床晒过太阳的被子。");t.push("你沉默了很久。你说：「我见过一个人，被审判骑士带走了。他没有做错什么，我只是……没有帮他。」");t.push("神父那边安静了一会儿。然后他说：「你为此感到愧疚吗？」");t.push("「我不知道。」你说，「我只是觉得，那一天，我本来可以做点什么。」");t.push("神父轻轻叹了口气：「孩子，愧疚是一种好的痛。它说明，你的心还是软的。」他顿了顿，「但你要小心——圣城有一句老话：愧疚用久了，会变成石头。别让它在你心里待太久。」");t.push("你走出告解室。阳光照在脸上，暖的。你忽然觉得，那句「别让它待太久」，也许比告解本身，更值得记住。");return t;
} /*v45inj:city_holy_confession*/,options:[
  {t:"真心忏悔",go:"city_holy_forgiven",effect:{time:1,san:10,karma:3,church_rep:5}},
  {t:"说一些无关紧要的事",go:"city_holy_entry",effect:{time:1,san:2}},
  {t:"离开告解室",go:"city_holy_cathedral",effect:{time:1}}
]}};

N["city_holy_inquisition"]=function(){return{place:"审判骑士团总部",text:function(){
  var t=[];
  t.push("审判骑士团的总部，在大教堂的旁边。一栋灰色的建筑，没有窗户，只有一扇厚重的铁门。");
  t.push("门口站着两个审判骑士。他们穿着黑色的铠甲，脸上戴着面具——只露出眼睛。他们的眼睛——很冷。");
  t.push("你走过去，被拦住了。「审判骑士团总部，非相关人员不得入内。」");
  t.push("你看了看那扇铁门。门后面——是什么？审判室？监狱？还是——更可怕的东西？");
  t.push("净化令。教会正在清查异端。审判骑士团——就是执行净化令的人。");
  t.push("你听说过他们的手段。不是所有被抓的人，都是异端。但——审判骑士团不在乎。他们只在乎——结果。");
  t.push("审判庭的空气，是冷的。");t.push("你站在旁听席的角落，看着铁栏后的被告——一个瘦弱的女人，穿着洗得发白的衣服。她低着头，看不清表情。");t.push("主审官念着罪状：「修习灵魂魔法，证据确凿。按教规，当处以……」他没有念完，因为女人忽然抬起头，打断了他。");t.push("「我没有修习灵魂魔法。」她说，声音不大，却很稳，「我救人的时候，用的是药，是水，是两只手。你们说的灵魂魔法——我连那三个字，都是今天第一次听清。」");t.push("主审官没有回答。他翻开另一页纸，继续念。女人不再说话了。");t.push("你站在角落里，忽然觉得，审判庭的冷，不是来自石头——是来自那些把「有罪」两个字，念得那么熟练的嘴。");t.push("你转身离开。身后，审判还在继续。你没有回头。");return t;
} /*v45inj:city_holy_inquisition*/,options:[
  {t:"问他们关于净化令的事",check:{a:"CHA",sk:"persu",label:"说服"},go:"city_holy_inquisition_talk",fail:"city_holy_entry"},
  {t:"找机会溜进去",check:{a:"AGI",sk:"stealth",label:"潜行"},go:"city_holy_inquisition_sneak",fail:"city_holy_caught"},
  {t:"离开",go:"city_holy_entry",effect:{time:1}}
]}};

/* ================================================================
   城市三：铁峰堡（矮人王国）— 深度剧情
   ================================================================ */

N["city_ironpeak_entry"]=function(){return{place:"铁峰堡",where:"正午",text:function(){
  var t=[];
  t.push("铁峰堡的城门，是用铁做的。");
  t.push("不是普通的铁——是矮人用秘法锻造的『魔铁』。据说，这种铁比钢还硬，比银还轻。而且——能抵抗魔法。");
  t.push("你走进城门。和人类的城市不一样——铁峰堡是建在山里面的。整个城市，就是一个巨大的山洞。");
  t.push("山洞里点着无数的火把和魔法灯，把整个空间照得通明。街道是用石头铺的，两边是矮人的房屋——石头砌的，很结实，但也很朴素。");
  t.push("你能听到——敲打声。到处都是敲打声。矮人是天生的工匠，铁峰堡里，有几百个锻造炉，日夜不停地工作。");
  t.push("空气里弥漫着煤烟和铁的味道。很呛人，但矮人似乎很享受。");
  t.push("第四印。永恒熔炉心。就在铁峰堡的最深处。");
  t.push("铁峰堡的城门，是两扇铸铁大门，厚得像一座山的剖面。门轴转动的声音，沉闷悠长，像巨兽在低吼。");t.push("你走进门洞，脚下是整块的岩石，被千万双脚磨得发亮。空气里有铁锈味、煤灰味，还有一股说不清的、温热的甜味——像烤过的麦芽。");t.push("街边的铺子大多是工坊，锤声此起彼伏，叮叮当当，像这座城市的心跳。一个矮人学徒从铺子里探出头，看了你一眼，又缩了回去，很快，里面传来一声师父的呵斥。");t.push("你忽然觉得，这座城市和别处不一样——它不欢迎闲人，它只敬重手上有一层老茧的人。");t.push("你把袖口卷起来，露出常年劳作磨出的茧子，大步走了进去。");return t;
} /*v45inj:city_ironpeak_entry*/,options:[
  {t:"去矮人王宫",go:"city_ironpeak_palace",effect:{time:1}},
  {t:"去锻造区看看",go:"city_ironpeak_forge",effect:{time:1}},
  {t:"去酒馆喝一杯",go:"city_ironpeak_tavern",effect:{time:1}},
  {t:"去永恒熔炉（第四印）",go:"seal4_act1_intro",effect:{time:1}},
  {t:"离开铁峰堡",go:"fc_jiaohui_entry",effect:{time:1}}
]}};

N["city_ironpeak_forge"]=function(){return{place:"铁峰堡 · 锻造区",text:function(){
  var t=[];
  t.push("锻造区是铁峰堡最热闹的地方。");
  t.push("几百个锻造炉排成一排，每个炉子前面都有一个矮人在工作。他们光着膀子，肌肉发达，手里的锤子抡得虎虎生风。");
  t.push("你走到一个老矮人旁边。他正在锻造一把剑。每一次敲打，都精准地落在同一个点上。火星四溅，但他连眼睛都不眨。");
  t.push("「好剑。」你说。");
  t.push("老矮人抬头看了你一眼。「人类？」他哼了一声，「你懂剑？」");
  t.push("「略懂。」");
  t.push("他把剑递给你。你接过来——很沉，但平衡性极好。剑刃上有一层淡淡的蓝光——是魔法附魔。");
  t.push("「这把剑，」老矮人说，「我打了三个月。用的是『星辰铁』。整个大陆，只有三把。」");
  t.push("铁峰堡的锻坊，不分昼夜。");t.push("你走进去的时候，一个老矮人正坐在铁砧边，一块一块地敲着一根铁条。他没有看你，可你知道，他听见了你进来。");t.push("「人类。」他说，语气像在陈述一件不需要确认的事，「摸过锤子吗？」");t.push("你点头。他放下铁条，朝对面努了努嘴：「那边有炉子，有铁。打一件东西给我看。」");t.push("你走过去，握起锤子。锤柄是温的——上一个用的人，刚放下不久。你烧红铁块，抡起锤子。铁花四溅，声音在锻坊里回荡。");t.push("老矮人听了一会儿，忽然说：「停。」你停下来。他走过来，看了看你的铁块：「手不抖。心不慌。谁教你的？」");t.push("「我父亲。」你说。");t.push("他点了点头：「你父亲，是个好铁匠。」他接过你的锤子，替你补了几锤，铁块立刻圆润起来。「记住，铁这东西，你骗它，它就骗你。」");return t;
} /*v45inj:city_ironpeak_forge*/,options:[
  {t:"问他能不能教你锻造",check:{a:"STR",sk:"craft",label:"锻造"},go:"city_ironpeak_learn",fail:"city_ironpeak_forge"},
  {t:"问他这把剑卖不卖",go:"city_ironpeak_buy",effect:{time:1}},
  {t:"问他关于永恒熔炉的事",check:{a:"CHA",sk:"persu",label:"说服"},go:"city_ironpeak_furnace",fail:"city_ironpeak_forge"},
  {t:"离开锻造区",go:"city_ironpeak_entry",effect:{time:1}}
]}};

N["city_ironpeak_tavern"]=function(){return{place:"铁峰堡 · 铁锤酒馆",text:function(){
  var t=[];
  t.push("铁锤酒馆是铁峰堡最大的酒馆。");
  t.push("里面很吵——矮人喝酒的时候，喜欢唱歌。虽然他们的歌声——实在不敢恭维。但他们唱得很投入，很快乐。");
  t.push("你找了个位置坐下。一个矮人女招待走过来，她的胡子比你的头发还长。「喝点什么？我们这里有矮人烈酒——人类喝一口就能醉三天。」");
  t.push("你看了看周围。大部分是矮人，但也有几个人类和精灵。铁峰堡——虽然是矮人的城市，但并不排斥外族。");
  t.push("然后你注意到了——角落里，一个矮人在独自喝酒。他的表情很沉重。和周围欢乐的气氛，格格不入。");
  t.push("矮人的歌，你第一次听，觉得吵；听久了，居然听出一点味道来。");t.push("他们唱的不是什么英雄史诗。唱的是炉子，是矿脉，是哪个矿洞出了好铁，是谁家的女儿嫁了个打铁的。调子简单，翻来覆去，可每一句都唱得理直气壮。");t.push("有个老矮人唱到一半，忽然停下来，举起酒杯，冲你这边喊了一句什么。周围的矮人都笑了，也举起杯子。你虽然听不懂，还是端起酒，冲他们点了点头。");t.push("老矮人咧开嘴笑了，露出一口被酒染黑的牙，转头继续唱。");t.push("你端着那杯矮人烈酒，小口地抿。酒很烈，像一口吞下一团火。可过了一会儿，那火变成了暖意，从胃里一直漫到指尖。");t.push("你忽然觉得，这座建在山肚子里的城市，没有你想象的那么冷。它的热闹，是炉火一样的——烫，但有人情味。");return t;
} /*v45inj:city_ironpeak_tavern*/,options:[
  {t:"点一杯矮人烈酒",check:{a:"CON",sk:"endurance",label:"体质"},go:"city_ironpeak_drink",fail:"city_ironpeak_drunk"},
  {t:"接近那个独自喝酒的矮人",check:{a:"CHA",sk:"persu",label:"说服"},go:"city_ironpeak_lonely",fail:"city_ironpeak_tavern"},
  {t:"听听矮人们在聊什么",go:"city_ironpeak_listen",effect:{time:1}},
  {t:"离开酒馆",go:"city_ironpeak_entry",effect:{time:1}}
]}};

N["city_ironpeak_lonely"]=function(){return{place:"铁锤酒馆",text:function(){
  var t=[];
  t.push("你走过去，在那个矮人对面坐下。");
  t.push("他抬头看了你一眼。「人类？」他的声音很沙哑，「有事？」");
  t.push("「看你一个人喝酒，想聊聊。」");
  t.push("他沉默了一会儿，然后给你倒了一杯酒。「我叫铜须。」他说，「曾经是——深渊矿层的矿工。」");
  t.push("「曾经？」");
  t.push("「现在不是了。」他喝了一大口酒，「深渊矿层——出事了。所有的矿工，都死了。只有我——活了下来。」");
  t.push("你想起了第四印的事。永恒熔炉心。贪婪。深渊矿层——就是第四印的所在地。");
  t.push("「你知道第四印的事？」你问。");
  t.push("铜须的手停住了。「你怎么知道第四印？」他的眼神变得锐利，「你——是什么人？」");
  t.push("铜须给你也倒了一杯酒。酒是黑的，像稀释过的墨水，入口却意外的甜。");t.push("「深渊矿层出事那晚，」他慢慢地喝了一口，「我刚好在洞口修镐子。轰的一声，整座山都在抖。我跑出来的时候，后面已经——什么都没有了。」");t.push("他放下酒杯，看着自己的手：「后来他们说是塌方。可我知道不是。我听见了——那下面，有什么东西，在笑。」");t.push("你没有接话。他沉默了一会儿，又给自己倒了一杯：「我活了四十三年，挖了三十年矿。那晚之后，我再没下过矿。」");t.push("「那你现在做什么？」你问。");t.push("「喝酒。」他说，「还有，等人。」");t.push("「等谁？」");t.push("他没有回答，只是又喝了一口，然后低声说：「等一个，敢听我说完的人。」");return t;
} /*v45inj:city_ironpeak_lonely*/,options:[
  {t:"告诉他你的身份和目的",go:"city_ironpeak_copper_truth",effect:{time:1,flag:"copper_whisker_ally"}},
  {t:"说你只是好奇",go:"city_ironpeak_copper_lie",effect:{time:1}},
  {t:"道歉，离开",go:"city_ironpeak_tavern",effect:{time:1}}
]}};

